CREATE OR REPLACE FUNCTION "public"."_consume_inventory_item"("p_user_id" "uuid", "p_item_id" "text", "p_qty" integer) RETURNS boolean
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_remaining INT := p_qty;
  v_row RECORD;
  v_take INT;
BEGIN
  IF p_qty IS NULL OR p_qty <= 0 THEN
    RETURN true;
  END IF;

  IF (
    SELECT COALESCE(SUM(quantity), 0)::INT
    FROM public.inventory
    WHERE user_id = p_user_id AND item_id = p_item_id
  ) < p_qty THEN
    RETURN false;
  END IF;

  FOR v_row IN
    SELECT row_id, quantity
    FROM public.inventory
    WHERE user_id = p_user_id AND item_id = p_item_id AND quantity > 0
    ORDER BY created_at ASC
    FOR UPDATE
  LOOP
    EXIT WHEN v_remaining <= 0;
    v_take := LEAST(v_row.quantity, v_remaining);
    IF v_row.quantity > v_take THEN
      UPDATE public.inventory
      SET quantity = quantity - v_take, updated_at = now()
      WHERE row_id = v_row.row_id;
    ELSE
      DELETE FROM public.inventory WHERE row_id = v_row.row_id;
    END IF;
    v_remaining := v_remaining - v_take;
  END LOOP;

  RETURN v_remaining <= 0;
END;
$$;


ALTER FUNCTION "public"."_consume_inventory_item"("p_user_id" "uuid", "p_item_id" "text", "p_qty" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_consume_inventory_row"("p_row_id" "uuid", "p_user_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_qty INT;
BEGIN
  SELECT quantity INTO v_qty
  FROM public.inventory
  WHERE row_id = p_row_id AND user_id = p_user_id
  FOR UPDATE;

  IF NOT FOUND OR v_qty IS NULL OR v_qty <= 0 THEN
    RETURN false;
  END IF;

  IF v_qty = 1 THEN
    DELETE FROM public.inventory
    WHERE row_id = p_row_id AND user_id = p_user_id;
  ELSE
    UPDATE public.inventory
    SET quantity = quantity - 1,
        updated_at = now()
    WHERE row_id = p_row_id AND user_id = p_user_id AND quantity > 1;
  END IF;

  RETURN true;
END;
$$;


ALTER FUNCTION "public"."_consume_inventory_row"("p_row_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_craft_workshop_category"("p_type" "text", "p_equip_slot" "text", "p_item_id" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT CASE
    WHEN lower(COALESCE(p_type, '')) = 'weapon' OR p_equip_slot = 'weapon' THEN 'weapon'
    WHEN p_equip_slot IN ('ring', 'necklace') THEN 'accessory'
    WHEN lower(COALESCE(p_type, '')) = 'armor'
      AND COALESCE(p_equip_slot, 'none') IN ('chest', 'head', 'legs', 'boots', 'gloves') THEN 'armor'
    WHEN lower(COALESCE(p_type, '')) IN ('potion', 'catalyst')
      OR (
        lower(COALESCE(p_type, '')) = 'consumable'
        AND COALESCE(p_item_id, '') NOT LIKE 'box\_%' ESCAPE '\'
      ) THEN 'potion'
    WHEN lower(COALESCE(p_type, '')) = 'rune' THEN 'rune'
    WHEN lower(COALESCE(p_type, '')) = 'scroll' THEN 'scroll'
    WHEN COALESCE(p_item_id, '') LIKE 'box\_%' ESCAPE '\' THEN 'other'
    ELSE 'other'
  END;
$$;


ALTER FUNCTION "public"."_craft_workshop_category"("p_type" "text", "p_equip_slot" "text", "p_item_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_dungeon_farm_reward_multiplier"("p_player_level" integer, "p_dungeon_power_requirement" integer, "p_success_rate" numeric, "p_is_first_clear" boolean DEFAULT false) RETURNS numeric
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
DECLARE
  v_rec_level INTEGER;
  v_level_gap INTEGER;
  v_level_mult NUMERIC;
  v_success_mult NUMERIC := 1.0;
  v_first_clear_mult NUMERIC := 1.0;
BEGIN
  v_rec_level := GREATEST(1, FLOOR(COALESCE(p_dungeon_power_requirement, 0) / 500.0));
  v_level_gap := GREATEST(0, COALESCE(p_player_level, 1) - v_rec_level);

  -- Overlevel curve: gap 0 => 100%, gap 10 => ~44%, gap 30+ => ~20% floor
  v_level_mult := GREATEST(0.20, 1.0 / (1.0 + v_level_gap * 0.08));

  -- Only penalize trivial farming when success is extremely high
  IF COALESCE(p_success_rate, 0) >= 0.90 THEN
    v_success_mult := GREATEST(
      0.45,
      1.0 - ((p_success_rate - 0.90) / 0.05) * 0.55
    );
  END IF;

  IF COALESCE(p_is_first_clear, false) THEN
    v_first_clear_mult := 1.75;
  END IF;

  RETURN v_level_mult * v_success_mult * v_first_clear_mult;
END;
$$;


ALTER FUNCTION "public"."_dungeon_farm_reward_multiplier"("p_player_level" integer, "p_dungeon_power_requirement" integer, "p_success_rate" numeric, "p_is_first_clear" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_dungeon_grant_milestones"("p_player_id" "uuid", "p_dungeon_id" "text", "p_total_attempts" integer, "p_zone" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_milestone INTEGER;
  v_rewards JSONB := '[]'::JSONB;
  v_claimed INTEGER[];
  v_gold_bonus INTEGER;
  v_loot_item RECORD;
  v_item_added BOOLEAN;
  v_label TEXT;
BEGIN
  SELECT COALESCE(claimed_milestones, '{}') INTO v_claimed
  FROM public.player_dungeon_stats
  WHERE player_id = p_player_id AND dungeon_id = p_dungeon_id;

  IF NOT FOUND THEN
    RETURN '[]'::JSONB;
  END IF;

  FOREACH v_milestone IN ARRAY ARRAY[10, 25, 50] LOOP
    IF p_total_attempts < v_milestone THEN
      CONTINUE;
    END IF;

    IF v_milestone = ANY(v_claimed) THEN
      CONTINUE;
    END IF;

    IF v_milestone = 10 THEN
      v_gold_bonus := 5000 + GREATEST(1, p_zone) * 2000;
      UPDATE public.users SET gold = gold + v_gold_bonus WHERE auth_id = p_player_id;
      SELECT * INTO v_loot_item
      FROM public.items
      WHERE lower(type) = 'scroll'
      ORDER BY random()
      LIMIT 1;
      v_label := '10. koşu: +' || v_gold_bonus || ' altın';
    ELSIF v_milestone = 25 THEN
      v_gold_bonus := 15000 + GREATEST(1, p_zone) * 5000;
      UPDATE public.users SET gold = gold + v_gold_bonus WHERE auth_id = p_player_id;
      SELECT * INTO v_loot_item
      FROM public.items
      WHERE lower(type) IN ('material', 'consumable')
      ORDER BY random()
      LIMIT 1;
      v_label := '25. koşu: +' || v_gold_bonus || ' altın';
    ELSE
      v_gold_bonus := 40000 + GREATEST(1, p_zone) * 10000;
      UPDATE public.users SET gold = gold + v_gold_bonus WHERE auth_id = p_player_id;
      SELECT * INTO v_loot_item
      FROM public.items
      WHERE lower(type) IN ('material', 'consumable', 'scroll')
      ORDER BY random()
      LIMIT 1;
      v_label := '50. koşu: +' || v_gold_bonus || ' altın';
    END IF;

    IF FOUND THEN
      v_item_added := public.dungeon_add_item(p_player_id, v_loot_item.id, 1);
      IF v_item_added THEN
        v_label := v_label || ' + ' || v_loot_item.name;
      END IF;
    END IF;

    UPDATE public.player_dungeon_stats
    SET claimed_milestones = array_append(COALESCE(claimed_milestones, '{}'), v_milestone)
    WHERE player_id = p_player_id AND dungeon_id = p_dungeon_id;

    v_rewards := v_rewards || jsonb_build_object(
      'milestone', v_milestone,
      'label', v_label,
      'gold', v_gold_bonus,
      'item_name', CASE WHEN FOUND THEN v_loot_item.name ELSE NULL END
    );
  END LOOP;

  RETURN v_rewards;
END;
$$;


ALTER FUNCTION "public"."_dungeon_grant_milestones"("p_player_id" "uuid", "p_dungeon_id" "text", "p_total_attempts" integer, "p_zone" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_dungeon_runs_since_best_rarity"("p_player_id" "uuid", "p_dungeon_id" "text") RETURNS integer
    LANGUAGE "sql" STABLE
    AS $$
  SELECT COALESCE(COUNT(*)::INTEGER, 0)
  FROM public.dungeon_runs dr
  WHERE dr.player_id = p_player_id
    AND dr.dungeon_id = p_dungeon_id
    AND dr.created_at > COALESCE(
      (
        SELECT MAX(dr2.created_at)
        FROM public.dungeon_runs dr2
        WHERE dr2.player_id = p_player_id
          AND dr2.dungeon_id = p_dungeon_id
          AND dr2.success = true
          AND EXISTS (
            SELECT 1
            FROM jsonb_array_elements(COALESCE(dr2.items_dropped, '[]'::jsonb)) elem
            WHERE lower(COALESCE(elem->>'rarity', '')) IN ('epic', 'legendary', 'mythic')
          )
      ),
      '1970-01-01'::timestamptz
    );
$$;


ALTER FUNCTION "public"."_dungeon_runs_since_best_rarity"("p_player_id" "uuid", "p_dungeon_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_effective_suspicion_risk"("p_raw" integer, "p_class" "text") RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT CASE
    WHEN COALESCE(p_class, '') = 'shadow' THEN LEAST(80, GREATEST(0, p_raw))
    ELSE LEAST(100, GREATEST(0, p_raw))
  END;
$$;


ALTER FUNCTION "public"."_effective_suspicion_risk"("p_raw" integer, "p_class" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_enrich_craft_ingredients"("p_ingredients" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    AS $$
  SELECT COALESCE(
    (
      SELECT jsonb_agg(
        jsonb_build_object(
          'item_id', ing->>'item_id',
          'item_name', COALESCE(it.name, ing->>'item_id'),
          'quantity', GREATEST(1, COALESCE((ing->>'quantity')::int, 1))
        )
        ORDER BY ing->>'item_id'
      )
      FROM jsonb_array_elements(COALESCE(p_ingredients, '[]'::jsonb)) ing
      LEFT JOIN public.items it ON it.id = ing->>'item_id'
    ),
    '[]'::jsonb
  );
$$;


ALTER FUNCTION "public"."_enrich_craft_ingredients"("p_ingredients" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_fac_unlock_facility_core"("p_user_id" "uuid", "p_type" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_player record;
  v_required_level integer;
  v_required_cost bigint;
  v_existing uuid;
BEGIN
  IF p_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  v_required_level := public._plan2_facility_unlock_level(p_type);
  v_required_cost := public._plan2_facility_unlock_cost(p_type);

  SELECT * INTO v_player
  FROM public.users u
  WHERE u.auth_id = p_user_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Player not found');
  END IF;

  IF v_player.prison_until IS NOT NULL AND v_player.prison_until > now() THEN
    RETURN jsonb_build_object('success', false, 'error', 'Cezaevindeyken tesis acilamaz');
  END IF;

  IF COALESCE(v_player.level, 1) < v_required_level THEN
    RETURN jsonb_build_object('success', false, 'error', 'Seviye yetersiz');
  END IF;

  IF COALESCE(v_player.gold, 0) < v_required_cost THEN
    RETURN jsonb_build_object('success', false, 'error', 'Altin yetersiz');
  END IF;

  SELECT f.id INTO v_existing
  FROM public.facilities f
  WHERE f.user_id = p_user_id
    AND f.type = p_type
    AND COALESCE(f.is_active, true) = true
  LIMIT 1;

  IF v_existing IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Tesis zaten acik');
  END IF;

  UPDATE public.users
  SET gold = gold - v_required_cost,
      updated_at = now()
  WHERE auth_id = p_user_id
    AND gold >= v_required_cost;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Altin yetersiz');
  END IF;

  INSERT INTO public.facilities (user_id, type, level, suspicion_level, is_active, updated_at)
  VALUES (p_user_id, p_type, 1, 0, true, now())
  ON CONFLICT (user_id, type) DO UPDATE
  SET is_active = true,
      suspicion_level = 0,
      updated_at = now();

  RETURN jsonb_build_object('success', true, 'facility_type', p_type);
END;
$$;


ALTER FUNCTION "public"."_fac_unlock_facility_core"("p_user_id" "uuid", "p_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_facility_production_counts"("p_started_at" timestamp with time zone, "p_level" integer, "p_facility_type" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    AS $$
DECLARE
  v_base_rate numeric;
  v_elapsed_seconds numeric;
  v_max_count integer;
  v_base_count integer;
  v_upper_bound integer;
  v_clamped_count integer;
  v_jitter_step integer;
  v_seed bigint;
  v_remaining integer;
BEGIN
  IF p_started_at IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Production not active'
    );
  END IF;

  v_base_rate := public._plan2_facility_base_rate(p_facility_type);
  v_elapsed_seconds := EXTRACT(EPOCH FROM (now() - p_started_at));
  IF v_elapsed_seconds >= 115 THEN
    v_elapsed_seconds := 120;
  END IF;
  v_elapsed_seconds := LEAST(120, GREATEST(0, v_elapsed_seconds));
  v_remaining := GREATEST(0, CEIL(120 - v_elapsed_seconds))::integer;

  v_max_count := ROUND((v_elapsed_seconds / 3600.0) * (v_base_rate * GREATEST(p_level, 1) * 10))::integer;
  v_base_count := v_max_count;
  v_seed := public._facility_production_seed(p_started_at);

  IF v_base_count < 20 THEN
    v_clamped_count := v_base_count;
  ELSE
    v_jitter_step := ((abs(v_seed) % 11)::integer) - 5;
    v_clamped_count := ROUND(v_base_count::numeric * (1 + (v_jitter_step::numeric / 100.0)))::integer;
  END IF;

  v_upper_bound := GREATEST(v_max_count + CEIL(v_max_count::numeric * 0.10)::integer, 0);
  v_clamped_count := LEAST(GREATEST(v_clamped_count, 0), v_upper_bound);

  RETURN jsonb_build_object(
    'success', true,
    'seed', v_seed,
    'elapsed_seconds', v_elapsed_seconds,
    'remaining_seconds', v_remaining,
    'is_ready', v_elapsed_seconds >= 115,
    'max_count', v_max_count,
    'base_count', v_base_count,
    'total_count', v_clamped_count
  );
END;
$$;


ALTER FUNCTION "public"."_facility_production_counts"("p_started_at" timestamp with time zone, "p_level" integer, "p_facility_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_facility_production_seed"("p_started_at" timestamp with time zone) RETURNS bigint
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
DECLARE
  v_text text := COALESCE(p_started_at::text, '');
  v_hash bigint := 0;
  v_i integer;
  v_code integer;
BEGIN
  FOR v_i IN 1..length(v_text) LOOP
    v_code := ascii(substr(v_text, v_i, 1));
    v_hash := mod(((v_hash << 5) - v_hash) + v_code, 2147483647);
  END LOOP;
  RETURN abs(v_hash);
END;
$$;


ALTER FUNCTION "public"."_facility_production_seed"("p_started_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_facility_resource_index"("p_seed" bigint, "p_i" integer, "p_pool_len" integer) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_index_rng double precision;
    v_idx int;
BEGIN
    -- Use a second LCG to decorrelate index selection from rarity RNG.
    -- Constants: multiplier 48271 (Park-Miller), modulus 2147483647 (2^31-1)
    v_index_rng := ((p_seed + (p_i * 7)) * 48271.0 % 2147483647.0) / 2147483647.0;

    IF p_pool_len <= 0 THEN
        RETURN 0;
    END IF;

    v_idx := floor(v_index_rng * p_pool_len)::INT;

    IF v_idx < 0 THEN
        v_idx := 0;
    ELSIF v_idx >= p_pool_len THEN
        v_idx := p_pool_len - 1;
    END IF;

    RETURN v_idx;
END;
$$;


ALTER FUNCTION "public"."_facility_resource_index"("p_seed" bigint, "p_i" integer, "p_pool_len" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_facility_simulate_rarity_items"("p_count" integer, "p_seed" bigint, "p_level" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
DECLARE
  v_lcg_mod bigint := 2147483647;
  v_lcg_mult bigint := 16807;
  v_rarity_state bigint;
  v_roll numeric;
  v_total_weight integer;
  v_common_weight integer;
  v_uncommon_weight integer;
  v_rare_weight integer;
  v_epic_weight integer;
  v_legendary_weight integer;
  v_mythic_weight integer;
  v_current_weight integer;
  v_selected_rarity text;
  v_i integer;
  v_quotas jsonb := jsonb_build_object(
    'common', 0, 'uncommon', 0, 'rare', 0, 'epic', 0, 'legendary', 0, 'mythic', 0
  );
  v_items jsonb := '[]'::jsonb;
  v_key text;
  v_val text;
  v_quota integer;
BEGIN
  IF p_count <= 0 THEN
    RETURN jsonb_build_object('items', '[]'::jsonb, 'quotas', v_quotas);
  END IF;

  v_rarity_state := mod(abs(COALESCE(p_seed, 0)) + 13579, v_lcg_mod);
  FOR v_i IN 1..5 LOOP
    v_rarity_state := mod(v_rarity_state * v_lcg_mult, v_lcg_mod);
  END LOOP;

  v_common_weight := public._plan2_rarity_weight(p_level, 'common');
  v_uncommon_weight := public._plan2_rarity_weight(p_level, 'uncommon');
  v_rare_weight := public._plan2_rarity_weight(p_level, 'rare');
  v_epic_weight := public._plan2_rarity_weight(p_level, 'epic');
  v_legendary_weight := public._plan2_rarity_weight(p_level, 'legendary');
  v_mythic_weight := public._plan2_rarity_weight(p_level, 'mythic');
  v_total_weight := v_common_weight + v_uncommon_weight + v_rare_weight + v_epic_weight + v_legendary_weight + v_mythic_weight;

  FOR v_i IN 1..p_count LOOP
    v_rarity_state := mod(v_rarity_state * v_lcg_mult, v_lcg_mod);
    v_roll := (v_rarity_state::numeric / v_lcg_mod::numeric) * v_total_weight;

    v_current_weight := 0;
    v_selected_rarity := 'common';

    v_current_weight := v_current_weight + v_common_weight;
    IF v_roll < v_current_weight AND v_selected_rarity = 'common' THEN v_selected_rarity := 'common'; END IF;

    IF v_selected_rarity = 'common' AND v_roll >= v_current_weight THEN
      v_current_weight := v_current_weight + v_uncommon_weight;
      IF v_roll < v_current_weight THEN v_selected_rarity := 'uncommon'; END IF;
    END IF;

    IF v_selected_rarity = 'common' AND v_roll >= v_current_weight THEN
      v_current_weight := v_current_weight + v_rare_weight;
      IF v_roll < v_current_weight THEN v_selected_rarity := 'rare'; END IF;
    END IF;

    IF v_selected_rarity = 'common' AND v_roll >= v_current_weight THEN
      v_current_weight := v_current_weight + v_epic_weight;
      IF v_roll < v_current_weight THEN v_selected_rarity := 'epic'; END IF;
    END IF;

    IF v_selected_rarity = 'common' AND v_roll >= v_current_weight THEN
      v_current_weight := v_current_weight + v_legendary_weight;
      IF v_roll < v_current_weight THEN v_selected_rarity := 'legendary'; END IF;
    END IF;

    IF v_selected_rarity = 'common' AND v_roll >= v_current_weight THEN
      v_selected_rarity := 'mythic';
    END IF;

    IF GREATEST(p_level, 1) < public._plan2_rarity_unlock_level(v_selected_rarity) THEN
      v_selected_rarity := 'common';
    END IF;

    v_quotas := jsonb_set(
      v_quotas,
      ARRAY[v_selected_rarity],
      to_jsonb((COALESCE((v_quotas->>v_selected_rarity)::integer, 0) + 1))
    );
  END LOOP;

  FOR v_key, v_val IN SELECT * FROM jsonb_each_text(v_quotas)
  LOOP
    v_quota := v_val::integer;
    IF v_quota <= 0 THEN
      CONTINUE;
    END IF;
    v_items := v_items || jsonb_build_array(
      jsonb_build_object('rarity', v_key, 'quantity', v_quota)
    );
  END LOOP;

  RETURN jsonb_build_object('items', v_items, 'quotas', v_quotas);
END;
$$;


ALTER FUNCTION "public"."_facility_simulate_rarity_items"("p_count" integer, "p_seed" bigint, "p_level" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_guild_war_bracket_seed_order"("p_size" integer) RETURNS integer[]
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
DECLARE
  v_half INT[];
  v_result INT[] := '{}';
  v_s INT;
BEGIN
  IF p_size <= 1 THEN
    RETURN ARRAY[1];
  END IF;
  IF p_size = 2 THEN
    RETURN ARRAY[1, 2];
  END IF;

  v_half := public._guild_war_bracket_seed_order(p_size / 2);
  FOREACH v_s IN ARRAY v_half LOOP
    v_result := v_result || v_s || (p_size + 1 - v_s);
  END LOOP;
  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."_guild_war_bracket_seed_order"("p_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_guild_war_round_name"("p_bracket_size" integer, "p_round" integer) RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
DECLARE
  v_rounds INT;
BEGIN
  v_rounds := CEIL(LOG(2, GREATEST(p_bracket_size, 2)))::INT;
  IF p_round = v_rounds THEN RETURN 'Final'; END IF;
  IF p_round = v_rounds - 1 THEN RETURN 'Yarı Final'; END IF;
  IF p_round = v_rounds - 2 THEN RETURN 'Çeyrek Final'; END IF;
  RETURN 'Tur ' || p_round;
END;
$$;


