CREATE OR REPLACE FUNCTION "public"."_horse_race_clamp_mult"("p_value" double precision, "p_min" double precision, "p_max" double precision) RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT ROUND(LEAST(p_max, GREATEST(p_min, p_value))::NUMERIC, 2);
$$;


ALTER FUNCTION "public"."_horse_race_clamp_mult"("p_value" double precision, "p_min" double precision, "p_max" double precision) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_horse_race_create_round"() RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_settings RECORD;
  v_round_id UUID;
  v_horse RECORD;
  v_gold_min NUMERIC := 1.20;
  v_gold_max NUMERIC := 5.00;
  v_gem_min NUMERIC := 1.10;
  v_gem_max NUMERIC := 2.00;
  v_house_edge NUMERIC := 0.92;
  v_count INTEGER;
  v_total_weight NUMERIC := 0;
  v_weight NUMERIC;
  v_win_prob NUMERIC;
  v_gold_mult NUMERIC;
  v_gem_mult NUMERIC;
  v_entries JSONB := '[]'::jsonb;
  v_row RECORD;
  v_weights NUMERIC[];
  v_idx INTEGER := 0;
BEGIN
  SELECT *
  INTO v_settings
  FROM public.horse_race_settings
  WHERE id = 'default' AND is_active = TRUE
  LIMIT 1;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'horse race settings missing';
  END IF;

  v_gold_max := COALESCE(v_settings.gold_max_multiplier, 12.00);
  v_gem_max := COALESCE(v_settings.gem_max_multiplier, 12.00);
  v_house_edge := COALESCE(v_settings.house_edge, 0.92);

  SELECT COUNT(*) INTO v_count
  FROM public.horse_race_templates
  WHERE is_active = TRUE;

  IF v_count < 2 THEN
    RAISE EXCEPTION 'not enough active horses';
  END IF;

  v_count := LEAST(v_count, 6);
  v_weights := public._horse_race_sample_entry_weights(v_count);

  INSERT INTO public.horse_race_rounds (
    status,
    betting_ends_at
  ) VALUES (
    'betting',
    now() + make_interval(secs => v_settings.betting_seconds)
  )
  RETURNING id INTO v_round_id;

  FOR v_horse IN
    SELECT id
    FROM public.horse_race_templates
    WHERE is_active = TRUE
    ORDER BY random()
    LIMIT v_count
  LOOP
    v_idx := v_idx + 1;
    v_weight := v_weights[v_idx];
    v_total_weight := v_total_weight + v_weight;

    v_entries := v_entries || jsonb_build_array(
      jsonb_build_object(
        'horse_id', v_horse.id,
        'win_weight', v_weight
      )
    );
  END LOOP;

  FOR v_row IN
    SELECT *
    FROM jsonb_to_recordset(v_entries) AS e(
      horse_id TEXT,
      win_weight NUMERIC
    )
  LOOP
    v_win_prob := v_row.win_weight / NULLIF(v_total_weight, 0);
    v_gold_mult := public._horse_race_clamp_mult(
      ((1 / NULLIF(v_win_prob, 0)) * v_house_edge)::DOUBLE PRECISION,
      v_gold_min::DOUBLE PRECISION,
      v_gold_max::DOUBLE PRECISION
    );
    v_gem_mult := public._horse_race_clamp_mult(
      ((1 / NULLIF(v_win_prob, 0)) * v_house_edge)::DOUBLE PRECISION,
      v_gem_min::DOUBLE PRECISION,
      v_gem_max::DOUBLE PRECISION
    );

    INSERT INTO public.horse_race_round_entries (
      round_id,
      horse_id,
      gold_multiplier,
      gem_multiplier,
      win_weight,
      win_chance_pct,
      sort_order
    ) VALUES (
      v_round_id,
      v_row.horse_id,
      v_gold_mult,
      v_gem_mult,
      v_row.win_weight,
      ROUND((v_win_prob * 100)::NUMERIC, 2),
      0
    );
  END LOOP;

  WITH ranked AS (
    SELECT
      e.id,
      ROW_NUMBER() OVER (ORDER BY e.gold_multiplier ASC) AS rn
    FROM public.horse_race_round_entries e
    WHERE e.round_id = v_round_id
  )
  UPDATE public.horse_race_round_entries e
  SET sort_order = ranked.rn
  FROM ranked
  WHERE e.id = ranked.id;

  RETURN v_round_id;
END;
$$;


ALTER FUNCTION "public"."_horse_race_create_round"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_horse_race_generate_race_script"("p_winner_id" "text", "p_horse_ids" "text"[], "p_duration_ms" integer DEFAULT 8000) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_finish_order TEXT[] := ARRAY[]::TEXT[];
  v_remaining TEXT[];
  v_leader TEXT;
  v_hid TEXT;
  v_positions JSONB := '{}'::jsonb;
  v_keyframes JSONB := '[]'::jsonb;
  v_t NUMERIC;
  v_progress NUMERIC;
  v_winner_progress NUMERIC;
  v_i INTEGER;
  v_j INTEGER;
  v_times NUMERIC[] := ARRAY[0.0, 0.18, 0.38, 0.58, 0.78, 1.0];
BEGIN
  v_remaining := ARRAY(SELECT unnest(p_horse_ids) EXCEPT SELECT unnest(ARRAY[p_winner_id]));
  v_remaining := ARRAY(SELECT x FROM unnest(v_remaining) AS x ORDER BY random());
  v_finish_order := v_remaining || ARRAY[p_winner_id];

  FOREACH v_t IN ARRAY v_times LOOP
    v_positions := '{}'::jsonb;
    v_leader := v_finish_order[1 + (FLOOR(v_t * 3)::INTEGER % GREATEST(array_length(v_finish_order, 1), 1))];

    FOR v_i IN 1..array_length(p_horse_ids, 1) LOOP
      v_hid := p_horse_ids[v_i];
      v_j := array_position(v_finish_order, v_hid);
      IF v_j IS NULL THEN
        v_j := array_length(v_finish_order, 1);
      END IF;

      v_progress := GREATEST(0, LEAST(1, v_t * (0.55 + (array_length(v_finish_order, 1) - v_j + 1)::NUMERIC * 0.08)));

      IF v_hid = p_winner_id AND v_t >= 0.82 THEN
        v_winner_progress := 0.70 + (v_t - 0.82) / 0.18 * 0.30;
        v_progress := GREATEST(v_progress, LEAST(1, v_winner_progress));
      END IF;

      IF v_hid = v_leader AND v_t < 0.82 THEN
        v_progress := v_progress + 0.06;
      END IF;

      v_positions := v_positions || jsonb_build_object(v_hid, ROUND(LEAST(1, v_progress)::NUMERIC, 4));
    END LOOP;

    v_keyframes := v_keyframes || jsonb_build_array(
      jsonb_build_object('t', v_t, 'positions', v_positions, 'leader_id', v_leader)
    );
  END LOOP;

  RETURN jsonb_build_object(
    'duration_ms', p_duration_ms,
    'finish_order', to_jsonb(v_finish_order),
    'winner_id', p_winner_id,
    'keyframes', v_keyframes
  );
END;
$$;


ALTER FUNCTION "public"."_horse_race_generate_race_script"("p_winner_id" "text", "p_horse_ids" "text"[], "p_duration_ms" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_horse_race_resolve_round"("p_round_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_settings RECORD;
  v_winner_id TEXT;
  v_horse_ids TEXT[];
  v_race_script JSONB;
  v_bet RECORD;
  v_entry RECORD;
  v_mult NUMERIC;
  v_payout NUMERIC(14,2);
  v_won BOOLEAN;
BEGIN
  SELECT *
  INTO v_settings
  FROM public.horse_race_settings
  WHERE id = 'default'
  LIMIT 1;

  SELECT e.horse_id
  INTO v_winner_id
  FROM public.horse_race_round_entries e
  WHERE e.round_id = p_round_id
  ORDER BY -LN(GREATEST(random(), 1e-9)) / GREATEST(e.win_weight, 1e-9)
  LIMIT 1;

  SELECT ARRAY_AGG(e.horse_id ORDER BY e.sort_order)
  INTO v_horse_ids
  FROM public.horse_race_round_entries e
  WHERE e.round_id = p_round_id;

  v_race_script := public._horse_race_generate_race_script(
    v_winner_id,
    v_horse_ids,
    COALESCE(v_settings.racing_seconds, 8) * 1000
  );

  UPDATE public.horse_race_rounds
  SET
    status = 'racing',
    winner_horse_id = v_winner_id,
    race_script = v_race_script,
    racing_ends_at = now() + make_interval(secs => COALESCE(v_settings.racing_seconds, 8)),
    finished_ends_at = now()
      + make_interval(secs => COALESCE(v_settings.racing_seconds, 8) + COALESCE(v_settings.finished_seconds, 10)),
    updated_at = now()
  WHERE id = p_round_id;

  FOR v_bet IN
    SELECT *
    FROM public.horse_race_bets
    WHERE round_id = p_round_id
      AND won IS NULL
  LOOP
    SELECT *
    INTO v_entry
    FROM public.horse_race_round_entries
    WHERE round_id = p_round_id
      AND horse_id = v_bet.horse_id;

    v_mult := CASE
      WHEN v_bet.currency_type = 'gems' THEN v_entry.gem_multiplier
      ELSE v_entry.gold_multiplier
    END;

    v_won := v_bet.horse_id = v_winner_id;
    v_payout := 0;

    IF v_won THEN
      IF v_bet.currency_type = 'gems' THEN
        v_payout := ROUND((v_bet.bet_amount::NUMERIC * v_mult)::NUMERIC, 2);
        UPDATE public.users SET gems = gems + v_payout WHERE auth_id = v_bet.user_id;
      ELSE
        v_payout := GREATEST(1, FLOOR(v_bet.bet_amount * v_mult)::INTEGER);
        UPDATE public.users SET gold = gold + v_payout::INTEGER WHERE auth_id = v_bet.user_id;
      END IF;
    END IF;

    UPDATE public.horse_race_bets
    SET won = v_won, payout_amount = v_payout, multiplier = v_mult
    WHERE id = v_bet.id;

    INSERT INTO public.player_horse_race_logs (
      user_id,
      round_id,
      horse_id,
      picked_horse_id,
      winner_horse_id,
      currency_type,
      bet_amount,
      multiplier,
      won,
      payout_amount,
      metadata
    ) VALUES (
      v_bet.user_id,
      p_round_id,
      v_bet.horse_id,
      v_bet.horse_id,
      v_winner_id,
      v_bet.currency_type,
      v_bet.bet_amount,
      v_mult,
      v_won,
      v_payout,
      jsonb_build_object('race_script', v_race_script)
    );
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."_horse_race_resolve_round"("p_round_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_horse_race_sample_entry_weights"("p_count" integer DEFAULT 6) RETURNS numeric[]
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_weights NUMERIC[];
  v_total NUMERIC;
  v_min_prob NUMERIC;
  v_min_share CONSTANT NUMERIC := 0.08;
  v_i INTEGER;
  v_attempt INTEGER;
  v_w NUMERIC;
BEGIN
  IF p_count < 2 OR p_count > 12 THEN
    RAISE EXCEPTION 'p_count must be between 2 and 12';
  END IF;

  FOR v_attempt IN 1..64 LOOP
    v_weights := ARRAY[]::NUMERIC[];
    v_total := 0;

    FOR v_i IN 1..p_count LOOP
      v_w := GREATEST(0.05, random());
      v_weights := array_append(v_weights, v_w);
      v_total := v_total + v_w;
    END LOOP;

    SELECT MIN(w / NULLIF(v_total, 0))
    INTO v_min_prob
    FROM unnest(v_weights) AS w;

    IF COALESCE(v_min_prob, 0) >= v_min_share THEN
      RETURN v_weights;
    END IF;
  END LOOP;

  RETURN (
    SELECT ARRAY_AGG(v ORDER BY ord)
    FROM (
      VALUES
        (1, 0.30::NUMERIC),
        (2, 0.22::NUMERIC),
        (3, 0.18::NUMERIC),
        (4, 0.14::NUMERIC),
        (5, 0.10::NUMERIC),
        (6, 0.08::NUMERIC),
        (7, 0.06::NUMERIC),
        (8, 0.05::NUMERIC),
        (9, 0.04::NUMERIC),
        (10, 0.035::NUMERIC),
        (11, 0.03::NUMERIC),
        (12, 0.025::NUMERIC)
    ) AS ladder(ord, v)
    WHERE ord <= p_count
  );
END;
$$;


ALTER FUNCTION "public"."_horse_race_sample_entry_weights"("p_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_jsonb_to_int"("val" "jsonb", "default_val" integer DEFAULT 0) RETURNS integer
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    text_val text;
begin
    -- Check for null
    if val is null or val = 'null'::jsonb then
        return default_val;
    end if;
    
    -- Try direct cast first (for integer JSONB values)
    begin
        return (val)::int;
    exception when others then
        -- Try as numeric first (handles float JSONB like 1.0)
        begin
            return (val::numeric)::int;
        exception when others then
            -- Try as text first, then numeric, then int (handles string "1.0")
            begin
                text_val := val::text;
                -- Remove quotes if present
                text_val := trim(both '"' from text_val);
                return (text_val::numeric)::int;
            exception when others then
                return default_val;
            end;
        end;
    end;
end;
$$;


ALTER FUNCTION "public"."_jsonb_to_int"("val" "jsonb", "default_val" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_kingdom_election_candidate_guilds"("p_limit" integer DEFAULT 20) RETURNS TABLE("guild_id" "uuid", "guild_name" "text", "season_rank" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH active_season AS (
    SELECT id
    FROM public.guild_war_seasons
    WHERE is_active = true
    ORDER BY created_at DESC
    LIMIT 1
  ),
  ranked AS (
    SELECT
      r.guild_id,
      g.name AS guild_name,
      ROW_NUMBER() OVER (
        ORDER BY r.points DESC, r.wins DESC, g.name ASC
      )::integer AS season_rank
    FROM public.guild_war_rankings r
    JOIN public.guilds g ON g.id = r.guild_id
    WHERE r.season_id = (SELECT id FROM active_season)
  )
  SELECT guild_id, guild_name, season_rank
  FROM ranked
  WHERE season_rank <= GREATEST(p_limit, 1)
  ORDER BY season_rank;
$$;


ALTER FUNCTION "public"."_kingdom_election_candidate_guilds"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_kingdom_election_voter_context"("p_election_id" "uuid", "p_voting_open" boolean) RETURNS json
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_auth_id uuid := auth.uid();
  v_guild_id uuid;
  v_is_leader boolean := false;
  v_guild_rank integer;
  v_already_voted boolean := false;
  v_can_vote boolean := false;
BEGIN
  IF v_auth_id IS NULL THEN
    RETURN json_build_object(
      'is_leader', false,
      'guild_rank', NULL,
      'can_vote', false,
      'already_voted', false,
      'max_rank', 20
    );
  END IF;

  SELECT g.id, (g.leader_id = v_auth_id)
  INTO v_guild_id, v_is_leader
  FROM public.guilds g
  JOIN public.users u ON u.guild_id = g.id
  WHERE u.auth_id = v_auth_id;

  IF v_guild_id IS NOT NULL THEN
    v_guild_rank := public._guild_war_season_rank(v_guild_id);

    IF p_election_id IS NOT NULL THEN
      SELECT EXISTS (
        SELECT 1
        FROM public.kingdom_election_votes
        WHERE election_id = p_election_id
          AND voter_guild_id = v_guild_id
      ) INTO v_already_voted;
    END IF;

    v_can_vote := COALESCE(p_voting_open, false)
      AND v_is_leader
      AND v_guild_rank IS NOT NULL
      AND v_guild_rank <= 20
      AND NOT v_already_voted;
  END IF;

  RETURN json_build_object(
    'is_leader', v_is_leader,
    'guild_rank', v_guild_rank,
    'can_vote', v_can_vote,
    'already_voted', v_already_voted,
    'max_rank', 20
  );
END;
$$;


ALTER FUNCTION "public"."_kingdom_election_voter_context"("p_election_id" "uuid", "p_voting_open" boolean) OWNER TO "postgres";


