  RETURN CASE p_type
    WHEN 'mining' THEN 50000
    WHEN 'quarry' THEN 80000
    WHEN 'lumber_mill' THEN 100000
    WHEN 'clay_pit' THEN 120000
    WHEN 'sand_quarry' THEN 150000
    WHEN 'farming' THEN 200000
    WHEN 'herb_garden' THEN 250000
    WHEN 'ranch' THEN 300000
    WHEN 'apiary' THEN 350000
    WHEN 'mushroom_farm' THEN 400000
    WHEN 'rune_mine' THEN 500000
    WHEN 'holy_spring' THEN 600000
    WHEN 'shadow_pit' THEN 700000
    WHEN 'elemental_forge' THEN 800000
    WHEN 'time_well' THEN 1000000
    ELSE 999999999
  END;
END;
$$;


ALTER FUNCTION "public"."_plan2_facility_unlock_cost"("p_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_plan2_facility_unlock_level"("p_type" "text") RETURNS integer
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
BEGIN
  RETURN CASE p_type
    WHEN 'mining' THEN 1
    WHEN 'quarry' THEN 2
    WHEN 'lumber_mill' THEN 3
    WHEN 'clay_pit' THEN 4
    WHEN 'sand_quarry' THEN 5
    WHEN 'farming' THEN 6
    WHEN 'herb_garden' THEN 7
    WHEN 'ranch' THEN 8
    WHEN 'apiary' THEN 9
    WHEN 'mushroom_farm' THEN 10
    WHEN 'rune_mine' THEN 15
    WHEN 'holy_spring' THEN 20
    WHEN 'shadow_pit' THEN 25
    WHEN 'elemental_forge' THEN 30
    WHEN 'time_well' THEN 40
    ELSE 99
  END;
END;
$$;


ALTER FUNCTION "public"."_plan2_facility_unlock_level"("p_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_plan2_facility_upgrade_cost"("p_type" "text", "p_current_level" integer) RETURNS bigint
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
DECLARE
  v_base bigint;
  v_mult numeric;
  v_level integer := GREATEST(1, LEAST(COALESCE(p_current_level, 1), 10));
  v_cost numeric;
  v_i integer;
BEGIN
  SELECT base_cost, multiplier
  INTO v_base, v_mult
  FROM (VALUES
    ('mining', 100000::bigint, 1.5::numeric),
    ('quarry', 120000, 1.5),
    ('lumber_mill', 150000, 1.5),
    ('clay_pit', 180000, 1.5),
    ('sand_quarry', 200000, 1.5),
    ('farming', 250000, 1.5),
    ('herb_garden', 300000, 1.5),
    ('ranch', 350000, 1.5),
    ('apiary', 400000, 1.5),
    ('mushroom_farm', 450000, 1.5),
    ('rune_mine', 500000, 1.7),
    ('holy_spring', 600000, 1.7),
    ('shadow_pit', 700000, 1.7),
    ('elemental_forge', 800000, 1.7),
    ('time_well', 1000000, 1.7)
  ) AS t(facility_type, base_cost, multiplier)
  WHERE facility_type = p_type;

  IF v_base IS NULL THEN
    RETURN 0;
  END IF;

  v_cost := v_base;
  FOR v_i IN 2..v_level LOOP
    v_cost := v_cost * v_mult;
  END LOOP;

  RETURN FLOOR(v_cost)::bigint;
END;
$$;


ALTER FUNCTION "public"."_plan2_facility_upgrade_cost"("p_type" "text", "p_current_level" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_plan2_rarity_unlock_level"("p_rarity" "text") RETURNS integer
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN CASE lower(p_rarity)
    WHEN 'common' THEN 1
    WHEN 'uncommon' THEN 3
    WHEN 'rare' THEN 5
    WHEN 'epic' THEN 7
    WHEN 'legendary' THEN 9
    WHEN 'mythic' THEN 10
    ELSE 10
  END;
END;
$$;


ALTER FUNCTION "public"."_plan2_rarity_unlock_level"("p_rarity" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_plan2_rarity_weight"("p_level" integer, "p_rarity" "text") RETURNS integer
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_level integer := GREATEST(1, LEAST(COALESCE(p_level, 1), 10));
BEGIN
  RETURN CASE v_level
    WHEN 1 THEN CASE lower(p_rarity) WHEN 'common' THEN 100 ELSE 0 END
    WHEN 2 THEN CASE lower(p_rarity) WHEN 'common' THEN 90 WHEN 'uncommon' THEN 10 ELSE 0 END
    WHEN 3 THEN CASE lower(p_rarity) WHEN 'common' THEN 70 WHEN 'uncommon' THEN 25 WHEN 'rare' THEN 5 ELSE 0 END
    WHEN 4 THEN CASE lower(p_rarity) WHEN 'common' THEN 55 WHEN 'uncommon' THEN 30 WHEN 'rare' THEN 13 WHEN 'epic' THEN 2 ELSE 0 END
    WHEN 5 THEN CASE lower(p_rarity) WHEN 'common' THEN 40 WHEN 'uncommon' THEN 30 WHEN 'rare' THEN 20 WHEN 'epic' THEN 8 WHEN 'legendary' THEN 2 ELSE 0 END
    WHEN 6 THEN CASE lower(p_rarity) WHEN 'common' THEN 30 WHEN 'uncommon' THEN 28 WHEN 'rare' THEN 22 WHEN 'epic' THEN 14 WHEN 'legendary' THEN 5 WHEN 'mythic' THEN 1 ELSE 0 END
    WHEN 7 THEN CASE lower(p_rarity) WHEN 'common' THEN 22 WHEN 'uncommon' THEN 25 WHEN 'rare' THEN 23 WHEN 'epic' THEN 18 WHEN 'legendary' THEN 9 WHEN 'mythic' THEN 3 ELSE 0 END
    WHEN 8 THEN CASE lower(p_rarity) WHEN 'common' THEN 15 WHEN 'uncommon' THEN 22 WHEN 'rare' THEN 24 WHEN 'epic' THEN 22 WHEN 'legendary' THEN 12 WHEN 'mythic' THEN 5 ELSE 0 END
    WHEN 9 THEN CASE lower(p_rarity) WHEN 'common' THEN 10 WHEN 'uncommon' THEN 18 WHEN 'rare' THEN 24 WHEN 'epic' THEN 24 WHEN 'legendary' THEN 16 WHEN 'mythic' THEN 8 ELSE 0 END
    ELSE CASE lower(p_rarity) WHEN 'common' THEN 5 WHEN 'uncommon' THEN 14 WHEN 'rare' THEN 22 WHEN 'epic' THEN 26 WHEN 'legendary' THEN 20 WHEN 'mythic' THEN 13 ELSE 0 END
  END;
END;
$$;


ALTER FUNCTION "public"."_plan2_rarity_weight"("p_level" integer, "p_rarity" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_pvp_round_name"("p_participants" integer, "p_round" integer) RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
DECLARE
  v_rounds INT;
BEGIN
  v_rounds := CEIL(LOG(2, GREATEST(p_participants, 2)))::INT;
  IF p_round = v_rounds THEN RETURN 'Final'; END IF;
  IF p_round = v_rounds - 1 THEN RETURN 'Yarı Final'; END IF;
  IF p_round = v_rounds - 2 THEN RETURN 'Çeyrek Final'; END IF;
  RETURN 'Tur ' || p_round;
END;
$$;


ALTER FUNCTION "public"."_pvp_round_name"("p_participants" integer, "p_round" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_qa_horse_race_sim_entries"() RETURNS TABLE("horse_id" "text", "gold_multiplier" numeric, "gem_multiplier" numeric, "win_weight" numeric, "sort_order" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_settings RECORD;
  v_horse RECORD;
  v_gold_min NUMERIC := 1.20;
  v_gold_max NUMERIC := 5.00;
  v_gem_min NUMERIC := 1.10;
  v_gem_max NUMERIC := 2.00;
  v_house_edge NUMERIC := 0.92;
  v_count INTEGER;
  v_total_weight NUMERIC := 0;
  v_entries JSONB := '[]'::jsonb;
  v_weights NUMERIC[];
  v_idx INTEGER := 0;
  v_weight NUMERIC;
BEGIN
  SELECT *
  INTO v_settings
  FROM public.horse_race_settings
  WHERE id = 'default' AND is_active = TRUE
  LIMIT 1;

  IF FOUND THEN
    v_gold_max := COALESCE(v_settings.gold_max_multiplier, 12.00);
    v_gem_max := COALESCE(v_settings.gem_max_multiplier, 12.00);
    v_house_edge := COALESCE(v_settings.house_edge, 0.92);
  END IF;

  SELECT COUNT(*) INTO v_count
  FROM public.horse_race_templates
  WHERE is_active = TRUE;

  IF v_count < 2 THEN
    RAISE EXCEPTION 'not enough active horses for smoke sim';
  END IF;

  v_count := LEAST(v_count, 6);
  v_weights := public._horse_race_sample_entry_weights(v_count);

  FOR v_horse IN
    SELECT id
    FROM public.horse_race_templates
    WHERE is_active = TRUE
    ORDER BY random()
    LIMIT v_count
  LOOP
    v_idx := v_idx + 1;
    v_weight := v_weights[v_idx];
    v_total_weight := v_total_weight + v_weight;
    v_entries := v_entries || jsonb_build_array(
      jsonb_build_object('horse_id', v_horse.id, 'win_weight', v_weight)
    );
  END LOOP;

  RETURN QUERY
  WITH base AS (
    SELECT
      e.horse_id,
      e.win_weight,
      (e.win_weight / NULLIF(v_total_weight, 0)) AS win_prob
    FROM jsonb_to_recordset(v_entries) AS e(
      horse_id TEXT,
      win_weight NUMERIC
    )
  ),
  priced AS (
    SELECT
      b.horse_id,
      b.win_weight,
      b.win_prob,
      public._horse_race_clamp_mult(
        ((1 / NULLIF(b.win_prob, 0)) * v_house_edge)::DOUBLE PRECISION,
        v_gold_min::DOUBLE PRECISION,
        v_gold_max::DOUBLE PRECISION
      ) AS gold_multiplier,
      public._horse_race_clamp_mult(
        ((1 / NULLIF(b.win_prob, 0)) * v_house_edge)::DOUBLE PRECISION,
        v_gem_min::DOUBLE PRECISION,
        v_gem_max::DOUBLE PRECISION
      ) AS gem_multiplier
    FROM base b
  )
  SELECT
    p.horse_id,
    p.gold_multiplier,
    p.gem_multiplier,
    p.win_weight,
    ROW_NUMBER() OVER (ORDER BY p.gold_multiplier ASC)::INTEGER AS sort_order
  FROM priced p;
END;
$$;


ALTER FUNCTION "public"."_qa_horse_race_sim_entries"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_recompute_global_suspicion"("p_user_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_bribe_ts timestamptz;
  v_active_count integer := 0;
  v_level_sum integer := 0;
  v_risk integer;
  v_class text;
  v_reduction numeric;
BEGIN
  SELECT last_bribe_at, character_class
  INTO v_bribe_ts, v_class
  FROM public.users
  WHERE auth_id = p_user_id OR id = p_user_id
  LIMIT 1;

  SELECT
    COUNT(*)::integer,
    COALESCE(SUM(level), 0)::integer
  INTO v_active_count, v_level_sum
  FROM public.facilities f
  WHERE f.user_id = p_user_id
    AND COALESCE(f.is_active, true) = true
    AND f.production_started_at IS NOT NULL
    AND (v_bribe_ts IS NULL OR f.production_started_at >= v_bribe_ts);

  v_risk := (v_active_count * 5) + (v_level_sum / 2);

  IF COALESCE(v_class, '') = 'shadow' THEN
    v_reduction := public._passive_bonus('shadow', 'facility_suspicion_reduction', 0.30);
    v_risk := floor(v_risk * (1 - v_reduction));
  END IF;

  v_risk := LEAST(100, GREATEST(0, v_risk));

  UPDATE public.users
  SET global_suspicion_level = v_risk,
      updated_at = now()
  WHERE auth_id = p_user_id OR id = p_user_id;

  RETURN v_risk;
END;
$$;


ALTER FUNCTION "public"."_recompute_global_suspicion"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_trade_apply_rejection_penalty"("p_rejector" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_reject_count int;
  v_distinct_initiators int;
BEGIN
  SELECT COUNT(*), COUNT(DISTINCT initiator_id)
  INTO v_reject_count, v_distinct_initiators
  FROM public.trade_rejection_events
  WHERE rejector_id = p_rejector
    AND created_at > now() - interval '24 hours';

  IF v_reject_count >= 5 AND v_distinct_initiators >= 3 THEN
    UPDATE public.users
    SET trade_banned_until = GREATEST(COALESCE(trade_banned_until, now()), now()) + interval '12 hours'
    WHERE auth_id = p_rejector;
  END IF;
END;
$$;


ALTER FUNCTION "public"."_trade_apply_rejection_penalty"("p_rejector" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_trade_expire_stale_sessions"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  UPDATE public.trade_sessions
  SET status = 'cancelled', updated_at = now()
  WHERE status = 'pending'
    AND created_at < now() - interval '15 minutes';

  UPDATE public.trade_sessions
  SET status = 'cancelled', updated_at = now()
  WHERE status = 'active'
    AND partner_accepted_at IS NULL;

  UPDATE public.trade_sessions ts
  SET status = 'cancelled', updated_at = now()
  WHERE ts.status = 'active'
    AND ts.updated_at < now() - interval '30 minutes'
    AND COALESCE(ts.initiator_gold, 0) = 0
    AND COALESCE(ts.partner_gold, 0) = 0
    AND NOT EXISTS (SELECT 1 FROM public.trade_items ti WHERE ti.session_id = ts.id);
END;
$$;


ALTER FUNCTION "public"."_trade_expire_stale_sessions"() OWNER TO "postgres";


