    LANGUAGE "sql" STABLE
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.trade_items ti
    JOIN public.trade_sessions ts ON ts.id = ti.session_id
    WHERE ti.inventory_row_id = p_row_id
