CREATE OR REPLACE FUNCTION "public"."add_inventory_item"("item_data" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_item_id text;
    v_user_id uuid;
    v_quantity int;
    v_new_row jsonb;
begin
    -- Get User ID
    v_user_id := auth.uid();
    if v_user_id is null then
        return '{"success": false, "error": "Not authenticated"}'::jsonb;
    end if;

    -- Extract Key Data
    v_item_id := item_data->>'id';
    if v_item_id is null or v_item_id = '' then
        return '{"success": false, "error": "item_id is required"}'::jsonb;
    end if;
    
    -- Safe CAST for quantity (handles "1.0" string from JSON, floats, and integers)
    v_quantity := public._jsonb_to_int(item_data->'quantity', 1);

    -- 1. Upsert Item Definition (Ensure item exists in DB)
    -- We update the definition to match the client's latest data
    insert into public.items (
        id, name, description, icon, type, rarity, equip_slot,
        weapon_type, armor_type, material_type, potion_type,
        attack, defense, health, power, energy_restore, heal_amount,
        base_price, vendor_sell_price, can_enhance, max_enhancement,
        is_tradeable, is_stackable, max_stack,
        required_level, required_class, tolerance_increase, overdose_risk, production_building_type
    ) values (
        v_item_id,
        item_data->>'name',
        item_data->>'description',
        item_data->>'icon',
        item_data->>'item_type',
        item_data->>'rarity',
        item_data->>'equip_slot',
        item_data->>'weapon_type',
        item_data->>'armor_type',
        item_data->>'material_type',
        item_data->>'potion_type',
        public._jsonb_to_int(item_data->'attack', 0),
        public._jsonb_to_int(item_data->'defense', 0),
        public._jsonb_to_int(item_data->'health', 0),
        public._jsonb_to_int(item_data->'power', 0),
        public._jsonb_to_int(item_data->'energy_restore', 0),
        public._jsonb_to_int(item_data->'heal_amount', 0),
        public._jsonb_to_int(item_data->'base_price', 0),
        public._jsonb_to_int(item_data->'vendor_sell_price', 0),
        coalesce((item_data->>'can_enhance')::boolean, false),
        public._jsonb_to_int(item_data->'max_enhancement', 0),
        coalesce((item_data->>'is_tradeable')::boolean, true),
        coalesce((item_data->>'is_stackable')::boolean, true),
        public._jsonb_to_int(item_data->'max_stack', 999),
        public._jsonb_to_int(item_data->'required_level', 1),
        item_data->>'required_class',
        public._jsonb_to_int(item_data->'tolerance_increase', 0),
        coalesce((item_data->>'overdose_risk')::numeric, 0),
        item_data->>'production_building_type'
    )
    on conflict (id) do update set
        name = excluded.name,
        description = excluded.description,
        icon = excluded.icon,
        attack = excluded.attack,
        defense = excluded.defense,
        health = excluded.health,
        power = excluded.power,
        energy_restore = excluded.energy_restore,
        heal_amount = excluded.heal_amount,
        base_price = excluded.base_price,
        vendor_sell_price = excluded.vendor_sell_price,
        required_level = excluded.required_level,
        required_class = excluded.required_class,
        tolerance_increase = excluded.tolerance_increase,
        overdose_risk = excluded.overdose_risk,
        production_building_type = excluded.production_building_type
    where items.id = excluded.id;  -- Ensure we only update the matching row

    -- 2. Upsert Inventory Record
    -- Ensure required columns exist (migration checks)
    -- Note: ALTER TABLE cannot be executed inside a function transaction, so we handle this before the function
    -- For now, we'll ensure the insert works by using only columns that should exist
    
    -- Validate that item_id is not null (extracted above)
    if v_item_id is null or v_item_id = '' then
        return '{"success": false, "error": "item_id cannot be null or empty"}'::jsonb;
    end if;
    
    -- Check if item is stackable from items definition
    declare
        v_is_stackable boolean;
    begin
        select coalesce(is_stackable, true) into v_is_stackable
        from public.items
        where id = v_item_id;
        
        -- If item is stackable AND player already has it, increase quantity
        -- If item is NOT stackable (equipment), always insert new row
        if v_is_stackable and exists (select 1 from public.inventory where user_id = v_user_id and item_id = v_item_id) then
            update public.inventory
            set quantity = quantity + v_quantity,
                updated_at = now()
            where user_id = v_user_id and item_id = v_item_id
            returning to_jsonb(inventory.*) into v_new_row;
        else
            -- Insert new item (for non-stackable items or first-time stackable items)
            -- Handle case where old 'id' column might exist and need a value
            declare
                v_has_old_id_column boolean;
            begin
                -- Check if old 'id' text column exists
                select exists (
                    select 1 from information_schema.columns 
                    where table_schema = 'public' 
                    and table_name = 'inventory' 
                    and column_name = 'id' 
                    and data_type = 'text'
                ) into v_has_old_id_column;
                
                if v_has_old_id_column then
                    -- Insert with old 'id' column set to item_id value
                    insert into public.inventory (
                        user_id, item_id, id, quantity, enhancement_level, is_equipped, obtained_at
                    ) values (
                        v_user_id,
                        v_item_id,
                        v_item_id,  -- Set old 'id' column to item_id value
                        v_quantity,
                        public._jsonb_to_int(item_data->'enhancement_level', 0),
                        false,
                        extract(epoch from now())::bigint
                    )
                    returning to_jsonb(inventory.*) into v_new_row;
                else
                    -- Standard insert without old 'id' column
                    insert into public.inventory (
                        user_id, item_id, quantity, enhancement_level, is_equipped, obtained_at
                    ) values (
                        v_user_id,
                        v_item_id,
                        v_quantity,
                        public._jsonb_to_int(item_data->'enhancement_level', 0),
                        false,
                        extract(epoch from now())::bigint
                    )
                    returning to_jsonb(inventory.*) into v_new_row;
                end if;
            end;
        end if;
    end;

    return jsonb_build_object('success', true, 'data', v_new_row);
end;
$$;


ALTER FUNCTION "public"."add_inventory_item"("item_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_inventory_item_v2"("item_data" "jsonb", "p_slot_position" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_auth_id UUID;
  v_item_id TEXT;
  v_quantity INTEGER;
  v_is_stackable BOOLEAN;
  v_catalog_stack BOOLEAN;
  v_slot INTEGER;
  v_existing RECORD;
  v_row_id UUID;
BEGIN
  v_auth_id := auth.uid();
  IF v_auth_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  v_item_id := item_data->>'item_id';
  v_quantity := COALESCE((item_data->>'quantity')::INTEGER, 1);

  -- Allow caller (claim) to control stacking via item_data.allow_stack (default true)
  v_is_stackable := COALESCE((item_data->>'allow_stack')::boolean, true);

  -- Enforce catalog: if item is not stackable in items table, do NOT stack regardless of caller flag
  SELECT is_stackable INTO v_catalog_stack FROM public.items WHERE id = v_item_id;
  IF v_catalog_stack IS NULL THEN
    v_catalog_stack := false;
  END IF;

  v_is_stackable := v_is_stackable AND v_catalog_stack;

  IF v_item_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'item_id required');
  END IF;
  -- Stack behavior respecting catalog.max_stack:
  IF v_is_stackable THEN
    -- Get max stack size for item from catalog
    DECLARE
      v_max_stack INTEGER := 0;
      v_existing_space INTEGER := 0;
      v_space INTEGER := 0;
      v_add INTEGER := 0;
      v_required_slots INTEGER := 0;
      v_free_slots INTEGER := 0;
      v_rows RECORD;
    BEGIN
      SELECT COALESCE(max_stack, 999999) INTO v_max_stack FROM public.items WHERE id = v_item_id;
      IF v_max_stack IS NULL OR v_max_stack <= 0 THEN
        v_max_stack := 999999;
      END IF;

      -- Total available space in existing stacks for this item
      SELECT COALESCE(SUM(GREATEST(0, v_max_stack - quantity)), 0) INTO v_existing_space
      FROM public.inventory
      WHERE user_id = v_auth_id AND item_id = v_item_id AND is_equipped = false;

      -- If all quantity fits into existing stacks, just fill them
      IF v_quantity <= v_existing_space THEN
        FOR v_rows IN
          SELECT row_id, quantity FROM public.inventory
          WHERE user_id = v_auth_id AND item_id = v_item_id AND is_equipped = false
          ORDER BY created_at ASC
        LOOP
          EXIT WHEN v_quantity <= 0;
          v_space := v_max_stack - v_rows.quantity;
          IF v_space > 0 THEN
            v_add := LEAST(v_space, v_quantity);
            UPDATE public.inventory
            SET quantity = quantity + v_add, updated_at = NOW()
            WHERE row_id = v_rows.row_id;
            v_quantity := v_quantity - v_add;
          END IF;
        END LOOP;
        RETURN jsonb_build_object('success', true, 'action', 'stacked');
      END IF;

      -- Need new slots as well. Compute required new slots and ensure enough free slots exist
      v_required_slots := CEIL( (v_quantity - v_existing_space)::numeric / v_max_stack::numeric )::integer;
      SELECT COUNT(*) INTO v_free_slots FROM generate_series(0,19) AS s(slot)
      WHERE NOT EXISTS (
        SELECT 1 FROM public.inventory WHERE user_id = v_auth_id AND slot_position = s.slot AND is_equipped = false
      );

      IF v_free_slots < v_required_slots THEN
        RETURN jsonb_build_object('success', false, 'error', 'Envanter dolu');
      END IF;

      -- Fill existing stacks first
      FOR v_rows IN
        SELECT row_id, quantity FROM public.inventory
        WHERE user_id = v_auth_id AND item_id = v_item_id AND is_equipped = false
        ORDER BY created_at ASC
      LOOP
        EXIT WHEN v_quantity <= 0;
        v_space := v_max_stack - v_rows.quantity;
        IF v_space > 0 THEN
          v_add := LEAST(v_space, v_quantity);
          UPDATE public.inventory
          SET quantity = quantity + v_add, updated_at = NOW()
          WHERE row_id = v_rows.row_id;
          v_quantity := v_quantity - v_add;
        END IF;
      END LOOP;

      -- Insert new rows for remaining quantity
      WHILE v_quantity > 0 LOOP
        v_add := LEAST(v_max_stack, v_quantity);
        SELECT s.slot INTO v_slot FROM generate_series(0,19) AS s(slot)
        WHERE NOT EXISTS (
          SELECT 1 FROM public.inventory WHERE user_id = v_auth_id AND slot_position = s.slot AND is_equipped = false
        ) ORDER BY s.slot LIMIT 1;

        INSERT INTO public.inventory (user_id, item_id, quantity, slot_position, obtained_at)
        VALUES (v_auth_id, v_item_id, v_add, v_slot, EXTRACT(EPOCH FROM NOW())::BIGINT)
        RETURNING row_id INTO v_row_id;

        v_quantity := v_quantity - v_add;
      END LOOP;

      RETURN jsonb_build_object('success', true, 'action', 'stacked_inserted');
    END;
  END IF;

  -- Boş slot bul
  v_slot := p_slot_position;
  IF v_slot IS NULL THEN
    SELECT s.slot INTO v_slot
    FROM generate_series(0, 19) AS s(slot)
    WHERE NOT EXISTS (
      SELECT 1 FROM public.inventory
      WHERE user_id = v_auth_id AND slot_position = s.slot AND is_equipped = false
    )
    ORDER BY s.slot LIMIT 1;
  END IF;

  IF v_slot IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Envanter dolu');
  END IF;

  INSERT INTO public.inventory (user_id, item_id, quantity, slot_position, obtained_at)
  VALUES (v_auth_id, v_item_id, v_quantity, v_slot, EXTRACT(EPOCH FROM NOW())::BIGINT)
  RETURNING row_id INTO v_row_id;

  RETURN jsonb_build_object('success', true, 'row_id', v_row_id, 'slot_position', v_slot, 'action', 'inserted');
END;
$$;


ALTER FUNCTION "public"."add_inventory_item_v2"("item_data" "jsonb", "p_slot_position" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_territory_defense"("p_territory_id" "uuid", "p_gems" integer) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_player_id uuid := auth.uid();
  v_guild_id uuid;
  v_territory record;
  v_player_gems integer;
  v_defense_increase integer;
BEGIN
  -- Get player's guild
  SELECT guild_id INTO v_guild_id 
  FROM public.users 
  WHERE auth_id = v_player_id;

  IF v_guild_id IS NULL THEN
    RETURN json_build_object('success', false, 'error', 'Bir loncaya üye değilsiniz.');
  END IF;

  -- Get territory
  SELECT * INTO v_territory 
  FROM public.guild_war_territories 
  WHERE id = p_territory_id;

  IF v_territory IS NULL THEN
    RETURN json_build_object('success', false, 'error', 'Bölge bulunamadı.');
  END IF;

  -- Check ownership
  IF v_territory.owner_guild_id != v_guild_id THEN
    RETURN json_build_object('success', false, 'error', 'Sadece kendi bölgenize savunma ekleyebilirsiniz.');
  END IF;

  -- Check player gems
  SELECT gems INTO v_player_gems
  FROM public.users
  WHERE auth_id = v_player_id;

  IF v_player_gems < p_gems THEN
    RETURN json_build_object('success', false, 'error', 'Yeterli elmasınız yok.');
  END IF;

  -- Calculate defense increase (e.g., 1 gem = 10 defense power)
  v_defense_increase := p_gems * 10;

  -- Deduct gems
  UPDATE public.users
  SET gems = gems - p_gems
  WHERE auth_id = v_player_id;

  -- Add defense
  UPDATE public.guild_war_territories
  SET defense_power = defense_power + v_defense_increase,
      defense_added_at = now()
  WHERE id = p_territory_id;

  RETURN json_build_object(
    'success', true,
    'message', 'Savunma başarıyla eklendi.',
    'new_defense', v_territory.defense_power + v_defense_increase
  );
END;
$$;


ALTER FUNCTION "public"."add_territory_defense"("p_territory_id" "uuid", "p_gems" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_trade_item"("p_session_id" "uuid", "p_item_row_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid UUID;
  v_sess RECORD;
  v_inv RECORD;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Oturum bulunamadı.');
  END IF;

  SELECT * INTO v_sess FROM public.trade_sessions WHERE id = p_session_id FOR UPDATE;
  IF v_sess IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Ticaret oturumu bulunamadı.');
  END IF;
  IF v_sess.status <> 'active' OR v_sess.partner_accepted_at IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Ticaret aktif değil.');
  END IF;
  IF v_uid <> v_sess.initiator_id AND v_uid <> v_sess.partner_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'Bu ticaretin katılımcısı değilsiniz.');
  END IF;

  SELECT i.row_id, i.user_id, i.is_equipped,
         COALESCE(it.is_tradeable, true) AS is_tradeable,
         COALESCE(it.is_direct_tradeable, true) AS is_direct_tradeable
  INTO v_inv
  FROM public.inventory i
  LEFT JOIN public.items it ON it.id = i.item_id
  WHERE i.row_id = p_item_row_id
  FOR UPDATE OF i;

  IF v_inv IS NULL OR v_inv.user_id <> v_uid THEN
    RETURN jsonb_build_object('success', false, 'error', 'Eşya envanterinizde yok.');
  END IF;
  IF v_inv.is_equipped THEN
    RETURN jsonb_build_object('success', false, 'error', 'Takılı eşya takas edilemez.');
  END IF;
  IF NOT v_inv.is_tradeable OR NOT v_inv.is_direct_tradeable THEN
    RETURN jsonb_build_object('success', false, 'error', 'Bu eşya takas edilemez.');
  END IF;
  IF public._trade_item_in_open_session(p_item_row_id, p_session_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Eşya başka bir ticarette kullanılıyor.');
  END IF;

  INSERT INTO public.trade_items (session_id, owner_id, inventory_row_id)
  VALUES (p_session_id, v_uid, p_item_row_id)
  ON CONFLICT (session_id, inventory_row_id) DO NOTHING;

  UPDATE public.trade_sessions
  SET initiator_confirmed = false,
      partner_confirmed = false,
      updated_at = now()
  WHERE id = p_session_id;

  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."add_trade_item"("p_session_id" "uuid", "p_item_row_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admit_to_hospital"("p_auth_id" "uuid", "p_duration_minutes" integer, "p_reason" "text") RETURNS TABLE("success" boolean, "hospital_until" timestamp without time zone, "release_time" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_release_time TIMESTAMP;
BEGIN
  v_release_time := NOW() + (p_duration_minutes || ' minutes')::INTERVAL;
  
  UPDATE public.users
  SET 
    hospital_until = v_release_time,
    hospital_reason = p_reason,
    updated_at = NOW()
  WHERE auth_id = p_auth_id;
  
  RETURN QUERY
  SELECT 
    TRUE,
    v_release_time,
    EXTRACT(EPOCH FROM v_release_time)::BIGINT;
END;
$$;


ALTER FUNCTION "public"."admit_to_hospital"("p_auth_id" "uuid", "p_duration_minutes" integer, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admit_to_prison"("p_facility_id" "uuid", "p_suspicion_level" integer DEFAULT 80) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_user_id UUID;
    v_sentence_hours INT;
    v_release_time TIMESTAMPTZ;
    v_prison_record_id UUID;
BEGIN
    v_user_id := auth.uid();

    IF NOT EXISTS (
        SELECT 1 FROM public.facilities 
        WHERE id = p_facility_id AND user_id = v_user_id
    ) THEN
        RETURN jsonb_build_object('success', false, 'error', 'Facility not found');
    END IF;

    IF EXISTS (
        SELECT 1 FROM public.prison_records
        WHERE user_id = v_user_id AND released_at IS NULL
    ) THEN
        RETURN jsonb_build_object('success', false, 'error', 'Already in prison');
    END IF;

    v_sentence_hours := 2 + (p_suspicion_level / 10);
    v_release_time := NOW() + (v_sentence_hours || ' hours')::INTERVAL;

    INSERT INTO public.prison_records (
        user_id, facility_id, reason, sentence_hours, admitted_at, released_at
    ) VALUES (
        v_user_id, p_facility_id, 'High suspicion at facility operations', v_sentence_hours, NOW(), v_release_time
    ) RETURNING id INTO v_prison_record_id;

    UPDATE public.facilities
    SET suspicion_level = 0
    WHERE id = p_facility_id;

    UPDATE public.users
    SET in_prison = true,
        prison_until = v_release_time
    WHERE auth_id = v_user_id;

    RETURN jsonb_build_object(
        'success', true,
        'message', 'Admitted to prison',
        'prison_record_id', v_prison_record_id,
        'sentence_hours', v_sentence_hours,
        'release_time', v_release_time
    );
END;
$$;


ALTER FUNCTION "public"."admit_to_prison"("p_facility_id" "uuid", "p_suspicion_level" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."allocate_stat_points"("p_attack" integer DEFAULT 0, "p_defense" integer DEFAULT 0, "p_luck" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_auth_id UUID;
  v_total INTEGER;
  v_available INTEGER;
BEGIN
  v_auth_id := auth.uid();
  IF v_auth_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  IF p_attack < 0 OR p_defense < 0 OR p_luck < 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invalid allocation');
  END IF;

  v_total := p_attack + p_defense + p_luck;
  IF v_total <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Nothing to allocate');
  END IF;

  SELECT stat_points INTO v_available
  FROM public.users
  WHERE auth_id = v_auth_id
  FOR UPDATE;

  IF v_available IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'User not found');
  END IF;

  IF v_available < v_total THEN
    RETURN jsonb_build_object('success', false, 'error', 'Insufficient stat points');
  END IF;

  UPDATE public.users
  SET attack = COALESCE(attack, 0) + p_attack,
      defense = COALESCE(defense, 0) + p_defense,
      luck = COALESCE(luck, 0) + p_luck,
      stat_points = stat_points - v_total,
      stat_allocated_attack = COALESCE(stat_allocated_attack, 0) + p_attack,
      stat_allocated_defense = COALESCE(stat_allocated_defense, 0) + p_defense,
      stat_allocated_luck = COALESCE(stat_allocated_luck, 0) + p_luck,
      updated_at = NOW()
  WHERE auth_id = v_auth_id;

  RETURN jsonb_build_object(
    'success', true,
    'spent', v_total,
    'remaining', v_available - v_total
  );
END;
$$;


ALTER FUNCTION "public"."allocate_stat_points"("p_attack" integer, "p_defense" integer, "p_luck" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_chat_filters"("p_content" "text", "p_channel" "text", "p_guild_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_result TEXT := p_content;
  v_filter RECORD;
BEGIN
  FOR v_filter IN
    SELECT term, replacement
    FROM public.chat_filters
    WHERE is_active = true
      AND (
        scope = 'global'
        OR (scope = 'channel' AND channel = p_channel)
        OR (scope = 'guild' AND p_channel = 'guild' AND guild_id = p_guild_id)
      )
    ORDER BY char_length(term) DESC
  LOOP
    v_result := regexp_replace(
      v_result,
      public.escape_chat_regex(v_filter.term),
      v_filter.replacement,
      'gi'
    );
  END LOOP;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."apply_chat_filters"("p_content" "text", "p_channel" "text", "p_guild_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_level_up_stats"("p_user_id" "uuid", "p_new_level" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user record;
  v_class record;
  v_levels_gained integer;
BEGIN
  -- KullanÄ±cÄ±yÄ± al
  SELECT * INTO v_user FROM public.users WHERE auth_id = p_user_id;
  IF NOT FOUND OR v_user.character_class IS NULL THEN
    RETURN; -- SÄ±nÄ±f seÃ§ilmemiÅŸse gÃ¼ncelleme yapma
  END IF;

  -- SÄ±nÄ±f bÃ¼yÃ¼me verilerini al
  SELECT * INTO v_class FROM public.character_classes WHERE id = v_user.character_class;
  IF NOT FOUND THEN
    RETURN;
  END IF;

  v_levels_gained := p_new_level - v_user.level; 
  IF v_levels_gained <= 0 THEN
    RETURN;
  END IF;

  UPDATE public.users SET
    attack     = attack     + (v_class.attack_per_level  * v_levels_gained),
    defense    = defense    + (v_class.defense_per_level * v_levels_gained),
    max_health = max_health + (v_class.health_per_level  * v_levels_gained),
    health     = health     + (v_class.health_per_level  * v_levels_gained),
    luck       = luck       + (v_class.luck_per_level    * v_levels_gained),
    level      = p_new_level
  WHERE auth_id = p_user_id;
END;
$$;


ALTER FUNCTION "public"."apply_level_up_stats"("p_user_id" "uuid", "p_new_level" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_monument_dungeon_drops"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_zone INT;
  v_is_boss BOOLEAN;
  v_structural INT := 0;
  v_mystical INT := 0;
  v_critical INT := 0;
BEGIN
  IF coalesce(current_setting('app.qa_mode', true), '') = 'true' THEN
    RETURN NEW;
  END IF;

  IF NOT NEW.success THEN
    RETURN NEW;
  END IF;

  SELECT COALESCE(d.zone, 1), COALESCE(d.is_boss, false)
  INTO v_zone, v_is_boss
  FROM public.dungeons d
  WHERE d.id = NEW.dungeon_id;

  IF v_zone <= 3 THEN
    v_structural := 2 + floor(random() * 9)::INT;
  ELSIF v_zone <= 5 THEN
    v_structural := 5 + floor(random() * 16)::INT;
  ELSE
    v_structural := 10 + floor(random() * 21)::INT;
  END IF;

  IF v_is_boss THEN
    IF v_zone <= 3 THEN
      v_mystical := 5 + floor(random() * 16)::INT;
    ELSIF v_zone <= 5 THEN
      v_mystical := 15 + floor(random() * 26)::INT;
    ELSE
      v_mystical := 30 + floor(random() * 51)::INT;
    END IF;
  END IF;

  IF v_zone >= 6 THEN
    IF v_zone >= 7 AND random() <= 0.50 THEN
      v_critical := 2 + floor(random() * 4)::INT;
    ELSIF random() <= 0.30 THEN
      v_critical := 1 + floor(random() * 3)::INT;
    END IF;
  END IF;

  IF v_is_boss AND v_zone >= 5 THEN
    v_critical := v_critical + 5 + floor(random() * 11)::INT;
  END IF;

  PERFORM public.grant_monument_resource_items(NEW.player_id, v_structural, v_mystical, v_critical);
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."apply_monument_dungeon_drops"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assign_chat_moderator"("p_target_user_id" "uuid", "p_channel" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor public.users%ROWTYPE;
  v_target RECORD;
  v_scope TEXT;
  v_guild_id UUID;
  v_assignment_id UUID;
BEGIN
  v_actor := public.get_current_chat_user();

  IF p_target_user_id IS NULL OR p_target_user_id = v_actor.id THEN
    RETURN jsonb_build_object('success', false, 'error', 'Gecersiz hedef');
  END IF;

  IF p_channel NOT IN ('global', 'guild', 'dm', 'trade') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Gecersiz kanal');
  END IF;

  SELECT id, guild_id INTO v_target FROM public.users WHERE id = p_target_user_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Hedef oyuncu bulunamadi');
  END IF;

  v_scope := CASE WHEN p_channel = 'guild' THEN 'guild' ELSE 'channel' END;
  v_guild_id := CASE WHEN p_channel = 'guild' THEN v_actor.guild_id ELSE NULL END;

  IF NOT public.has_chat_permission(v_actor.id, 'manage_moderators', p_channel, v_guild_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Moderator atama yetkiniz yok');
  END IF;

  IF p_channel = 'guild' AND (v_target.guild_id IS NULL OR v_target.guild_id <> v_actor.guild_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Lonca moderatorlugu sadece ayni loncadaki oyuncuya verilebilir');
  END IF;

  INSERT INTO public.chat_moderators (
    user_id,
    scope,
    channel,
    guild_id,
    can_delete,
    can_ban,
    can_manage_filters,
    can_manage_moderators,
    assigned_by_user_id
  )
  SELECT
    p_target_user_id,
    v_scope,
    CASE WHEN v_scope = 'channel' THEN p_channel ELSE 'guild' END,
    CASE WHEN v_scope = 'guild' THEN v_guild_id ELSE NULL END,
    true,
    true,
    false,
    false,
    v_actor.id
  WHERE NOT EXISTS (
    SELECT 1
    FROM public.chat_moderators cm
    WHERE cm.user_id = p_target_user_id
      AND cm.scope = v_scope
      AND COALESCE(cm.channel, '') = COALESCE(CASE WHEN v_scope = 'channel' THEN p_channel ELSE 'guild' END, '')
      AND COALESCE(cm.guild_id, '00000000-0000-0000-0000-000000000000'::uuid) = COALESCE(CASE WHEN v_scope = 'guild' THEN v_guild_id ELSE NULL END, '00000000-0000-0000-0000-000000000000'::uuid)
      AND cm.revoked_at IS NULL
  )
  RETURNING id INTO v_assignment_id;

  IF v_assignment_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Bu kullanici zaten moderator');
  END IF;

  PERFORM public.write_chat_audit(v_actor.id, 'moderator_assigned', p_target_user_id, NULL, jsonb_build_object('channel', p_channel, 'assignment_id', v_assignment_id));

  RETURN jsonb_build_object('success', true, 'assignment_id', v_assignment_id);
END;
$$;


ALTER FUNCTION "public"."assign_chat_moderator"("p_target_user_id" "uuid", "p_channel" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."attack_dungeon"("p_dungeon_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_gate JSONB;
BEGIN
  v_gate := public.enforce_rate_limit('dungeon', 20, 300);
  IF v_gate IS NOT NULL THEN RETURN v_gate; END IF;
  RETURN public.attack_dungeon_rl_inner(p_dungeon_id);
END;
$$;


ALTER FUNCTION "public"."attack_dungeon"("p_dungeon_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."attack_dungeon_rl_inner"("p_dungeon_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_result           JSONB;
  v_items_raw        JSONB;
  v_hospital_until   TIMESTAMPTZ;
  v_hospital_secs    INTEGER := 0;
  v_player_id        UUID;
  v_run_count        INTEGER;
  v_dungeon_num      INTEGER;
  v_item             RECORD;
  v_qty              INTEGER;
BEGIN
  v_player_id := auth.uid();
  v_result := public.enter_dungeon(v_player_id, p_dungeon_id);

  IF v_result ? 'error' THEN
    RETURN v_result;
  END IF;

  v_items_raw := COALESCE(v_result->'items', '[]'::JSONB);

  IF COALESCE((v_result->>'success')::BOOLEAN, false) THEN
    v_dungeon_num := COALESCE(NULLIF(regexp_replace(p_dungeon_id, '\D', '', 'g'), '')::INTEGER, 0);

    SELECT COUNT(*) INTO v_run_count
    FROM public.dungeon_runs
    WHERE player_id = v_player_id;

    IF v_run_count <= 1 THEN
      SELECT id, name, type INTO v_item
      FROM public.items
      WHERE lower(rarity) = 'common'
        AND lower(type) IN ('weapon', 'armor', 'helmet', 'gloves', 'boots', 'accessory')
      ORDER BY random()
      LIMIT 1;

      IF FOUND AND public.dungeon_add_item(v_player_id, v_item.id, 1) THEN
        v_items_raw := v_items_raw || jsonb_build_object(
          'item_id', v_item.id, 'name', v_item.name,
          'rarity', 'common', 'type', v_item.type, 'quantity', 1
        );
      END IF;

      IF public.dungeon_add_item(v_player_id, 'scroll_upgrade_low', 1) THEN
        v_items_raw := v_items_raw || jsonb_build_object(
          'item_id', 'scroll_upgrade_low', 'name', 'Lesser Upgrade Scroll',
          'rarity', 'common', 'type', 'scroll', 'quantity', 1
        );
      END IF;
    END IF;

    IF v_dungeon_num BETWEEN 1 AND 10 AND random() < 0.40 THEN
      SELECT i.id, i.name, i.type INTO v_item
      FROM public.items i
      WHERE lower(i.rarity) = 'common'
        AND lower(i.type) IN ('weapon', 'armor', 'helmet', 'gloves', 'boots', 'accessory')
      ORDER BY
        (EXISTS (
          SELECT 1 FROM public.inventory inv
          JOIN public.items it ON it.id = inv.item_id
          WHERE inv.user_id = v_player_id
            AND lower(it.type) = lower(i.type)
        )) ASC,
        (EXISTS (
          SELECT 1 FROM public.inventory inv
          WHERE inv.user_id = v_player_id AND inv.item_id = i.id
        )) ASC,
        random()
      LIMIT 1;

      IF FOUND AND public.dungeon_add_item(v_player_id, v_item.id, 1) THEN
        v_items_raw := v_items_raw || jsonb_build_object(
          'item_id', v_item.id, 'name', v_item.name,
          'rarity', 'common', 'type', v_item.type, 'quantity', 1
        );
      END IF;
    END IF;

    v_qty := 5 + floor(random() * 11)::INTEGER;

    SELECT id, name, type INTO v_item
    FROM public.items
    WHERE lower(rarity) = 'common'
      AND lower(type) = 'material'
      AND COALESCE(is_stackable, false)
    ORDER BY COALESCE(base_price, 0) ASC, random()
    LIMIT 1;

    IF FOUND AND public.dungeon_add_item(v_player_id, v_item.id, v_qty) THEN
      v_items_raw := v_items_raw || jsonb_build_object(
        'item_id', v_item.id, 'name', v_item.name,
        'rarity', 'common', 'type', v_item.type, 'quantity', v_qty
      );
    END IF;
  END IF;

  IF (v_result->>'hospital_until') IS NOT NULL THEN
    BEGIN
      v_hospital_until := (v_result->>'hospital_until')::TIMESTAMPTZ;
      v_hospital_secs  := GREATEST(0, EXTRACT(EPOCH FROM (v_hospital_until - now()))::INTEGER);
    EXCEPTION WHEN OTHERS THEN
      v_hospital_secs := 0;
    END;
  END IF;

  RETURN jsonb_build_object(
    'success',             COALESCE((v_result->>'success')::BOOLEAN, false),
    'gold',                COALESCE((v_result->>'gold_earned')::INTEGER, 0),
    'gold_earned',         COALESCE((v_result->>'gold_earned')::INTEGER, 0),
    'xp',                  COALESCE((v_result->>'xp_earned')::INTEGER, 0),
    'xp_earned',           COALESCE((v_result->>'xp_earned')::INTEGER, 0),
    'items',               v_items_raw,
    'item_details',        v_items_raw,
    'hospitalized',        COALESCE((v_result->>'hospitalized')::BOOLEAN, false),
    'hospital_duration',   v_hospital_secs,
    'hospital_until',      v_result->>'hospital_until',
    'inventory_full',      COALESCE((v_result->>'inventory_full')::BOOLEAN, false),
    'is_critical',         COALESCE((v_result->>'is_critical')::BOOLEAN, false),
    'is_first_clear',      COALESCE((v_result->>'is_first_clear')::BOOLEAN, false),
    'success_rate',        COALESCE((v_result->>'success_rate')::NUMERIC, 0),
    'reward_multiplier',   COALESCE((v_result->>'reward_multiplier')::NUMERIC, 1),
    'hospital_risk_pct',   COALESCE((v_result->>'hospital_risk_pct')::NUMERIC, 0),
    'milestone_rewards',   COALESCE(v_result->'milestone_rewards', '[]'::jsonb)
  );
END;
$$;


ALTER FUNCTION "public"."attack_dungeon_rl_inner"("p_dungeon_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."attack_guild_war_territory"("p_territory_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_player_id uuid := auth.uid();
  v_guild_id uuid;
  v_territory record;
  v_attack_power integer;
  v_success boolean;
  v_points_gained integer;
  v_active_season_id uuid;
BEGIN
  SELECT guild_id INTO v_guild_id
  FROM public.users
  WHERE auth_id = v_player_id;

  IF v_guild_id IS NULL THEN
    RETURN json_build_object('success', false, 'error', 'Bir loncaya üye değilsiniz.');
  END IF;

  SELECT * INTO v_territory
  FROM public.guild_war_territories
  WHERE id = p_territory_id;

  IF v_territory IS NULL THEN
    RETURN json_build_object('success', false, 'error', 'Bölge bulunamadı.');
  END IF;

  IF v_territory.owner_guild_id = v_guild_id THEN
    RETURN json_build_object('success', false, 'error', 'Kendi bölgenize saldıramazsınız.');
  END IF;

  SELECT COALESCE(level * 50, 100) INTO v_attack_power
  FROM public.users WHERE auth_id = v_player_id;

  v_success := (random() * v_attack_power) > (random() * GREATEST(v_territory.defense_power, 1));
  v_points_gained := CASE WHEN v_success THEN 100 ELSE 10 END;

  SELECT id INTO v_active_season_id
  FROM public.guild_war_seasons
  WHERE is_active = true
  ORDER BY created_at DESC
  LIMIT 1;

  IF v_active_season_id IS NOT NULL THEN
    INSERT INTO public.guild_war_rankings (season_id, guild_id, points, wins, losses)
    VALUES (
      v_active_season_id,
      v_guild_id,
      v_points_gained,
      CASE WHEN v_success THEN 1 ELSE 0 END,
      CASE WHEN v_success THEN 0 ELSE 1 END
    )
    ON CONFLICT (season_id, guild_id)
    DO UPDATE SET
      points = guild_war_rankings.points + v_points_gained,
      wins = guild_war_rankings.wins + (CASE WHEN v_success THEN 1 ELSE 0 END),
      losses = guild_war_rankings.losses + (CASE WHEN v_success THEN 0 ELSE 1 END),
      updated_at = now();
  END IF;

  IF v_success THEN
    UPDATE public.guild_war_territories
    SET owner_guild_id = v_guild_id,
        defense_power = v_attack_power,
        updated_at = now()
    WHERE id = p_territory_id;
  END IF;

  INSERT INTO public.guild_war_attack_logs (
    territory_id,
    attacker_guild_id,
    defender_guild_id,
    attack_power,
    defense_power,
    success,
    points_gained
  ) VALUES (
    p_territory_id,
    v_guild_id,
    v_territory.owner_guild_id,
    v_attack_power,
    v_territory.defense_power,
    v_success,
    v_points_gained
  );

  RETURN json_build_object(
    'success', v_success,
    'message', CASE WHEN v_success THEN 'Bölge ele geçirildi!' ELSE 'Saldırı başarısız!' END,
    'points_gained', v_points_gained,
    'attack_power', v_attack_power,
    'defense_power', v_territory.defense_power,
    'territory_name', v_territory.name
  );
END;
$$;


ALTER FUNCTION "public"."attack_guild_war_territory"("p_territory_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."attempt_hospital_escape"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id uuid;
  v_user record;
  v_base_chance numeric := 0.15;
  v_roll numeric;
  v_locked_until timestamptz;
  v_penalty_minutes int;
BEGIN
  v_user_id := auth.uid();
  RAISE LOG 'attempt_hospital_escape start uid=%', v_user_id;

  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT * INTO v_user
  FROM public.users
  WHERE auth_id = v_user_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE LOG 'attempt_hospital_escape user not found uid=%', v_user_id;
    RETURN jsonb_build_object('success', false, 'error', 'User not found');
  END IF;

  IF v_user.hospital_until IS NULL OR v_user.hospital_until <= now() THEN
    RAISE LOG 'attempt_hospital_escape not in hospital uid=% hospital_until=%', v_user_id, v_user.hospital_until;
    RETURN jsonb_build_object('success', false, 'error', 'You are not in the hospital');
  END IF;

  IF COALESCE(v_user.hospital_escape_attempted, false) THEN
    RAISE LOG 'attempt_hospital_escape already attempted uid=%', v_user_id;
    RETURN jsonb_build_object('success', false, 'error', 'Bu hastane sürecinde kaçmayı zaten denedin.');
  END IF;

  UPDATE public.users
  SET hospital_escape_attempted = true
  WHERE auth_id = v_user_id
    AND COALESCE(hospital_escape_attempted, false) = false
  RETURNING hospital_until INTO v_locked_until;

  IF NOT FOUND THEN
    RAISE LOG 'attempt_hospital_escape atomic guard blocked uid=%', v_user_id;
    RETURN jsonb_build_object('success', false, 'error', 'Bu hastane sürecinde kaçma hakkın tükendi.');
  END IF;

  v_roll := random();
  RAISE LOG 'attempt_hospital_escape roll uid=% roll=% chance=%', v_user_id, v_roll, v_base_chance;

  IF v_roll <= v_base_chance THEN
    UPDATE public.users
    SET hospital_until = NULL,
        hospital_reason = NULL,
        hospital_escape_attempted = false
    WHERE auth_id = v_user_id;

    RETURN jsonb_build_object('success', true, 'escaped', true, 'message', 'Gizlice hastaneden kacmayi basardin! Artik ozgursun.');
  END IF;

  -- Random penalty between 15 and 60 minutes
  v_penalty_minutes := floor(random() * 46 + 15)::int;

  UPDATE public.users
  SET hospital_until = COALESCE(v_locked_until, v_user.hospital_until, now()) + (v_penalty_minutes || ' minutes')::interval
  WHERE auth_id = v_user_id;

  RETURN jsonb_build_object('success', true, 'escaped', false, 'message', 'Doktorlar seni koridorda yakaladi! Bu hastane surecinde tekrar kacamazsin. Tedavin +' || v_penalty_minutes || ' dakika uzatildi.');
EXCEPTION WHEN OTHERS THEN
  RAISE LOG 'attempt_hospital_escape exception uid=% err=%', v_user_id, SQLERRM;
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;


ALTER FUNCTION "public"."attempt_hospital_escape"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."attempt_prison_escape"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id uuid;
  v_user record;
  v_class record;
  v_base_chance numeric := 0.15;
  v_total_chance numeric;
  v_roll numeric;
  v_escape_bonus numeric := 0;
  v_locked_until timestamptz;
  v_penalty_minutes int;
BEGIN
  v_user_id := auth.uid();
  RAISE LOG 'attempt_prison_escape start uid=%', v_user_id;

  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT * INTO v_user
  FROM public.users
  WHERE auth_id = v_user_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE LOG 'attempt_prison_escape user not found uid=%', v_user_id;
    RETURN jsonb_build_object('success', false, 'error', 'User not found');
  END IF;

  IF v_user.prison_until IS NULL OR v_user.prison_until <= now() THEN
    RAISE LOG 'attempt_prison_escape not in prison uid=% prison_until=%', v_user_id, v_user.prison_until;
    RETURN jsonb_build_object('success', false, 'error', 'You are not in prison');
  END IF;

  IF COALESCE(v_user.prison_escape_attempted, false) THEN
    RAISE LOG 'attempt_prison_escape already attempted uid=%', v_user_id;
    RETURN jsonb_build_object('success', false, 'error', 'Bu hapis surecinde kacmayi zaten denedin.');
  END IF;

  IF v_user.character_class IS NOT NULL THEN
    SELECT * INTO v_class FROM public.character_classes WHERE id = v_user.character_class;
    IF FOUND AND v_class.passive_bonuses ? 'prison_escape_bonus' THEN
      v_escape_bonus := (v_class.passive_bonuses->>'prison_escape_bonus')::numeric;
    END IF;
  END IF;

  v_total_chance := v_base_chance + v_escape_bonus;

  UPDATE public.users
  SET prison_escape_attempted = true
  WHERE auth_id = v_user_id
    AND COALESCE(prison_escape_attempted, false) = false
  RETURNING prison_until INTO v_locked_until;

  IF NOT FOUND THEN
    RAISE LOG 'attempt_prison_escape atomic guard blocked uid=%', v_user_id;
    RETURN jsonb_build_object('success', false, 'error', 'Bu hapis surecinde kacma hakkin tukendi.');
  END IF;

  v_roll := random();
  RAISE LOG 'attempt_prison_escape roll uid=% roll=% chance=% bonus=%', v_user_id, v_roll, v_total_chance, v_escape_bonus;

  IF v_roll <= v_total_chance THEN
    UPDATE public.users
    SET prison_until = NULL,
        prison_reason = NULL,
        prison_escape_attempted = false
    WHERE auth_id = v_user_id;

    RETURN jsonb_build_object('success', true, 'escaped', true, 'message', 'Hapishaneden basarili bir sekilde kactin!');
  END IF;

  -- Random penalty between 15 and 60 minutes
  v_penalty_minutes := floor(random() * 46 + 15)::int;

  UPDATE public.users
  SET prison_until = COALESCE(v_locked_until, v_user.prison_until, now()) + (v_penalty_minutes || ' minutes')::interval
  WHERE auth_id = v_user_id;

  RETURN jsonb_build_object('success', true, 'escaped', false, 'message', 'Kacma plani basarisiz oldu! Bu hapis surecinde tekrar kacamazsin ve cezana ' || v_penalty_minutes || ' dakika eklendi.');
EXCEPTION WHEN OTHERS THEN
  RAISE LOG 'attempt_prison_escape exception uid=% err=%', v_user_id, SQLERRM;
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;


ALTER FUNCTION "public"."attempt_prison_escape"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ban_chat_user"("p_target_user_id" "uuid", "p_channel" "text", "p_duration_minutes" integer, "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor public.users%ROWTYPE;
  v_target RECORD;
  v_scope TEXT;
  v_guild_id UUID;
  v_ban_id UUID;
BEGIN
  v_actor := public.get_current_chat_user();

  IF p_target_user_id IS NULL OR p_target_user_id = v_actor.id THEN
    RETURN jsonb_build_object('success', false, 'error', 'Gecersiz hedef');
  END IF;

  IF p_channel NOT IN ('global', 'guild', 'dm', 'trade') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Gecersiz kanal');
  END IF;

  IF p_duration_minutes IS NULL OR p_duration_minutes < 1 OR p_duration_minutes > 10080 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Ban suresi 1 ile 10080 dakika arasinda olmali');
  END IF;

  SELECT id, guild_id INTO v_target FROM public.users WHERE id = p_target_user_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Hedef oyuncu bulunamadi');
  END IF;

  v_scope := CASE WHEN p_channel = 'guild' THEN 'guild' ELSE 'channel' END;
  v_guild_id := CASE WHEN p_channel = 'guild' THEN v_actor.guild_id ELSE NULL END;

  IF p_channel = 'guild' AND (v_actor.guild_id IS NULL OR v_actor.guild_id <> v_target.guild_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Lonca moderasyonu sadece ayni loncadaki oyuncular icin kullanilabilir');
  END IF;

  IF NOT public.has_chat_permission(v_actor.id, 'ban', p_channel, v_guild_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Bu kanalda ban yetkiniz yok');
  END IF;

  INSERT INTO public.chat_bans (user_id, scope, channel, guild_id, reason, expires_at, created_by_user_id)
  VALUES (
    p_target_user_id,
    v_scope,
    CASE WHEN v_scope = 'channel' THEN p_channel ELSE 'guild' END,
    CASE WHEN v_scope = 'guild' THEN v_guild_id ELSE NULL END,
    left(public.normalize_chat_content(p_reason), 200),
    now() + make_interval(mins => p_duration_minutes),
    v_actor.id
  )
  RETURNING id INTO v_ban_id;

  PERFORM public.write_chat_audit(
    v_actor.id,
    'user_banned',
    p_target_user_id,
    NULL,
    jsonb_build_object('channel', p_channel, 'duration_minutes', p_duration_minutes, 'ban_id', v_ban_id)
  );

  RETURN jsonb_build_object('success', true, 'ban_id', v_ban_id);
END;
$$;


ALTER FUNCTION "public"."ban_chat_user"("p_target_user_id" "uuid", "p_channel" "text", "p_duration_minutes" integer, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bank_first_free_slot"("p_user_id" "uuid", "p_max_slots" integer DEFAULT 200) RETURNS integer
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT s.slot
  FROM generate_series(0, GREATEST(p_max_slots, 1) - 1) AS s(slot)
  WHERE NOT EXISTS (
    SELECT 1
    FROM public.bank_items bi
    WHERE bi.user_id = p_user_id
      AND bi.slot_position = s.slot
  )
  ORDER BY s.slot
  LIMIT 1;
$$;


ALTER FUNCTION "public"."bank_first_free_slot"("p_user_id" "uuid", "p_max_slots" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."block_chat_user"("p_blocked_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user public.users%ROWTYPE;
BEGIN
  v_user := public.get_current_chat_user();

  IF p_blocked_user_id IS NULL OR p_blocked_user_id = v_user.id THEN
    RETURN jsonb_build_object('success', false, 'error', 'Gecersiz kullanici');
  END IF;

  INSERT INTO public.chat_blocks (blocker_user_id, blocked_user_id)
  VALUES (v_user.id, p_blocked_user_id)
  ON CONFLICT (blocker_user_id, blocked_user_id) DO NOTHING;

  PERFORM public.write_chat_audit(v_user.id, 'user_blocked', p_blocked_user_id, NULL, '{}'::jsonb);

  RETURN jsonb_build_object('success', true);
END;
$$;


