CREATE OR REPLACE FUNCTION "public"."bp_check_level_up"("p_player_id" "uuid", "p_season_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_current_bpp integer;
  v_calculated_level integer;
BEGIN
  SELECT current_bpp FROM public.bp_player_status
  WHERE player_id = p_player_id AND season_id = p_season_id
  INTO v_current_bpp;

  IF v_current_bpp IS NULL THEN RETURN; END IF;

  v_calculated_level := LEAST(v_current_bpp / 1000, 20);

  UPDATE public.bp_player_status
  SET current_level = v_calculated_level,
      updated_at = now()
  WHERE player_id = p_player_id AND season_id = p_season_id;
END;
$$;


ALTER FUNCTION "public"."bp_check_level_up"("p_player_id" "uuid", "p_season_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bp_claim_quest_reward"("p_quest_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_player_id uuid := auth.uid();
  v_active_season_id uuid;
  v_quest record;
  v_template record;
BEGIN
  IF v_player_id IS NULL THEN
    RETURN json_build_object('success', false, 'error', 'Oturum bulunamadı.');
  END IF;

  SELECT id FROM public.bp_seasons WHERE is_active = true INTO v_active_season_id;
  IF v_active_season_id IS NULL THEN
    RETURN json_build_object('success', false, 'error', 'Aktif sezon bulunamadı.');
  END IF;

  SELECT q.*, t.bpp_reward, t.description
  INTO v_quest
  FROM public.bp_player_quests q
  JOIN public.bp_quest_templates t ON t.id = q.template_id
  WHERE q.id = p_quest_id
    AND q.player_id = v_player_id
    AND q.season_id = v_active_season_id;

  IF NOT FOUND THEN
    RETURN json_build_object('success', false, 'error', 'Görev bulunamadı.');
  END IF;

  IF NOT v_quest.is_completed THEN
    RETURN json_build_object('success', false, 'error', 'Görev henüz tamamlanmadı.');
  END IF;

  IF v_quest.reward_claimed THEN
    RETURN json_build_object('success', false, 'error', 'Ödül zaten alındı.');
  END IF;

  UPDATE public.bp_player_status
  SET current_bpp = current_bpp + v_quest.bpp_reward,
      updated_at = now()
  WHERE player_id = v_player_id AND season_id = v_active_season_id;

  UPDATE public.bp_player_quests
  SET reward_claimed = true,
      updated_at = now()
  WHERE id = p_quest_id;

  PERFORM public.bp_check_level_up(v_player_id, v_active_season_id);

  RETURN json_build_object(
    'success', true,
    'bpp_reward', v_quest.bpp_reward,
    'message', 'Sezon görev ödülü alındı.'
  );
END;
$$;


ALTER FUNCTION "public"."bp_claim_quest_reward"("p_quest_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bp_claim_reward"("p_level" integer, "p_is_vip" boolean) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_player_id uuid := auth.uid();
  v_active_season_id uuid;
  v_season_number integer := 1;
  v_status record;
  v_reward record;
  v_item_id text;
  v_qty integer;
  v_added boolean;
BEGIN
  SELECT id, season_number INTO v_active_season_id, v_season_number
  FROM public.bp_seasons WHERE is_active = true;
  IF v_active_season_id IS NULL THEN
    RETURN json_build_object('success', false, 'error', 'Aktif sezon bulunamadı.');
  END IF;

  PERFORM public.bp_ensure_player_initialized();

  SELECT * FROM public.bp_player_status
  WHERE player_id = v_player_id AND season_id = v_active_season_id
  INTO v_status;

  IF v_status IS NULL THEN
    RETURN json_build_object('success', false, 'error', 'Sezon katılımı bulunamadı.');
  END IF;

  IF p_level > v_status.current_level THEN
    RETURN json_build_object('success', false, 'error', 'Bu seviyeye henüz ulaşmadınız.');
  END IF;

  IF p_is_vip THEN
    IF NOT v_status.has_vip THEN
      RETURN json_build_object('success', false, 'error', 'VIP Pass sahibi değilsiniz.');
    END IF;
    IF p_level = ANY(v_status.claimed_vip) THEN
      RETURN json_build_object('success', false, 'error', 'Bu ödül zaten alındı.');
    END IF;
  ELSE
    IF p_level = ANY(v_status.claimed_normal) THEN
      RETURN json_build_object('success', false, 'error', 'Bu ödül zaten alındı.');
    END IF;
  END IF;

  SELECT * FROM public.bp_level_rewards WHERE level = p_level INTO v_reward;
  IF v_reward IS NULL THEN
    RETURN json_build_object('success', false, 'error', 'Ödül tanımı bulunamadı.');
  END IF;

  IF p_is_vip THEN
    IF v_reward.vip_reward_gold > 0 THEN
      UPDATE public.users SET gold = gold + v_reward.vip_reward_gold WHERE auth_id = v_player_id;
    END IF;
    v_item_id := v_reward.vip_reward_item_id;
    v_qty := COALESCE(v_reward.vip_reward_quantity, 1);
    IF v_item_id IS NOT NULL THEN
      v_added := public.dungeon_add_item(v_player_id, v_item_id, v_qty);
      IF NOT v_added THEN
        RETURN json_build_object('success', false, 'error', 'Envanter dolu — ödül alınamadı.');
      END IF;
    END IF;
    UPDATE public.bp_player_status
    SET claimed_vip = array_append(claimed_vip, p_level), updated_at = now()
    WHERE player_id = v_player_id AND season_id = v_active_season_id;
  ELSE
    IF v_reward.normal_reward_gold > 0 THEN
      UPDATE public.users SET gold = gold + v_reward.normal_reward_gold WHERE auth_id = v_player_id;
    END IF;
    IF p_level = 20 THEN
      v_item_id := public.ensure_season_badge_item(v_season_number);
    ELSE
      v_item_id := v_reward.normal_reward_item_id;
    END IF;
    v_qty := COALESCE(v_reward.normal_reward_quantity, 1);
    IF v_item_id IS NOT NULL THEN
      v_added := public.dungeon_add_item(v_player_id, v_item_id, v_qty);
      IF NOT v_added THEN
        RETURN json_build_object('success', false, 'error', 'Envanter dolu — ödül alınamadı.');
      END IF;
    END IF;
    UPDATE public.bp_player_status
    SET claimed_normal = array_append(claimed_normal, p_level), updated_at = now()
    WHERE player_id = v_player_id AND season_id = v_active_season_id;
  END IF;

  RETURN json_build_object(
    'success', true,
    'message', 'Ödül başarıyla alındı.',
    'item_id', v_item_id
  );
END;
$$;


ALTER FUNCTION "public"."bp_claim_reward"("p_level" integer, "p_is_vip" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bp_ensure_player_initialized"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_player_id uuid := auth.uid();
  v_active_season_id uuid;
  v_existing_quests integer;
BEGIN
  IF v_player_id IS NULL THEN RETURN; END IF;

  SELECT id FROM public.bp_seasons WHERE is_active = true INTO v_active_season_id;
  IF v_active_season_id IS NULL THEN RETURN; END IF;

  INSERT INTO public.bp_player_status (
    player_id, season_id, current_bpp, current_level,
    daily_grind_bpp_pool, daily_pvp_bpp_pool, has_vip,
    claimed_normal, claimed_vip
  )
  VALUES (v_player_id, v_active_season_id, 0, 0, 0, 0, false, '{}', '{}')
  ON CONFLICT (player_id, season_id) DO NOTHING;

  SELECT COUNT(*) INTO v_existing_quests
  FROM public.bp_player_quests
  WHERE player_id = v_player_id AND season_id = v_active_season_id;

  IF v_existing_quests = 0 THEN
    INSERT INTO public.bp_player_quests (player_id, season_id, template_id)
    SELECT v_player_id, v_active_season_id, t.id
    FROM (
      SELECT id FROM public.bp_quest_templates
      WHERE quest_type = 'daily'
      ORDER BY random() LIMIT 3
    ) t
    ON CONFLICT (player_id, season_id, template_id) DO NOTHING;

    INSERT INTO public.bp_player_quests (player_id, season_id, template_id)
    SELECT v_player_id, v_active_season_id, id
    FROM public.bp_quest_templates
    WHERE quest_type = 'weekly'
    ON CONFLICT (player_id, season_id, template_id) DO NOTHING;
  END IF;
END;
$$;


ALTER FUNCTION "public"."bp_ensure_player_initialized"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bp_trigger_crafting"("p_player_id" "uuid", "p_rarity" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_active_season_id uuid;
  v_bpp_reward integer;
BEGIN
  SELECT id FROM public.bp_seasons WHERE is_active = true INTO v_active_season_id;
  IF v_active_season_id IS NULL THEN RETURN; END IF;

  v_bpp_reward := CASE 
    WHEN p_rarity = 'common' THEN 20
    WHEN p_rarity = 'uncommon' THEN 50
    WHEN p_rarity = 'rare' THEN 100
    WHEN p_rarity = 'epic' THEN 250
    WHEN p_rarity = 'legendary' THEN 500
    ELSE 20 END;

  UPDATE public.bp_player_status
  SET 
    current_bpp = current_bpp + v_bpp_reward,
    updated_at = now()
  WHERE player_id = p_player_id AND season_id = v_active_season_id;

  -- Crafting görev ilerlemesini güncelle
  UPDATE public.bp_player_quests q
  SET current_progress = current_progress + 1, updated_at = now()
  FROM public.bp_quest_templates t
  WHERE q.template_id = t.id 
    AND q.player_id = p_player_id 
    AND q.season_id = v_active_season_id
    AND t.target_system = 'craft' 
    AND q.is_completed = false;
    
  -- Görev tamamlanma kontrolü
  WITH completed_quests AS (
    UPDATE public.bp_player_quests q
    SET is_completed = true
    FROM public.bp_quest_templates t
    WHERE q.template_id = t.id 
      AND q.current_progress >= t.target_count 
      AND q.is_completed = false
      AND q.player_id = p_player_id
      AND q.season_id = v_active_season_id
    RETURNING t.bpp_reward
  )
  UPDATE public.bp_player_status
  SET current_bpp = current_bpp + (SELECT COALESCE(SUM(bpp_reward), 0) FROM completed_quests),
      updated_at = now()
  WHERE player_id = p_player_id AND season_id = v_active_season_id;

  PERFORM public.bp_check_level_up(p_player_id, v_active_season_id);
END;
$$;


ALTER FUNCTION "public"."bp_trigger_crafting"("p_player_id" "uuid", "p_rarity" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bp_trigger_dungeon_clear"("p_player_id" "uuid", "p_zone_tier" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_active_season_id uuid;
  v_bpp_reward integer;
BEGIN
  SELECT id FROM public.bp_seasons WHERE is_active = true INTO v_active_season_id;
  IF v_active_season_id IS NULL THEN RETURN; END IF;

  -- Points based on tier (5, 10, 15, 20)
  v_bpp_reward := LEAST(p_zone_tier * 5, 20);

  -- Handle daily reset and point addition in one robust update
  UPDATE public.bp_player_status
  SET 
    daily_grind_bpp_pool = CASE WHEN updated_at::date < now()::date THEN 0 ELSE daily_grind_bpp_pool END,
    daily_pvp_bpp_pool = CASE WHEN updated_at::date < now()::date THEN 0 ELSE daily_pvp_bpp_pool END
  WHERE player_id = p_player_id AND season_id = v_active_season_id;

  -- Attempt to add reward if under 300 limit
  UPDATE public.bp_player_status
  SET 
    current_bpp = current_bpp + LEAST(v_bpp_reward, GREATEST(300 - daily_grind_bpp_pool, 0)),
    daily_grind_bpp_pool = daily_grind_bpp_pool + LEAST(v_bpp_reward, GREATEST(300 - daily_grind_bpp_pool, 0)),
    updated_at = now()
  WHERE player_id = p_player_id AND season_id = v_active_season_id
    AND daily_grind_bpp_pool < 300;

  -- Always trigger quest progress
  PERFORM public.bp_trigger_quest_progress(p_player_id, 'dungeon', 1);
END;
$$;


ALTER FUNCTION "public"."bp_trigger_dungeon_clear"("p_player_id" "uuid", "p_zone_tier" integer) OWNER TO "postgres";


