CREATE OR REPLACE FUNCTION "public"."bp_trigger_quest_progress"("p_player_id" "uuid", "p_target_system" "text", "p_progress_amount" integer DEFAULT 1) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_active_season_id uuid;
BEGIN
  SELECT id FROM public.bp_seasons WHERE is_active = true INTO v_active_season_id;
  IF v_active_season_id IS NULL THEN RETURN; END IF;

  UPDATE public.bp_player_quests q
  SET current_progress = LEAST(q.current_progress + p_progress_amount, t.target_count),
      updated_at = now()
  FROM public.bp_quest_templates t
  WHERE q.template_id = t.id
    AND q.player_id = p_player_id
    AND q.season_id = v_active_season_id
    AND t.target_system = p_target_system
    AND q.is_completed = false
    AND q.reward_claimed = false;

  UPDATE public.bp_player_quests q
  SET is_completed = true,
      updated_at = now()
  FROM public.bp_quest_templates t
  WHERE q.template_id = t.id
    AND q.current_progress >= t.target_count
    AND q.is_completed = false
    AND q.reward_claimed = false
    AND q.player_id = p_player_id
    AND q.season_id = v_active_season_id;
END;
$$;


ALTER FUNCTION "public"."bp_trigger_quest_progress"("p_player_id" "uuid", "p_target_system" "text", "p_progress_amount" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bribe_officials"("p_facility_type" "text", "p_amount_gems" integer DEFAULT 5) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_player record;
  v_facility record;
  v_gem_cost integer := GREATEST(COALESCE(p_amount_gems, 5), 5);
  v_reduction numeric;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT * INTO v_player
  FROM public.users u
  WHERE u.auth_id = v_user_id OR u.id = v_user_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Player not found');
  END IF;

  IF COALESCE(v_player.global_suspicion_level, 0) <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Suphe 0 iken rusvet verilemez');
  END IF;

  IF COALESCE(v_player.character_class, '') = 'shadow' THEN
    v_reduction := public._passive_bonus('shadow', 'bribe_cost_reduction', 0.25);
    v_gem_cost := GREATEST(1, CEIL(v_gem_cost * (1 - v_reduction))::integer);
  END IF;

  IF COALESCE(v_player.gems, 0) < v_gem_cost THEN
    RETURN jsonb_build_object('success', false, 'error', 'Gem yetersiz');
  END IF;

  SELECT * INTO v_facility
  FROM public.facilities
  WHERE user_id = v_user_id
    AND type = p_facility_type
    AND COALESCE(is_active, true) = true
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Tesis bulunamadi');
  END IF;

  UPDATE public.users
  SET gems = gems - v_gem_cost,
      global_suspicion_level = GREATEST(0, COALESCE(global_suspicion_level, 0) - 15),
      last_bribe_at = now(),
      updated_at = now()
  WHERE (auth_id = v_user_id OR id = v_user_id)
    AND gems >= v_gem_cost;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Gem yetersiz');
  END IF;

  UPDATE public.facilities
  SET suspicion_level = GREATEST(0, COALESCE(suspicion_level, 0) - 20),
      updated_at = now()
  WHERE id = v_facility.id;

  PERFORM public._recompute_global_suspicion(v_user_id);

  RETURN jsonb_build_object('success', true, 'gems_spent', v_gem_cost);
END;
$$;


