CREATE OR REPLACE FUNCTION "public"."buy_from_mekan"("p_buyer_id" "uuid", "p_mekan_id" "uuid", "p_item_id" "text", "p_quantity" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_stock RECORD; v_mekan RECORD; v_gross BIGINT; v_buyer_pays BIGINT; v_owner_profit BIGINT;
  v_buyer_gold BIGINT; v_add_res JSONB; v_happy BOOLEAN := false; v_profit_bonus NUMERIC;
  v_is_contraband BOOLEAN; v_raid BOOLEAN := false; v_raid_chance NUMERIC; v_penalty BIGINT := 0; v_stock_value BIGINT;
BEGIN
  IF p_buyer_id != auth.uid() THEN RETURN jsonb_build_object('success', false, 'error', 'Yetkisiz islem'); END IF;
  IF NOT public.mekan_is_stock_eligible(p_item_id) THEN RETURN jsonb_build_object('success', false, 'error', 'Bu esya mekandan satilamaz'); END IF;
  IF p_quantity IS NULL OR p_quantity < 1 THEN RETURN jsonb_build_object('success', false, 'error', 'Gecersiz miktar'); END IF;
  SELECT * INTO v_mekan FROM public.mekans WHERE id = p_mekan_id AND is_open = true FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'Mekan kapali veya bulunamadi'); END IF;
  IF v_mekan.closed_until IS NOT NULL AND v_mekan.closed_until > now() THEN
    RETURN jsonb_build_object('success', false, 'error', 'Mekan polis baskini nedeniyle kapali'); END IF;
  IF p_buyer_id = v_mekan.owner_id THEN RETURN jsonb_build_object('success', false, 'error', 'Kendi mekaninizdan satin alamazsiniz'); END IF;
  SELECT * INTO v_stock FROM public.mekan_stock WHERE mekan_id = p_mekan_id AND item_id = p_item_id AND quantity >= p_quantity FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'Stok yetersiz'); END IF;
  v_gross := v_stock.sell_price * p_quantity;
  v_happy := v_mekan.happy_hour_until IS NOT NULL AND v_mekan.happy_hour_until > now();
  IF v_happy THEN v_buyer_pays := floor(v_gross * 0.80)::BIGINT; ELSE v_buyer_pays := v_gross; END IF;
  v_profit_bonus := public.mekan_profit_bonus_pct(v_mekan.level);
  v_owner_profit := floor(v_buyer_pays * (1 + v_profit_bonus))::BIGINT;
  SELECT gold INTO v_buyer_gold FROM public.users WHERE auth_id = p_buyer_id FOR UPDATE;
  IF v_buyer_gold < v_buyer_pays THEN RETURN jsonb_build_object('success', false, 'error', 'Gold yetersiz'); END IF;
  v_add_res := public.add_inventory_item_v2(jsonb_build_object('item_id', p_item_id, 'quantity', p_quantity, 'allow_stack', true), NULL);
  IF v_add_res IS NULL OR (v_add_res->>'success')::boolean IS NOT TRUE THEN
    RETURN jsonb_build_object('success', false, 'error', COALESCE(v_add_res->>'error', 'Envanter dolu')); END IF;
  UPDATE public.users SET gold = gold - v_buyer_pays WHERE auth_id = p_buyer_id AND gold >= v_buyer_pays;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'Islem sirasinda altin yetersiz kaldi'); END IF;
  UPDATE public.users SET gold = gold + v_owner_profit WHERE auth_id = v_mekan.owner_id;
  UPDATE public.mekan_stock SET quantity = quantity - p_quantity WHERE mekan_id = p_mekan_id AND item_id = p_item_id;
  INSERT INTO public.mekan_sales (mekan_id, buyer_id, item_id, quantity, price_per_unit, total_price, owner_profit)
  VALUES (p_mekan_id, p_buyer_id, p_item_id, p_quantity,
    CASE WHEN p_quantity > 0 THEN (v_buyer_pays / p_quantity) ELSE v_buyer_pays END, v_buyer_pays, v_owner_profit);
  UPDATE public.mekans SET fame = fame + GREATEST(1, floor(v_buyer_pays * 0.001)::INT) + 1 + (level / 2),
    total_revenue = total_revenue + v_owner_profit, total_sales = total_sales + p_quantity WHERE id = p_mekan_id;
  v_is_contraband := public.mekan_is_contraband(p_item_id);
  IF v_is_contraband AND v_mekan.mekan_type = 'yeralti' THEN
    UPDATE public.mekans SET suspicion = LEAST(100, suspicion + 5 * p_quantity) WHERE id = p_mekan_id RETURNING suspicion INTO v_mekan.suspicion;
    v_raid_chance := 0.02 + (v_mekan.suspicion::numeric / 100.0) * 0.30;
    IF random() <= v_raid_chance THEN
      v_raid := true;
      SELECT COALESCE(SUM(quantity * sell_price), 0) INTO v_stock_value FROM public.mekan_stock WHERE mekan_id = p_mekan_id;
      v_penalty := floor(v_stock_value * 0.50)::BIGINT;
      UPDATE public.users SET gold = GREATEST(0, gold - v_penalty) WHERE auth_id = v_mekan.owner_id;
      UPDATE public.mekans SET is_open = false, closed_until = now() + INTERVAL '48 hours', fame = GREATEST(0, fame - 500), suspicion = 0 WHERE id = p_mekan_id;
      UPDATE public.users SET prison_until = now() + INTERVAL '24 hours' WHERE auth_id = v_mekan.owner_id;
    END IF;
  END IF;
  RETURN jsonb_build_object('success', true, 'total_price', v_buyer_pays, 'happy_hour', v_happy, 'police_raid', v_raid, 'penalty', v_penalty);
END;
$$;


ALTER FUNCTION "public"."buy_from_mekan"("p_buyer_id" "uuid", "p_mekan_id" "uuid", "p_item_id" "text", "p_quantity" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."buy_shop_item"("p_item_id" "text", "p_currency" "text", "p_price" bigint, "p_quantity" integer DEFAULT 1) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_user_id UUID;
    v_item RECORD;
    v_unit_price BIGINT;
    v_currency TEXT;
    v_total BIGINT;
    v_current_gold BIGINT;
    v_current_gems NUMERIC;
    v_old_gold BIGINT;
    v_old_gems NUMERIC;
    v_inventory_slot INT;
    v_existing_row RECORD;
    v_new_quantity INT;
    v_capacity INT := 20;
    v_occupied INT;
BEGIN
    v_user_id := auth.uid();
    IF v_user_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
    END IF;

    IF p_quantity < 1 OR p_quantity > 999 THEN
        RETURN jsonb_build_object('success', false, 'error', 'Invalid quantity');
    END IF;

    SELECT
        id,
        name,
        base_price,
        is_stackable,
        max_stack,
        COALESCE(shop_available, false) AS shop_available,
        COALESCE(NULLIF(shop_currency, ''), 'gold') AS shop_currency
    INTO v_item
    FROM public.items
    WHERE id = p_item_id;

    IF v_item.id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Item not found');
    END IF;

    IF NOT v_item.shop_available THEN
        RETURN jsonb_build_object('success', false, 'error', 'Item not in shop');
    END IF;

    v_unit_price := GREATEST(COALESCE(v_item.base_price, 0), 0);
    v_currency := v_item.shop_currency;

    IF p_currency IS NOT NULL
       AND lower(trim(p_currency)) <> ''
       AND lower(trim(p_currency)) <> lower(v_currency) THEN
        RETURN jsonb_build_object('success', false, 'error', 'Currency mismatch');
    END IF;

    v_total := v_unit_price * p_quantity;

    SELECT gold, gems INTO v_current_gold, v_current_gems
    FROM public.users
    WHERE auth_id = v_user_id OR id = v_user_id
    LIMIT 1
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'User not found');
    END IF;

    v_old_gold := v_current_gold;
    v_old_gems := v_current_gems;

    IF v_currency = 'gold' THEN
        IF v_current_gold < v_total THEN
            RETURN jsonb_build_object('success', false, 'error', 'Insufficient gold');
        END IF;
        UPDATE public.users
        SET gold = gold - v_total
        WHERE auth_id = v_user_id OR id = v_user_id;
    ELSIF v_currency = 'gems' THEN
        IF v_current_gems < v_total THEN
            RETURN jsonb_build_object('success', false, 'error', 'Insufficient gems');
        END IF;
        UPDATE public.users
        SET gems = gems - v_total
        WHERE auth_id = v_user_id OR id = v_user_id;
    ELSE
        RETURN jsonb_build_object('success', false, 'error', 'Invalid currency');
    END IF;

    BEGIN
        IF v_item.is_stackable THEN
            SELECT row_id, quantity INTO v_existing_row
            FROM public.inventory
            WHERE user_id = v_user_id AND item_id = p_item_id AND NOT is_equipped
            LIMIT 1;

            IF v_existing_row.row_id IS NOT NULL THEN
                v_new_quantity := LEAST(
                    v_existing_row.quantity + p_quantity,
                    COALESCE(v_item.max_stack, 999)
                );
                UPDATE public.inventory
                SET quantity = v_new_quantity,
                    updated_at = NOW()
                WHERE row_id = v_existing_row.row_id;
            ELSE
                SELECT COUNT(*) INTO v_occupied
                FROM public.inventory
                WHERE user_id = v_user_id AND NOT is_equipped;

                IF v_occupied >= v_capacity THEN
                    IF v_currency = 'gold' THEN
                        UPDATE public.users SET gold = v_old_gold WHERE auth_id = v_user_id OR id = v_user_id;
                    ELSE
                        UPDATE public.users SET gems = v_old_gems WHERE auth_id = v_user_id OR id = v_user_id;
                    END IF;
                    RETURN jsonb_build_object('success', false, 'error', 'Inventory full');
                END IF;

                SELECT s INTO v_inventory_slot
                FROM generate_series(0, v_capacity - 1) s
                WHERE s NOT IN (
                    SELECT slot_position FROM public.inventory
                    WHERE user_id = v_user_id AND slot_position IS NOT NULL
                )
                LIMIT 1;

                INSERT INTO public.inventory (
                    user_id, item_id, quantity, slot_position, is_equipped
                ) VALUES (
                    v_user_id, p_item_id, p_quantity, COALESCE(v_inventory_slot, 0), false
                );
            END IF;
        ELSE
            SELECT COUNT(*) INTO v_occupied
            FROM public.inventory
            WHERE user_id = v_user_id AND NOT is_equipped;

            IF v_occupied + p_quantity > v_capacity THEN
                IF v_currency = 'gold' THEN
                    UPDATE public.users SET gold = v_old_gold WHERE auth_id = v_user_id OR id = v_user_id;
                ELSE
                    UPDATE public.users SET gems = v_old_gems WHERE auth_id = v_user_id OR id = v_user_id;
                END IF;
                RETURN jsonb_build_object('success', false, 'error', 'Inventory full');
            END IF;

            FOR i IN 1..p_quantity LOOP
                SELECT s INTO v_inventory_slot
                FROM generate_series(0, v_capacity - 1) s
                WHERE s NOT IN (
                    SELECT slot_position FROM public.inventory
                    WHERE user_id = v_user_id AND slot_position IS NOT NULL
                )
                LIMIT 1;

                INSERT INTO public.inventory (
                    user_id, item_id, quantity, slot_position, is_equipped
                ) VALUES (
                    v_user_id, p_item_id, 1, COALESCE(v_inventory_slot, i - 1), false
                );
            END LOOP;
        END IF;

    EXCEPTION WHEN OTHERS THEN
        IF v_currency = 'gold' THEN
            UPDATE public.users SET gold = v_old_gold WHERE auth_id = v_user_id OR id = v_user_id;
        ELSE
            UPDATE public.users SET gems = v_old_gems WHERE auth_id = v_user_id OR id = v_user_id;
        END IF;
        RETURN jsonb_build_object('success', false, 'error', 'Failed to add item to inventory: ' || SQLERRM);
    END;

    RETURN jsonb_build_object(
        'success', true,
        'item_id', p_item_id,
        'quantity', p_quantity,
        'unit_price', v_unit_price,
        'total_cost', v_total,
        'currency', v_currency
    );
END;
$$;


ALTER FUNCTION "public"."buy_shop_item"("p_item_id" "text", "p_currency" "text", "p_price" bigint, "p_quantity" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."buy_vip_pass"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_player_id UUID;
  v_active_season_id UUID;
  v_status RECORD;
  v_gems INTEGER;
  v_vip_cost CONSTANT INTEGER := 500;
BEGIN
  v_player_id := auth.uid();
  IF v_player_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Oturum bulunamadı.');
  END IF;

  SELECT id FROM public.bp_seasons WHERE is_active = true INTO v_active_season_id;
  IF v_active_season_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Aktif sezon bulunamadı.');
  END IF;

  SELECT gems INTO v_gems FROM public.users WHERE auth_id = v_player_id FOR UPDATE;
  IF v_gems IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Kullanıcı profili bulunamadı.');
  END IF;

  SELECT * FROM public.bp_player_status WHERE player_id = v_player_id AND season_id = v_active_season_id INTO v_status FOR UPDATE;
  IF v_status IS NULL THEN
    INSERT INTO public.bp_player_status (player_id, season_id, current_bpp, current_level, daily_grind_bpp_pool, daily_pvp_bpp_pool, has_vip, claimed_normal, claimed_vip)
    VALUES (v_player_id, v_active_season_id, 0, 1, 0, 0, false, '{}', '{}')
    RETURNING * INTO v_status;
  END IF;

  IF v_status.has_vip THEN
    RETURN jsonb_build_object('success', false, 'error', 'Zaten VIP aktif.');
  END IF;

  IF v_gems < v_vip_cost THEN
    RETURN jsonb_build_object('success', false, 'error', 'Yetersiz elmas! VIP Pass için ' || v_vip_cost || ' 💎 gerekiyor, ' || v_gems || ' 💎 var.', 'required', v_vip_cost, 'current', v_gems);
  END IF;

  UPDATE public.users SET gems = gems - v_vip_cost WHERE auth_id = v_player_id;
  UPDATE public.bp_player_status SET has_vip = true, updated_at = now() WHERE player_id = v_player_id AND season_id = v_active_season_id;

  RETURN jsonb_build_object('success', true, 'message', 'VIP Pass başarıyla aktif edildi!', 'new_gem_balance', v_gems - v_vip_cost);
END;
$$;


ALTER FUNCTION "public"."buy_vip_pass"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_global_suspicion"("p_user_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_active_count INT;
    v_level_sum INT;
    v_immunity TIMESTAMPTZ;
    v_risk FLOAT;
BEGIN
    -- Check Immunity
    SELECT suspicion_immunity_until INTO v_immunity FROM public.users WHERE id = p_user_id;
    
    IF v_immunity > NOW() THEN
        RETURN 0;
    END IF;

    -- Calculate Active Facilities (Production started less than 1 hour ago)
    SELECT 
        COUNT(*),
        COALESCE(SUM(level), 0)
    INTO 
        v_active_count,
        v_level_sum
    FROM public.facilities
    WHERE user_id = p_user_id
        AND production_started_at IS NOT NULL
        AND production_started_at > NOW() - INTERVAL '1 hour';
        
    -- Formula: (Active Count * 5) + (Level Sum * 0.5)
    -- Example: 4 Active (Lvl 1) -> 20 + 2 = 22%
    -- Example: 10 Active (Lvl 5) -> 50 + 25 = 75%
    
    v_risk := (v_active_count * 5.0) + (v_level_sum * 0.5);
    
    -- Clamp and Return
    IF v_risk > 100 THEN v_risk := 100; END IF;
    IF v_risk < 0 THEN v_risk := 0; END IF;
    
    RETURN CAST(v_risk AS INT);
END;
$$;


ALTER FUNCTION "public"."calculate_global_suspicion"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_item_power"("p_item_id" "text", "p_enhancement_level" integer) RETURNS numeric
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_item RECORD;
  v_base_stat_sum NUMERIC;
  v_enhancement_mult NUMERIC;
  v_final_power NUMERIC;
BEGIN
  -- Get item stats
  SELECT * INTO v_item FROM public.items WHERE id = p_item_id;
  IF NOT FOUND THEN
    RETURN 0;
  END IF;

  -- Sum of base stats (attack + defense + hp/10 + luck * 2) as defined in PLAN_01
  v_base_stat_sum := COALESCE(v_item.attack, 0) 
                   + COALESCE(v_item.defense, 0) 
                   + (COALESCE(v_item.health, 0) / 10.0) 
                   + (COALESCE(v_item.luck, 0) * 2.0);

  -- Enhancement Multiplier
  v_enhancement_mult := 1.0 + (COALESCE(p_enhancement_level, 0) * 0.15);

  -- Rarity multiplier should be already included in the base stats per PLAN_01, 
  -- so we only apply the enhancement multiplier.
  v_final_power := v_base_stat_sum * v_enhancement_mult;

  RETURN v_final_power;
END;
$$;


ALTER FUNCTION "public"."calculate_item_power"("p_item_id" "text", "p_enhancement_level" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_offline_production"("p_facility_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_facility public.facilities%ROWTYPE;
  v_queue_count INT;
  v_offline_hours INT;
  v_production_per_hour INT;
  v_total_production INT;
BEGIN
  -- Facility verisini al
  SELECT * INTO v_facility 
  FROM public.facilities 
  WHERE id = p_facility_id;
  
  IF NOT FOUND THEN
    RETURN 0;
  END IF;
  
  -- Queue'deki aktif işleri say
  SELECT COUNT(*) INTO v_queue_count
  FROM public.facility_queue
  WHERE facility_id = p_facility_id 
    AND (status = 'in_progress' OR status IS NULL);
  
  -- Queue dolu mu kontrol et
  IF v_queue_count >= 10 THEN
    RETURN 0;
  END IF;
  
  -- Offline saat hesapla (max 24 saat)
  v_offline_hours := LEAST(24, 
    EXTRACT(EPOCH FROM (NOW() - v_facility.last_production_collected_at)) / 3600
  );
  
  -- Production per hour: level * 50 + workers * 10
  v_production_per_hour := (v_facility.level * 50) + (v_facility.workers * 10);
  
  -- Toplam offline production
  v_total_production := v_production_per_hour * v_offline_hours;
  
  RETURN LEAST(v_total_production, v_facility.offline_production_cap);
END;
$$;


ALTER FUNCTION "public"."calculate_offline_production"("p_facility_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_user_total_power"("p_user_id" "uuid") RETURNS numeric
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user RECORD;
  v_equipment_power NUMERIC := 0;
  v_total_power NUMERIC := 0;
BEGIN
  -- 1. Calculate Equipment Power (Sum of equipped items)
  SELECT COALESCE(SUM(public.calculate_item_power(i.item_id, COALESCE(i.enhancement_level, 0))), 0)
  INTO v_equipment_power
  FROM public.inventory i
  WHERE i.user_id = p_user_id AND i.is_equipped = true;

  -- 2. Get User Stats
  SELECT level, reputation, attack, defense, health, luck INTO v_user
  FROM public.users
  WHERE auth_id = p_user_id;

  IF NOT FOUND THEN
    RETURN 0;
  END IF;

  -- 3. Calculate Total Power (matching Flutter calculation)
  -- totalPower = equipmentPower + (level × 500) + (reputation × 0.1) + (luck × 50)
  v_total_power := v_equipment_power 
                   + (COALESCE(v_user.level, 1) * 500) 
                   + (COALESCE(v_user.reputation, 0) * 0.1)
                   + (COALESCE(v_user.luck, 0) * 50);

  RETURN v_total_power;
END;
$$;


ALTER FUNCTION "public"."calculate_user_total_power"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_box_opening"("p_opening_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
  v_open RECORD;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT * INTO v_open
  FROM public.box_openings
  WHERE id = p_opening_id AND user_id = v_user_id
  FOR UPDATE;

  IF NOT FOUND OR v_open.status != 'opening' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Açılma kaydı bulunamadı');
  END IF;

  DELETE FROM public.inventory
  WHERE row_id = v_open.inventory_row_id AND user_id = v_user_id;

  UPDATE public.box_openings SET status = 'deleted' WHERE id = p_opening_id;

  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."cancel_box_opening"("p_opening_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_craft_item"("p_queue_item_id" "uuid") RETURNS TABLE("success" boolean, "message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id uuid;
  v_queue craft_queue%ROWTYPE;
BEGIN
  -- Verify user is authenticated
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN QUERY SELECT false, 'Not authenticated'::text;
    RETURN;
  END IF;

  -- Fetch queue item - ensure it belongs to authenticated user
  SELECT * FROM public.craft_queue WHERE id = p_queue_item_id AND user_id = v_user_id INTO v_queue;
  IF v_queue.id IS NULL THEN
    RETURN QUERY SELECT false, 'Queue item not found or unauthorized'::text;
    RETURN;
  END IF;

  -- Check if already completed or claimed
  IF v_queue.is_completed OR v_queue.claimed THEN
    RETURN QUERY SELECT false, 'Cannot cancel completed or claimed item'::text;
    RETURN;
  END IF;

  -- Delete from queue (NO REFUND - as per requirement)
  DELETE FROM public.craft_queue WHERE id = p_queue_item_id;

  RETURN QUERY SELECT true, 'Craft cancelled (items NOT refunded)'::text;
END;
$$;


ALTER FUNCTION "public"."cancel_craft_item"("p_queue_item_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_sell_order"("p_order_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_order RECORD;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Giris yapmalisiniz';
  END IF;

  SELECT * INTO v_order
  FROM public.market_orders
  WHERE order_id = p_order_id
    AND seller_id = v_user_id
    AND status = 'open'
    AND side = 'sell'
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Ilan bulunamadi veya iptal edilemez';
  END IF;

  IF NOT public.market_give_items(
    v_user_id, v_order.item_id, v_order.quantity, v_order.enhancement_level
  ) THEN
    RAISE EXCEPTION 'Envanter dolu, ilan geri cekilemedi';
  END IF;

  UPDATE public.market_orders
  SET status = 'cancelled', updated_at = now()
  WHERE order_id = p_order_id;

  RETURN jsonb_build_object('success', true, 'order_id', p_order_id);
END;
$$;


ALTER FUNCTION "public"."cancel_sell_order"("p_order_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_trade"("p_session_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_uid UUID; v_sess RECORD;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'Oturum bulunamadı.'); END IF;
  SELECT * INTO v_sess FROM public.trade_sessions WHERE id = p_session_id FOR UPDATE;
  IF v_sess IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'Ticaret oturumu bulunamadı.'); END IF;
  IF v_uid <> v_sess.initiator_id AND v_uid <> v_sess.partner_id THEN RETURN jsonb_build_object('success', false, 'error', 'Bu ticaretin katılımcısı değilsiniz.'); END IF;
  IF v_sess.status = 'active' THEN UPDATE public.trade_sessions SET status = 'cancelled', updated_at = now() WHERE id = p_session_id; END IF;
  RETURN jsonb_build_object('success', true);
END; $$;


ALTER FUNCTION "public"."cancel_trade"("p_session_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_and_release_from_prison"("p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_today TIMESTAMPTZ := NOW();
    v_prison_record RECORD;
    v_released_count INT := 0;
BEGIN
    FOR v_prison_record IN
        SELECT id, user_id FROM public.prison_records
        WHERE user_id = p_user_id
          AND released_at IS NOT NULL
          AND released_at <= v_today
          AND released_at > (SELECT COALESCE(MAX(released_at), '1900-01-01'::TIMESTAMPTZ) FROM public.prison_records 
                          WHERE user_id = p_user_id AND released_at < v_today)
    LOOP
        v_released_count := v_released_count + 1;
    END LOOP;
    
    IF v_released_count > 0 THEN
        UPDATE public.users
        SET in_prison = false,
            hospital_until = NULL
        WHERE id = p_user_id
          AND NOT EXISTS (
              SELECT 1 FROM public.prison_records
              WHERE user_id = p_user_id AND released_at IS NULL
          );
    END IF;
    
    RETURN jsonb_build_object(
        'success', true,
        'released', v_released_count > 0,
        'message', CASE WHEN v_released_count > 0 
            THEN 'Released from prison' 
            ELSE 'Still in prison' 
        END
    );
END;
$$;


ALTER FUNCTION "public"."check_and_release_from_prison"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_facility_upgrade_when_producing"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- If level is increasing
  IF NEW.level > OLD.level THEN
    -- And production is currently active or finished but not collected
    IF OLD.production_started_at IS NOT NULL THEN
      RAISE EXCEPTION 'Üretim devam ederken veya toplanmamış kaynak varken tesis yükseltilemez.';
    END IF;
  END IF;
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."check_facility_upgrade_when_producing"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_alchemist_detox"() RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_user_id uuid := auth.uid();
  v_player record;
  v_item_id uuid;
  v_last_claim timestamptz;
  v_now timestamptz := NOW();
BEGIN
  -- 1. Check player class
  EXECUTE 'SELECT * FROM public.users WHERE auth_id = $1' INTO v_player USING v_user_id;
  IF NOT FOUND THEN
    RETURN json_build_object('success', false, 'message', 'Player not found');
  END IF;

  IF (v_player).character_class IS DISTINCT FROM 'alchemist' THEN
    RETURN json_build_object('success', false, 'message', 'Only Alchemists can claim this.');
  END IF;

  -- 2. Check cooldown (24 hours) from custom fields or a new field.
  -- We will store the timestamp in the JSONB custom_fields column.
  v_last_claim := (v_player.custom_fields->>'last_alchemist_detox_claim')::timestamptz;
  
  IF v_last_claim IS NOT NULL AND v_now < (v_last_claim + INTERVAL '24 hours') THEN
    RETURN json_build_object('success', false, 'message', 'You can only claim this once per 24 hours. Try again later.');
  END IF;

  -- 3. Get the item_id for Minor Detox Potion
  -- Minor Detox is usually 'item_potion_detox_minor' or 'potion_antidote_minor'
  -- Let's check the items table. If we assume 'potion_antidote_minor' or 'potion_detox_minor'.
  EXECUTE 'SELECT id FROM public.items WHERE item_id = $1 OR item_id = $2 LIMIT 1' INTO v_item_id
    USING 'potion_antidote', 'potion_antidote_minor';
  IF NOT FOUND THEN
    RETURN json_build_object('success', false, 'message', 'Detox potion item not found in database.');
  END IF;

  -- 4. Add item to inventory
  PERFORM add_item_to_inventory(v_user_id, v_item_id, 1);

  -- 5. Update last claim time (use dynamic SQL to avoid compile-time dependency)
  EXECUTE 'UPDATE public.users SET custom_fields = jsonb_set(COALESCE(custom_fields, ''{}''::jsonb), ''{last_alchemist_detox_claim}'', to_jsonb($1)) WHERE auth_id = $2'
    USING v_now, v_user_id;

  RETURN json_build_object('success', true, 'message', 'Minor Detox claimed successfully!');
END;
$_$;


ALTER FUNCTION "public"."claim_alchemist_detox"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_box_reward"("p_opening_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
  v_open RECORD;
  v_inv RECORD;
  v_box RECORD;
  v_drop RECORD;
  v_free_slots INT;
  v_reward_qty INT := 1;
  v_spent_currency TEXT;
  v_spent_amount INT;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT * INTO v_open
  FROM public.box_openings
  WHERE id = p_opening_id AND user_id = v_user_id
  FOR UPDATE;

  IF NOT FOUND OR v_open.status != 'opening' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Açılma kaydı bulunamadı');
  END IF;

  IF now() < v_open.opens_at THEN
    RETURN jsonb_build_object('success', false, 'error', 'Kutu henüz açılmadı');
  END IF;

  SELECT * INTO v_inv
  FROM public.inventory
  WHERE row_id = v_open.inventory_row_id AND user_id = v_user_id AND quantity > 0
  FOR UPDATE;

  IF NOT FOUND THEN
    UPDATE public.box_openings SET status = 'deleted' WHERE id = p_opening_id;
    RETURN jsonb_build_object('success', false, 'error', 'Kutu envanterde yok — ödül iptal');
  END IF;

  SELECT COUNT(*) INTO v_free_slots
  FROM generate_series(0, 19) s(slot)
  WHERE NOT EXISTS (
    SELECT 1
    FROM public.inventory inv
    WHERE inv.user_id = v_user_id
      AND inv.is_equipped = false
      AND inv.slot_position = s.slot
      AND inv.row_id != v_open.inventory_row_id
  );

  IF v_free_slots < 1 THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'inventory_full',
      'message', 'Envanterin dolu! Ödülü almak için yer aç.'
    );
  END IF;

  SELECT * INTO v_box FROM public.loot_box_configs WHERE id = v_open.box_id;

  SELECT
    e.item_id, e.weight, e.min_quantity, e.max_quantity,
    i.name AS item_name, i.icon,
    COALESCE(i.is_stackable, false) AS is_stackable
  INTO v_drop
  FROM public.loot_box_drop_entries e
  JOIN public.items i ON i.id = e.item_id
  WHERE e.box_id = v_open.box_id AND e.is_active = TRUE
  ORDER BY -LN(GREATEST(random(), 1e-9)) / GREATEST(e.weight, 1e-9)
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Bu kutu için ödül tanımı yok');
  END IF;

  IF NOT public._consume_inventory_row(v_open.inventory_row_id, v_user_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Kutu tüketilemedi');
  END IF;

  IF COALESCE(v_drop.is_stackable, false) THEN
    v_reward_qty := GREATEST(
      1,
      FLOOR(random() * (v_drop.max_quantity - v_drop.min_quantity + 1) + v_drop.min_quantity)::INT
    );
  END IF;

  IF NOT public.dungeon_add_item(v_user_id, v_drop.item_id, v_reward_qty) THEN
    INSERT INTO public.inventory (user_id, item_id, quantity, slot_position, is_equipped)
    VALUES (v_user_id, v_open.box_id, 1, v_inv.slot_position, false);

    IF NOT EXISTS (SELECT 1 FROM public.items WHERE id = v_drop.item_id) THEN
      RETURN jsonb_build_object(
        'success', false,
        'error', 'reward_item_missing',
        'message', 'Ödül eşyası tanımlı değil. Kutu iade edildi.'
      );
    END IF;

    RETURN jsonb_build_object(
      'success', false,
      'error', 'inventory_full',
      'message', 'Envanterin dolu! Ödülü almak için yer aç.'
    );
  END IF;

  IF v_open.payment = 'ad' THEN
    v_spent_currency := 'ad';
    v_spent_amount := 0;
  ELSE
    v_spent_currency := COALESCE(v_open.payment, 'gems');
    v_spent_amount := COALESCE(v_open.gems_spent, 0)::INT;
  END IF;

  UPDATE public.box_openings
  SET status = 'claimed', claimed_at = now()
  WHERE id = p_opening_id;

  INSERT INTO public.player_loot_box_logs (
    user_id, box_id, spent_currency, spent_amount,
    reward_type, reward_item_id, reward_amount, roll_weight, metadata
  )
  VALUES (
    v_user_id, v_open.box_id, v_spent_currency, v_spent_amount,
    'item', v_drop.item_id, v_reward_qty, v_drop.weight,
    jsonb_build_object(
      'source', 'box_opening',
      'opening_id', p_opening_id,
      'box_name', COALESCE(v_box.name, v_open.box_id),
      'item_name', v_drop.item_name,
      'payment', v_open.payment
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'box_id', v_open.box_id,
    'box_name', COALESCE(v_box.name, v_open.box_id),
    'reward', jsonb_build_object(
      'type', 'item',
      'item_id', v_drop.item_id,
      'name', v_drop.item_name,
      'icon', v_drop.icon,
      'quantity', v_reward_qty
    )
  );
END;
$$;


ALTER FUNCTION "public"."claim_box_reward"("p_opening_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_crafted_item"("p_queue_item_id" "uuid") RETURNS TABLE("success" boolean, "message" "text", "xp_awarded" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id uuid;
  v_queue craft_queue%ROWTYPE;
  v_recipe crafting_recipes%ROWTYPE;
  v_final_qty integer;
  v_add_res jsonb;
  v_is_stackable boolean;
  v_free_slots integer;
  v_success_rate double precision;
  v_roll double precision;
  v_xp integer;
BEGIN
  -- Verify user is authenticated
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN QUERY SELECT false, 'Not authenticated'::text, 0;
    RETURN;
  END IF;

  -- Fetch and lock queue item to avoid races
  SELECT * FROM public.craft_queue WHERE id = p_queue_item_id AND user_id = v_user_id FOR UPDATE INTO v_queue;
  IF v_queue.id IS NULL THEN
    RETURN QUERY SELECT false, 'Queue item not found or unauthorized'::text, 0;
    RETURN;
  END IF;

  -- Check if already claimed
  IF v_queue.claimed THEN
    RETURN QUERY SELECT false, 'Already claimed'::text, 0;
    RETURN;
  END IF;

  -- Fetch recipe to get output item
  SELECT * FROM public.crafting_recipes WHERE id = v_queue.recipe_id INTO v_recipe;

  -- Ensure the item is completed (either marked or time has passed)
  IF NOT v_queue.is_completed AND v_queue.completes_at > now() THEN
    RETURN QUERY SELECT false, 'Not ready to claim'::text, 0;
    RETURN;
  END IF;

  -- Validate output_item_id exists before attempting inventory add
  IF v_recipe.output_item_id IS NULL OR trim(v_recipe.output_item_id) = '' THEN
    RETURN QUERY SELECT false, 'Recipe output_item_id is missing'::text, 0;
    RETURN;
  END IF;

  -- Determine if item is stackable from catalog (decide at claim time)
  SELECT is_stackable INTO v_is_stackable FROM public.items WHERE id = v_recipe.output_item_id;
  IF v_is_stackable IS NULL THEN
    v_is_stackable := false;
  END IF;

  -- Compute final quantity to add (use batch_count)
  v_final_qty := COALESCE(v_queue.batch_count, 1);

  -- If the item hasn't been finalized yet but completion time passed, finalize it
  IF NOT v_queue.is_completed AND v_queue.completes_at <= now() THEN
    -- finalize_crafted_item will lock and set failed/is_completed deterministically
    PERFORM public.finalize_crafted_item(p_queue_item_id);
    -- re-load updated queue row
    SELECT * FROM public.craft_queue WHERE id = p_queue_item_id AND user_id = v_user_id INTO v_queue;
  END IF;

  -- If finalized as failed, return failure
  IF v_queue.failed THEN
    RETURN QUERY SELECT false, 'Üretim başarısız'::text, 0;
    RETURN;
  END IF;

  -- Calculate XP reward for successful production
  v_xp := COALESCE(v_recipe.xp_reward, 0) * v_final_qty;

  -- Add produced item to inventory via helper.
  -- If item is stackable, add once (may stack). If not, add one-by-one into separate slots.
  IF v_is_stackable THEN
    v_add_res := public.add_inventory_item_v2(
      jsonb_build_object('item_id', v_recipe.output_item_id, 'quantity', v_final_qty, 'allow_stack', true),
      NULL
    );

    -- Check if inventory add succeeded
    IF v_add_res IS NULL OR (v_add_res->>'success')::boolean IS NOT TRUE THEN
      RETURN QUERY SELECT false, COALESCE(v_add_res->>'error', 'Failed to add to inventory')::text, 0;
      RETURN;
    END IF;
  ELSE
    -- Non-stackable: insert v_final_qty times as separate items
    -- Check free slots first to avoid partial adds
    SELECT COUNT(*) INTO v_free_slots
    FROM generate_series(0, 19) AS s(slot)
    WHERE NOT EXISTS (
      SELECT 1 FROM public.inventory
      WHERE user_id = v_user_id AND slot_position = s.slot AND is_equipped = false
    );

    IF v_free_slots < GREATEST(1, v_final_qty) THEN
      RETURN QUERY SELECT false, 'Envanter dolu'::text, 0;
      RETURN;
    END IF;
    FOR i IN 1..GREATEST(1, v_final_qty) LOOP
      v_add_res := public.add_inventory_item_v2(
        jsonb_build_object('item_id', v_recipe.output_item_id, 'quantity', 1, 'allow_stack', false),
        NULL
      );
      IF v_add_res IS NULL OR (v_add_res->>'success')::boolean IS NOT TRUE THEN
        RETURN QUERY SELECT false, COALESCE(v_add_res->>'error', 'Failed to add non-stackable item to inventory')::text, 0;
        RETURN;
      END IF;
    END LOOP;
  END IF;

  -- Award XP to user if successful and return authoritative total XP
  DECLARE
    v_new_xp integer := NULL;
  BEGIN
    IF v_xp > 0 THEN
      UPDATE public.users
      SET xp = COALESCE(xp, 0) + v_xp
      WHERE auth_id = v_user_id
      RETURNING xp INTO v_new_xp;
    END IF;

    -- If DB returned new total XP, use that as the xp_awarded value
    IF v_new_xp IS NOT NULL THEN
      v_xp := v_new_xp;
    END IF;
  END;

    PERFORM public.grant_monument_craft_byproduct(v_user_id, COALESCE((SELECT lower(rarity) FROM public.items WHERE id = v_recipe.output_item_id), 'common'), v_final_qty);

  -- Remove queue item after successful claim
  DELETE FROM public.craft_queue WHERE id = p_queue_item_id;

  RETURN QUERY SELECT true, 'Item claimed and added to inventory'::text, v_xp;
END;
$$;


ALTER FUNCTION "public"."claim_crafted_item"("p_queue_item_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_daily_reward"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id UUID;
  v_today DATE;
  v_player RECORD;
  v_state RECORD;
  v_config public.daily_reward_config%ROWTYPE;
  v_grant JSONB;
  v_gold INTEGER;
  v_xp INTEGER;
  v_energy INTEGER;
  v_new_streak INTEGER;
  v_add_result JSONB;
  v_rewards_granted JSONB;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Oturum bulunamadı.');
  END IF;

  v_today := (now() AT TIME ZONE 'UTC')::date;

  SELECT * INTO v_player
  FROM public.users
  WHERE auth_id = v_user_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Kullanıcı profili bulunamadı.');
  END IF;

  IF v_player.hospital_until IS NOT NULL AND v_player.hospital_until > now() THEN
    RETURN jsonb_build_object('success', false, 'error', 'Hastanedeyken günlük ödül alınamaz.');
  END IF;

  IF v_player.prison_until IS NOT NULL AND v_player.prison_until > now() THEN
    RETURN jsonb_build_object('success', false, 'error', 'Hapishanedeyken günlük ödül alınamaz.');
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.daily_reward_claims
    WHERE user_id = v_user_id AND claim_date = v_today
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Bugünkü ödül zaten alındı.');
  END IF;

  SELECT * INTO v_state
  FROM public.daily_reward_resolve_state(v_user_id, v_today);

  IF NOT v_state.can_claim THEN
    RETURN jsonb_build_object('success', false, 'error', 'Ödül alınamaz durumda.');
  END IF;

  SELECT * INTO v_config
  FROM public.daily_reward_config
  WHERE cycle_day = v_state.next_cycle_day;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Ödül konfigürasyonu bulunamadı.');
  END IF;

  v_grant := public.daily_reward_build_grant(v_state.next_cycle_day, v_player.level);
  v_gold := (v_grant->>'gold')::INTEGER;
  v_xp := (v_grant->>'xp')::INTEGER;
  v_energy := (v_grant->>'energy')::INTEGER;

  v_new_streak := CASE
    WHEN v_state.next_cycle_day = 1 AND (v_state.streak_length = 0) THEN 1
    ELSE v_state.streak_length + 1
  END;

  IF v_config.item_id IS NOT NULL AND v_config.item_quantity > 0 THEN
    v_add_result := public.add_inventory_item_v2(
      jsonb_build_object(
        'item_id', v_config.item_id,
        'quantity', v_config.item_quantity,
        'allow_stack', true
      ),
      NULL
    );

    IF COALESCE((v_add_result->>'success')::BOOLEAN, FALSE) = FALSE THEN
      RETURN jsonb_build_object(
        'success', false,
        'error', 'Envanter dolu. Ödül verilemedi: ' || COALESCE(v_add_result->>'error', 'unknown')
      );
    END IF;
  END IF;

  v_rewards_granted := v_grant;

  UPDATE public.users
  SET
    gold = COALESCE(gold, 0) + v_gold,
    gems = COALESCE(gems, 0) + (v_grant->>'gems')::INTEGER,
    xp = COALESCE(xp, 0) + v_xp,
    energy = CASE
      WHEN v_energy > 0 THEN LEAST(COALESCE(max_energy, 100), COALESCE(energy, 0) + v_energy)
      ELSE energy
    END,
    updated_at = now()
  WHERE auth_id = v_user_id;

  INSERT INTO public.daily_reward_claims (
    user_id, claim_date, cycle_day, streak_length, rewards_granted
  ) VALUES (
    v_user_id, v_today, v_state.next_cycle_day, v_new_streak, v_rewards_granted
  );

  SELECT gold, gems, xp, energy
  INTO v_player.gold, v_player.gems, v_player.xp, v_player.energy
  FROM public.users
  WHERE auth_id = v_user_id;

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Günlük ödül alındı!',
    'cycle_day', v_state.next_cycle_day,
    'streak_length', v_new_streak,
    'rewards_granted', v_rewards_granted,
    'new_balances', jsonb_build_object(
      'gold', v_player.gold,
      'gems', v_player.gems,
      'xp', v_player.xp,
      'energy', v_player.energy
    )
  );
EXCEPTION
  WHEN unique_violation THEN
    RETURN jsonb_build_object('success', false, 'error', 'Bugünkü ödül zaten alındı.');
END;
$$;


ALTER FUNCTION "public"."claim_daily_reward"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_quest_reward"("p_quest_id" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_status text;
  v_gold integer;
  v_xp integer;
  v_gem integer;
BEGIN
  IF p_quest_id LIKE 'bp_%' THEN
    RAISE EXCEPTION 'Sezon görev ödülü sezon sayfasından alınır.';
  END IF;

  SELECT status INTO v_status
  FROM public.player_quests
  WHERE user_id = v_user_id AND quest_id = p_quest_id;

  IF NOT FOUND OR v_status != 'completed' THEN
    RAISE EXCEPTION 'Ödül alınabilir durumda değil.';
  END IF;

  SELECT gold_reward, xp_reward, gem_reward INTO v_gold, v_xp, v_gem
  FROM public.quests WHERE quest_id = p_quest_id;

  UPDATE public.users
  SET gold = gold + v_gold, xp = xp + v_xp, gems = gems + v_gem
  WHERE auth_id = v_user_id;

  UPDATE public.player_quests
  SET status = 'claimed'
  WHERE user_id = v_user_id AND quest_id = p_quest_id;
END;
$$;


ALTER FUNCTION "public"."claim_quest_reward"("p_quest_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_referral_rewards"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_me UUID;
  v_row RECORD;
  v_total INTEGER := 0;
  v_count INTEGER := 0;
BEGIN
  v_me := auth.uid();
  IF v_me IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  INSERT INTO public.referral_rewards (referrer_id, referred_id)
  SELECT u.referred_by, u.auth_id
  FROM public.users u
  WHERE u.referred_by IS NOT NULL
    AND u.level >= 5
    AND (u.referred_by = v_me OR u.auth_id = v_me)
  ON CONFLICT (referred_id) DO NOTHING;

  FOR v_row IN
    SELECT id, referrer_gems FROM public.referral_rewards
    WHERE referrer_id = v_me AND referrer_claimed_at IS NULL
    FOR UPDATE
  LOOP
    UPDATE public.referral_rewards
    SET referrer_claimed_at = now()
    WHERE id = v_row.id;
    v_total := v_total + v_row.referrer_gems;
    v_count := v_count + 1;
  END LOOP;

  FOR v_row IN
    SELECT id, referred_gems FROM public.referral_rewards
    WHERE referred_id = v_me AND referred_claimed_at IS NULL
    FOR UPDATE
  LOOP
    UPDATE public.referral_rewards
    SET referred_claimed_at = now()
    WHERE id = v_row.id;
    v_total := v_total + v_row.referred_gems;
    v_count := v_count + 1;
  END LOOP;

  IF v_total > 0 THEN
    UPDATE public.users
    SET gems = COALESCE(gems, 0) + v_total,
        updated_at = now()
    WHERE auth_id = v_me;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'gems_earned', v_total,
    'rewards_claimed', v_count
  );
END;
$$;


