CREATE OR REPLACE FUNCTION "public"."get_chat_history"("p_channel" "text", "p_limit" integer DEFAULT 50) RETURNS TABLE("id" "uuid", "channel" "text", "sender_id" "uuid", "sender_name" "text", "content" "text", "timestamp" timestamp with time zone, "is_system" boolean, "recipient_user_id" "uuid", "guild_id" "uuid", "sender_is_online" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user public.users%ROWTYPE;
BEGIN
  v_user := public.get_current_chat_user();

  IF p_channel NOT IN ('global', 'guild', 'dm', 'trade', 'system') THEN
    RAISE EXCEPTION 'Gecersiz kanal';
  END IF;

  IF p_channel = 'guild' AND v_user.guild_id IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    cm.id,
    cm.channel,
    cm.sender_user_id,
    cm.sender_name,
    cm.content,
    cm.created_at,
    cm.is_system,
    cm.recipient_user_id,
    cm.guild_id,
    public.is_user_online(u.is_online, u.last_active_at)
  FROM public.chat_messages cm
  JOIN public.users u ON u.id = cm.sender_user_id
  WHERE cm.deleted_at IS NULL
    AND cm.channel = p_channel
    AND (
      p_channel IN ('global', 'trade', 'system')
      OR (p_channel = 'guild' AND cm.guild_id = v_user.guild_id)
      OR (p_channel = 'dm' AND (cm.sender_user_id = v_user.id OR cm.recipient_user_id = v_user.id))
    )
    AND NOT EXISTS (
      SELECT 1 FROM public.chat_blocks cb
      WHERE cb.blocker_user_id = v_user.id
        AND cb.blocked_user_id = cm.sender_user_id
    )
  ORDER BY cm.created_at DESC
  LIMIT LEAST(GREATEST(COALESCE(p_limit, 50), 1), 100);
END;
$$;


ALTER FUNCTION "public"."get_chat_history"("p_channel" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_chat_moderation_state"("p_channel" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user public.users%ROWTYPE;
  v_filters JSONB;
  v_bans JSONB;
BEGIN
  v_user := public.get_current_chat_user();

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', cf.id,
    'term', cf.term,
    'replacement', cf.replacement,
    'channel', cf.channel,
    'scope', cf.scope,
    'guild_id', cf.guild_id,
    'created_at', cf.created_at
  ) ORDER BY cf.created_at DESC), '[]'::jsonb)
  INTO v_filters
  FROM public.chat_filters cf
  WHERE cf.is_active = true
    AND (
      (p_channel = 'guild' AND cf.scope = 'guild' AND cf.guild_id = v_user.guild_id)
      OR (cf.scope = 'channel' AND cf.channel = p_channel)
      OR (cf.scope = 'global')
    );

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', cb.id,
    'channel', cb.channel,
    'scope', cb.scope,
    'reason', cb.reason,
    'expires_at', cb.expires_at
  ) ORDER BY cb.expires_at DESC), '[]'::jsonb)
  INTO v_bans
  FROM public.chat_bans cb
  WHERE cb.user_id = v_user.id
    AND cb.revoked_at IS NULL
    AND cb.expires_at > now();

  RETURN jsonb_build_object(
    'success', true,
    'channel', p_channel,
    'filters', v_filters,
    'active_bans', v_bans,
    'permissions', jsonb_build_object(
      'can_delete', public.has_chat_permission(v_user.id, 'delete', p_channel, v_user.guild_id),
      'can_ban', public.has_chat_permission(v_user.id, 'ban', p_channel, v_user.guild_id),
      'can_manage_filters', public.has_chat_permission(v_user.id, 'manage_filters', p_channel, v_user.guild_id),
      'can_manage_moderators', public.has_chat_permission(v_user.id, 'manage_moderators', p_channel, v_user.guild_id)
    )
  );
END;
$$;


ALTER FUNCTION "public"."get_chat_moderation_state"("p_channel" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_chat_presence"("p_user_ids" "uuid"[]) RETURNS TABLE("user_id" "uuid", "is_online" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  PERFORM public.get_current_chat_user();

  IF p_user_ids IS NULL OR cardinality(p_user_ids) = 0 THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    u.id,
    public.is_user_online(u.is_online, u.last_active_at)
  FROM public.users u
  WHERE u.id = ANY(p_user_ids);
END;
$$;


ALTER FUNCTION "public"."get_chat_presence"("p_user_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_craft_queue"() RETURNS TABLE("id" "uuid", "recipe_id" "uuid", "recipe_name" "text", "recipe_icon" "text", "batch_count" integer, "started_at" timestamp with time zone, "completes_at" timestamp with time zone, "is_completed" boolean, "claimed" boolean, "failed" boolean, "xp_reward" integer, "output_item_id" "text", "output_quantity" integer, "output_name" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id uuid;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  RETURN QUERY
  SELECT
    cq.id,
    cq.recipe_id,
    cr.name as recipe_name,
    ii.icon as recipe_icon,
    cq.batch_count,
    cq.started_at,
    cq.completes_at,
    (cq.is_completed OR cq.completes_at <= now()) as is_completed,
    cq.claimed,
    cq.failed,
    COALESCE(cr.xp_reward, 0) as xp_reward,
    cr.output_item_id,
    cr.output_quantity,
    COALESCE(output_items.name, cr.output_item_id) as output_name
  FROM public.craft_queue cq
  LEFT JOIN public.crafting_recipes cr ON cq.recipe_id = cr.id
  LEFT JOIN public.items ii ON ii.id = cr.output_item_id
  LEFT JOIN public.items output_items ON output_items.id = cr.output_item_id
  WHERE cq.user_id = v_user_id
  ORDER BY cq.started_at DESC;
END;
$$;


ALTER FUNCTION "public"."get_craft_queue"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_craft_recipes"("p_user_level" integer DEFAULT 1) RETURNS TABLE("id" "uuid", "recipe_id" "uuid", "name" "text", "output_item_id" "text", "output_name" "text", "output_quantity" integer, "output_rarity" "text", "item_type" "text", "recipe_type" "text", "required_level" integer, "production_time_seconds" integer, "success_rate" double precision, "xp_reward" integer, "ingredients" "jsonb", "gold_cost" bigint, "gem_cost" integer, "description" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    cr.id,
    cr.id AS recipe_id,
    COALESCE(ii.name, cr.output_item_id) AS name,
    cr.output_item_id,
    COALESCE(ii.name, cr.output_item_id) AS output_name,
    1 AS output_quantity,
    lower(COALESCE(ii.rarity, 'common')) AS output_rarity,
    lower(COALESCE(ii.type, 'misc')) AS item_type,
    public._craft_workshop_category(ii.type, ii.equip_slot, ii.id) AS recipe_type,
    cr.required_level,
    COALESCE(cr.production_time_seconds, 30) AS production_time_seconds,
    cr.success_rate,
    cr.xp_reward,
    public._enrich_craft_ingredients(cr.ingredients) AS ingredients,
    COALESCE(cr.gold_cost, 0) AS gold_cost,
    0 AS gem_cost,
    COALESCE(ii.description, '') AS description
  FROM public.crafting_recipes cr
  LEFT JOIN public.items ii ON ii.id = cr.output_item_id
  WHERE cr.required_level <= p_user_level
  ORDER BY public._craft_workshop_category(ii.type, ii.equip_slot, ii.id), cr.required_level, cr.output_item_id;
END;
$$;


ALTER FUNCTION "public"."get_craft_recipes"("p_user_level" integer) OWNER TO "postgres";


