CREATE OR REPLACE FUNCTION "public"."get_current_election"() RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_election public.kingdom_elections%ROWTYPE;
  v_loop_id uuid;
  v_candidates json;
  v_winner record;
  v_voting_open boolean;
  v_voter json;
BEGIN
  FOR v_loop_id IN
    SELECT id FROM public.kingdom_elections
    WHERE status = 'active'
      AND end_at IS NOT NULL
      AND end_at <= now()
  LOOP
    PERFORM public.finalize_kingdom_election(v_loop_id);
  END LOOP;

  v_election := NULL;

  SELECT * INTO v_election
  FROM public.kingdom_elections
  WHERE status = 'active'
  ORDER BY start_at DESC NULLS LAST, created_at DESC
  LIMIT 1;

  IF FOUND THEN
    v_voting_open := (v_election.start_at IS NULL OR v_election.start_at <= now())
      AND (v_election.end_at IS NULL OR v_election.end_at > now());

    SELECT COALESCE(json_agg(row_to_json(c)), '[]'::json) INTO v_candidates
    FROM (
      SELECT
        cg.guild_id AS id,
        cg.guild_name AS name,
        cg.season_rank AS rank,
        COUNT(v.id)::integer AS vote_count
      FROM public._kingdom_election_candidate_guilds(20) cg
      LEFT JOIN public.kingdom_election_votes v
        ON v.candidate_guild_id = cg.guild_id AND v.election_id = v_election.id
      GROUP BY cg.guild_id, cg.guild_name, cg.season_rank
      ORDER BY cg.season_rank
    ) c;

    IF v_election.end_at IS NOT NULL AND v_election.end_at <= now() THEN
      PERFORM public.finalize_kingdom_election(v_election.id);
    ELSE
      v_voter := public._kingdom_election_voter_context(v_election.id, v_voting_open);

      RETURN json_build_object(
        'active', true,
        'status', 'active',
        'voting_open', v_voting_open,
        'id', v_election.id,
        'month', v_election.month,
        'start_at', v_election.start_at,
        'end_at', v_election.end_at,
        'candidates', v_candidates,
        'winner', NULL,
        'voter', v_voter
      );
    END IF;
  END IF;

  v_election := NULL;

  SELECT * INTO v_election
  FROM public.kingdom_elections
  WHERE status = 'completed'
  ORDER BY end_at DESC NULLS LAST, created_at DESC
  LIMIT 1;

  IF NOT FOUND THEN
    SELECT * INTO v_election
    FROM public.kingdom_elections
    ORDER BY created_at DESC
    LIMIT 1;
  END IF;

  IF NOT FOUND THEN
    RETURN json_build_object('active', false, 'status', 'none');
  END IF;

  SELECT COALESCE(json_agg(row_to_json(c)), '[]'::json) INTO v_candidates
  FROM (
    SELECT
      cg.guild_id AS id,
      cg.guild_name AS name,
      cg.season_rank AS rank,
      COUNT(v.id)::integer AS vote_count
    FROM public._kingdom_election_candidate_guilds(20) cg
    LEFT JOIN public.kingdom_election_votes v
      ON v.candidate_guild_id = cg.guild_id AND v.election_id = v_election.id
    GROUP BY cg.guild_id, cg.guild_name, cg.season_rank
    ORDER BY cg.season_rank
  ) c;

  v_voter := public._kingdom_election_voter_context(v_election.id, false);

  IF v_election.status = 'active' THEN
    RETURN json_build_object(
      'active', true,
      'status', 'active',
      'voting_open', false,
      'id', v_election.id,
      'month', v_election.month,
      'start_at', v_election.start_at,
      'end_at', v_election.end_at,
      'candidates', v_candidates,
      'winner', NULL,
      'voter', v_voter
    );
  END IF;

  SELECT g.id, g.name, COUNT(v.id)::integer AS vote_count
  INTO v_winner
  FROM public.guilds g
  LEFT JOIN public.kingdom_election_votes v
    ON v.candidate_guild_id = g.id AND v.election_id = v_election.id
  WHERE g.id = v_election.winner_guild_id
  GROUP BY g.id, g.name;

  IF v_winner IS NULL AND v_election.winner_guild_id IS NOT NULL THEN
    SELECT g.id, g.name, 0 AS vote_count
    INTO v_winner
    FROM public.guilds g
    WHERE g.id = v_election.winner_guild_id;
  END IF;

  IF v_winner IS NULL THEN
    SELECT g.id, g.name, COUNT(v.id)::integer AS vote_count
    INTO v_winner
    FROM public.kingdom_election_votes v
    JOIN public.guilds g ON g.id = v.candidate_guild_id
    WHERE v.election_id = v_election.id
    GROUP BY g.id, g.name
    ORDER BY COUNT(*) DESC, g.id
    LIMIT 1;
  END IF;

  RETURN json_build_object(
    'active', false,
    'status', 'completed',
    'voting_open', false,
    'id', v_election.id,
    'month', v_election.month,
    'start_at', v_election.start_at,
    'end_at', v_election.end_at,
    'candidates', v_candidates,
    'winner', CASE WHEN v_winner IS NULL THEN NULL ELSE json_build_object(
      'id', v_winner.id,
      'name', v_winner.name,
      'vote_count', v_winner.vote_count
    ) END,
    'voter', v_voter
  );
END;
$$;


ALTER FUNCTION "public"."get_current_election"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_current_user"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id uuid;
  v_user record;
  v_class record;
  v_result jsonb;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT * INTO v_user FROM public.users WHERE auth_id = v_user_id;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  -- BaÅŸlangÄ±Ã§ objesi
  v_result := to_jsonb(v_user);

  -- Pasif bonuslarÄ± ekle (sÄ±nÄ±f varsa)
  IF v_user.character_class IS NOT NULL THEN
    SELECT * INTO v_class FROM public.character_classes WHERE id = v_user.character_class;
    IF FOUND THEN
      v_result := v_result || jsonb_build_object(
        'class_passive_bonuses', v_class.passive_bonuses
      );
    END IF;
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_current_user"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_daily_reward_status"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_user_id UUID; v_today DATE; v_player RECORD; v_state RECORD; v_calendar JSONB := '[]'::jsonb; v_config RECORD; v_day_status TEXT; v_target_day INTEGER; v_grant JSONB; v_today_grant JSONB; v_next_reset TIMESTAMPTZ; v_cycle_max INTEGER;
BEGIN
  v_user_id := auth.uid(); IF v_user_id IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'Oturum bulunamadı.'); END IF;
  v_today := (now() AT TIME ZONE 'UTC')::date; v_next_reset := ((v_today + 1)::timestamp AT TIME ZONE 'UTC'); v_cycle_max := public.daily_reward_cycle_max();
  SELECT level INTO v_player FROM public.users WHERE auth_id = v_user_id; IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'Kullanıcı profili bulunamadı.'); END IF;
  SELECT * INTO v_state FROM public.daily_reward_resolve_state(v_user_id, v_today);
  v_target_day := CASE WHEN v_state.can_claim THEN v_state.next_cycle_day ELSE v_state.today_cycle_day END;
  FOR v_config IN SELECT * FROM public.daily_reward_config ORDER BY cycle_day LOOP
    IF v_config.cycle_day < v_target_day THEN v_day_status := 'completed';
    ELSIF v_config.cycle_day = v_target_day THEN v_day_status := CASE WHEN v_state.can_claim THEN 'today' ELSE 'completed' END;
    ELSE v_day_status := 'locked'; END IF;
    v_grant := public.daily_reward_build_grant(v_config.cycle_day, v_player.level);
    v_calendar := v_calendar || jsonb_build_array(jsonb_build_object('cycle_day', v_config.cycle_day, 'status', v_day_status, 'reward', v_grant));
  END LOOP;
  v_today_grant := public.daily_reward_build_grant(v_target_day, v_player.level);
  RETURN jsonb_build_object('success', true, 'can_claim', v_state.can_claim, 'cycle_day', v_target_day, 'cycle_length', v_cycle_max, 'streak_length', v_state.streak_length, 'claimed_today', v_state.claimed_today, 'today_reward', v_today_grant, 'week_calendar', v_calendar, 'next_reset_at', v_next_reset, 'timezone', 'UTC');
END; $$;


ALTER FUNCTION "public"."get_daily_reward_status"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dm_conversations"() RETURNS TABLE("peer_user_id" "uuid", "peer_username" "text", "peer_display_name" "text", "last_message_id" "uuid", "last_message_content" "text", "last_message_at" timestamp with time zone, "unread_count" bigint, "last_sender_id" "uuid", "peer_is_online" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user public.users%ROWTYPE;
BEGIN
  v_user := public.get_current_chat_user();

  RETURN QUERY
  WITH dm_rows AS (
    SELECT
      CASE
        WHEN cm.sender_user_id = v_user.id THEN cm.recipient_user_id
        ELSE cm.sender_user_id
      END AS peer_id,
      cm.id,
      cm.content,
      cm.created_at,
      cm.sender_user_id,
      cm.recipient_user_id,
      cm.read_at,
      row_number() OVER (
        PARTITION BY CASE
          WHEN cm.sender_user_id = v_user.id THEN cm.recipient_user_id
          ELSE cm.sender_user_id
        END
        ORDER BY cm.created_at DESC
      ) AS row_num
    FROM public.chat_messages cm
    WHERE cm.deleted_at IS NULL
      AND cm.channel = 'dm'
      AND (cm.sender_user_id = v_user.id OR cm.recipient_user_id = v_user.id)
      AND NOT EXISTS (
        SELECT 1 FROM public.chat_dm_message_hides h
        WHERE h.message_id = cm.id
          AND h.user_id = v_user.id
      )
      AND NOT EXISTS (
        SELECT 1 FROM public.chat_blocks cb
        WHERE cb.blocker_user_id = v_user.id
          AND cb.blocked_user_id = CASE
            WHEN cm.sender_user_id = v_user.id THEN cm.recipient_user_id
            ELSE cm.sender_user_id
          END
      )
  ), unread_totals AS (
    SELECT
      cm.sender_user_id AS peer_id,
      count(*) AS unread_count
    FROM public.chat_messages cm
    WHERE cm.deleted_at IS NULL
      AND cm.channel = 'dm'
      AND cm.recipient_user_id = v_user.id
      AND cm.read_at IS NULL
      AND NOT EXISTS (
        SELECT 1 FROM public.chat_dm_message_hides h
        WHERE h.message_id = cm.id
          AND h.user_id = v_user.id
      )
      AND NOT EXISTS (
        SELECT 1 FROM public.chat_dm_conversation_hides ch
        WHERE ch.user_id = v_user.id
          AND ch.peer_user_id = cm.sender_user_id
          AND cm.created_at <= ch.hidden_at
      )
    GROUP BY cm.sender_user_id
  )
  SELECT
    peer.id,
    peer.username,
    peer.display_name,
    dm.id,
    dm.content,
    dm.created_at,
    COALESCE(unread_totals.unread_count, 0),
    dm.sender_user_id,
    public.is_user_online(peer.is_online, peer.last_active_at)
  FROM dm_rows dm
  JOIN public.users peer ON peer.id = dm.peer_id
  LEFT JOIN unread_totals ON unread_totals.peer_id = dm.peer_id
  WHERE dm.row_num = 1
    AND NOT EXISTS (
      SELECT 1 FROM public.chat_dm_conversation_hides ch
      WHERE ch.user_id = v_user.id
        AND ch.peer_user_id = dm.peer_id
        AND dm.created_at <= ch.hidden_at
    )
  ORDER BY dm.created_at DESC;
END;
$$;


ALTER FUNCTION "public"."get_dm_conversations"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dm_messages"("p_peer_user_id" "uuid", "p_limit" integer DEFAULT 50) RETURNS TABLE("id" "uuid", "channel" "text", "sender_id" "uuid", "sender_name" "text", "content" "text", "timestamp" timestamp with time zone, "is_system" boolean, "recipient_user_id" "uuid", "guild_id" "uuid", "read_at" timestamp with time zone, "sender_is_online" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user public.users%ROWTYPE;
BEGIN
  v_user := public.get_current_chat_user();

  IF p_peer_user_id IS NULL OR p_peer_user_id = v_user.id THEN
    RAISE EXCEPTION 'Gecersiz hedef kullanici';
  END IF;

  RETURN QUERY
  SELECT
    cm.id,
    cm.channel,
    cm.sender_user_id,
    cm.sender_name,
    cm.content,
    cm.created_at,
    cm.is_system,
    cm.recipient_user_id,
    cm.guild_id,
    cm.read_at,
    public.is_user_online(u.is_online, u.last_active_at)
  FROM public.chat_messages cm
  JOIN public.users u ON u.id = cm.sender_user_id
  WHERE cm.deleted_at IS NULL
    AND cm.channel = 'dm'
    AND (
      (cm.sender_user_id = v_user.id AND cm.recipient_user_id = p_peer_user_id)
      OR (cm.sender_user_id = p_peer_user_id AND cm.recipient_user_id = v_user.id)
    )
    AND NOT EXISTS (
      SELECT 1 FROM public.chat_blocks cb
      WHERE cb.blocker_user_id = v_user.id
        AND cb.blocked_user_id = cm.sender_user_id
    )
    AND NOT EXISTS (
      SELECT 1 FROM public.chat_dm_message_hides h
      WHERE h.message_id = cm.id
        AND h.user_id = v_user.id
    )
  ORDER BY cm.created_at DESC
  LIMIT LEAST(GREATEST(COALESCE(p_limit, 50), 1), 100);
END;
$$;


ALTER FUNCTION "public"."get_dm_messages"("p_peer_user_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dungeons"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_player_id UUID := auth.uid();
  v_result JSONB;
BEGIN
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', d.id,
      'dungeon_id', d.id,
      'name', COALESCE(NULLIF(d.name_tr, ''), d.name),
      'description', COALESCE(d.description, ''),
      'difficulty', CASE
        WHEN d.is_boss THEN 'dungeon'
        WHEN COALESCE(d.power_requirement, 0) < 15000 THEN 'easy'
        WHEN COALESCE(d.power_requirement, 0) < 45000 THEN 'medium'
        ELSE 'hard'
      END,
      'required_level', GREATEST(1, floor(COALESCE(d.power_requirement, 0) / 500.0)::INT),
      'min_level', GREATEST(1, floor(COALESCE(d.power_requirement, 0) / 500.0)::INT),
      'power_requirement', COALESCE(d.power_requirement, 0),
      'max_players', 1,
      'energy_cost', COALESCE(d.energy_cost, 0),
      'min_gold', COALESCE(d.gold_min, 0),
      'max_gold', COALESCE(d.gold_max, 0),
      'xp_reward', COALESCE(d.xp_reward, 0),
      'base_gold_reward', floor((COALESCE(d.gold_min, 0) + COALESCE(d.gold_max, 0)) / 2.0)::INT,
      'base_xp_reward', COALESCE(d.xp_reward, 0),
      'is_group', false,
      'loot_table', '[]'::jsonb,
      'equipment_drop_chance', COALESCE(d.equipment_drop_chance, 0),
      'resource_drop_chance', COALESCE(d.resource_drop_chance, 0),
      'catalyst_drop_chance', COALESCE(d.catalyst_drop_chance, 0),
      'scroll_drop_chance', COALESCE(d.scroll_drop_chance, 0),
      'loot_rarity_weights', COALESCE(d.loot_rarity_weights, '{}'::jsonb),
      'boss_name', CASE WHEN COALESCE(d.is_boss, false) THEN COALESCE(d.name_tr, d.name) ELSE NULL END,
      'zone', COALESCE(d.zone, 1),
      'zone_name', COALESCE(d.zone_name, ''),
      'dungeon_order', COALESCE(d.dungeon_order, 0),
      'is_boss', COALESCE(d.is_boss, false),
      'daily_boss_limit', COALESCE(d.daily_boss_limit, 3),
      'total_attempts', COALESCE(pds.total_attempts, 0),
      'total_successes', COALESCE(pds.total_successes, 0),
      'first_clear_at', pds.first_clear_at,
      'today_attempts', COALESCE(pds.today_attempts, 0),
      'today_boss_attempts', COALESCE(pds.today_boss_attempts, 0),
      'runs_since_best_rarity', CASE
        WHEN v_player_id IS NULL THEN 0
        ELSE public._dungeon_runs_since_best_rarity(v_player_id, d.id)
      END
    )
    ORDER BY COALESCE(d.dungeon_order, 0)
  ), '[]'::JSONB)
  INTO v_result
  FROM public.dungeons d
  LEFT JOIN public.player_dungeon_stats pds
    ON pds.dungeon_id = d.id
   AND pds.player_id = v_player_id;

  RETURN COALESCE(v_result, '[]'::JSONB);
END;
$$;


ALTER FUNCTION "public"."get_dungeons"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_enhancement_config"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_player RECORD;
  v_monument_level INT := 0;
  v_gold_discount_pct INT := 0;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object('error', 'unauthorized');
  END IF;

  SELECT * INTO v_player FROM public.users WHERE auth_id = auth.uid();

  IF v_player.guild_id IS NOT NULL THEN
    SELECT monument_level
    INTO v_monument_level
    FROM public.guilds
    WHERE id = v_player.guild_id;
  END IF;

  IF COALESCE(v_monument_level, 0) >= 90 THEN
    v_gold_discount_pct := 5;
  END IF;

  RETURN jsonb_build_object(
    'base_costs', jsonb_build_array(
      100000, 200000, 300000, 500000, 1500000, 3500000,
      7500000, 15000000, 50000000, 200000000, 1000000000
    ),
    'success_rates', jsonb_build_array(100, 100, 100, 100, 70, 60, 50, 35, 20, 10, 3),
    'destroy_rates', jsonb_build_array(0, 0, 0, 0, 0, 0, 100, 100, 100, 100, 100),
    'rarity_multipliers', jsonb_build_object(
      'common', 1.0,
      'uncommon', 1.5,
      'rare', 2.5,
      'epic', 4.0,
      'legendary', 7.0,
      'mythic', 12.0
    ),
    'gold_discount_pct', v_gold_discount_pct,
    'monument_level', COALESCE(v_monument_level, 0)
  );
END;
$$;


ALTER FUNCTION "public"."get_enhancement_config"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_equipped_items"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_user_id UUID;
    v_equipped_items JSONB;
BEGIN
    v_user_id := auth.uid();
    IF v_user_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
    END IF;

    SELECT jsonb_agg(
        jsonb_build_object(
            'row_id', inv.row_id,
            'item_id', inv.item_id,
            'equip_slot', inv.equip_slot,
            'enhancement_level', COALESCE(inv.enhancement_level, 0),
            'quantity', inv.quantity,
            'obtained_at', inv.obtained_at,
            'name', it.name,
            'description', it.description,
            'icon', it.icon,
            'item_type', it.type,
            'rarity', it.rarity,
            'attack', it.attack,
            'defense', it.defense,
            'health', it.health,
            'power', it.power,
            'required_level', COALESCE(it.required_level, 1),
            'required_class', it.required_class
        )
    )
    INTO v_equipped_items
    FROM public.inventory inv
    LEFT JOIN public.items it ON inv.item_id = it.id
    WHERE inv.user_id = v_user_id AND inv.is_equipped = TRUE;

    IF v_equipped_items IS NULL THEN
        v_equipped_items := '[]'::jsonb;
    END IF;

    RETURN jsonb_build_object('success', true, 'items', v_equipped_items);
END;
$$;


ALTER FUNCTION "public"."get_equipped_items"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_facility_recipes_rpc"("p_facility_type" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_user_id UUID;
    v_recipes JSONB := '[]'::jsonb;
    v_recipe RECORD;
    v_recipe_count INT := 0;
BEGIN
    v_user_id := auth.uid();
    
    IF v_user_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
    END IF;
    
    IF p_facility_type IS NULL OR p_facility_type = '' THEN
        RETURN jsonb_build_object('success', false, 'error', 'Facility type required');
    END IF;
    
    -- Get recipes for this facility type - uses required_level (correct column name)
    FOR v_recipe IN 
        SELECT 
            id, 
            facility_type, 
            output_item_id, 
            output_quantity, 
            input_materials, 
            gold_cost, 
            duration_seconds, 
            required_level,
            success_rate, 
            base_suspicion_increase,
            production_speed_bonus,
            rarity_distribution,
            created_at
        FROM public.facility_recipes 
        WHERE facility_type = p_facility_type
        ORDER BY required_level ASC
    LOOP
        v_recipe_count := v_recipe_count + 1;
        
        v_recipes := v_recipes || jsonb_build_object(
            'id', v_recipe.id,
            'facility_type', v_recipe.facility_type,
            'output_item_id', v_recipe.output_item_id,
            'output_quantity', v_recipe.output_quantity,
            'input_materials', v_recipe.input_materials,
            'gold_cost', v_recipe.gold_cost,
            'duration_seconds', v_recipe.duration_seconds,
            'required_level', v_recipe.required_level,
            'success_rate', v_recipe.success_rate,
            'base_suspicion_increase', v_recipe.base_suspicion_increase,
            'production_speed_bonus', v_recipe.production_speed_bonus,
            'rarity_distribution', v_recipe.rarity_distribution,
            'created_at', v_recipe.created_at
        );
    END LOOP;
    
    RETURN jsonb_build_object(
        'success', true,
        'recipes', v_recipes,
        'count', v_recipe_count,
        'facility_type', p_facility_type
    );
    
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;


ALTER FUNCTION "public"."get_facility_recipes_rpc"("p_facility_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_friends"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_me UUID;
  v_friends JSONB;
  v_incoming JSONB;
  v_outgoing JSONB;
BEGIN
  v_me := auth.uid();
  IF v_me IS NULL THEN
    RETURN jsonb_build_object('friends', '[]'::jsonb, 'incoming', '[]'::jsonb, 'outgoing', '[]'::jsonb);
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'friendship_id', f.id,
    'auth_id', u.auth_id,
    'username', u.username,
    'display_name', u.display_name,
    'avatar_url', u.avatar_url,
    'level', u.level,
    'power', u.power,
    'is_online', COALESCE(u.is_online, false)
  ) ORDER BY COALESCE(u.is_online, false) DESC, u.username), '[]'::jsonb)
  INTO v_friends
  FROM public.friendships f
  JOIN public.users u
    ON u.auth_id = CASE WHEN f.requester_id = v_me THEN f.addressee_id ELSE f.requester_id END
  WHERE f.status = 'accepted' AND v_me IN (f.requester_id, f.addressee_id);

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'friendship_id', f.id,
    'auth_id', u.auth_id,
    'username', u.username,
    'display_name', u.display_name,
    'avatar_url', u.avatar_url,
    'level', u.level
  ) ORDER BY f.created_at DESC), '[]'::jsonb)
  INTO v_incoming
  FROM public.friendships f
  JOIN public.users u ON u.auth_id = f.requester_id
  WHERE f.status = 'pending' AND f.addressee_id = v_me;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'friendship_id', f.id,
    'auth_id', u.auth_id,
    'username', u.username,
    'display_name', u.display_name,
    'avatar_url', u.avatar_url,
    'level', u.level
  ) ORDER BY f.created_at DESC), '[]'::jsonb)
  INTO v_outgoing
  FROM public.friendships f
  JOIN public.users u ON u.auth_id = f.addressee_id
  WHERE f.status = 'pending' AND f.requester_id = v_me;

  RETURN jsonb_build_object(
    'friends', v_friends,
    'incoming', v_incoming,
    'outgoing', v_outgoing
  );
END;
$$;


ALTER FUNCTION "public"."get_friends"() OWNER TO "postgres";


