CREATE OR REPLACE FUNCTION "public"."get_guild_info"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_auth_id UUID; v_user RECORD; v_guild RECORD; v_members JSONB;
BEGIN
  v_auth_id := auth.uid();
  IF v_auth_id IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'Kimlik dogrulama gerekli'); END IF;
  SELECT guild_id FROM public.users WHERE auth_id = v_auth_id INTO v_user;
  IF NOT FOUND OR v_user.guild_id IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'Herhangi bir loncada degilsiniz'); END IF;
  SELECT * FROM public.guilds WHERE id = v_user.guild_id INTO v_guild;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'Lonca bulunamadi'); END IF;
  SELECT jsonb_agg(jsonb_build_object('player_id', u.id, 'user_id', u.auth_id, 'username', u.username, 'level', u.level, 'role', u.guild_role, 'power', COALESCE(u.power, 0), 'is_online', COALESCE(u.is_online, false)) ORDER BY u.guild_role, u.level DESC) INTO v_members FROM public.users u WHERE u.guild_id = v_guild.id;
  RETURN jsonb_build_object('success', true, 'guild_id', v_guild.id, 'name', v_guild.name, 'description', v_guild.description, 'level', v_guild.level, 'leader_id', v_guild.leader_id, 'monument_level', v_guild.monument_level, 'monument_structural', v_guild.monument_structural, 'monument_mystical', v_guild.monument_mystical, 'monument_critical', v_guild.monument_critical, 'monument_gold_pool', v_guild.monument_gold_pool, 'min_join_power', COALESCE(v_guild.min_join_power, 0), 'members', COALESCE(v_members, '[]'::jsonb), 'member_count', (SELECT COUNT(*) FROM public.users WHERE guild_id = v_guild.id), 'max_members', v_guild.max_members, 'total_power', (SELECT COALESCE(SUM(power), 0) FROM public.users WHERE guild_id = v_guild.id));
END;
$$;


ALTER FUNCTION "public"."get_guild_info"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_guild_monument_bonuses"("p_auth_id" "uuid" DEFAULT "auth"."uid"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_level INT;
  v_every5 INT;
BEGIN
  v_level := public._monument_level_for_auth(p_auth_id);
  v_every5 := (v_level / 5);
  RETURN jsonb_build_object(
    'monument_level', v_level,
    'xp_bonus_pct', (CASE WHEN v_level >= 5 THEN 5 ELSE 0 END + CASE WHEN v_level >= 50 THEN 5 ELSE 0 END + CASE WHEN v_level >= 75 THEN 8 ELSE 0 END) + v_every5 * 0.2,
    'gold_bonus_pct', (CASE WHEN v_level >= 10 THEN 3 ELSE 0 END) + v_every5 * 0.2,
    'max_energy_bonus', public._monument_energy_bonus(v_level),
    'overdose_reduction_pct', CASE WHEN v_level >= 20 THEN 10 ELSE 0 END,
    'facility_speed_pct', CASE WHEN v_level >= 25 THEN 5 ELSE 0 END,
    'loot_luck_bonus', CASE WHEN v_level >= 30 THEN 10 ELSE 0 END,
    'craft_success_pct', CASE WHEN v_level >= 35 THEN 3 ELSE 0 END,
    'pvp_gold_loss_reduction_pct', CASE WHEN v_level >= 40 THEN 10 ELSE 0 END,
    'enhancement_gold_reduction_pct', (CASE WHEN v_level >= 45 THEN 3 ELSE 0 END + CASE WHEN v_level >= 90 THEN 5 ELSE 0 END),
    'boss_success_pct', CASE WHEN v_level >= 55 THEN 5 ELSE 0 END,
    'hospital_reduction_pct', CASE WHEN v_level >= 60 THEN 10 ELSE 0 END,
    'reputation_bonus_pct', CASE WHEN v_level >= 70 THEN 5 ELSE 0 END,
    'stat_bonus_pct', v_every5 * 0.5
  );
END;
$$;


ALTER FUNCTION "public"."get_guild_monument_bonuses"("p_auth_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_guild_war_attack_logs"("p_limit" integer DEFAULT 50, "p_guild_id" "uuid" DEFAULT NULL::"uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_result json;
BEGIN
  SELECT COALESCE(json_agg(row_to_json(t)), '[]'::json)
  INTO v_result
  FROM (
    SELECT
      l.id,
      l.territory_id,
      ter.name AS territory_name,
      l.attacker_guild_id,
      ag.name AS attacker_guild_name,
      l.defender_guild_id,
      dg.name AS defender_guild_name,
      l.attack_power,
      l.defense_power,
      l.success,
      l.points_gained,
      l.created_at
    FROM public.guild_war_attack_logs l
    JOIN public.guild_war_territories ter ON ter.id = l.territory_id
    JOIN public.guilds ag ON ag.id = l.attacker_guild_id
    LEFT JOIN public.guilds dg ON dg.id = l.defender_guild_id
    WHERE p_guild_id IS NULL
       OR l.attacker_guild_id = p_guild_id
       OR l.defender_guild_id = p_guild_id
    ORDER BY l.created_at DESC
    LIMIT GREATEST(1, LEAST(COALESCE(p_limit, 50), 100))
  ) t;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_guild_war_attack_logs"("p_limit" integer, "p_guild_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_guild_war_rankings"() RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$DECLARE
  v_active_season_id uuid;
  v_result json;
BEGIN
  SELECT id INTO v_active_season_id 
  FROM public.guild_war_seasons 
  WHERE is_active = true 
  ORDER BY created_at DESC 
  LIMIT 1;

  IF v_active_season_id IS NULL THEN
    RETURN '[]'::json;
  END IF;

  SELECT COALESCE(json_agg(row_to_json(t)), '[]'::json)
  INTO v_result
  FROM (
    SELECT 
      ROW_NUMBER() OVER (ORDER BY r.points DESC) AS rank,
      g.name AS "guild_name",
      r.points,
      r.wins,
      r.losses
    FROM public.guild_war_rankings r
    JOIN public.guilds g ON g.id = r.guild_id
    WHERE r.season_id = v_active_season_id
    ORDER BY r.points DESC
    LIMIT 50
  ) t;

  RETURN v_result;
END;$$;


ALTER FUNCTION "public"."get_guild_war_rankings"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_guild_war_season"() RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_season record;
BEGIN
  SELECT season_number, week_number, end_at
  FROM public.guild_war_seasons
  WHERE is_active = true
  ORDER BY created_at DESC
  LIMIT 1
  INTO v_season;

  IF v_season IS NULL THEN
    RETURN json_build_object('season', 1, 'week', 1, 'end_at', null);
  END IF;

  RETURN json_build_object(
    'season', v_season.season_number,
    'week', v_season.week_number,
    'end_at', v_season.end_at
  );
END;
$$;


