CREATE OR REPLACE FUNCTION "public"."get_horse_race_state"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_round RECORD;
  v_settings RECORD;
  v_my_bet JSONB;
  v_horses JSONB;
  v_recent JSONB;
  v_seconds_left INTEGER;
BEGIN
  PERFORM public.tick_horse_race_engine();

  SELECT *
  INTO v_settings
  FROM public.horse_race_settings
  WHERE id = 'default' AND is_active = TRUE
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'message', 'At yarisi kapali.');
  END IF;

  SELECT *
  INTO v_round
  FROM public.horse_race_rounds
  ORDER BY created_at DESC
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'message', 'Aktif tur yok.');
  END IF;

  v_seconds_left := CASE v_round.status
    WHEN 'betting' THEN GREATEST(0, EXTRACT(EPOCH FROM (v_round.betting_ends_at - now()))::INTEGER)
    WHEN 'racing' THEN GREATEST(0, EXTRACT(EPOCH FROM (v_round.racing_ends_at - now()))::INTEGER)
    WHEN 'finished' THEN GREATEST(0, EXTRACT(EPOCH FROM (v_round.finished_ends_at - now()))::INTEGER)
    ELSE 0
  END;

  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'horse_id', e.horse_id,
      'name', t.name,
      'emoji', t.emoji,
      'lane_color', t.lane_color,
      'gold_multiplier', e.gold_multiplier,
      'gem_multiplier', e.gem_multiplier,
      'win_chance_pct', e.win_chance_pct,
      'sort_order', e.sort_order
    )
    ORDER BY e.sort_order ASC
  ), '[]'::jsonb)
  INTO v_horses
  FROM public.horse_race_round_entries e
  JOIN public.horse_race_templates t ON t.id = e.horse_id
  WHERE e.round_id = v_round.id;

  IF v_user_id IS NOT NULL THEN
    SELECT jsonb_build_object(
      'horse_id', b.horse_id,
      'currency_type', b.currency_type,
      'bet_amount', b.bet_amount,
      'multiplier', b.multiplier,
      'won', b.won,
      'payout_amount', b.payout_amount
    )
    INTO v_my_bet
    FROM public.horse_race_bets b
    WHERE b.round_id = v_round.id
      AND b.user_id = v_user_id
    LIMIT 1;
  END IF;

  SELECT COALESCE(jsonb_agg(x ORDER BY x->>'finished_at' DESC), '[]'::jsonb)
  INTO v_recent
  FROM (
    SELECT jsonb_build_object(
      'round_id', r.id,
      'winner_horse_id', r.winner_horse_id,
      'winner_name', t.name,
      'winner_emoji', t.emoji,
      'finished_at', r.racing_ends_at
    ) AS x
    FROM public.horse_race_rounds r
    LEFT JOIN public.horse_race_templates t ON t.id = r.winner_horse_id
    WHERE r.status = 'finished'
      AND r.winner_horse_id IS NOT NULL
    ORDER BY r.racing_ends_at DESC NULLS LAST
    LIMIT 30
  ) sub;

  RETURN jsonb_build_object(
    'success', true,
    'settings', jsonb_build_object(
      'gold_min_bet', v_settings.gold_min_bet,
      'gold_max_bet', v_settings.gold_max_bet,
      'gem_min_bet', v_settings.gem_min_bet,
      'gem_max_bet', v_settings.gem_max_bet,
      'gold_max_multiplier', v_settings.gold_max_multiplier,
      'gem_max_multiplier', v_settings.gem_max_multiplier,
      'betting_seconds', v_settings.betting_seconds,
      'racing_seconds', v_settings.racing_seconds,
      'finished_seconds', v_settings.finished_seconds
    ),
    'round', jsonb_build_object(
      'id', v_round.id,
      'status', v_round.status,
      'seconds_left', v_seconds_left,
      'betting_ends_at', v_round.betting_ends_at,
      'racing_ends_at', v_round.racing_ends_at,
      'finished_ends_at', v_round.finished_ends_at,
      'winner_horse_id', v_round.winner_horse_id,
      'race_script', COALESCE(v_round.race_script, '{}'::jsonb)
    ),
    'horses', v_horses,
    'my_bet', COALESCE(v_my_bet, 'null'::jsonb),
    'recent_winners', v_recent
  );
END;
$$;


ALTER FUNCTION "public"."get_horse_race_state"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_hospital_status"("p_auth_id" "uuid") RETURNS TABLE("in_hospital" boolean, "release_time" bigint, "hospital_reason" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    COALESCE(u.hospital_until > NOW(), FALSE),
    EXTRACT(EPOCH FROM u.hospital_until)::BIGINT,
    u.hospital_reason
  FROM public.users u
  WHERE u.auth_id = p_auth_id
  LIMIT 1;
END;
$$;


ALTER FUNCTION "public"."get_hospital_status"("p_auth_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_inventory"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_items jsonb;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  WITH free_slots AS (
    SELECT s.slot,
           row_number() OVER (ORDER BY s.slot) AS rn
    FROM generate_series(0, 19) AS s(slot)
    WHERE NOT EXISTS (
      SELECT 1
      FROM public.inventory inv2
      WHERE inv2.user_id = v_user_id
        AND inv2.is_equipped = false
        AND inv2.slot_position = s.slot
    )
  ),
  unassigned_rows AS (
    SELECT inv1.row_id,
           row_number() OVER (ORDER BY inv1.created_at, inv1.row_id) AS rn
    FROM public.inventory inv1
    WHERE inv1.user_id = v_user_id
      AND inv1.is_equipped = false
      AND inv1.slot_position IS NULL
  )
  UPDATE public.inventory inv
  SET slot_position = fs.slot,
      updated_at = now()
  FROM unassigned_rows ur
  JOIN free_slots fs ON fs.rn = ur.rn
  WHERE inv.row_id = ur.row_id;

  SELECT jsonb_agg(
    jsonb_build_object(
      'row_id', inv.row_id,
      'user_id', inv.user_id,
      'item_id', inv.item_id,
      'quantity', inv.quantity,
      'slot_position', inv.slot_position,
      'is_equipped', COALESCE(inv.is_equipped, false),
      'equipped_slot', COALESCE(inv.equip_slot, ''),
      'equip_slot', COALESCE(it.equip_slot, 'none'),
      'created_at', inv.created_at,
      'updated_at', inv.updated_at,
      'enhancement_level', COALESCE(inv.enhancement_level, 0),
      'obtained_at', inv.obtained_at,
      'is_favorite', COALESCE(inv.is_favorite, false),
      'description', COALESCE(inv.description, it.description),
      'icon', COALESCE(inv.icon, it.icon),
      'name', COALESCE(it.name, inv.item_id),
      'item_type', lower(COALESCE(it.type, 'misc')),
      'rarity', lower(COALESCE(it.rarity, 'common')),
      'facility_type', it.facility_type,
      'attack', COALESCE(it.attack, 0),
      'defense', COALESCE(it.defense, 0),
      'health', COALESCE(it.health, 0),
      'power', COALESCE(it.power, 0),
      'luck', COALESCE(it.luck, 0),
      'required_level', COALESCE(it.required_level, 1),
      'required_class', it.required_class,
      'weapon_type', COALESCE(inv.weapon_type, it.weapon_type),
      'armor_type', COALESCE(inv.armor_type, it.armor_type),
      'material_type', COALESCE(inv.material_type, it.material_type),
      'potion_type', lower(COALESCE(inv.potion_type, it.potion_type, 'none')),
      'base_price', COALESCE(inv.base_price, it.base_price, 0),
      'vendor_sell_price', COALESCE(inv.vendor_sell_price, it.vendor_sell_price, 0),
      'is_tradeable', COALESCE(inv.is_tradeable, it.is_tradeable, true),
      'is_stackable', COALESCE(inv.is_stackable, it.is_stackable, true),
      'max_stack', COALESCE(inv.max_stack, it.max_stack, 999),
      'max_enhancement', COALESCE(inv.max_enhancement, it.max_enhancement, 0),
      'can_enhance', COALESCE(inv.can_enhance, it.can_enhance, false),
      'heal_amount', COALESCE(inv.heal_amount, it.heal_amount, 0),
      'health_restore', COALESCE(it.health_restore, inv.heal_amount, it.heal_amount, 0),
      'energy_restore', COALESCE(it.energy_restore, 0),
      'tolerance_increase', COALESCE(inv.tolerance_increase, it.tolerance_increase, 0),
      'overdose_risk', COALESCE(inv.overdose_risk, it.overdose_risk, 0),
      'is_han_only', COALESCE(it.is_han_only, false),
      'is_market_tradeable', COALESCE(it.is_market_tradeable, true),
      'is_direct_tradeable', COALESCE(it.is_direct_tradeable, true),
      'pending_sync', COALESCE(inv.pending_sync, false)
    )
    ORDER BY COALESCE(inv.slot_position, 999), inv.created_at
  )
  INTO v_items
  FROM public.inventory inv
  LEFT JOIN public.items it ON inv.item_id = it.id
  WHERE inv.user_id = v_user_id AND inv.is_equipped = false;

  RETURN jsonb_build_object('success', true, 'items', COALESCE(v_items, '[]'::jsonb));
END;
$$;


ALTER FUNCTION "public"."get_inventory"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_leaderboard"("p_category" "text", "p_limit" integer DEFAULT 30, "p_timeframe" "text" DEFAULT 'alltime'::"text") RETURNS TABLE("rank" integer, "username" "text", "value" integer, "level" integer, "guild" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_week_start DATE := date_trunc('week', now())::DATE;
BEGIN
  IF p_timeframe = 'weekly' AND p_category = 'pvp_rating' THEN
    IF EXISTS (SELECT 1 FROM public.pvp_leaderboard WHERE week_start = v_week_start) THEN
      RETURN QUERY
      SELECT pl.rank::INT, u.username, pl.rating AS value, u.level, g.name AS guild
      FROM public.pvp_leaderboard pl
      JOIN public.users u ON pl.user_id = u.id
      LEFT JOIN public.guilds g ON u.guild_id = g.id
      WHERE pl.week_start = v_week_start
      ORDER BY pl.rank ASC
      LIMIT p_limit;
      RETURN;
    END IF;
  END IF;

  IF p_timeframe = 'weekly' AND p_category = 'guild_power' THEN
    IF EXISTS (SELECT 1 FROM public.guild_leaderboard WHERE week_start = v_week_start) THEN
      RETURN QUERY
      SELECT gl.rank::INT, g.name AS username, gl.monument_level AS value, g.level, g.tag AS guild
      FROM public.guild_leaderboard gl
      JOIN public.guilds g ON gl.guild_id = g.id
      WHERE gl.week_start = v_week_start
      ORDER BY gl.rank ASC
      LIMIT p_limit;
      RETURN;
    END IF;
  END IF;

  IF p_timeframe = 'weekly' AND p_category = 'gold' THEN
    RETURN QUERY
    SELECT (ROW_NUMBER() OVER (ORDER BY COALESCE(w.metric, 0) DESC))::INT AS rank,
      u.username, COALESCE(w.metric, 0)::INT AS value, u.level, g.name AS guild
    FROM public.users u
    LEFT JOIN public.guilds g ON u.guild_id = g.id
    LEFT JOIN (
      SELECT dr.player_id AS user_id, SUM(COALESCE(dr.gold_earned, 0)) AS metric
      FROM public.dungeon_runs dr
      WHERE dr.created_at >= now() - interval '7 days' AND COALESCE(dr.success, false) = true
      GROUP BY dr.player_id
    ) w ON w.user_id = u.auth_id
    WHERE COALESCE(w.metric, 0) > 0
    ORDER BY COALESCE(w.metric, 0) DESC
    LIMIT p_limit;
    RETURN;
  END IF;

  IF p_timeframe = 'weekly' AND p_category = 'level' THEN
    RETURN QUERY
    SELECT (ROW_NUMBER() OVER (ORDER BY COALESCE(w.metric, 0) DESC))::INT AS rank,
      u.username, COALESCE(w.metric, 0)::INT AS value, u.level, g.name AS guild
    FROM public.users u
    LEFT JOIN public.guilds g ON u.guild_id = g.id
    LEFT JOIN (
      SELECT dr.player_id AS user_id, SUM(COALESCE(dr.xp_earned, 0)) AS metric
      FROM public.dungeon_runs dr
      WHERE dr.created_at >= now() - interval '7 days' AND COALESCE(dr.success, false) = true
      GROUP BY dr.player_id
    ) w ON w.user_id = u.auth_id
    WHERE COALESCE(w.metric, 0) > 0
    ORDER BY COALESCE(w.metric, 0) DESC
    LIMIT p_limit;
    RETURN;
  END IF;

  IF p_timeframe = 'weekly' AND p_category = 'power' THEN
    RETURN QUERY
    SELECT (ROW_NUMBER() OVER (ORDER BY COALESCE(w.metric, 0) DESC))::INT AS rank,
      u.username, COALESCE(w.metric, 0)::INT AS value, u.level, g.name AS guild
    FROM public.users u
    LEFT JOIN public.guilds g ON u.guild_id = g.id
    LEFT JOIN (
      SELECT dr.player_id AS user_id, MAX(COALESCE(dr.player_power, 0)) AS metric
      FROM public.dungeon_runs dr
      WHERE dr.created_at >= now() - interval '7 days'
      GROUP BY dr.player_id
    ) w ON w.user_id = u.auth_id
    WHERE COALESCE(w.metric, 0) > 0
    ORDER BY COALESCE(w.metric, 0) DESC
    LIMIT p_limit;
    RETURN;
  END IF;

  IF p_category = 'gold' THEN
    RETURN QUERY
    SELECT (ROW_NUMBER() OVER (ORDER BY u.gold DESC))::INT AS rank, u.username, u.gold AS value, u.level, g.name AS guild
    FROM public.users u LEFT JOIN public.guilds g ON u.guild_id = g.id
    ORDER BY u.gold DESC LIMIT p_limit;
  ELSIF p_category = 'pvp_rating' THEN
    RETURN QUERY
    SELECT (ROW_NUMBER() OVER (ORDER BY u.pvp_rating DESC))::INT AS rank, u.username, u.pvp_rating AS value, u.level, g.name AS guild
    FROM public.users u LEFT JOIN public.guilds g ON u.guild_id = g.id
    ORDER BY u.pvp_rating DESC LIMIT p_limit;
  ELSIF p_category = 'level' THEN
    RETURN QUERY
    SELECT (ROW_NUMBER() OVER (ORDER BY u.level DESC, u.xp DESC))::INT AS rank, u.username, u.level AS value, u.level, g.name AS guild
    FROM public.users u LEFT JOIN public.guilds g ON u.guild_id = g.id
    ORDER BY u.level DESC, u.xp DESC LIMIT p_limit;
  ELSIF p_category = 'power' THEN
    RETURN QUERY
    SELECT (ROW_NUMBER() OVER (ORDER BY u.power DESC))::INT AS rank, u.username, u.power AS value, u.level, g.name AS guild
    FROM public.users u LEFT JOIN public.guilds g ON u.guild_id = g.id
    ORDER BY u.power DESC LIMIT p_limit;
  ELSIF p_category = 'guild_power' THEN
    RETURN QUERY
    SELECT (ROW_NUMBER() OVER (ORDER BY g.xp DESC))::INT AS rank, g.name AS username, g.xp::INT AS value, g.level, g.tag AS guild
    FROM public.guilds g ORDER BY g.xp DESC LIMIT p_limit;
  END IF;
END;
$$;


ALTER FUNCTION "public"."get_leaderboard"("p_category" "text", "p_limit" integer, "p_timeframe" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_leaderboard_rank"("p_category" "text", "p_timeframe" "text" DEFAULT 'alltime'::"text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_auth_id UUID := auth.uid();
  v_rank INT;
  v_value INT;
  v_rival_value INT;
  v_gap INT;
BEGIN
  IF v_auth_id IS NULL THEN
    RETURN json_build_object('rank', NULL, 'value', NULL, 'rival_value', NULL, 'gap', NULL);
  END IF;

  IF p_timeframe = 'weekly' AND p_category = 'gold' THEN
    WITH weekly AS (
      SELECT u.auth_id, COALESCE(SUM(dr.gold_earned), 0)::INT AS metric
      FROM public.users u
      LEFT JOIN public.dungeon_runs dr ON dr.player_id = u.auth_id
        AND dr.created_at >= now() - interval '7 days' AND COALESCE(dr.success, false) = true
      GROUP BY u.auth_id
    ), ranked AS (
      SELECT auth_id, metric, ROW_NUMBER() OVER (ORDER BY metric DESC) AS rk FROM weekly WHERE metric > 0
    )
    SELECT r.rk::INT, r.metric, (SELECT metric FROM ranked WHERE rk = r.rk - 1)
    INTO v_rank, v_value, v_rival_value FROM ranked r WHERE r.auth_id = v_auth_id;

  ELSIF p_timeframe = 'weekly' AND p_category = 'level' THEN
    WITH weekly AS (
      SELECT u.auth_id, COALESCE(SUM(dr.xp_earned), 0)::INT AS metric
      FROM public.users u
      LEFT JOIN public.dungeon_runs dr ON dr.player_id = u.auth_id
        AND dr.created_at >= now() - interval '7 days' AND COALESCE(dr.success, false) = true
      GROUP BY u.auth_id
    ), ranked AS (
      SELECT auth_id, metric, ROW_NUMBER() OVER (ORDER BY metric DESC) AS rk FROM weekly WHERE metric > 0
    )
    SELECT r.rk::INT, r.metric, (SELECT metric FROM ranked WHERE rk = r.rk - 1)
    INTO v_rank, v_value, v_rival_value FROM ranked r WHERE r.auth_id = v_auth_id;

  ELSIF p_timeframe = 'weekly' AND p_category = 'power' THEN
    WITH weekly AS (
      SELECT u.auth_id, COALESCE(MAX(dr.player_power), 0)::INT AS metric
      FROM public.users u
      LEFT JOIN public.dungeon_runs dr ON dr.player_id = u.auth_id
        AND dr.created_at >= now() - interval '7 days'
      GROUP BY u.auth_id
    ), ranked AS (
      SELECT auth_id, metric, ROW_NUMBER() OVER (ORDER BY metric DESC) AS rk FROM weekly WHERE metric > 0
    )
    SELECT r.rk::INT, r.metric, (SELECT metric FROM ranked WHERE rk = r.rk - 1)
    INTO v_rank, v_value, v_rival_value FROM ranked r WHERE r.auth_id = v_auth_id;

  ELSIF p_category = 'gold' THEN
    WITH ranked AS (
      SELECT u.auth_id, u.gold AS metric, ROW_NUMBER() OVER (ORDER BY u.gold DESC) AS rk FROM public.users u
    )
    SELECT r.rk::INT, r.metric::INT, (SELECT metric::INT FROM ranked WHERE rk = r.rk - 1)
    INTO v_rank, v_value, v_rival_value FROM ranked r WHERE r.auth_id = v_auth_id;

  ELSIF p_category = 'pvp_rating' THEN
    WITH ranked AS (
      SELECT u.auth_id, u.pvp_rating AS metric, ROW_NUMBER() OVER (ORDER BY u.pvp_rating DESC) AS rk FROM public.users u
    )
    SELECT r.rk::INT, r.metric::INT, (SELECT metric::INT FROM ranked WHERE rk = r.rk - 1)
    INTO v_rank, v_value, v_rival_value FROM ranked r WHERE r.auth_id = v_auth_id;

  ELSIF p_category = 'level' THEN
    WITH ranked AS (
      SELECT u.auth_id, u.level AS metric, ROW_NUMBER() OVER (ORDER BY u.level DESC, u.xp DESC) AS rk FROM public.users u
    )
    SELECT r.rk::INT, r.metric::INT, (SELECT metric::INT FROM ranked WHERE rk = r.rk - 1)
    INTO v_rank, v_value, v_rival_value FROM ranked r WHERE r.auth_id = v_auth_id;

  ELSIF p_category = 'power' THEN
    WITH ranked AS (
      SELECT u.auth_id, u.power AS metric, ROW_NUMBER() OVER (ORDER BY u.power DESC NULLS LAST) AS rk FROM public.users u
    )
    SELECT r.rk::INT, r.metric::INT, (SELECT metric::INT FROM ranked WHERE rk = r.rk - 1)
    INTO v_rank, v_value, v_rival_value FROM ranked r WHERE r.auth_id = v_auth_id;

  ELSIF p_category = 'guild_power' THEN
    WITH ranked AS (
      SELECT g.id AS guild_id, g.xp AS metric, ROW_NUMBER() OVER (ORDER BY g.xp DESC) AS rk FROM public.guilds g
    ), me AS (
      SELECT r.rk, r.metric FROM ranked r JOIN public.users u ON u.guild_id = r.guild_id WHERE u.auth_id = v_auth_id
    )
    SELECT me.rk::INT, me.metric::INT, (SELECT metric::INT FROM ranked WHERE rk = me.rk - 1)
    INTO v_rank, v_value, v_rival_value FROM me;

  ELSE
    RETURN json_build_object('rank', NULL, 'value', NULL, 'rival_value', NULL, 'gap', NULL);
  END IF;

  IF v_rank IS NULL THEN
    RETURN json_build_object('rank', NULL, 'value', NULL, 'rival_value', NULL, 'gap', NULL);
  END IF;

  IF v_rank <= 1 OR v_rival_value IS NULL OR v_value IS NULL THEN
    v_gap := 0;
  ELSE
    v_gap := GREATEST(0, v_rival_value - v_value);
  END IF;

  RETURN json_build_object('rank', v_rank, 'value', v_value, 'rival_value', v_rival_value, 'gap', v_gap);
END;
$$;


ALTER FUNCTION "public"."get_leaderboard_rank"("p_category" "text", "p_timeframe" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_loot_box_drops"("p_box_id" "text") RETURNS TABLE("item_id" "text", "item_name" "text", "icon" "text", "rarity" "text", "min_quantity" integer, "max_quantity" integer, "weight" numeric, "drop_rate" numeric, "is_featured" boolean)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  WITH pool AS (SELECT COALESCE(SUM(e.weight),0)::numeric total_weight FROM public.loot_box_drop_entries e WHERE e.box_id=p_box_id AND e.is_active=true)
  SELECT e.item_id, i.name, i.icon, COALESCE(i.rarity,'common'), e.min_quantity, e.max_quantity, e.weight,
    (e.weight/NULLIF(pool.total_weight,0)*100)::numeric, COALESCE(e.is_featured,false)
  FROM public.loot_box_drop_entries e JOIN public.items i ON i.id=e.item_id CROSS JOIN pool
  WHERE e.box_id=p_box_id AND e.is_active=true AND e.show_in_preview=true
  ORDER BY e.is_featured DESC, (e.weight/NULLIF(pool.total_weight,0)*100) DESC, i.name ASC;
$$;


ALTER FUNCTION "public"."get_loot_box_drops"("p_box_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_loot_boxes_with_stats"() RETURNS TABLE("id" "text", "name" "text", "description" "text", "currency_type" "text", "price" integer, "reward_multiplier" numeric, "art_asset" "text", "drop_count" integer, "total_weight" numeric, "jackpot_rate" numeric, "display_order" integer, "theme_id" "text")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT b.id, b.name, b.description, b.currency_type, b.price, b.reward_multiplier, b.art_asset,
    COUNT(e.id)::int, COALESCE(SUM(e.weight),0)::numeric,
    COALESCE(SUM(e.weight) FILTER (WHERE COALESCE(i.rarity,'common') IN ('legendary','mythic'))/NULLIF(SUM(e.weight),0),0)::numeric,
    b.display_order, b.theme_id
  FROM public.loot_box_configs b
  LEFT JOIN public.loot_box_drop_entries e ON e.box_id=b.id AND e.is_active=true
  LEFT JOIN public.items i ON i.id=e.item_id
  WHERE b.is_active=true GROUP BY b.id ORDER BY b.display_order, b.id;
$$;


ALTER FUNCTION "public"."get_loot_boxes_with_stats"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_mekan_arena_ranking"("p_limit" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_rows JSONB;
BEGIN
  SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb) INTO v_rows FROM (
    SELECT u.auth_id, u.username, u.level, COALESCE(u.pvp_rating, 1000) AS pvp_rating,
      COALESCE(u.pvp_wins, 0) AS pvp_wins, COALESCE(u.pvp_losses, 0) AS pvp_losses, rnk.rank,
      CASE WHEN rnk.rank = 1 THEN 2000000 WHEN rnk.rank BETWEEN 2 AND 5 THEN 1000000
        WHEN rnk.rank BETWEEN 6 AND 10 THEN 500000 WHEN rnk.rank BETWEEN 11 AND 25 THEN 200000
        WHEN rnk.rank BETWEEN 26 AND 50 THEN 100000 ELSE 0 END AS weekly_reward
    FROM (SELECT auth_id, ROW_NUMBER() OVER (ORDER BY COALESCE(pvp_rating, 1000) DESC) AS rank FROM public.users) rnk
    JOIN public.users u ON u.auth_id = rnk.auth_id ORDER BY rnk.rank LIMIT GREATEST(1, LEAST(p_limit, 100))
  ) t;
  RETURN jsonb_build_object('success', true, 'ranking', v_rows);
END;
$$;


ALTER FUNCTION "public"."get_mekan_arena_ranking"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_mekan_fame_leaderboard"("p_limit" integer DEFAULT 20) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_rows JSONB;
BEGIN
  SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb) INTO v_rows FROM (
    SELECT m.id, m.name, m.mekan_type, m.level, m.fame, m.is_open, u.username AS owner_name,
      ROW_NUMBER() OVER (ORDER BY m.fame DESC, m.level DESC) AS rank
    FROM public.mekans m LEFT JOIN public.users u ON u.auth_id = m.owner_id
    ORDER BY m.fame DESC, m.level DESC LIMIT GREATEST(1, LEAST(p_limit, 100))
  ) t;
  RETURN jsonb_build_object('success', true, 'leaderboard', v_rows);
END;
$$;


ALTER FUNCTION "public"."get_mekan_fame_leaderboard"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_mekan_presence"("p_mekan_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_rows JSONB;
BEGIN
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'auth_id', u.auth_id,
    'username', u.username,
    'display_name', u.display_name,
    'avatar_url', u.avatar_url,
    'level', u.level,
    'power', u.power,
    'pvp_rating', COALESCE(u.pvp_rating, 1000)
  ) ORDER BY COALESCE(u.pvp_rating, 1000) DESC), '[]'::JSONB)
  INTO v_rows
  FROM public.users u
  WHERE u.current_mekan_id = p_mekan_id
    AND COALESCE(u.is_online, false) = true
    AND COALESCE(u.last_active_at, now() - interval '1 hour') > now() - interval '10 minutes';

  RETURN v_rows;
END;
$$;


