CREATE OR REPLACE FUNCTION "public"."get_online_players"("p_limit" integer DEFAULT 30) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_me UUID;
  v_rows JSONB;
BEGIN
  v_me := auth.uid();

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'auth_id', u.auth_id,
    'username', u.username,
    'display_name', u.display_name,
    'avatar_url', u.avatar_url,
    'level', u.level,
    'power', u.power,
    'pvp_rating', COALESCE(u.pvp_rating, 1000)
  ) ORDER BY COALESCE(u.pvp_rating, 1000) DESC), '[]'::JSONB)
  INTO v_rows
  FROM (
    SELECT * FROM public.users
    WHERE COALESCE(is_online, false) = true
      AND auth_id != COALESCE(v_me, '00000000-0000-0000-0000-000000000000'::uuid)
    LIMIT GREATEST(1, LEAST(p_limit, 100))
  ) u;

  RETURN v_rows;
END;
$$;


