CREATE OR REPLACE FUNCTION "public"."get_pending_pvp_invites"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_me UUID;
  v_rows JSONB;
BEGIN
  v_me := auth.uid();
  IF v_me IS NULL THEN
    RETURN '[]'::JSONB;
  END IF;

  UPDATE public.pvp_invites SET status = 'expired'
  WHERE status = 'pending' AND expires_at <= now();

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'invite_id', i.id,
    'wager', i.wager,
    'expires_at', i.expires_at,
    'challenger', jsonb_build_object(
      'auth_id', u.auth_id,
      'username', u.username,
      'display_name', u.display_name,
      'avatar_url', u.avatar_url,
      'level', u.level,
      'power', u.power,
      'pvp_rating', COALESCE(u.pvp_rating, 1000)
    )
  ) ORDER BY i.created_at ASC), '[]'::JSONB)
  INTO v_rows
  FROM public.pvp_invites i
  JOIN public.users u ON u.auth_id = i.challenger_id
  WHERE i.target_id = v_me AND i.status = 'pending';

  RETURN v_rows;
END;
$$;


ALTER FUNCTION "public"."get_pending_pvp_invites"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_pending_trade_invites"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid UUID;
  v_rows jsonb;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN RETURN '[]'::jsonb; END IF;

  PERFORM public._trade_expire_stale_sessions();

  IF EXISTS (
    SELECT 1 FROM public.trade_sessions ts
    WHERE ts.initiator_id = v_uid AND ts.status = 'pending'
  ) OR EXISTS (
    SELECT 1 FROM public.trade_sessions ts
    WHERE (ts.initiator_id = v_uid OR ts.partner_id = v_uid)
      AND ts.status = 'active'
      AND ts.partner_accepted_at IS NOT NULL
  ) THEN
    RETURN '[]'::jsonb;
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'session_id', ts.id,
    'initiator_name', u.username,
    'initiator_id', ts.initiator_id,
    'created_at', ts.created_at
  ) ORDER BY ts.created_at DESC), '[]'::jsonb)
  INTO v_rows
  FROM public.trade_sessions ts
  JOIN public.users u ON u.auth_id = ts.initiator_id
  WHERE ts.partner_id = v_uid
    AND ts.status = 'pending'
    AND ts.partner_accepted_at IS NULL;

  RETURN v_rows;
END;
$$;


ALTER FUNCTION "public"."get_pending_trade_invites"() OWNER TO "postgres";


