CREATE OR REPLACE FUNCTION "public"."get_pvp_dashboard"("p_match_limit" integer DEFAULT 8) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_arenas JSONB;
  v_matches JSONB;
BEGIN
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', m.id,
    'name', m.name,
    'mekan_type', m.mekan_type
  ) ORDER BY m.name), '[]'::jsonb)
  INTO v_arenas
  FROM public.mekans m
  WHERE m.mekan_type IN ('dovus_kulubu', 'luks_lounge', 'yeralti')
    AND m.is_open = true;

  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('arenas', v_arenas, 'recent_matches', '[]'::jsonb);
  END IF;

  SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb ORDER BY t.created_at DESC), '[]'::jsonb)
  INTO v_matches
  FROM (
    SELECT *
    FROM (
      SELECT
        pm.id::text AS id,
        'pvp'::text AS match_source,
        pm.attacker_id,
        pm.defender_id,
        pm.winner_id,
        pm.gold_stolen,
        pm.rep_change_winner,
        pm.rep_change_loser,
        COALESCE(pm.is_critical_success, false) AS is_critical_success,
        pm.attacker_hp_remaining,
        pm.created_at,
        ua.username AS attacker_username,
        ud.username AS defender_username
      FROM public.pvp_matches pm
      LEFT JOIN public.users ua ON ua.auth_id = pm.attacker_id
      LEFT JOIN public.users ud ON ud.auth_id = pm.defender_id
      WHERE pm.attacker_id = v_uid OR pm.defender_id = v_uid

      UNION ALL

      SELECT
        mpm.id::text,
        'arena'::text,
        mpm.attacker_id,
        mpm.defender_id,
        mpm.winner_id,
        CASE
          WHEN mpm.winner_id = v_uid THEN GREATEST(mpm.gold_won - mpm.gold_wagered, 0)
          ELSE mpm.gold_wagered
        END AS gold_stolen,
        CASE
          WHEN v_uid = mpm.attacker_id THEN GREATEST(mpm.attacker_rating_change, 0)
          ELSE GREATEST(mpm.defender_rating_change, 0)
        END AS rep_change_winner,
        CASE
          WHEN v_uid = mpm.attacker_id THEN ABS(LEAST(mpm.attacker_rating_change, 0))
          ELSE ABS(LEAST(mpm.defender_rating_change, 0))
        END AS rep_change_loser,
        false AS is_critical_success,
        0 AS attacker_hp_remaining,
        mpm.created_at,
        ua.username AS attacker_username,
        ud.username AS defender_username
      FROM public.mekan_pvp_matches mpm
      LEFT JOIN public.users ua ON ua.auth_id = mpm.attacker_id
      LEFT JOIN public.users ud ON ud.auth_id = mpm.defender_id
      WHERE mpm.attacker_id = v_uid OR mpm.defender_id = v_uid
    ) combined
    ORDER BY created_at DESC
    LIMIT GREATEST(p_match_limit, 1)
  ) t;

  RETURN jsonb_build_object(
    'arenas', v_arenas,
    'recent_matches', v_matches
  );
END;
$$;


ALTER FUNCTION "public"."get_pvp_dashboard"("p_match_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_pvp_history"("p_limit" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_rows JSONB;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Oturum bulunamadı.', 'matches', '[]'::jsonb);
  END IF;

  SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb ORDER BY t.created_at DESC), '[]'::jsonb)
  INTO v_rows
  FROM (
    SELECT *
    FROM (
      SELECT
        pm.id::text AS id,
        'pvp'::text AS match_source,
        pm.attacker_id,
        pm.defender_id,
        pm.winner_id,
        pm.gold_stolen,
        pm.rep_change_winner,
        pm.rep_change_loser,
        COALESCE(pm.is_critical_success, false) AS is_critical_success,
        pm.created_at,
        ua.username AS attacker_username,
        ud.username AS defender_username
      FROM public.pvp_matches pm
      LEFT JOIN public.users ua ON ua.auth_id = pm.attacker_id
      LEFT JOIN public.users ud ON ud.auth_id = pm.defender_id
      WHERE pm.attacker_id = v_uid OR pm.defender_id = v_uid

      UNION ALL

      SELECT
        mpm.id::text,
        'arena'::text,
        mpm.attacker_id,
        mpm.defender_id,
        mpm.winner_id,
        CASE
          WHEN mpm.winner_id = v_uid THEN GREATEST(mpm.gold_won - mpm.gold_wagered, 0)
          ELSE mpm.gold_wagered
        END AS gold_stolen,
        CASE
          WHEN v_uid = mpm.attacker_id THEN GREATEST(mpm.attacker_rating_change, 0)
          ELSE GREATEST(mpm.defender_rating_change, 0)
        END AS rep_change_winner,
        CASE
          WHEN v_uid = mpm.attacker_id THEN ABS(LEAST(mpm.attacker_rating_change, 0))
          ELSE ABS(LEAST(mpm.defender_rating_change, 0))
        END AS rep_change_loser,
        false AS is_critical_success,
        mpm.created_at,
        ua.username AS attacker_username,
        ud.username AS defender_username
      FROM public.mekan_pvp_matches mpm
      LEFT JOIN public.users ua ON ua.auth_id = mpm.attacker_id
      LEFT JOIN public.users ud ON ud.auth_id = mpm.defender_id
      WHERE mpm.attacker_id = v_uid OR mpm.defender_id = v_uid
    ) combined
    ORDER BY created_at DESC
    LIMIT GREATEST(p_limit, 1)
  ) t;

  RETURN jsonb_build_object('success', true, 'matches', v_rows);
END;
$$;


ALTER FUNCTION "public"."get_pvp_history"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_pvp_loadout"("p_auth_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user RECORD;
  v_items JSONB;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT * INTO v_user FROM public.users WHERE auth_id = p_auth_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Oyuncu bulunamadı');
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'item_id', inv.item_id,
    'name', COALESCE(it.name_tr, it.name, inv.item_id),
    'icon', COALESCE(it.icon, ''),
    'rarity', COALESCE(it.rarity, 'common'),
    'type', COALESCE(it.type, ''),
    'enhancement_level', COALESCE(inv.enhancement_level, 0)
  ) ORDER BY it.type), '[]'::JSONB)
  INTO v_items
  FROM public.inventory inv
  LEFT JOIN public.items it ON it.id = inv.item_id
  WHERE inv.user_id = p_auth_id AND inv.is_equipped = true;

  RETURN jsonb_build_object(
    'success', true,
    'player', jsonb_build_object(
      'auth_id', v_user.auth_id,
      'username', v_user.username,
      'display_name', v_user.display_name,
      'avatar_url', v_user.avatar_url,
      'level', v_user.level,
      'power', v_user.power,
      'attack', COALESCE(v_user.attack, 10),
      'defense', COALESCE(v_user.defense, 10),
      'pvp_rating', COALESCE(v_user.pvp_rating, 1000),
      'pvp_wins', COALESCE(v_user.pvp_wins, 0),
      'pvp_losses', COALESCE(v_user.pvp_losses, 0),
      'character_class', COALESCE(v_user.character_class, '')
    ),
    'items', v_items
  );
END;
$$;


ALTER FUNCTION "public"."get_pvp_loadout"("p_auth_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_recommended_guilds"("p_limit" integer DEFAULT 15) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_results JSONB; v_limit INT;
BEGIN
  v_limit := GREATEST(1, LEAST(COALESCE(p_limit, 15), 30));
  SELECT jsonb_agg(row_data ORDER BY sort_key DESC) INTO v_results FROM (
    SELECT jsonb_build_object('id', g.id, 'guild_id', g.id, 'name', g.name, 'level', g.level, 'description', g.description, 'member_count', mc.cnt, 'max_members', COALESCE(g.max_members, 50), 'total_power', COALESCE(mc.total_pwr, 0), 'monument_level', COALESCE(g.monument_level, 0), 'min_join_power', COALESCE(g.min_join_power, 0)) AS row_data,
    (COALESCE(g.monument_level, 0) * 1000000 + COALESCE(g.level, 1) * 1000 + COALESCE(mc.total_pwr, 0))::bigint AS sort_key
    FROM public.guilds g JOIN LATERAL (SELECT COUNT(*)::INT AS cnt, COALESCE(SUM(u.power), 0)::BIGINT AS total_pwr FROM public.users u WHERE u.guild_id = g.id) mc ON true
    WHERE mc.cnt < COALESCE(g.max_members, 50) ORDER BY sort_key DESC LIMIT v_limit
  ) ranked;
  RETURN COALESCE(v_results, '[]'::jsonb);
END;
$$;


ALTER FUNCTION "public"."get_recommended_guilds"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_referral_info"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_me UUID;
  v_code TEXT;
  v_referred JSONB;
  v_claimable INTEGER := 0;
BEGIN
  v_me := auth.uid();
  IF v_me IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT referral_code INTO v_code FROM public.users WHERE auth_id = v_me;

  IF v_code IS NULL OR v_code = '' THEN
    v_code := upper(substr(md5(v_me::text || now()::text), 1, 8));
    UPDATE public.users SET referral_code = v_code WHERE auth_id = v_me;
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'username', u.username,
    'level', u.level,
    'eligible', u.level >= 5,
    'claimed', rr.referrer_claimed_at IS NOT NULL
  ) ORDER BY u.level DESC), '[]'::jsonb)
  INTO v_referred
  FROM public.users u
  LEFT JOIN public.referral_rewards rr ON rr.referred_id = u.auth_id
  WHERE u.referred_by = v_me;

  SELECT COALESCE(SUM(sub.gems), 0)::INT INTO v_claimable FROM (
    SELECT rr.referrer_gems AS gems
    FROM public.referral_rewards rr
    WHERE rr.referrer_id = v_me AND rr.referrer_claimed_at IS NULL
    UNION ALL
    SELECT 50 FROM public.users u
    WHERE u.referred_by = v_me AND u.level >= 5
      AND NOT EXISTS (SELECT 1 FROM public.referral_rewards r2 WHERE r2.referred_id = u.auth_id)
    UNION ALL
    SELECT rr.referred_gems
    FROM public.referral_rewards rr
    WHERE rr.referred_id = v_me AND rr.referred_claimed_at IS NULL
    UNION ALL
    SELECT 25 FROM public.users me
    WHERE me.auth_id = v_me AND me.referred_by IS NOT NULL AND me.level >= 5
      AND NOT EXISTS (SELECT 1 FROM public.referral_rewards r3 WHERE r3.referred_id = v_me)
  ) sub;

  RETURN jsonb_build_object(
    'success', true,
    'referral_code', v_code,
    'referred', v_referred,
    'claimable_gems', v_claimable
  );
END;
$$;


ALTER FUNCTION "public"."get_referral_info"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_territory_detail"("p_territory_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_territory json;
  v_recent_attacks json;
BEGIN
  SELECT row_to_json(t)
  INTO v_territory
  FROM (
    SELECT
      t.id,
      t.name,
      t.owner_guild_id,
      COALESCE(g.name, 'Sahipsiz') AS owner_guild,
      t.defense_power,
      t.base_defense_power,
      t.defense_line_level,
      t.reward,
      COALESCE(t.trade_income, 0) AS trade_income,
      t.defense_added_at,
      t.updated_at
    FROM public.guild_war_territories t
    LEFT JOIN public.guilds g ON g.id = t.owner_guild_id
    WHERE t.id = p_territory_id
  ) t;

  IF v_territory IS NULL THEN
    RETURN json_build_object('error', 'Bölge bulunamadı.');
  END IF;

  SELECT COALESCE(json_agg(row_to_json(a)), '[]'::json)
  INTO v_recent_attacks
  FROM (
    SELECT
      l.id,
      l.attacker_guild_id,
      ag.name AS attacker_guild_name,
      l.defender_guild_id,
      dg.name AS defender_guild_name,
      l.attack_power,
      l.defense_power,
      l.success,
      l.points_gained,
      l.created_at
    FROM public.guild_war_attack_logs l
    JOIN public.guilds ag ON ag.id = l.attacker_guild_id
    LEFT JOIN public.guilds dg ON dg.id = l.defender_guild_id
    WHERE l.territory_id = p_territory_id
    ORDER BY l.created_at DESC
    LIMIT 5
  ) a;

  RETURN json_build_object(
    'territory', v_territory,
    'recent_attacks', v_recent_attacks
  );
END;
$$;


ALTER FUNCTION "public"."get_territory_detail"("p_territory_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_tournament_bracket"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_tournament_id UUID;
  v_tournament RECORD;
  v_rounds JSONB := '[]'::jsonb;
  v_champion_name TEXT := '';
  rec_round RECORD;
  v_matches JSONB;
BEGIN
  v_tournament_id := public.ensure_current_pvp_tournament();

  SELECT * INTO v_tournament
  FROM public.pvp_tournaments
  WHERE id = v_tournament_id;

  PERFORM public.seed_pvp_tournament_bracket(v_tournament_id);

  IF v_tournament.champion_user_id IS NOT NULL THEN
    SELECT username INTO v_champion_name
    FROM public.users
    WHERE auth_id = v_tournament.champion_user_id;
  ELSIF EXISTS (
    SELECT 1 FROM public.pvp_tournament_matches
    WHERE tournament_id = v_tournament_id AND round_number = (
      SELECT MAX(round_number) FROM public.pvp_tournament_matches WHERE tournament_id = v_tournament_id
    ) AND status = 'completed' AND winner_id IS NOT NULL
  ) THEN
    SELECT u.username INTO v_champion_name
    FROM public.pvp_tournament_matches m
    JOIN public.users u ON u.auth_id = m.winner_id
    WHERE m.tournament_id = v_tournament_id
      AND m.round_number = (SELECT MAX(round_number) FROM public.pvp_tournament_matches WHERE tournament_id = v_tournament_id)
      AND m.status = 'completed'
    ORDER BY m.match_order
    LIMIT 1;
  END IF;

  FOR rec_round IN
    SELECT DISTINCT round_number, round_name
    FROM public.pvp_tournament_matches
    WHERE tournament_id = v_tournament_id
    ORDER BY round_number
  LOOP
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'id', m.id,
      'player1_name', COALESCE(u1.username, CASE WHEN m.player1_id IS NULL THEN 'BYE' ELSE '?' END),
      'player2_name', COALESCE(u2.username, CASE WHEN m.player2_id IS NULL THEN 'BYE' ELSE '?' END),
      'player1_score', m.player1_score,
      'player2_score', m.player2_score,
      'winner_name', COALESCE(uw.username, ''),
      'status', m.status
    ) ORDER BY m.match_order), '[]'::jsonb)
    INTO v_matches
    FROM public.pvp_tournament_matches m
    LEFT JOIN public.users u1 ON u1.auth_id = m.player1_id
    LEFT JOIN public.users u2 ON u2.auth_id = m.player2_id
    LEFT JOIN public.users uw ON uw.auth_id = m.winner_id
    WHERE m.tournament_id = v_tournament_id
      AND m.round_number = rec_round.round_number;

    v_rounds := v_rounds || jsonb_build_array(jsonb_build_object(
      'title', rec_round.round_name,
      'round_number', rec_round.round_number,
      'matches', v_matches
    ));
  END LOOP;

  RETURN jsonb_build_object(
    'tournament_id', v_tournament_id,
    'tournament_name', v_tournament.name,
    'champion_name', COALESCE(v_champion_name, ''),
    'registration_open', v_tournament.registration_open,
    'status', v_tournament.status,
    'participant_count', (
      SELECT COUNT(*) FROM public.pvp_tournament_participants WHERE tournament_id = v_tournament_id
    ),
    'prize_pool', v_tournament.prize_pool,
    'rounds', v_rounds
  );
END;
$$;


ALTER FUNCTION "public"."get_tournament_bracket"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_tournament_participants"("p_tournament_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_result json;
BEGIN
  SELECT COALESCE(json_agg(row_to_json(t)), '[]'::json)
  INTO v_result
  FROM (
    SELECT
      p.id,
      p.guild_id,
      g.name AS guild_name,
      p.joined_at
    FROM public.guild_war_participants p
    JOIN public.guilds g ON g.id = p.guild_id
    WHERE p.tournament_id = p_tournament_id
    ORDER BY p.joined_at ASC
  ) t;

  RETURN v_result;
END;
$$;


