CREATE OR REPLACE FUNCTION "public"."get_trade_history"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid UUID;
  v_rows jsonb;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RETURN '[]'::jsonb;
  END IF;

  SELECT jsonb_agg(row_json ORDER BY updated_at DESC)
  INTO v_rows
  FROM (
    SELECT
      ts.updated_at,
      jsonb_build_object(
        'id', ts.id,
        'date', to_char(ts.updated_at, 'YYYY-MM-DD'),
        'partner', CASE WHEN ts.initiator_id = v_uid
                        THEN (SELECT username FROM public.users WHERE auth_id = ts.partner_id)
                        ELSE (SELECT username FROM public.users WHERE auth_id = ts.initiator_id) END,
        'status', CASE WHEN ts.status = 'completed' THEN 'completed' ELSE 'cancelled' END,
        'my_gold', CASE WHEN ts.initiator_id = v_uid
                        THEN COALESCE(ts.initiator_gold, 0)
                        ELSE COALESCE(ts.partner_gold, 0) END,
        'their_gold', CASE WHEN ts.initiator_id = v_uid
                           THEN COALESCE(ts.partner_gold, 0)
                           ELSE COALESCE(ts.initiator_gold, 0) END,
        'my_items', COALESCE((
          SELECT jsonb_agg(jsonb_build_object(
            'name', COALESCE(it.name_tr, it.name, i.item_id),
            'item_id', i.item_id,
            'icon', COALESCE(it.icon, ''),
            'item_type', lower(COALESCE(it.type, 'misc')),
            'quantity', COALESCE(i.quantity, 1),
            'rarity', COALESCE(it.rarity, 'common')
          ) ORDER BY ti.created_at)
          FROM public.trade_items ti
          JOIN public.inventory i ON i.row_id = ti.inventory_row_id
          LEFT JOIN public.items it ON it.id = i.item_id
          WHERE ti.session_id = ts.id AND ti.owner_id = v_uid
        ), '[]'::jsonb),
        'their_items', COALESCE((
          SELECT jsonb_agg(jsonb_build_object(
            'name', COALESCE(it.name_tr, it.name, i.item_id),
            'item_id', i.item_id,
            'icon', COALESCE(it.icon, ''),
            'item_type', lower(COALESCE(it.type, 'misc')),
            'quantity', COALESCE(i.quantity, 1),
            'rarity', COALESCE(it.rarity, 'common')
          ) ORDER BY ti.created_at)
          FROM public.trade_items ti
          JOIN public.inventory i ON i.row_id = ti.inventory_row_id
          LEFT JOIN public.items it ON it.id = i.item_id
          WHERE ti.session_id = ts.id AND ti.owner_id <> v_uid
        ), '[]'::jsonb)
      ) AS row_json
    FROM public.trade_sessions ts
    WHERE (ts.initiator_id = v_uid OR ts.partner_id = v_uid)
      AND ts.status IN ('completed', 'cancelled')
    ORDER BY ts.updated_at DESC
    LIMIT 30
  ) sub;

  RETURN COALESCE(v_rows, '[]'::jsonb);
END;
$$;


ALTER FUNCTION "public"."get_trade_history"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_trade_session_details"("p_session_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid UUID;
  v_sess RECORD;
  v_my_items jsonb;
  v_partner_items jsonb;
  v_partner_name text;
  v_my_gold bigint;
  v_partner_gold bigint;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Oturum bulunamadı.');
  END IF;

  SELECT * INTO v_sess FROM public.trade_sessions WHERE id = p_session_id;
  IF v_sess IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Ticaret oturumu bulunamadı.');
  END IF;
  IF v_uid <> v_sess.initiator_id AND v_uid <> v_sess.partner_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'Bu ticaretin katılımcısı değilsiniz.');
  END IF;

  IF v_uid = v_sess.initiator_id THEN
    SELECT username INTO v_partner_name FROM public.users WHERE auth_id = v_sess.partner_id;
    v_my_gold := v_sess.initiator_gold;
    v_partner_gold := v_sess.partner_gold;
  ELSE
    SELECT username INTO v_partner_name FROM public.users WHERE auth_id = v_sess.initiator_id;
    v_my_gold := v_sess.partner_gold;
    v_partner_gold := v_sess.initiator_gold;
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'row_id', i.row_id,
    'item_id', i.item_id,
    'name', COALESCE(it.name_tr, it.name, i.item_id),
    'icon', COALESCE(it.icon, ''),
    'item_type', lower(COALESCE(it.type, 'misc')),
    'quantity', COALESCE(i.quantity, 1),
    'rarity', COALESCE(it.rarity, 'common')
  ) ORDER BY ti.created_at), '[]'::jsonb)
  INTO v_my_items
  FROM public.trade_items ti
  JOIN public.inventory i ON i.row_id = ti.inventory_row_id
  LEFT JOIN public.items it ON it.id = i.item_id
  WHERE ti.session_id = p_session_id AND ti.owner_id = v_uid;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'row_id', i.row_id,
    'item_id', i.item_id,
    'name', COALESCE(it.name_tr, it.name, i.item_id),
    'icon', COALESCE(it.icon, ''),
    'item_type', lower(COALESCE(it.type, 'misc')),
    'quantity', COALESCE(i.quantity, 1),
    'rarity', COALESCE(it.rarity, 'common')
  ) ORDER BY ti.created_at), '[]'::jsonb)
  INTO v_partner_items
  FROM public.trade_items ti
  JOIN public.inventory i ON i.row_id = ti.inventory_row_id
  LEFT JOIN public.items it ON it.id = i.item_id
  WHERE ti.session_id = p_session_id AND ti.owner_id <> v_uid;

  RETURN jsonb_build_object(
    'success', true,
    'status', v_sess.status,
    'my_confirmed', CASE
      WHEN v_uid = v_sess.initiator_id THEN v_sess.initiator_confirmed
      ELSE v_sess.partner_confirmed
    END,
    'partner_confirmed', CASE
      WHEN v_uid = v_sess.initiator_id THEN v_sess.partner_confirmed
      ELSE v_sess.initiator_confirmed
    END,
    'partner_name', COALESCE(v_partner_name, ''),
    'my_items', v_my_items,
    'partner_items', v_partner_items,
    'my_gold', COALESCE(v_my_gold, 0),
    'partner_gold', COALESCE(v_partner_gold, 0),
    'is_initiator', v_uid = v_sess.initiator_id
  );
END;
$$;


ALTER FUNCTION "public"."get_trade_session_details"("p_session_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_unseen_friendship_events"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_me UUID;
  v_rows JSONB;
BEGIN
  v_me := auth.uid();
  IF v_me IS NULL THEN
    RETURN '[]'::JSONB;
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'event_id', e.id,
    'event_type', e.event_type,
    'friendship_id', e.friendship_id,
    'created_at', e.created_at,
    'actor', jsonb_build_object(
      'auth_id', u.auth_id,
      'username', u.username,
      'display_name', u.display_name,
      'avatar_url', u.avatar_url,
      'level', u.level
    )
  ) ORDER BY e.created_at DESC), '[]'::JSONB)
  INTO v_rows
  FROM public.friendship_events e
  JOIN public.users u ON u.auth_id = e.actor_id
  WHERE e.recipient_id = v_me
    AND e.seen_at IS NULL;

  RETURN v_rows;
END;
$$;


ALTER FUNCTION "public"."get_unseen_friendship_events"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_unseen_pvp_results"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_me UUID;
  v_rows JSONB;
BEGIN
  v_me := auth.uid();
  IF v_me IS NULL THEN
    RETURN '[]'::JSONB;
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'invite_id', i.id,
    'wager', i.wager,
    'status', i.status,
    'result', i.result,
    'opponent', jsonb_build_object(
      'auth_id', u.auth_id,
      'username', u.username,
      'display_name', u.display_name,
      'avatar_url', u.avatar_url,
      'level', u.level,
      'power', u.power,
      'pvp_rating', COALESCE(u.pvp_rating, 1000)
    )
  ) ORDER BY i.created_at ASC), '[]'::JSONB)
  INTO v_rows
  FROM public.pvp_invites i
  JOIN public.users u ON u.auth_id = i.target_id
  WHERE i.challenger_id = v_me
    AND i.challenger_seen = false
    AND i.status IN ('accepted', 'declined');

  RETURN v_rows;
END;
$$;


ALTER FUNCTION "public"."get_unseen_pvp_results"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."grant_monument_boss_blueprint"("p_guild_id" "uuid", "p_zone" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_chance NUMERIC; v_bp_type TEXT; v_roll NUMERIC;
BEGIN
  IF p_guild_id IS NULL OR COALESCE(p_zone, 0) < 5 THEN RETURN; END IF;
  v_chance := 0.005 + (p_zone - 5) * 0.015;
  IF random() > v_chance THEN RETURN; END IF;
  IF p_zone = 5 THEN v_bp_type := 'phoenix';
  ELSIF p_zone = 6 THEN v_bp_type := 'leviathan';
  ELSE
    v_roll := random();
    IF v_roll < 0.40 THEN v_bp_type := 'titan';
    ELSIF v_roll < 0.70 THEN v_bp_type := 'world_eater';
    ELSE v_bp_type := 'eternal';
    END IF;
  END IF;
  INSERT INTO public.guild_blueprints (guild_id, blueprint_type, fragments, fragments_required)
  VALUES (p_guild_id, v_bp_type, 1, 100)
  ON CONFLICT (guild_id, blueprint_type) DO UPDATE SET fragments = public.guild_blueprints.fragments + 1;
END;
$$;


ALTER FUNCTION "public"."grant_monument_boss_blueprint"("p_guild_id" "uuid", "p_zone" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."grant_monument_craft_byproduct"("p_auth_id" "uuid", "p_output_rarity" "text", "p_quantity" integer DEFAULT 1) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_mystical INT := 0;
BEGIN
  IF lower(COALESCE(p_output_rarity,'')) IN ('epic','legendary','mythic') THEN
    v_mystical := GREATEST(1, LEAST(5, p_quantity));
    PERFORM public.grant_monument_resource_items(p_auth_id, 0, v_mystical, 0);
  END IF;
END;
$$;


ALTER FUNCTION "public"."grant_monument_craft_byproduct"("p_auth_id" "uuid", "p_output_rarity" "text", "p_quantity" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."grant_monument_facility_collect"("p_auth_id" "uuid", "p_facility_level" integer, "p_collected_count" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_structural INT; v_mystical INT := 0;
BEGIN
  IF p_collected_count <= 0 THEN RETURN; END IF;
  v_structural := GREATEST(1, LEAST(5, 1 + p_collected_count / 10));
  IF p_facility_level >= 7 THEN v_mystical := GREATEST(0, LEAST(3, p_facility_level - 6)); END IF;
  PERFORM public.grant_monument_resource_items(p_auth_id, v_structural, v_mystical, 0);
END;
$$;


ALTER FUNCTION "public"."grant_monument_facility_collect"("p_auth_id" "uuid", "p_facility_level" integer, "p_collected_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."grant_monument_resource_items"("p_auth_id" "uuid", "p_structural" integer DEFAULT 0, "p_mystical" integer DEFAULT 0, "p_critical" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_res JSONB;
BEGIN
  IF p_structural > 0 THEN
    v_res := public.add_inventory_item_v2(jsonb_build_object('item_id','resource_structural','quantity',p_structural,'allow_stack',true), NULL);
    IF COALESCE((v_res->>'success')::boolean,false) = false THEN RETURN jsonb_build_object('success', false, 'error', COALESCE(v_res->>'error','structural add failed')); END IF;
  END IF;
  IF p_mystical > 0 THEN
    v_res := public.add_inventory_item_v2(jsonb_build_object('item_id','resource_mystical','quantity',p_mystical,'allow_stack',true), NULL);
    IF COALESCE((v_res->>'success')::boolean,false) = false THEN RETURN jsonb_build_object('success', false, 'error', COALESCE(v_res->>'error','mystical add failed')); END IF;
  END IF;
  IF p_critical > 0 THEN
    v_res := public.add_inventory_item_v2(jsonb_build_object('item_id','resource_critical','quantity',p_critical,'allow_stack',true), NULL);
    IF COALESCE((v_res->>'success')::boolean,false) = false THEN RETURN jsonb_build_object('success', false, 'error', COALESCE(v_res->>'error','critical add failed')); END IF;
  END IF;
  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."grant_monument_resource_items"("p_auth_id" "uuid", "p_structural" integer, "p_mystical" integer, "p_critical" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guild_size_multiplier"("p_member_count" integer) RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT CASE
    WHEN p_member_count <= 10 THEN 0.35
    WHEN p_member_count <= 20 THEN 0.55
    WHEN p_member_count <= 30 THEN 0.75
    WHEN p_member_count <= 40 THEN 0.90
    ELSE 1.00
  END;
$$;


ALTER FUNCTION "public"."guild_size_multiplier"("p_member_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_new_user"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_ref_code TEXT;
    v_referrer UUID;
BEGIN
    v_ref_code := NEW.raw_user_meta_data->>'referral_code';
    IF v_ref_code IS NOT NULL AND trim(v_ref_code) != '' THEN
        SELECT auth_id INTO v_referrer
        FROM public.users
        WHERE upper(referral_code) = upper(trim(v_ref_code))
        LIMIT 1;
    END IF;

    INSERT INTO public.users (auth_id, email, username, display_name, referral_code, referred_by)
    VALUES (
        NEW.id,
        NEW.email,
        COALESCE(NEW.raw_user_meta_data->>'username', split_part(NEW.email, '@', 1)),
        COALESCE(NEW.raw_user_meta_data->>'display_name', split_part(NEW.email, '@', 1)),
        upper(substr(md5(NEW.id::text || now()::text), 1, 8)),
        v_referrer
    )
    ON CONFLICT (auth_id) DO NOTHING;
    RETURN NEW;
EXCEPTION
    WHEN OTHERS THEN
        RAISE WARNING 'Failed to create game profile for user %: %', NEW.id, SQLERRM;
        RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."handle_new_user"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_xp_level_progression"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_old_level integer;
  v_new_level integer;
  v_levels_gained integer;
  v_next_level_total_xp integer;
  v_class_key text;
  v_attack_gain integer := 0;
  v_defense_gain integer := 0;
  v_health_gain integer := 0;
  v_luck_gain integer := 0;
  v_level_cap constant integer := 70;
BEGIN
  IF COALESCE(NEW.xp, 0) <= COALESCE(OLD.xp, 0) THEN
    RETURN NEW;
  END IF;

  v_old_level := GREATEST(COALESCE(OLD.level, 1), 1);
  v_new_level := v_old_level;

  IF v_old_level >= v_level_cap THEN
    NEW.level := v_old_level;
    RETURN NEW;
  END IF;

  LOOP
    EXIT WHEN v_new_level >= v_level_cap;
    v_next_level_total_xp := public.total_xp_for_level(v_new_level + 1);
    EXIT WHEN COALESCE(NEW.xp, 0) < v_next_level_total_xp;
    v_new_level := v_new_level + 1;
  END LOOP;

  v_levels_gained := v_new_level - v_old_level;

  IF v_levels_gained <= 0 THEN
    RETURN NEW;
  END IF;

  NEW.level := v_new_level;

  NEW.stat_points := COALESCE(NEW.stat_points, 0) + (3 * v_levels_gained);

  v_class_key := lower(COALESCE(NEW.character_class, OLD.character_class, ''));
  IF v_class_key <> '' THEN
    SELECT
      COALESCE(attack_per_level, 0),
      COALESCE(defense_per_level, 0),
      COALESCE(health_per_level, 0),
      COALESCE(luck_per_level, 0)
    INTO
      v_attack_gain,
      v_defense_gain,
      v_health_gain,
      v_luck_gain
    FROM public.character_classes
    WHERE id = v_class_key
    LIMIT 1;

    IF NOT FOUND THEN
      CASE v_class_key
        WHEN 'warrior' THEN
          v_attack_gain := 3; v_defense_gain := 2; v_health_gain := 15; v_luck_gain := 1;
        WHEN 'alchemist' THEN
          v_attack_gain := 1; v_defense_gain := 2; v_health_gain := 20; v_luck_gain := 2;
        WHEN 'shadow' THEN
          v_attack_gain := 2; v_defense_gain := 1; v_health_gain := 12; v_luck_gain := 3;
        ELSE
          v_attack_gain := 0; v_defense_gain := 0; v_health_gain := 0; v_luck_gain := 0;
      END CASE;
    END IF;

    NEW.attack := COALESCE(NEW.attack, 0) + (v_attack_gain * v_levels_gained);
    NEW.defense := COALESCE(NEW.defense, 0) + (v_defense_gain * v_levels_gained);
    NEW.max_health := COALESCE(NEW.max_health, 0) + (v_health_gain * v_levels_gained);
    NEW.health := COALESCE(NEW.health, 0) + (v_health_gain * v_levels_gained);
    NEW.luck := COALESCE(NEW.luck, 0) + (v_luck_gain * v_levels_gained);
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."handle_xp_level_progression"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."has_chat_permission"("p_actor_user_id" "uuid", "p_permission" "text", "p_channel" "text", "p_guild_id" "uuid" DEFAULT NULL::"uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor RECORD;
BEGIN
  SELECT id, guild_id, guild_role INTO v_actor FROM public.users WHERE id = p_actor_user_id;
  IF NOT FOUND THEN
    RETURN false;
  END IF;

  IF p_channel = 'guild'
     AND v_actor.guild_id = p_guild_id
     AND COALESCE(v_actor.guild_role, '') IN ('leader', 'commander')
  THEN
    RETURN true;
  END IF;

  RETURN EXISTS (
    SELECT 1
    FROM public.chat_moderators cm
    WHERE cm.user_id = p_actor_user_id
      AND cm.revoked_at IS NULL
      AND (
        cm.scope = 'global'
        OR (cm.scope = 'channel' AND cm.channel = p_channel)
        OR (cm.scope = 'guild' AND p_channel = 'guild' AND cm.guild_id = p_guild_id)
      )
      AND (
        p_permission = 'delete' AND cm.can_delete
        OR p_permission = 'ban' AND cm.can_ban
        OR p_permission = 'manage_filters' AND cm.can_manage_filters
        OR p_permission = 'manage_moderators' AND cm.can_manage_moderators
      )
  );
END;
$$;


ALTER FUNCTION "public"."has_chat_permission"("p_actor_user_id" "uuid", "p_permission" "text", "p_channel" "text", "p_guild_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."heal_with_gems"() RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_user_id uuid; v_hospital_until timestamptz; v_gems int; v_hospital_count int; v_level int; v_rate int; v_minutes_left int; v_gem_cost int;
BEGIN
    v_user_id := auth.uid();
    IF v_user_id IS NULL THEN RETURN json_build_object('success', false, 'error', 'Not authenticated'); END IF;
    SELECT hospital_until, gems, COALESCE(hospital_lifetime_count, 0), COALESCE(level, 1) INTO v_hospital_until, v_gems, v_hospital_count, v_level FROM public.users WHERE auth_id = v_user_id;
    IF v_hospital_until IS NULL OR v_hospital_until <= now() THEN
        UPDATE public.users SET hospital_until = NULL, hospital_reason = NULL WHERE auth_id = v_user_id;
        RETURN json_build_object('success', true);
    END IF;
    IF v_hospital_count <= 2 THEN
        UPDATE public.users SET hospital_until = NULL, hospital_reason = NULL WHERE auth_id = v_user_id;
        RETURN json_build_object('success', true, 'was_free', true, 'cost', 0, 'free_discharges_remaining', GREATEST(0, 2 - v_hospital_count));
    END IF;
    v_minutes_left := CEIL(EXTRACT(EPOCH FROM (v_hospital_until - now())) / 60.0);
    IF v_minutes_left < 1 THEN v_minutes_left := 1; END IF;
    v_rate := CASE WHEN v_level < 10 THEN 1 WHEN v_level < 20 THEN 2 ELSE 3 END;
    v_gem_cost := v_minutes_left * v_rate;
    IF v_gems < v_gem_cost THEN RETURN json_build_object('success', false, 'error', 'Yetersiz elmas. Gerekli: ' || v_gem_cost); END IF;
    UPDATE public.users SET gems = gems - v_gem_cost, hospital_until = NULL, hospital_reason = NULL WHERE auth_id = v_user_id;
    RETURN json_build_object('success', true, 'was_free', false, 'cost', v_gem_cost, 'free_discharges_remaining', 0);
END; $$;


ALTER FUNCTION "public"."heal_with_gems"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."hide_dm_conversation"("p_peer_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user public.users%ROWTYPE;
BEGIN
  v_user := public.get_current_chat_user();

  IF p_peer_user_id IS NULL OR p_peer_user_id = v_user.id THEN
    RETURN jsonb_build_object('success', false, 'error', 'Gecersiz hedef');
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.users WHERE id = p_peer_user_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Kullanici bulunamadi');
  END IF;

  INSERT INTO public.chat_dm_conversation_hides (user_id, peer_user_id, hidden_at)
  VALUES (v_user.id, p_peer_user_id, now())
  ON CONFLICT (user_id, peer_user_id) DO UPDATE SET hidden_at = excluded.hidden_at;

  UPDATE public.chat_messages
  SET read_at = now()
  WHERE channel = 'dm'
    AND recipient_user_id = v_user.id
    AND sender_user_id = p_peer_user_id
    AND read_at IS NULL
    AND deleted_at IS NULL;

  PERFORM public.write_chat_audit(
    v_user.id,
    'dm_conversation_hidden',
    p_peer_user_id,
    NULL,
    '{}'::jsonb
  );

  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."hide_dm_conversation"("p_peer_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."hide_dm_message"("p_message_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user public.users%ROWTYPE;
  v_message RECORD;
BEGIN
  IF p_message_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Gecersiz mesaj');
  END IF;

  v_user := public.get_current_chat_user();

  SELECT id, channel, sender_user_id, recipient_user_id, deleted_at, read_at, is_system
  INTO v_message
  FROM public.chat_messages
  WHERE id = p_message_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Mesaj bulunamadi');
  END IF;

  IF v_message.deleted_at IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Mesaj zaten silinmis');
  END IF;

  IF v_message.is_system THEN
    RETURN jsonb_build_object('success', false, 'error', 'Sistem mesaji silinemez');
  END IF;

  IF v_message.channel <> 'dm' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Yalnizca ozel mesajlar silinebilir');
  END IF;

  IF v_user.id NOT IN (v_message.sender_user_id, v_message.recipient_user_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Bu mesaji silme yetkiniz yok');
  END IF;

  INSERT INTO public.chat_dm_message_hides (user_id, message_id)
  VALUES (v_user.id, p_message_id)
  ON CONFLICT (user_id, message_id) DO NOTHING;

  IF v_user.id = v_message.recipient_user_id AND v_message.read_at IS NULL THEN
    UPDATE public.chat_messages
    SET read_at = now()
    WHERE id = p_message_id;
  END IF;

  PERFORM public.write_chat_audit(
    v_user.id,
    'dm_message_hidden',
    CASE WHEN v_user.id = v_message.sender_user_id THEN v_message.recipient_user_id ELSE v_message.sender_user_id END,
    p_message_id,
    '{}'::jsonb
  );

  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."hide_dm_message"("p_message_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."increment_facility_suspicion"("p_facility_id" "uuid", "p_amount" integer DEFAULT 5) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_user_id UUID;
    v_new_suspicion INT;
    v_global_suspicion INT;
BEGIN
    v_user_id := auth.uid();
    
    UPDATE public.facilities
    SET suspicion_level = LEAST(suspicion_level + p_amount, 100)
    WHERE id = p_facility_id AND user_id = v_user_id
    RETURNING suspicion_level INTO v_new_suspicion;
    
    IF v_new_suspicion IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Facility not found or not owned');
    END IF;
    
    -- NOTE: Don't update global_suspicion_level here!
    -- Client handles risk calculation and syncs via update_global_suspicion_level RPC
    -- This keeps risk sync centralized and prevents conflicts
    
    RETURN jsonb_build_object(
        'success', true,
        'facility_suspicion', v_new_suspicion,
        'global_suspicion', 0,
        'message', CASE WHEN v_new_suspicion >= 80 THEN 'High suspicion! Risk of prison!' ELSE 'OK' END
    );
END;
$$;


ALTER FUNCTION "public"."increment_facility_suspicion"("p_facility_id" "uuid", "p_amount" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."increment_quest_progress"("p_user_id" "uuid", "p_trigger_event" "text", "p_amount" integer DEFAULT 1) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  UPDATE public.player_quests pq
  SET progress = LEAST(pq.progress + p_amount, pq.progress_max)
  FROM public.quests q
  WHERE pq.quest_id = q.quest_id
    AND pq.user_id = p_user_id
    AND pq.status = 'active'
    AND q.trigger_event = p_trigger_event;
END;
$$;


ALTER FUNCTION "public"."increment_quest_progress"("p_user_id" "uuid", "p_trigger_event" "text", "p_amount" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."initiate_trade"("target_username" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid UUID;
  v_partner_id UUID;
  v_partner_name text;
  v_session_id UUID;
  v_status text;
  v_initiator_id UUID;
  v_partner_online boolean;
  v_last_active timestamptz;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Oturum bulunamadı.');
  END IF;

  PERFORM public._trade_expire_stale_sessions();

  IF public._trade_is_banned(v_uid) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Ticaret yasağınız var. 12 saat sonra tekrar deneyin.');
  END IF;

  SELECT auth_id, username INTO v_partner_id, v_partner_name
  FROM public.users WHERE username = target_username;

  IF v_partner_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Oyuncu bulunamadı: ' || target_username);
  END IF;
  IF v_partner_id = v_uid THEN
    RETURN jsonb_build_object('success', false, 'error', 'Kendinizle ticaret yapamazsınız.');
  END IF;

  IF public._trade_is_blocked(v_uid, v_partner_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Bu oyuncu ile ticaret engelli.');
  END IF;

  IF public._trade_is_banned(v_partner_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Karşı oyuncunun ticaret yasağı var.');
  END IF;

  SELECT id, status, initiator_id
  INTO v_session_id, v_status, v_initiator_id
  FROM public.trade_sessions
  WHERE (
      (status = 'pending')
      OR (status = 'active' AND partner_accepted_at IS NOT NULL)
    )
    AND ((initiator_id = v_uid AND partner_id = v_partner_id)
      OR (initiator_id = v_partner_id AND partner_id = v_uid))
  ORDER BY updated_at DESC
  LIMIT 1;

  IF v_session_id IS NOT NULL THEN
    IF v_status = 'pending' AND v_initiator_id <> v_uid THEN
      RETURN jsonb_build_object(
        'success', false,
        'error', 'Size gelen ticaret davetini popup üzerinden kabul edin.'
      );
    END IF;
    IF v_status = 'pending' AND v_initiator_id = v_uid THEN
      RETURN jsonb_build_object(
        'success', true,
        'session_id', v_session_id,
        'partner_name', v_partner_name,
        'status', v_status,
        'is_initiator', true
      );
    END IF;
    IF v_status = 'active' THEN
      RETURN jsonb_build_object(
        'success', true,
        'session_id', v_session_id,
        'partner_name', v_partner_name,
        'status', v_status,
        'is_initiator', v_initiator_id = v_uid
      );
    END IF;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.trade_sessions ts
    WHERE (
        (ts.initiator_id = v_uid AND ts.status = 'pending')
        OR (ts.partner_id = v_uid AND ts.status = 'pending' AND ts.partner_accepted_at IS NULL)
        OR (
          (ts.initiator_id = v_uid OR ts.partner_id = v_uid)
          AND ts.status = 'active'
          AND ts.partner_accepted_at IS NOT NULL
        )
      )
      AND NOT (
        (ts.initiator_id = v_uid AND ts.partner_id = v_partner_id)
        OR (ts.initiator_id = v_partner_id AND ts.partner_id = v_uid)
      )
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Zaten aktif bir ticaretiniz var.');
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.trade_sessions ts
    WHERE (
        (ts.initiator_id = v_partner_id AND ts.status = 'pending')
        OR (ts.partner_id = v_partner_id AND ts.status = 'pending' AND ts.partner_accepted_at IS NULL)
        OR (
          (ts.initiator_id = v_partner_id OR ts.partner_id = v_partner_id)
          AND ts.status = 'active'
          AND ts.partner_accepted_at IS NOT NULL
        )
      )
      AND NOT (
        (ts.initiator_id = v_uid AND ts.partner_id = v_partner_id)
        OR (ts.initiator_id = v_partner_id AND ts.partner_id = v_uid)
      )
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Oyuncunun zaten aktif bir ticareti var.');
  END IF;

  SELECT COALESCE(u.is_online, false), u.last_active_at
  INTO v_partner_online, v_last_active
  FROM public.users u
  WHERE u.auth_id = v_partner_id;

  IF NOT v_partner_online
     OR v_last_active IS NULL
     OR v_last_active < now() - interval '5 minutes' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Oyuncu çevrimiçi değil.');
  END IF;

  INSERT INTO public.trade_sessions (initiator_id, partner_id, status)
  VALUES (v_uid, v_partner_id, 'pending')
  RETURNING id, status INTO v_session_id, v_status;

  RETURN jsonb_build_object(
    'success', true,
    'session_id', v_session_id,
    'partner_name', v_partner_name,
    'status', v_status,
    'is_initiator', true
  );
END;
$$;


ALTER FUNCTION "public"."initiate_trade"("target_username" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."is_user_online"("p_is_online" boolean, "p_last_active_at" timestamp with time zone) RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
