CREATE OR REPLACE FUNCTION "public"."join_guild"("p_guild_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_auth_id UUID; v_user RECORD; v_guild RECORD; v_members BIGINT; v_power INT;
BEGIN
  v_auth_id := auth.uid();
  IF v_auth_id IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'Kimlik dogrulama gerekli'); END IF;
  SELECT id, guild_id, power FROM public.users WHERE auth_id = v_auth_id INTO v_user;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'Kullanici bulunamadi'); END IF;
  IF v_user.guild_id IS NOT NULL THEN RETURN jsonb_build_object('success', false, 'error', 'Zaten bir lonca uyesisiniz. Oncelikle loncayi terk edin'); END IF;
  SELECT * FROM public.guilds WHERE id = p_guild_id INTO v_guild;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'Lonca bulunamadi'); END IF;
  v_power := COALESCE(v_user.power, 0);
  IF COALESCE(v_guild.min_join_power, 0) > 0 AND v_power < v_guild.min_join_power THEN
    RETURN jsonb_build_object('success', false, 'error', format('Bu lonca en az %s guc gerektiriyor (sizin gucunuz: %s)', v_guild.min_join_power, v_power));
  END IF;
  SELECT COUNT(*) INTO v_members FROM public.users WHERE guild_id = p_guild_id;
  IF v_members >= COALESCE(v_guild.max_members, 50) THEN RETURN jsonb_build_object('success', false, 'error', 'Lonca dolu (maks. 50 uye)'); END IF;
  UPDATE public.users SET guild_id = p_guild_id, guild_role = 'member' WHERE auth_id = v_auth_id;
  INSERT INTO public.guild_contributions (guild_id, user_id) VALUES (p_guild_id, v_auth_id) ON CONFLICT (guild_id, user_id) DO NOTHING;
  PERFORM public.sync_guild_member_monument_stats(p_guild_id);
  RETURN jsonb_build_object('success', true, 'guild_id', p_guild_id, 'name', v_guild.name, 'role', 'member');
END;
$$;


ALTER FUNCTION "public"."join_guild"("p_guild_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."join_guild_war"("p_tournament_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$DECLARE
  v_player_id uuid := auth.uid();
  v_guild_id uuid;
BEGIN
  -- Oyuncunun loncasını bul
  SELECT guild_id INTO v_guild_id 
  FROM public.users 
  WHERE auth_id = v_player_id;

  IF v_guild_id IS NULL THEN
    RETURN json_build_object('success', false, 'error', 'Bir loncaya üye değilsiniz.');
  END IF;

  -- Zaten katılmış mı?
  IF EXISTS (
    SELECT 1 FROM public.guild_war_participants 
    WHERE tournament_id = p_tournament_id AND guild_id = v_guild_id
  ) THEN
    RETURN json_build_object('success', false, 'error', 'Zaten bu turnuvaya katıldınız.');
  END IF;

  -- Katıl
  INSERT INTO public.guild_war_participants (tournament_id, guild_id)
  VALUES (p_tournament_id, v_guild_id);

  -- Lonca sayısını güncelle
  UPDATE public.guild_war_tournaments 
  SET guild_count = guild_count + 1 
  WHERE id = p_tournament_id;

  RETURN json_build_object('success', true, 'message', 'Turnuvaya katıldınız!');
END;$$;


ALTER FUNCTION "public"."join_guild_war"("p_tournament_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."join_pvp_tournament"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_user RECORD;
  v_tournament_id UUID;
  v_tournament RECORD;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Oturum bulunamadı.');
  END IF;

  SELECT * INTO v_user FROM public.users WHERE auth_id = v_uid;
  IF v_user IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Profil bulunamadı.');
  END IF;

  IF v_user.level < 10 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Turnuva için minimum seviye 10.');
  END IF;

  IF v_user.hospital_until IS NOT NULL AND v_user.hospital_until > now() THEN
    RETURN jsonb_build_object('success', false, 'error', 'Hastanedeyken turnuvaya katılamazsınız.');
  END IF;

  IF v_user.prison_until IS NOT NULL AND v_user.prison_until > now() THEN
    RETURN jsonb_build_object('success', false, 'error', 'Hapishanedeyken turnuvaya katılamazsınız.');
  END IF;

  v_tournament_id := public.ensure_current_pvp_tournament();

  SELECT * INTO v_tournament FROM public.pvp_tournaments WHERE id = v_tournament_id;

  IF NOT v_tournament.registration_open THEN
    RETURN jsonb_build_object('success', false, 'error', 'Kayıtlar kapalı.');
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.pvp_tournament_participants
    WHERE tournament_id = v_tournament_id AND user_id = v_uid
  ) THEN
    RETURN jsonb_build_object('success', true, 'message', 'Zaten kayıtlısınız.');
  END IF;

  INSERT INTO public.pvp_tournament_participants (tournament_id, user_id)
  VALUES (v_tournament_id, v_uid);

  RETURN jsonb_build_object('success', true, 'message', 'Turnuvaya katıldınız.');
END;
$$;


ALTER FUNCTION "public"."join_pvp_tournament"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kick_guild_member"("p_member_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_auth_id     UUID;
  v_caller      RECORD;
  v_member      RECORD;
BEGIN
  v_auth_id := auth.uid();
  IF v_auth_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Kimlik dogrulama gerekli');
  END IF;

  SELECT id, guild_id, guild_role FROM public.users WHERE auth_id = v_auth_id INTO v_caller;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Kullanici bulunamadi');
  END IF;

  IF COALESCE(v_caller.guild_role, '') != 'leader' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Sadece lider atabilir');
  END IF;

  SELECT id, guild_id, username FROM public.users WHERE id = p_member_id INTO v_member;
  IF NOT FOUND OR v_member.guild_id != v_caller.guild_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'Uye bulunamadi');
  END IF;

  UPDATE public.users
  SET guild_id   = NULL,
      guild_role = 'member'
  WHERE id = p_member_id;

  RETURN jsonb_build_object('success', true, 'username', v_member.username);
END;
$$;


ALTER FUNCTION "public"."kick_guild_member"("p_member_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."leave_guild"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_auth_id UUID;
  v_user    RECORD;
BEGIN
  v_auth_id := auth.uid();
  IF v_auth_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Kimlik dogrulama gerekli');
  END IF;

  SELECT id, guild_id, guild_role FROM public.users WHERE auth_id = v_auth_id INTO v_user;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Kullanici bulunamadi');
  END IF;

  IF v_user.guild_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Herhangi bir loncada degilsiniz');
  END IF;

  IF COALESCE(v_user.guild_role, '') = 'leader' THEN
    RETURN jsonb_build_object(
      'success', false,
      'error',   'Lonca lideri olarak ayrilamazsiniz. Once loncayi dagitmaniz veya liderlik devretmeniz gerekir'
    );
  END IF;

  UPDATE public.users
  SET guild_id   = NULL,
      guild_role = 'member'  -- reset to default; will be overwritten on next join
  WHERE auth_id = v_auth_id;

  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."leave_guild"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_dm_conversation_read"("p_peer_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user public.users%ROWTYPE;
  v_updated_count INTEGER := 0;
BEGIN
  v_user := public.get_current_chat_user();

  IF p_peer_user_id IS NULL OR p_peer_user_id = v_user.id THEN
    RETURN jsonb_build_object('success', false, 'error', 'Gecersiz hedef kullanici');
  END IF;

  UPDATE public.chat_messages
  SET read_at = now()
  WHERE channel = 'dm'
    AND deleted_at IS NULL
    AND sender_user_id = p_peer_user_id
    AND recipient_user_id = v_user.id
    AND read_at IS NULL;

  GET DIAGNOSTICS v_updated_count = ROW_COUNT;

  RETURN jsonb_build_object('success', true, 'updated_count', v_updated_count);
END;
$$;


