CREATE OR REPLACE FUNCTION "public"."normalize_chat_content"("p_content" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_content TEXT;
BEGIN
  v_content := regexp_replace(COALESCE(p_content, ''), '[[:cntrl:]]', '', 'g');
  v_content := regexp_replace(v_content, '\s+', ' ', 'g');
  v_content := btrim(v_content);
  RETURN v_content;
END;
$$;


ALTER FUNCTION "public"."normalize_chat_content"("p_content" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."open_inventory_loot_box"("p_row_id" "uuid", "p_user_id" "uuid" DEFAULT "auth"."uid"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_inv RECORD;
  v_box RECORD;
  v_drop RECORD;
  v_add_result JSONB;
  v_reward_qty INT := 1;
BEGIN
  IF p_user_id IS NULL OR p_user_id != auth.uid() THEN
    RETURN jsonb_build_object('success', false, 'error', 'Yetkisiz islem');
  END IF;

  SELECT inv.*, it.name AS item_name
  INTO v_inv
  FROM public.inventory inv
  JOIN public.items it ON it.id = inv.item_id
  WHERE inv.row_id = p_row_id
    AND inv.user_id = p_user_id
    AND inv.quantity > 0
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Kasa bulunamadi veya miktar yetersiz');
  END IF;

  IF v_inv.item_id NOT LIKE 'box\_%' ESCAPE '\' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Bu esya acilabilir bir kasa degil');
  END IF;

  SELECT *
  INTO v_box
  FROM public.loot_box_configs
  WHERE id = v_inv.item_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Kasa odul havuzu tanimli degil');
  END IF;

  SELECT
    e.item_id,
    e.weight,
    e.min_quantity,
    e.max_quantity,
    i.name AS item_name,
    i.icon,
    COALESCE(i.is_stackable, false) AS is_stackable
  INTO v_drop
  FROM public.loot_box_drop_entries e
  JOIN public.items i ON i.id = e.item_id
  WHERE e.box_id = v_inv.item_id
    AND e.is_active = TRUE
  ORDER BY -LN(GREATEST(random(), 1e-9)) / GREATEST(e.weight, 1e-9)
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Bu kasa icin odul tanimi yok');
  END IF;

  IF NOT public._consume_inventory_row(p_row_id, p_user_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Kasa tuketilemedi');
  END IF;

  IF COALESCE(v_drop.is_stackable, false) = FALSE THEN
    v_reward_qty := 1;
  ELSE
    v_reward_qty := GREATEST(
      1,
      FLOOR(random() * (v_drop.max_quantity - v_drop.min_quantity + 1) + v_drop.min_quantity)::INT
    );
  END IF;

  v_add_result := public.add_inventory_item_v2(
    jsonb_build_object(
      'item_id', v_drop.item_id,
      'quantity', v_reward_qty,
      'allow_stack', true
    ),
    NULL
  );

  IF COALESCE((v_add_result->>'success')::BOOLEAN, FALSE) = FALSE THEN
    INSERT INTO public.inventory (user_id, item_id, quantity, slot_position, is_equipped)
    VALUES (p_user_id, v_inv.item_id, 1, v_inv.slot_position, false);

    RETURN jsonb_build_object(
      'success', false,
      'error', COALESCE(v_add_result->>'error', 'Envanter dolu. Kasa iade edildi.')
    );
  END IF;

  INSERT INTO public.player_loot_box_logs (
    user_id,
    box_id,
    spent_currency,
    spent_amount,
    reward_type,
    reward_item_id,
    reward_amount,
    roll_weight,
    metadata
  )
  VALUES (
    p_user_id,
    v_inv.item_id,
    'gems',
    0,
    'item',
    v_drop.item_id,
    v_reward_qty,
    v_drop.weight,
    jsonb_build_object(
      'source', 'inventory',
      'box_name', v_box.name,
      'item_name', v_drop.item_name,
      'inventory_row_id', p_row_id
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'box_id', v_inv.item_id,
    'box_name', v_box.name,
    'reward', jsonb_build_object(
      'type', 'item',
      'item_id', v_drop.item_id,
      'name', v_drop.item_name,
      'icon', v_drop.icon,
      'quantity', v_reward_qty
    )
  );
END;
$$;


ALTER FUNCTION "public"."open_inventory_loot_box"("p_row_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."open_loot_box"("p_box_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_box RECORD; v_drop RECORD;
  v_balance_ok BOOLEAN := FALSE;
  v_reward_qty INTEGER; v_add_result JSONB;
  v_has_free_slot BOOLEAN := FALSE;
  v_force_rare_plus BOOLEAN := FALSE;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Not authenticated');
  END IF;
  SELECT * INTO v_box FROM public.loot_box_configs WHERE id = p_box_id AND is_active = TRUE FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'message', 'Kasa bulunamadi veya pasif.');
  END IF;
  SELECT EXISTS (
    SELECT 1 FROM generate_series(0, 19) AS s(slot)
    WHERE NOT EXISTS (
      SELECT 1 FROM public.inventory i
      WHERE i.user_id = v_user_id AND i.slot_position = s.slot AND i.is_equipped = FALSE
    )
  ) INTO v_has_free_slot;
  IF COALESCE(v_has_free_slot, FALSE) = FALSE THEN
    RETURN jsonb_build_object('success', false, 'message', 'Envanter dolu. Kasa acmak icin once bos slot acmalisin.');
  END IF;
  IF v_box.currency_type = 'gems' THEN
    UPDATE public.users SET gems = gems - v_box.price
    WHERE auth_id = v_user_id AND gems >= v_box.price RETURNING TRUE INTO v_balance_ok;
  ELSE
    UPDATE public.users SET gold = gold - v_box.price
    WHERE auth_id = v_user_id AND gold >= v_box.price RETURNING TRUE INTO v_balance_ok;
  END IF;
  IF COALESCE(v_balance_ok, FALSE) = FALSE THEN
    RETURN jsonb_build_object('success', false, 'message', 'Yetersiz bakiye.');
  END IF;
  IF v_box.currency_type = 'gems' THEN
    SELECT COUNT(*) = 8 AND COUNT(*) FILTER (WHERE recent.rarity IN ('common', 'uncommon')) = 8
    INTO v_force_rare_plus
    FROM (
      SELECT COALESCE(i.rarity, 'common') AS rarity
      FROM public.player_loot_box_logs l
      LEFT JOIN public.items i ON i.id = l.reward_item_id
      WHERE l.user_id = v_user_id AND l.box_id = p_box_id
      ORDER BY l.created_at DESC LIMIT 8
    ) recent;
    v_force_rare_plus := COALESCE(v_force_rare_plus, FALSE);
  END IF;
  SELECT e.item_id, e.weight, e.min_quantity, e.max_quantity, i.name AS item_name, i.icon,
    COALESCE(i.is_stackable, FALSE) AS is_stackable, COALESCE(i.rarity, 'common') AS rarity
  INTO v_drop
  FROM public.loot_box_drop_entries e JOIN public.items i ON i.id = e.item_id
  WHERE e.box_id = p_box_id AND e.is_active = TRUE
    AND (NOT v_force_rare_plus OR COALESCE(i.rarity, 'common') IN ('rare', 'epic', 'legendary', 'mythic'))
  ORDER BY -LN(GREATEST(random(), 1e-9)) / GREATEST(e.weight, 1e-9) LIMIT 1;
  IF NOT FOUND THEN
    SELECT e.item_id, e.weight, e.min_quantity, e.max_quantity, i.name AS item_name, i.icon,
      COALESCE(i.is_stackable, FALSE) AS is_stackable, COALESCE(i.rarity, 'common') AS rarity
    INTO v_drop
    FROM public.loot_box_drop_entries e JOIN public.items i ON i.id = e.item_id
    WHERE e.box_id = p_box_id AND e.is_active = TRUE
    ORDER BY -LN(GREATEST(random(), 1e-9)) / GREATEST(e.weight, 1e-9) LIMIT 1;
  END IF;
  IF NOT FOUND THEN
    IF v_box.currency_type = 'gems' THEN UPDATE public.users SET gems = gems + v_box.price WHERE auth_id = v_user_id;
    ELSE UPDATE public.users SET gold = gold + v_box.price WHERE auth_id = v_user_id; END IF;
    RETURN jsonb_build_object('success', false, 'message', 'Bu kasa icin drop tanimi yok.');
  END IF;
  v_reward_qty := FLOOR(random() * (v_drop.max_quantity - v_drop.min_quantity + 1) + v_drop.min_quantity)::INTEGER;
  v_reward_qty := GREATEST(1, FLOOR(v_reward_qty * COALESCE(v_box.reward_multiplier, 1))::INTEGER);
  IF COALESCE(v_drop.is_stackable, FALSE) = FALSE THEN v_reward_qty := 1; END IF;
  v_add_result := public.add_inventory_item_v2(jsonb_build_object('item_id', v_drop.item_id, 'quantity', v_reward_qty, 'allow_stack', true), NULL);
  IF COALESCE((v_add_result->>'success')::BOOLEAN, FALSE) = FALSE THEN
    IF v_box.currency_type = 'gems' THEN UPDATE public.users SET gems = gems + v_box.price WHERE auth_id = v_user_id;
    ELSE UPDATE public.users SET gold = gold + v_box.price WHERE auth_id = v_user_id; END IF;
    RETURN jsonb_build_object('success', false, 'message', 'Envanter dolu. Kasa ucreti iade edildi.');
  END IF;
  INSERT INTO public.player_loot_box_logs (
    user_id, box_id, spent_currency, spent_amount, reward_type, reward_item_id, reward_amount, roll_weight, metadata
  ) VALUES (
    v_user_id, v_box.id, v_box.currency_type, v_box.price, 'item', v_drop.item_id, v_reward_qty, v_drop.weight,
    jsonb_build_object('box_name', v_box.name, 'item_name', v_drop.item_name, 'rarity', v_drop.rarity, 'pity_forced', v_force_rare_plus)
  );
  RETURN jsonb_build_object(
    'success', true, 'message', 'Kasa acildi.', 'box_id', v_box.id, 'box_name', v_box.name,
    'spent_currency', v_box.currency_type, 'spent_amount', v_box.price, 'pity_forced', v_force_rare_plus,
    'reward', jsonb_build_object('type', 'item', 'item_id', v_drop.item_id, 'name', v_drop.item_name, 'icon', v_drop.icon, 'rarity', v_drop.rarity, 'quantity', v_reward_qty)
  );
END;
$$;


ALTER FUNCTION "public"."open_loot_box"("p_box_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."open_mekan"("p_user_id" "uuid", "p_mekan_type" "text", "p_name" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_cost BIGINT;
  v_level_req INT;
  v_user_level INT;
  v_user_gold BIGINT;
BEGIN
  IF p_user_id != auth.uid() THEN
    RETURN jsonb_build_object('success', false, 'error', 'Yetkisiz işlem');
  END IF;

  -- Validate mekan type and get cost/level req
  IF p_mekan_type = 'bar' THEN
    v_cost := 5000000;
    v_level_req := 15;
  ELSIF p_mekan_type = 'kahvehane' THEN
    v_cost := 8000000;
    v_level_req := 20;
  ELSIF p_mekan_type = 'dovus_kulubu' THEN
    v_cost := 15000000;
    v_level_req := 30;
  ELSIF p_mekan_type = 'luks_lounge' THEN
    v_cost := 50000000;
    v_level_req := 45;
  ELSIF p_mekan_type = 'yeralti' THEN
    v_cost := 200000000;
    v_level_req := 60;
  ELSE
    RETURN jsonb_build_object('success', false, 'error', 'Geçersiz mekan türü');
  END IF;

  SELECT level, gold INTO v_user_level, v_user_gold
  FROM public.users WHERE auth_id = p_user_id;

  IF v_user_level < v_level_req THEN
    RETURN jsonb_build_object('success', false, 'error', 'Level yetersiz. Gereken: ' || v_level_req);
  END IF;

  IF v_user_gold < v_cost THEN
    RETURN jsonb_build_object('success', false, 'error', 'Gold yetersiz. Gereken: ' || v_cost);
  END IF;

  -- Check if user already has a mekan
  IF EXISTS (SELECT 1 FROM public.mekans WHERE owner_id = p_user_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Zaten bir mekanınız var');
  END IF;

  -- Deduct gold and insert mekan
  UPDATE public.users SET gold = gold - v_cost WHERE auth_id = p_user_id AND gold >= v_cost;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'İşlem sırasında altın yetersiz kaldı');
  END IF;

  INSERT INTO public.mekans (owner_id, mekan_type, name)
  VALUES (p_user_id, p_mekan_type, p_name);

  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."open_mekan"("p_user_id" "uuid", "p_mekan_type" "text", "p_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."organize_bank"("p_item_id" "uuid", "p_pin" boolean) RETURNS TABLE("success" boolean, "message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id uuid;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN QUERY SELECT false, 'Not authenticated'::text;
    RETURN;
  END IF;

  UPDATE public.bank_items
  SET is_pinned = p_pin,
      pinned_at = CASE WHEN p_pin THEN now() ELSE NULL END,
      updated_at = now()
  WHERE id = p_item_id AND user_id = v_user_id;

  RETURN QUERY SELECT true, 
    CASE WHEN p_pin THEN 'Item pinned' ELSE 'Item unpinned' END::text;
END;
$$;


ALTER FUNCTION "public"."organize_bank"("p_item_id" "uuid", "p_pin" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pay_mekan_rent"("p_mekan_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_auth_id UUID;
  v_mekan RECORD;
  v_rent BIGINT;
  v_gold BIGINT;
BEGIN
  v_auth_id := auth.uid();
  IF v_auth_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Kimlik dogrulama gerekli');
  END IF;
  SELECT * INTO v_mekan FROM public.mekans WHERE id = p_mekan_id AND owner_id = v_auth_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Mekan bulunamadi veya size ait degil');
  END IF;
  v_rent := public.mekan_monthly_rent(v_mekan.mekan_type);
  SELECT gold INTO v_gold FROM public.users WHERE auth_id = v_auth_id FOR UPDATE;
  IF v_gold < v_rent THEN
    RETURN jsonb_build_object('success', false, 'error', 'Gold yetersiz. Kira: ' || v_rent);
  END IF;
  UPDATE public.users SET gold = gold - v_rent WHERE auth_id = v_auth_id AND gold >= v_rent;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Islem sirasinda altin yetersiz kaldi');
  END IF;
  UPDATE public.mekans SET monthly_rent_paid_at = GREATEST(now(), monthly_rent_paid_at) WHERE id = p_mekan_id;
  RETURN jsonb_build_object('success', true, 'rent', v_rent);
END;
$$;


ALTER FUNCTION "public"."pay_mekan_rent"("p_mekan_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."place_horse_race_bet"("p_round_id" "uuid", "p_horse_id" "text", "p_currency_type" "text", "p_bet_amount" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_settings RECORD;
  v_round RECORD;
  v_entry RECORD;
  v_balance_ok BOOLEAN := FALSE;
  v_mult NUMERIC;
  v_existing UUID;
BEGIN
  IF v_user_id IS NULL THEN RETURN jsonb_build_object('success', false, 'message', 'Oturum gerekli.'); END IF;
  PERFORM public.tick_horse_race_engine();
  IF p_currency_type NOT IN ('gold', 'gems') THEN RETURN jsonb_build_object('success', false, 'message', 'Gecersiz para birimi.'); END IF;
  IF COALESCE(p_bet_amount, 0) <= 0 THEN RETURN jsonb_build_object('success', false, 'message', 'Bahis tutari gecersiz.'); END IF;
  SELECT * INTO v_settings FROM public.horse_race_settings WHERE id = 'default' AND is_active = TRUE;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'message', 'At yarisi kapali.'); END IF;
  SELECT * INTO v_round FROM public.horse_race_rounds WHERE id = p_round_id;
  IF NOT FOUND OR v_round.status <> 'betting' THEN RETURN jsonb_build_object('success', false, 'message', 'Bahis suresi kapandi.'); END IF;
  SELECT id INTO v_existing FROM public.horse_race_bets WHERE round_id = p_round_id AND user_id = v_user_id;
  IF FOUND THEN RETURN jsonb_build_object('success', false, 'message', 'Bu turda zaten bahis yaptin.'); END IF;
  SELECT * INTO v_entry FROM public.horse_race_round_entries WHERE round_id = p_round_id AND horse_id = p_horse_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'message', 'At bu turda yok.'); END IF;
  v_mult := CASE WHEN p_currency_type = 'gems' THEN v_entry.gem_multiplier ELSE v_entry.gold_multiplier END;
  IF p_currency_type = 'gems' THEN
    IF p_bet_amount < v_settings.gem_min_bet OR p_bet_amount > v_settings.gem_max_bet THEN
      RETURN jsonb_build_object('success', false, 'message', format('Elmas bahis %s-%s arasi olmali.', v_settings.gem_min_bet, v_settings.gem_max_bet));
    END IF;
    UPDATE public.users SET gems = gems - p_bet_amount WHERE auth_id = v_user_id AND gems >= p_bet_amount RETURNING TRUE INTO v_balance_ok;
  ELSE
    IF p_bet_amount < v_settings.gold_min_bet OR p_bet_amount > v_settings.gold_max_bet THEN
      RETURN jsonb_build_object('success', false, 'message', format('Altin bahis %s-%s arasi olmali.', v_settings.gold_min_bet, v_settings.gold_max_bet));
    END IF;
    UPDATE public.users SET gold = gold - p_bet_amount WHERE auth_id = v_user_id AND gold >= p_bet_amount RETURNING TRUE INTO v_balance_ok;
  END IF;
  IF COALESCE(v_balance_ok, FALSE) = FALSE THEN RETURN jsonb_build_object('success', false, 'message', 'Yetersiz bakiye.'); END IF;
  INSERT INTO public.horse_race_bets (round_id, user_id, horse_id, currency_type, bet_amount, multiplier)
  VALUES (p_round_id, v_user_id, p_horse_id, p_currency_type, p_bet_amount, v_mult);
  RETURN jsonb_build_object('success', true, 'message', 'Bahis alindi.', 'horse_id', p_horse_id, 'currency_type', p_currency_type, 'bet_amount', p_bet_amount, 'multiplier', v_mult);
END;
$$;


ALTER FUNCTION "public"."place_horse_race_bet"("p_round_id" "uuid", "p_horse_id" "text", "p_currency_type" "text", "p_bet_amount" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."place_sell_order"("p_item_row_id" "uuid", "p_quantity" integer, "p_price" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_row RECORD;
  v_qty INT;
  v_order_id UUID;
  v_total INT;
  v_seller_receives INT;
  v_fee INT;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Giris yapmalisiniz';
  END IF;

  IF p_price IS NULL OR p_price <= 0 THEN
    RAISE EXCEPTION 'Gecerli bir fiyat girin';
  END IF;

  SELECT inv.*,
         i.name AS catalog_name,
         COALESCE(i.type::TEXT, '') AS catalog_type,
         COALESCE(i.rarity::TEXT, 'common') AS catalog_rarity,
         COALESCE(i.is_market_tradeable, true) AS catalog_market_tradeable,
         COALESCE(i.is_han_only, false) AS catalog_han_only,
         COALESCE(i.is_stackable, inv.is_stackable, false) AS catalog_stackable,
         GREATEST(1, COALESCE(i.max_stack, inv.max_stack, 999)) AS catalog_max_stack
  INTO v_row
  FROM public.inventory inv
  JOIN public.items i ON i.id = inv.item_id
  WHERE inv.row_id = p_item_row_id
    AND inv.user_id = v_user_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Esya bulunamadi veya size ait degil';
  END IF;

  IF COALESCE(v_row.is_equipped, false) THEN
    RAISE EXCEPTION 'Kusanili esya pazara konulamaz';
  END IF;

  IF COALESCE(v_row.is_tradeable, true) = false THEN
    RAISE EXCEPTION 'Bu esya takas edilemez';
  END IF;

  IF v_row.catalog_market_tradeable = false OR v_row.catalog_han_only = true THEN
    RAISE EXCEPTION 'Bu esya pazarda satilamaz';
  END IF;

  IF v_row.catalog_stackable THEN
    v_qty := GREATEST(1, COALESCE(p_quantity, 1));
    IF v_qty > v_row.quantity THEN
      RAISE EXCEPTION 'Yeterli adet yok (max %)', v_row.quantity;
    END IF;
  ELSE
    v_qty := 1;
    IF v_row.quantity <> 1 THEN
      RAISE EXCEPTION 'Gecersiz envanter satiri';
    END IF;
  END IF;

  v_total := p_price * v_qty;
  v_fee := FLOOR(v_total * 0.05);
  v_seller_receives := v_total - v_fee;
  v_order_id := gen_random_uuid();

  IF v_row.catalog_stackable AND v_qty < v_row.quantity THEN
    UPDATE public.inventory
    SET quantity = quantity - v_qty, updated_at = now()
    WHERE row_id = p_item_row_id AND user_id = v_user_id;
  ELSE
    DELETE FROM public.inventory
    WHERE row_id = p_item_row_id AND user_id = v_user_id;
  END IF;

  INSERT INTO public.market_orders (
    order_id, seller_id, inventory_row_id, item_id, item_name, item_type, rarity,
    is_stackable, max_stack, enhancement_level, side, quantity, price, status, currency
  ) VALUES (
    v_order_id, v_user_id, p_item_row_id, v_row.item_id,
    COALESCE(v_row.catalog_name, 'Bilinmeyen Esya'),
    COALESCE(v_row.catalog_type, ''),
    COALESCE(v_row.catalog_rarity, 'common'),
    v_row.catalog_stackable, v_row.catalog_max_stack,
    COALESCE(v_row.enhancement_level, 0),
    'sell', v_qty, p_price, 'open', 'gold'
  );

  RETURN jsonb_build_object(
    'success', true,
    'order_id', v_order_id,
    'quantity', v_qty,
    'unit_price', p_price,
    'total', v_total,
    'fee', v_fee,
    'seller_receives', v_seller_receives
  );
END;
$$;


ALTER FUNCTION "public"."place_sell_order"("p_item_row_id" "uuid", "p_quantity" integer, "p_price" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."preview_facility_production"("p_facility_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_facility record;
  v_counts jsonb;
  v_sim jsonb;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT *
  INTO v_facility
  FROM public.facilities f
  WHERE f.id = p_facility_id
    AND f.user_id = v_user_id
    AND COALESCE(f.is_active, true) = true;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Facility not found');
  END IF;

  IF v_facility.production_started_at IS NULL THEN
    RETURN jsonb_build_object(
      'success', true,
      'production_started_at', NULL,
      'remaining_seconds', 0,
      'is_ready', false,
      'base_count', 0,
      'total_count', 0,
      'items', '[]'::jsonb
    );
  END IF;

  v_counts := public._facility_production_counts(
    v_facility.production_started_at,
    COALESCE(v_facility.level, 1),
    v_facility.type
  );

  IF COALESCE((v_counts->>'success')::boolean, false) = false THEN
    RETURN v_counts;
  END IF;

  v_sim := public._facility_simulate_rarity_items(
    COALESCE((v_counts->>'total_count')::integer, 0),
    COALESCE((v_counts->>'seed')::bigint, 0),
    COALESCE(v_facility.level, 1)
  );

  RETURN jsonb_build_object(
    'success', true,
    'production_started_at', v_facility.production_started_at,
    'remaining_seconds', COALESCE((v_counts->>'remaining_seconds')::integer, 0),
    'is_ready', COALESCE((v_counts->>'is_ready')::boolean, false),
    'base_count', COALESCE((v_counts->>'base_count')::integer, 0),
    'total_count', COALESCE((v_counts->>'total_count')::integer, 0),
    'items', COALESCE(v_sim->'items', '[]'::jsonb)
  );
END;
$$;


ALTER FUNCTION "public"."preview_facility_production"("p_facility_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."promote_guild_member"("p_member_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_auth_id     UUID;
  v_caller      RECORD;
  v_member      RECORD;
BEGIN
  v_auth_id := auth.uid();
  IF v_auth_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Kimlik dogrulama gerekli');
  END IF;

  SELECT id, guild_id, guild_role FROM public.users WHERE auth_id = v_auth_id INTO v_caller;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Kullanici bulunamadi');
  END IF;

  IF COALESCE(v_caller.guild_role, '') != 'leader' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Sadece lider yukseltebilir');
  END IF;

  SELECT id, guild_id, username FROM public.users WHERE id = p_member_id INTO v_member;
  IF NOT FOUND OR v_member.guild_id != v_caller.guild_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'Uye bulunamadi');
  END IF;

  UPDATE public.users SET guild_role = 'officer' WHERE id = p_member_id;

  RETURN jsonb_build_object('success', true, 'username', v_member.username);
END;
$$;


ALTER FUNCTION "public"."promote_guild_member"("p_member_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."purchase_market_listing"("p_order_id" "uuid", "p_quantity" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_gate JSONB;
BEGIN
  v_gate := public.enforce_rate_limit('market', 30, 300);
  IF v_gate IS NOT NULL THEN
    RAISE EXCEPTION 'captcha_required';
  END IF;
  RETURN public.purchase_market_listing_rl_inner(p_order_id, p_quantity);
END;
$$;


ALTER FUNCTION "public"."purchase_market_listing"("p_order_id" "uuid", "p_quantity" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."purchase_market_listing"("p_order_id" "uuid", "p_quantity" integer DEFAULT 1, "p_is_stackable" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_order RECORD;
    v_buyer_id UUID;
    v_seller_id UUID;
    v_total_price BIGINT;
    v_buyer_gold BIGINT;
    v_item_data JSONB;
    v_commission_rate NUMERIC := 0.05; -- 5% commission
    v_commission_amount BIGINT;
    v_seller_revenue BIGINT;
    v_seller_gold BIGINT;
    v_remaining_qty INT;
    v_transfer_qty INT;
    v_dest_slot INT;
    v_dest_qty INT;
    v_space INT;
    v_enhancement_level INT;
BEGIN
    -- Get current user (buyer)
    v_buyer_id := auth.uid();
    IF v_buyer_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
    END IF;

    -- Get Order
    SELECT * INTO v_order FROM public.market_orders WHERE id = p_order_id AND status = 'active' FOR UPDATE;
    
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Listing not found or no longer active');
    END IF;

    v_seller_id := v_order.seller_id;
    
    -- Prevent self-trading
    IF v_seller_id = v_buyer_id THEN
        RETURN jsonb_build_object('success', false, 'error', 'Cannot buy your own listing');
    END IF;
    
    -- Check Quantity
    IF p_quantity <= 0 THEN
         RETURN jsonb_build_object('success', false, 'error', 'Invalid quantity');
    END IF;
    
    IF v_order.quantity < p_quantity THEN
         RETURN jsonb_build_object('success', false, 'error', 'Not enough quantity available (Stock: ' || v_order.quantity || ')');
    END IF;

    -- Calculate Total Price
    v_total_price := v_order.price * p_quantity;
    
    -- Check Buyer Gold
    SELECT gold INTO v_buyer_gold FROM public.users WHERE auth_id = v_buyer_id OR id = v_buyer_id;
    
    IF v_buyer_gold < v_total_price THEN
        RETURN jsonb_build_object('success', false, 'error', 'Not enough gold');
    END IF;

    -- Transaction
    -- 1. Deduct Gold from Buyer
    UPDATE public.users 
    SET gold = gold - v_total_price 
    WHERE auth_id = v_buyer_id OR id = v_buyer_id
    RETURNING gold INTO v_buyer_gold;
    
    -- 2. Add Gold to Seller (minus commission)
    v_commission_amount := FLOOR(v_total_price * v_commission_rate);
    v_seller_revenue := v_total_price - v_commission_amount;
    
    UPDATE public.users 
    SET gold = gold + v_seller_revenue 
    WHERE auth_id = v_seller_id OR id = v_seller_id
    RETURNING gold INTO v_seller_gold;
    
    -- 3. Transfer Item to Buyer with Stacking Logic
    v_item_data := v_order.item_data;
    v_enhancement_level := COALESCE((v_item_data->>'enhancement_level')::int, 0);
    v_remaining_qty := p_quantity;
    
    -- Handling Logic based on Stackability
    IF p_is_stackable THEN
        -- Legacy Stackable Logic (Potion, etc)
        WHILE v_remaining_qty > 0 LOOP
            v_dest_slot := NULL;
            v_dest_qty := 0;
            
            -- Try to find existing partial stack
            SELECT slot_position, quantity INTO v_dest_slot, v_dest_qty
            FROM public.inventory
            WHERE user_id = v_buyer_id 
              AND item_id = v_order.item_id
              AND enhancement_level = v_enhancement_level
              AND quantity < 50
            ORDER BY quantity DESC 
            LIMIT 1;
            
            IF v_dest_slot IS NOT NULL THEN
                -- Fill Existing Stack
                v_space := 50 - v_dest_qty;
                v_transfer_qty := LEAST(v_remaining_qty, v_space);
                
                UPDATE public.inventory 
                SET quantity = quantity + v_transfer_qty
                WHERE user_id = v_buyer_id AND slot_position = v_dest_slot;
                
                v_remaining_qty := v_remaining_qty - v_transfer_qty;
            ELSE
                -- New Slot
                SELECT MIN(slot_num) INTO v_dest_slot
                FROM generate_series(0, 19) slot_num
                WHERE NOT EXISTS (SELECT 1 FROM public.inventory WHERE user_id = v_buyer_id AND slot_position = slot_num);
                
                IF v_dest_slot IS NULL THEN
                    RAISE EXCEPTION 'Inventory full';
                END IF;
                
                v_transfer_qty := LEAST(v_remaining_qty, 50);
                
                INSERT INTO public.inventory (
                    user_id, item_id, quantity, slot_position, 
                    enhancement_level, is_equipped, obtained_at
                )
                VALUES (
                    v_buyer_id, 
                    v_order.item_id, 
                    v_transfer_qty, 
                    v_dest_slot, 
                    v_enhancement_level,
                    false,
                    EXTRACT(EPOCH FROM NOW())::bigint
                );
                
                v_remaining_qty := v_remaining_qty - v_transfer_qty;
            END IF;
        END LOOP;
        
    ELSE
        -- Non-Stackable Logic (Equipment)
        -- Must find separate slots for EACH item if p_quantity > 1 (unlikely for equip, but safe to handle)
        FOR i IN 1..p_quantity LOOP
             -- Find ONE empty slot
             v_dest_slot := NULL;
             SELECT MIN(slot_num) INTO v_dest_slot
             FROM generate_series(0, 19) slot_num
             WHERE NOT EXISTS (SELECT 1 FROM public.inventory WHERE user_id = v_buyer_id AND slot_position = slot_num);
             
             IF v_dest_slot IS NULL THEN
                 RAISE EXCEPTION 'Inventory full';
             END IF;
             
             INSERT INTO public.inventory (
                user_id, item_id, quantity, slot_position, 
                enhancement_level, is_equipped, obtained_at
            )
            VALUES (
                v_buyer_id, 
                v_order.item_id, 
                1, -- Always 1 for non-stackable
                v_dest_slot, 
                v_enhancement_level,
                false,
                EXTRACT(EPOCH FROM NOW())::bigint
            );
        END LOOP;
    END IF;
    
    -- 4. Update or Delete Order
    IF v_order.quantity = p_quantity THEN
        DELETE FROM public.market_orders WHERE id = p_order_id;
    ELSE
        UPDATE public.market_orders SET quantity = quantity - p_quantity WHERE id = p_order_id;
    END IF;
    
    -- 5. Track History
    INSERT INTO public.market_history (item_id, seller_id, buyer_id, price, quantity, sold_at)
    VALUES (v_order.item_id, v_seller_id, v_buyer_id, v_order.price, p_quantity, NOW());
    
    RETURN jsonb_build_object(
        'success', true, 
        'message', 'Item purchased',
        'new_buyer_gold', v_buyer_gold,
        'new_seller_gold', v_seller_gold
    );

EXCEPTION 
    WHEN OTHERS THEN
         IF SQLERRM = 'Inventory full' THEN
             RETURN jsonb_build_object('success', false, 'error', 'Inventory full');
         END IF;
         RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;


ALTER FUNCTION "public"."purchase_market_listing"("p_order_id" "uuid", "p_quantity" integer, "p_is_stackable" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."purchase_market_listing_rl_inner"("p_order_id" "uuid", "p_quantity" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_buyer_id UUID := auth.uid();
  v_order RECORD;
  v_buy_qty INT;
  v_total INT;
  v_fee INT;
  v_seller_credit INT;
  v_buyer_gold INT;
BEGIN
  IF v_buyer_id IS NULL THEN
    RAISE EXCEPTION 'Giris yapmalisiniz';
  END IF;

  SELECT * INTO v_order
  FROM public.market_orders
  WHERE order_id = p_order_id
    AND status = 'open'
    AND side = 'sell'
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Ilan bulunamadi veya satildi';
  END IF;

  IF v_order.seller_id = v_buyer_id THEN
    RAISE EXCEPTION 'Kendi ilaninizi satin alamazsiniz';
  END IF;

  IF v_order.is_stackable THEN
    v_buy_qty := GREATEST(1, COALESCE(p_quantity, 1));
    IF v_buy_qty > v_order.quantity THEN
      RAISE EXCEPTION 'Ilanda yeterli adet yok (max %)', v_order.quantity;
    END IF;
  ELSE
    v_buy_qty := 1;
  END IF;

  IF NOT public.market_can_add_items(
    v_buyer_id, v_order.item_id, v_buy_qty, v_order.enhancement_level
  ) THEN
    RAISE EXCEPTION 'Envanter dolu veya esya eklenemiyor';
  END IF;

  v_total := v_order.price * v_buy_qty;
  v_fee := FLOOR(v_total * 0.05);
  v_seller_credit := v_total - v_fee;

  SELECT COALESCE(gold, 0) INTO v_buyer_gold
  FROM public.users
  WHERE auth_id = v_buyer_id
  FOR UPDATE;

  IF v_buyer_gold IS NULL THEN
    RAISE EXCEPTION 'Oyuncu bulunamadi';
  END IF;

  IF v_buyer_gold < v_total THEN
    RAISE EXCEPTION 'Yeterli altin yok';
  END IF;

  UPDATE public.users
  SET gold = gold - v_total
  WHERE auth_id = v_buyer_id;

  UPDATE public.users
  SET gold = COALESCE(gold, 0) + v_seller_credit
  WHERE auth_id = v_order.seller_id;

  IF NOT public.market_give_items(
    v_buyer_id, v_order.item_id, v_buy_qty, v_order.enhancement_level
  ) THEN
    RAISE EXCEPTION 'Esya envantere eklenemedi';
  END IF;

  IF v_buy_qty >= v_order.quantity THEN
    UPDATE public.market_orders
    SET status = 'filled', quantity = 0, fee = v_fee, filled_at = now(), updated_at = now()
    WHERE order_id = p_order_id;
  ELSE
    UPDATE public.market_orders
    SET quantity = quantity - v_buy_qty, fee = v_fee, updated_at = now()
    WHERE order_id = p_order_id;
  END IF;

  INSERT INTO public.market_history (
    order_id, buyer_id, seller_id, item_id, item_name, quantity, unit_price, total_price, fee
  ) VALUES (
    p_order_id, v_buyer_id, v_order.seller_id, v_order.item_id, v_order.item_name,
    v_buy_qty, v_order.price, v_total, v_fee
  );

  RETURN jsonb_build_object(
    'success', true,
    'quantity', v_buy_qty,
    'total', v_total,
    'fee', v_fee,
    'seller_credit', v_seller_credit
  );
END;
$$;


ALTER FUNCTION "public"."purchase_market_listing_rl_inner"("p_order_id" "uuid", "p_quantity" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pvp_attack"("p_attacker_id" "uuid", "p_defender_id" "uuid", "p_mekan_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_attacker RECORD;
  v_defender RECORD;
  v_mekan RECORD;
  v_attacker_hp INT;
  v_defender_hp INT;
  v_winner_id UUID;
  v_gold_stolen BIGINT;
  v_steal_rate NUMERIC;
  v_rep_change_winner INT;
  v_rep_change_loser INT;
  v_hospital_chance NUMERIC;
  v_hospital_triggered BOOLEAN := false;
  v_hospital_minutes INT;
  v_new_rating_a INT;
  v_new_rating_d INT;
  v_expected_a NUMERIC;
  v_rating_diff INT;
  v_daily_count INT;

  v_attacker_is_warrior BOOLEAN;
  v_defender_is_warrior BOOLEAN;
  v_attacker_is_shadow BOOLEAN;
  v_defender_is_shadow BOOLEAN;

  v_attacker_bloodlust_active BOOLEAN := false;
  v_defender_bloodlust_active BOOLEAN := false;
  v_attacker_bloodlust_mult NUMERIC := 1.0;
  v_defender_bloodlust_mult NUMERIC := 1.0;
BEGIN
  IF p_attacker_id != auth.uid() THEN
    RETURN jsonb_build_object('success', false, 'error', 'Yetkisiz islem');
  END IF;

  SELECT * INTO v_attacker FROM public.users WHERE auth_id = p_attacker_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Saldiran bulunamadi');
  END IF;

  SELECT * INTO v_defender FROM public.users WHERE auth_id = p_defender_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Hedef bulunamadi');
  END IF;

  IF p_attacker_id = p_defender_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'Kendine saldiramazsin');
  END IF;

  IF COALESCE(v_attacker.level, 1) < 10 OR COALESCE(v_defender.level, 1) < 10 THEN
    RETURN jsonb_build_object('success', false, 'error', 'PvP icin minimum level 10');
  END IF;

  IF v_attacker.energy < 15 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Enerji yetersiz (15 gerekli)');
  END IF;

  IF ((v_attacker.hospital_until IS NOT NULL AND v_attacker.hospital_until > now())
      OR (v_attacker.prison_until IS NOT NULL AND v_attacker.prison_until > now())) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Hastanede/hapiste PvP yapilamaz');
  END IF;

  IF ((v_defender.hospital_until IS NOT NULL AND v_defender.hospital_until > now())
      OR (v_defender.prison_until IS NOT NULL AND v_defender.prison_until > now())) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Rakip musait degil');
  END IF;

  IF v_attacker.guild_id IS NOT NULL AND v_attacker.guild_id = v_defender.guild_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'Ayni lonca uyesine saldirilamaz');
  END IF;

  SELECT COALESCE(attack_count, 0) INTO v_daily_count
  FROM public.pvp_daily_attacks
  WHERE attacker_id = p_attacker_id AND defender_id = p_defender_id AND attack_date = CURRENT_DATE;

  IF v_daily_count >= 3 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Bu oyuncuya bugun 3 kez saldirdiniz');
  END IF;

  SELECT * INTO v_mekan FROM public.mekans WHERE id = p_mekan_id AND is_open = true;
  IF NOT FOUND OR v_mekan.mekan_type NOT IN ('dovus_kulubu', 'luks_lounge', 'yeralti') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Bu mekanda PvP yapilamaz');
  END IF;

  IF ABS(COALESCE(v_attacker.pvp_rating, 1000) - COALESCE(v_defender.pvp_rating, 1000)) > 300 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Rating farki cok yuksek (max +-300)');
  END IF;

  v_attacker_is_warrior := COALESCE(v_attacker.character_class, '') = 'warrior';
  v_defender_is_warrior := COALESCE(v_defender.character_class, '') = 'warrior';
  v_attacker_is_shadow := COALESCE(v_attacker.character_class, '') = 'shadow';
  v_defender_is_shadow := COALESCE(v_defender.character_class, '') = 'shadow';

  v_attacker_bloodlust_active := v_attacker_is_warrior
    AND v_attacker.warrior_bloodlust_until IS NOT NULL
    AND v_attacker.warrior_bloodlust_until > now();

  v_defender_bloodlust_active := v_defender_is_warrior
    AND v_defender.warrior_bloodlust_until IS NOT NULL
    AND v_defender.warrior_bloodlust_until > now();

  IF v_attacker_bloodlust_active THEN
    v_attacker_bloodlust_mult := CASE
      WHEN COALESCE(v_attacker.warrior_bloodlust_streak, 0) >= 3 THEN 1.20
      ELSE 1.10
    END;
  END IF;

  IF v_defender_bloodlust_active THEN
    v_defender_bloodlust_mult := CASE
      WHEN COALESCE(v_defender.warrior_bloodlust_streak, 0) >= 3 THEN 1.20
      ELSE 1.10
    END;
  END IF;

  v_attacker_hp := COALESCE(v_attacker.health, 100);
  v_defender_hp := COALESCE(v_defender.health, 100);

  FOR i IN 1..3 LOOP
    DECLARE
      v_atk_dmg NUMERIC;
      v_def_dmg NUMERIC;
      v_atk_crit BOOLEAN;
      v_def_crit BOOLEAN;
      v_atk_dodge BOOLEAN;
      v_def_dodge BOOLEAN;
      v_atk_crit_chance NUMERIC;
      v_def_crit_chance NUMERIC;
      v_atk_dodge_chance NUMERIC;
      v_def_dodge_chance NUMERIC;
      v_atk_class_damage_mult NUMERIC;
      v_def_class_damage_mult NUMERIC;
    BEGIN
      v_atk_crit_chance := LEAST(0.95, GREATEST(0.0,
        COALESCE(v_attacker.luck, 0) * 0.002
        + CASE WHEN v_attacker_is_warrior THEN 0.10 ELSE 0.0 END
      ));

      v_def_crit_chance := LEAST(0.95, GREATEST(0.0,
        COALESCE(v_defender.luck, 0) * 0.002
        + CASE WHEN v_defender_is_warrior THEN 0.10 ELSE 0.0 END
      ));

      v_atk_dodge_chance := LEAST(0.80, GREATEST(0.0,
        COALESCE(v_attacker.luck, 0) * 0.001
        + CASE WHEN v_attacker_is_shadow THEN 0.15 ELSE 0.0 END
      ));

      v_def_dodge_chance := LEAST(0.80, GREATEST(0.0,
        COALESCE(v_defender.luck, 0) * 0.001
        + CASE WHEN v_defender_is_shadow THEN 0.15 ELSE 0.0 END
      ));

      v_atk_crit := random() < v_atk_crit_chance;
      v_def_crit := random() < v_def_crit_chance;
      v_atk_dodge := random() < v_atk_dodge_chance;
      v_def_dodge := random() < v_def_dodge_chance;

      v_atk_class_damage_mult := CASE WHEN v_attacker_is_warrior THEN 1.20 ELSE 1.0 END;
      v_def_class_damage_mult := CASE WHEN v_defender_is_warrior THEN 1.20 ELSE 1.0 END;

      IF v_def_dodge THEN
        v_atk_dmg := 0;
      ELSE
        v_atk_dmg := COALESCE(v_attacker.attack, 10) * (0.8 + random() * 0.4)
                     * CASE WHEN v_atk_crit THEN 1.5 ELSE 1.0 END
                     * v_atk_class_damage_mult
                     * v_attacker_bloodlust_mult
                     - COALESCE(v_defender.defense, 10) * 0.3;
        v_atk_dmg := GREATEST(v_atk_dmg, 1);
      END IF;

      IF v_atk_dodge THEN
        v_def_dmg := 0;
      ELSE
        v_def_dmg := COALESCE(v_defender.attack, 10) * (0.8 + random() * 0.4)
                     * CASE WHEN v_def_crit THEN 1.5 ELSE 1.0 END
                     * v_def_class_damage_mult
                     * v_defender_bloodlust_mult
                     - COALESCE(v_attacker.defense, 10) * 0.3;
        v_def_dmg := GREATEST(v_def_dmg, 1);
      END IF;

      v_defender_hp := v_defender_hp - v_atk_dmg::INT;
      v_attacker_hp := v_attacker_hp - v_def_dmg::INT;
    END;
  END LOOP;

  IF v_attacker_hp > v_defender_hp THEN
    v_winner_id := p_attacker_id;
  ELSIF v_defender_hp > v_attacker_hp THEN
    v_winner_id := p_defender_id;
  ELSE
    v_winner_id := CASE
      WHEN COALESCE(v_attacker.power, 0) >= COALESCE(v_defender.power, 0) THEN p_attacker_id
      ELSE p_defender_id
    END;
  END IF;

  UPDATE public.users SET energy = energy - 15 WHERE auth_id = p_attacker_id AND energy >= 15;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Islem sirasinda enerji yetersiz kaldi');
  END IF;

  v_rating_diff := COALESCE(v_defender.pvp_rating, 1000) - COALESCE(v_attacker.pvp_rating, 1000);
  v_expected_a := 1.0 / (1.0 + power(10.0, v_rating_diff::NUMERIC / 400.0));

  IF v_winner_id = p_attacker_id THEN
    v_new_rating_a := COALESCE(v_attacker.pvp_rating, 1000) + (32 * (1.0 - v_expected_a))::INT;
    v_new_rating_d := COALESCE(v_defender.pvp_rating, 1000) + (32 * (0.0 - (1.0 - v_expected_a)))::INT;
  ELSE
    v_new_rating_a := COALESCE(v_attacker.pvp_rating, 1000) + (32 * (0.0 - v_expected_a))::INT;
    v_new_rating_d := COALESCE(v_defender.pvp_rating, 1000) + (32 * (1.0 - (1.0 - v_expected_a)))::INT;
  END IF;

  v_new_rating_a := GREATEST(v_new_rating_a, 0);
  v_new_rating_d := GREATEST(v_new_rating_d, 0);

  v_rating_diff := COALESCE(v_attacker.pvp_rating, 1000) - COALESCE(v_defender.pvp_rating, 1000);

  IF v_winner_id = p_attacker_id THEN
    v_steal_rate := CASE
      WHEN v_rating_diff > 200  THEN 0.01
      WHEN v_rating_diff > 0    THEN 0.02
      WHEN v_rating_diff > -200 THEN 0.03
      ELSE 0.05
    END;
    v_gold_stolen := GREATEST(
      LEAST((v_defender.gold * v_steal_rate)::BIGINT, 5000000::BIGINT),
      10000::BIGINT
    );
  ELSE
    v_gold_stolen := 0;
  END IF;

  UPDATE public.users
  SET gold = gold + CASE WHEN v_winner_id = p_attacker_id THEN v_gold_stolen ELSE 0 END,
      pvp_rating = v_new_rating_a,
      pvp_wins = pvp_wins + CASE WHEN v_winner_id = p_attacker_id THEN 1 ELSE 0 END,
      pvp_losses = pvp_losses + CASE WHEN v_winner_id = p_defender_id THEN 1 ELSE 0 END,
      warrior_bloodlust_streak = CASE
        WHEN COALESCE(character_class, '') <> 'warrior' THEN 0
        WHEN v_winner_id = p_attacker_id THEN LEAST(COALESCE(warrior_bloodlust_streak, 0) + 1, 3)
        ELSE 0
      END,
      warrior_bloodlust_until = CASE
        WHEN COALESCE(character_class, '') <> 'warrior' THEN NULL
        WHEN v_winner_id = p_attacker_id THEN now() + interval '30 minutes'
        ELSE NULL
      END
  WHERE auth_id = p_attacker_id;

  UPDATE public.users
  SET gold = gold - CASE WHEN v_winner_id = p_attacker_id THEN v_gold_stolen ELSE 0 END,
      pvp_rating = v_new_rating_d,
      pvp_wins = pvp_wins + CASE WHEN v_winner_id = p_defender_id THEN 1 ELSE 0 END,
      pvp_losses = pvp_losses + CASE WHEN v_winner_id = p_attacker_id THEN 1 ELSE 0 END,
      warrior_bloodlust_streak = CASE
        WHEN COALESCE(character_class, '') <> 'warrior' THEN 0
        WHEN v_winner_id = p_defender_id THEN LEAST(COALESCE(warrior_bloodlust_streak, 0) + 1, 3)
        ELSE 0
      END,
      warrior_bloodlust_until = CASE
        WHEN COALESCE(character_class, '') <> 'warrior' THEN NULL
        WHEN v_winner_id = p_defender_id THEN now() + interval '30 minutes'
        ELSE NULL
      END
  WHERE auth_id = p_defender_id;

  v_rep_change_winner := CASE WHEN v_winner_id = p_attacker_id THEN 3 ELSE 2 END;
  v_rep_change_loser := -2;

  IF v_winner_id = p_attacker_id THEN
    UPDATE public.users SET reputation = reputation + v_rep_change_winner WHERE auth_id = p_attacker_id;
    UPDATE public.users SET reputation = reputation + v_rep_change_loser WHERE auth_id = p_defender_id;
  ELSE
    UPDATE public.users SET reputation = reputation + 2 WHERE auth_id = p_defender_id;
    UPDATE public.users SET reputation = reputation - 2 WHERE auth_id = p_attacker_id;
  END IF;

  v_hospital_chance := CASE
    WHEN v_winner_id = p_attacker_id THEN 0.05
    ELSE 0.25
  END;

  IF random() < v_hospital_chance THEN
    v_hospital_triggered := true;
    v_hospital_minutes := floor(30 + random() * 120)::INT;

    IF v_winner_id = p_attacker_id THEN
      UPDATE public.users
      SET hospital_until = now() + (v_hospital_minutes || ' minutes')::INTERVAL
      WHERE auth_id = p_defender_id;
    ELSE
      UPDATE public.users
      SET hospital_until = now() + (v_hospital_minutes || ' minutes')::INTERVAL
      WHERE auth_id = p_attacker_id;
    END IF;
  END IF;

  INSERT INTO public.pvp_matches (
    mekan_id, attacker_id, defender_id, winner_id,
    attacker_power, defender_power,
    attacker_hp_remaining, defender_hp_remaining,
    gold_stolen, rep_change_winner, rep_change_loser,
    attacker_rating_before, attacker_rating_after, 
    defender_rating_before, defender_rating_after,
    is_critical_success, hospital_triggered
  ) VALUES (
    p_mekan_id, p_attacker_id, p_defender_id, v_winner_id,
    COALESCE(v_attacker.power, 0), COALESCE(v_defender.power, 0),
    GREATEST(v_attacker_hp, 0), GREATEST(v_defender_hp, 0),
    v_gold_stolen, v_rep_change_winner, v_rep_change_loser,
    COALESCE(v_attacker.pvp_rating, 1000), v_new_rating_a,
    COALESCE(v_defender.pvp_rating, 1000), v_new_rating_d,
    random() < 0.10, v_hospital_triggered
  );

  INSERT INTO public.pvp_daily_attacks(attacker_id, defender_id, attack_date, attack_count)
  VALUES (p_attacker_id, p_defender_id, CURRENT_DATE, 1)
  ON CONFLICT (attacker_id, defender_id, attack_date)
  DO UPDATE SET attack_count = public.pvp_daily_attacks.attack_count + 1;

  RETURN jsonb_build_object(
    'success', true,
    'winner_id', v_winner_id,
    'gold_stolen', v_gold_stolen,
    'rep_change_winner', v_rep_change_winner,
    'rep_change_loser', v_rep_change_loser,
    'rating_change_attacker', (v_new_rating_a - COALESCE(v_attacker.pvp_rating, 1000)),
    'hospital_triggered', v_hospital_triggered,
    'attacker_bloodlust_active', v_attacker_bloodlust_active,
    'defender_bloodlust_active', v_defender_bloodlust_active,
    'attacker_bloodlust_mult', v_attacker_bloodlust_mult,
    'defender_bloodlust_mult', v_defender_bloodlust_mult
  );
END;
$$;


ALTER FUNCTION "public"."pvp_attack"("p_attacker_id" "uuid", "p_defender_id" "uuid", "p_mekan_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."qa_active_probability"("p_segment" "text", "p_day" integer) RETURNS numeric
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_prob numeric;
BEGIN
  v_prob := CASE p_segment
    WHEN 'newbie' THEN 0.90 * exp(-0.11 * (p_day - 1))
    WHEN 'casual' THEN 0.88 * exp(-0.07 * (p_day - 1))
    WHEN 'normal' THEN 0.92 * exp(-0.045 * (p_day - 1))
    WHEN 'hardcore' THEN 0.97 * exp(-0.022 * (p_day - 1))
    WHEN 'whale' THEN 0.98 * exp(-0.018 * (p_day - 1))
    WHEN 'trader' THEN 0.91 * exp(-0.035 * (p_day - 1))
    WHEN 'pvp' THEN 0.93 * exp(-0.033 * (p_day - 1))
    WHEN 'guild' THEN 0.94 * exp(-0.030 * (p_day - 1))
    WHEN 'multi' THEN 0.95 * exp(-0.040 * (p_day - 1))
    WHEN 'exploit' THEN 0.96 * exp(-0.028 * (p_day - 1))
    ELSE 0.85 * exp(-0.050 * (p_day - 1))
  END;
  RETURN GREATEST(0.02, LEAST(0.99, v_prob));
END; $$;


ALTER FUNCTION "public"."qa_active_probability"("p_segment" "text", "p_day" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."qa_assert_qa_mode"() RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF coalesce(current_setting('app.qa_mode', true), '') <> 'true' THEN
    RAISE EXCEPTION 'QA simulation blocked. Set app.qa_mode=true (staging) before seed/sim runs.';
  END IF;
END;
$$;


ALTER FUNCTION "public"."qa_assert_qa_mode"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."qa_badge_season_smoke"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_auth uuid := gen_random_uuid();
  v_season_id uuid;
  v_season_num integer;
  v_results jsonb := '[]'::jsonb;
  v_ok boolean;
  v_claim json;
  v_claim2 json;
  v_claim_vip json;
  v_claim_low json;
  v_badge_id text;
  v_has_badge boolean;
  v_i integer;
BEGIN
  PERFORM set_config('app.qa_mode', 'true', true);

  DELETE FROM public.bp_player_quests WHERE player_id IN (
    SELECT auth_id FROM public.users WHERE username = 'qa_badge_smoke'
  );
  DELETE FROM public.bp_player_status WHERE player_id IN (
    SELECT auth_id FROM public.users WHERE username = 'qa_badge_smoke'
  );
  DELETE FROM public.inventory WHERE user_id IN (
    SELECT auth_id FROM public.users WHERE username = 'qa_badge_smoke'
  );
  DELETE FROM auth.users WHERE email = 'qa_badge_smoke@sim.local';
  DELETE FROM public.users WHERE username = 'qa_badge_smoke';

  INSERT INTO auth.users (
    id, aud, role, email, email_confirmed_at, created_at, updated_at,
    raw_app_meta_data, raw_user_meta_data
  ) VALUES (
    v_auth, 'authenticated', 'authenticated',
    'qa_badge_smoke@sim.local', now(), now(), now(),
    jsonb_build_object('provider', 'email', 'providers', ARRAY['email']),
    jsonb_build_object('username', 'qa_badge_smoke', 'is_bot', true)
  );

  INSERT INTO public.users (
    id, auth_id, username, email, display_name, level, xp, gold, energy, max_energy,
    attack, defense, health, max_health, power, gems, created_at, updated_at
  ) VALUES (
    v_auth, v_auth, 'qa_badge_smoke', 'qa_badge_smoke@sim.local', 'QA Badge Smoke',
    10, 1000, 500000, 100, 100, 30, 25, 120, 120, 200, 500, now(), now()
  )
  ON CONFLICT (auth_id) DO UPDATE SET username = EXCLUDED.username;

  SELECT id, season_number INTO v_season_id, v_season_num
  FROM public.bp_seasons WHERE is_active = true LIMIT 1;

  IF v_season_id IS NULL THEN
    PERFORM public.cron_bp_season_rotation();
    SELECT id, season_number INTO v_season_id, v_season_num
    FROM public.bp_seasons WHERE is_active = true LIMIT 1;
  END IF;

  v_badge_id := public.ensure_season_badge_item(v_season_num);

  PERFORM set_config('request.jwt.claim.sub', v_auth::text, true);
  PERFORM public.bp_ensure_player_initialized();

  UPDATE public.bp_player_status
  SET current_bpp = 20000, current_level = 20, has_vip = true, updated_at = now()
  WHERE player_id = v_auth AND season_id = v_season_id;

  v_claim := public.bp_claim_reward(20, false);
  SELECT EXISTS (
    SELECT 1 FROM public.inventory WHERE user_id = v_auth AND item_id = v_badge_id
  ) INTO v_has_badge;
  v_ok := COALESCE((v_claim->>'success')::boolean, false) AND v_has_badge;
  v_results := v_results || jsonb_build_array(jsonb_build_object(
    'test', 'BADGE-01_l20_normal_claim', 'area', 'badge', 'pass', v_ok,
    'detail', jsonb_build_object('claim', v_claim::jsonb, 'badge_id', v_badge_id, 'has_badge', v_has_badge)
  ));

  v_claim2 := public.bp_claim_reward(20, false);
  v_ok := COALESCE((v_claim2->>'success')::boolean, true) = false
      AND (v_claim2->>'error') = 'Bu ödül zaten alındı.';
  v_results := v_results || jsonb_build_array(jsonb_build_object(
    'test', 'BADGE-02_duplicate_claim', 'area', 'badge', 'pass', v_ok,
    'detail', v_claim2::jsonb
  ));

  DELETE FROM public.inventory WHERE user_id = v_auth AND item_id = v_badge_id;
  UPDATE public.bp_player_status
  SET current_bpp = 19000, current_level = 19,
      claimed_normal = '{}', claimed_vip = '{}', updated_at = now()
  WHERE player_id = v_auth AND season_id = v_season_id;
  v_claim_low := public.bp_claim_reward(20, false);
  v_ok := COALESCE((v_claim_low->>'success')::boolean, true) = false;
  v_results := v_results || jsonb_build_array(jsonb_build_object(
    'test', 'BADGE-03_level_19_blocked', 'area', 'badge', 'pass', v_ok,
    'detail', v_claim_low::jsonb
  ));

  UPDATE public.bp_player_status
  SET current_bpp = 20000, current_level = 20, has_vip = true,
      claimed_normal = '{}', claimed_vip = '{}', updated_at = now()
  WHERE player_id = v_auth AND season_id = v_season_id;
  v_claim_vip := public.bp_claim_reward(20, true);
  v_ok := COALESCE((v_claim_vip->>'success')::boolean, false)
      AND NOT EXISTS (SELECT 1 FROM public.inventory WHERE user_id = v_auth AND item_id = v_badge_id)
      AND EXISTS (SELECT 1 FROM public.inventory WHERE user_id = v_auth AND item_id = 'box_weapon_legendary');
  v_results := v_results || jsonb_build_array(jsonb_build_object(
    'test', 'BADGE-04_vip_legendary_not_badge', 'area', 'badge', 'pass', v_ok,
    'detail', v_claim_vip::jsonb
  ));

  INSERT INTO public.inventory (row_id, user_id, item_id, quantity, slot_position, is_equipped)
  SELECT gen_random_uuid(), v_auth, v_badge_id, 1,
    COALESCE((SELECT MAX(slot_position) + 1 FROM public.inventory WHERE user_id = v_auth), 0),
    false
  WHERE NOT EXISTS (
    SELECT 1 FROM public.inventory WHERE user_id = v_auth AND item_id = v_badge_id
  );
  UPDATE public.bp_player_status
  SET current_bpp = 20000, current_level = 20, claimed_normal = array[20], updated_at = now()
  WHERE player_id = v_auth AND season_id = v_season_id;
  PERFORM public.cron_bp_season_rotation();
  SELECT id, season_number INTO v_season_id, v_season_num
  FROM public.bp_seasons WHERE is_active = true LIMIT 1;
  PERFORM public.bp_ensure_player_initialized();
  v_ok := EXISTS (SELECT 1 FROM public.inventory WHERE user_id = v_auth AND item_id LIKE 'badge_season_%')
      AND EXISTS (
        SELECT 1 FROM public.bp_player_status
        WHERE player_id = v_auth AND season_id = v_season_id AND current_level = 0
      );
  v_results := v_results || jsonb_build_array(jsonb_build_object(
    'test', 'BADGE-05_rotation_reset_status_keeps_badge', 'area', 'badge', 'pass', v_ok,
    'detail', jsonb_build_object('new_season', v_season_num)
  ));

  DELETE FROM public.inventory WHERE user_id = v_auth;
  FOR v_i IN 0..19 LOOP
    INSERT INTO public.inventory (row_id, user_id, item_id, quantity, slot_position, is_equipped)
    VALUES (gen_random_uuid(), v_auth, 'scroll_upgrade_low', 1, v_i, false);
  END LOOP;
  UPDATE public.bp_player_status
  SET current_bpp = 20000, current_level = 20, claimed_normal = '{}', updated_at = now()
  WHERE player_id = v_auth AND season_id = v_season_id;
  v_claim := public.bp_claim_reward(20, false);
  v_ok := COALESCE((v_claim->>'success')::boolean, true) = false
      AND (v_claim->>'error') ILIKE '%envanter%';
  v_results := v_results || jsonb_build_array(jsonb_build_object(
    'test', 'BADGE-06_full_inventory_blocked', 'area', 'badge', 'pass', v_ok,
    'detail', v_claim::jsonb
  ));

  DELETE FROM public.bp_player_quests WHERE player_id = v_auth;
  DELETE FROM public.bp_player_status WHERE player_id = v_auth;
  DELETE FROM public.inventory WHERE user_id = v_auth;
  DELETE FROM auth.users WHERE id = v_auth;
  DELETE FROM public.users WHERE auth_id = v_auth;

  RETURN jsonb_build_object(
    'verdict', CASE WHEN NOT EXISTS (
      SELECT 1 FROM jsonb_array_elements(v_results) t
      WHERE COALESCE((t->>'pass')::boolean, false) = false
    ) THEN 'PASS' ELSE 'FAIL' END,
    'tests', v_results,
    'passed', (SELECT COUNT(*) FROM jsonb_array_elements(v_results) t WHERE (t->>'pass')::boolean),
    'failed', (SELECT COUNT(*) FROM jsonb_array_elements(v_results) t WHERE NOT COALESCE((t->>'pass')::boolean, false)),
    'total', jsonb_array_length(v_results),
    'generated_at', now()
  );
END;
$$;


ALTER FUNCTION "public"."qa_badge_season_smoke"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."qa_box_opening_smoke"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_auth uuid := gen_random_uuid();
  v_row_box uuid := gen_random_uuid();
  v_row uuid;
  v_i int;
  v_start jsonb;
  v_claim jsonb;
  v_claim2 jsonb;
  v_opening_id uuid;
  v_results jsonb := '[]'::jsonb;
  v_ok boolean;
BEGIN
  PERFORM set_config('app.qa_mode', 'true', true);

  DELETE FROM public.box_openings WHERE user_id IN (
    SELECT auth_id FROM public.users WHERE username = 'qa_box_open'
  );
  DELETE FROM public.inventory WHERE user_id IN (
    SELECT auth_id FROM public.users WHERE username = 'qa_box_open'
  );
  DELETE FROM auth.users WHERE email = 'qa_box_open@sim.local';
  DELETE FROM public.users WHERE username = 'qa_box_open';

  INSERT INTO auth.users (
    id, aud, role, email, email_confirmed_at, created_at, updated_at,
    raw_app_meta_data, raw_user_meta_data
  ) VALUES (
    v_auth, 'authenticated', 'authenticated',
    'qa_box_open@sim.local', now(), now(), now(),
    jsonb_build_object('provider', 'email', 'providers', ARRAY['email']),
    jsonb_build_object('username', 'qa_box_open', 'is_bot', true)
  );

  INSERT INTO public.users (
    id, auth_id, username, email, display_name, level, xp, gold, energy, max_energy,
    attack, defense, health, max_health, power, gems, created_at, updated_at
  ) VALUES (
    v_auth, v_auth, 'qa_box_open', 'qa_box_open@sim.local', 'QA Box Open',
    10, 1000, 500000, 100, 100, 30, 25, 120, 120, 200, 500, now(), now()
  )
  ON CONFLICT (auth_id) DO UPDATE SET gems = 500, username = EXCLUDED.username;

  PERFORM set_config('request.jwt.claim.sub', v_auth::text, true);

  INSERT INTO public.inventory (row_id, user_id, item_id, quantity, slot_position, is_equipped)
  VALUES (v_row_box, v_auth, 'box_weapon_common', 1, 0, false);
  v_start := public.start_box_opening(v_row_box, 'gems');
  v_opening_id := (v_start->>'opening_id')::uuid;
  v_claim := public.claim_box_reward(v_opening_id);
  v_ok := COALESCE((v_start->>'success')::boolean, false)
      AND COALESCE((v_claim->>'success')::boolean, false);
  v_results := v_results || jsonb_build_array(jsonb_build_object(
    'test', 'sparse_gem_open_claim', 'area', 'loot_box', 'pass', v_ok,
    'detail', jsonb_build_object('start', v_start, 'claim', v_claim)
  ));

  DELETE FROM public.box_openings WHERE user_id = v_auth;
  DELETE FROM public.inventory WHERE user_id = v_auth;

  v_row_box := gen_random_uuid();
  FOR v_i IN 0..18 LOOP
    INSERT INTO public.inventory (row_id, user_id, item_id, quantity, slot_position, is_equipped)
    VALUES (gen_random_uuid(), v_auth, 'scroll_upgrade_low', 1, v_i, false);
  END LOOP;
  INSERT INTO public.inventory (row_id, user_id, item_id, quantity, slot_position, is_equipped)
  VALUES (v_row_box, v_auth, 'box_weapon_common', 1, 19, false);
  v_start := public.start_box_opening(v_row_box, 'gems');
  v_opening_id := (v_start->>'opening_id')::uuid;
  v_claim := public.claim_box_reward(v_opening_id);
  v_ok := COALESCE((v_start->>'success')::boolean, false)
      AND COALESCE((v_claim->>'success')::boolean, false);
  v_results := v_results || jsonb_build_array(jsonb_build_object(
    'test', 'full_grid_19_plus_box', 'area', 'loot_box', 'pass', v_ok,
    'detail', jsonb_build_object('start', v_start, 'claim', v_claim)
  ));

  DELETE FROM public.box_openings WHERE user_id = v_auth;
  DELETE FROM public.inventory WHERE user_id = v_auth;

  v_ok := public.dungeon_add_item(v_auth, 'box_weapon_common', 1);
  SELECT row_id INTO v_row FROM public.inventory
  WHERE user_id = v_auth AND item_id = 'box_weapon_common' LIMIT 1;
  v_start := public.start_box_opening(v_row, 'gems');
  v_opening_id := (v_start->>'opening_id')::uuid;
  v_claim := public.claim_box_reward(v_opening_id);
  v_ok := v_ok
      AND COALESCE((v_start->>'success')::boolean, false)
      AND COALESCE((v_claim->>'success')::boolean, false);
  v_results := v_results || jsonb_build_array(jsonb_build_object(
    'test', 'dungeon_drop_then_open', 'area', 'loot_box', 'pass', v_ok,
    'detail', jsonb_build_object('start', v_start, 'claim', v_claim)
  ));

  DELETE FROM public.box_openings WHERE user_id = v_auth;
  DELETE FROM public.inventory WHERE user_id = v_auth;

  v_row_box := gen_random_uuid();
  INSERT INTO public.inventory (row_id, user_id, item_id, quantity, slot_position, is_equipped)
  VALUES (v_row_box, v_auth, 'box_weapon_common', 1, 0, false);
  v_start := public.start_box_opening(v_row_box, 'gems');
  v_opening_id := (v_start->>'opening_id')::uuid;
  v_claim := public.claim_box_reward(v_opening_id);
  v_claim2 := public.claim_box_reward(v_opening_id);
  v_ok := COALESCE((v_claim->>'success')::boolean, false)
      AND COALESCE((v_claim2->>'success')::boolean, true) = false
      AND v_claim2->>'error' = 'Açılma kaydı bulunamadı';
  v_results := v_results || jsonb_build_array(jsonb_build_object(
    'test', 'double_claim_not_found', 'area', 'loot_box', 'pass', v_ok,
    'detail', jsonb_build_object('first', v_claim, 'second', v_claim2)
  ));

  DELETE FROM public.box_openings WHERE user_id = v_auth;
  DELETE FROM public.inventory WHERE user_id = v_auth;
  DELETE FROM auth.users WHERE id = v_auth;
  DELETE FROM public.users WHERE auth_id = v_auth;

  RETURN jsonb_build_object(
    'verdict', CASE WHEN NOT EXISTS (
      SELECT 1 FROM jsonb_array_elements(v_results) t
      WHERE COALESCE((t->>'pass')::boolean, false) = false
    ) THEN 'PASS' ELSE 'FAIL' END,
    'tests', v_results,
    'passed', (SELECT COUNT(*) FROM jsonb_array_elements(v_results) t WHERE (t->>'pass')::boolean),
    'failed', (SELECT COUNT(*) FROM jsonb_array_elements(v_results) t WHERE NOT COALESCE((t->>'pass')::boolean, false)),
    'total', jsonb_array_length(v_results),
    'generated_at', now()
  );
END;
$$;


ALTER FUNCTION "public"."qa_box_opening_smoke"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."qa_call_as_bot"("p_bot_auth" "uuid", "p_function_name" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  PERFORM set_config('request.jwt.claim.sub', p_bot_auth::text, true);
  EXECUTE format('SELECT to_jsonb(%I())', p_function_name) INTO v_result;
  RETURN coalesce(v_result, '{}'::jsonb);
EXCEPTION
  WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;


ALTER FUNCTION "public"."qa_call_as_bot"("p_bot_auth" "uuid", "p_function_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."qa_cleanup_bots"() RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp', 'auth'
    AS $$
DECLARE
  v_deleted_users integer;
  v_bot_ids uuid[];
BEGIN
  PERFORM public.qa_assert_qa_mode();

  SELECT array_agg(auth_id) INTO v_bot_ids
  FROM public.users
  WHERE username LIKE 'qa_bot_%';

  IF v_bot_ids IS NULL OR array_length(v_bot_ids, 1) IS NULL THEN
    DELETE FROM public.qa_bot_profiles;
    RETURN json_build_object('success', true, 'deleted_auth_users', 0);
  END IF;

  DELETE FROM public.market_orders WHERE seller_id = ANY(v_bot_ids);
  DELETE FROM public.pvp_matches
  WHERE attacker_id = ANY(v_bot_ids) OR defender_id = ANY(v_bot_ids);
  DELETE FROM public.mekan_pvp_matches
  WHERE attacker_id = ANY(v_bot_ids)
     OR defender_id = ANY(v_bot_ids);
  DELETE FROM public.dungeon_runs WHERE player_id = ANY(v_bot_ids);
  DELETE FROM public.inventory WHERE user_id = ANY(v_bot_ids);
  DELETE FROM public.facilities WHERE user_id = ANY(v_bot_ids);
  DELETE FROM public.mekans WHERE owner_id = ANY(v_bot_ids) OR name LIKE 'QA Mekan %';

  UPDATE public.users SET guild_id = NULL, guild_role = NULL
  WHERE auth_id = ANY(v_bot_ids);

  DELETE FROM public.guild_contributions
  WHERE guild_id IN (SELECT id FROM public.guilds WHERE name LIKE 'QA Lonca %' OR leader_id = ANY(v_bot_ids));
  DELETE FROM public.guild_activities
  WHERE guild_id IN (SELECT id FROM public.guilds WHERE name LIKE 'QA Lonca %' OR leader_id = ANY(v_bot_ids));
  DELETE FROM public.guild_blueprints
  WHERE guild_id IN (SELECT id FROM public.guilds WHERE name LIKE 'QA Lonca %' OR leader_id = ANY(v_bot_ids));
  DELETE FROM public.guild_daily_donations
  WHERE guild_id IN (SELECT id FROM public.guilds WHERE name LIKE 'QA Lonca %' OR leader_id = ANY(v_bot_ids));

  DELETE FROM public.guilds
  WHERE name LIKE 'QA Lonca %' OR leader_id = ANY(v_bot_ids);

  DELETE FROM auth.users au
  USING public.users u
  WHERE au.id = u.auth_id
    AND u.username LIKE 'qa_bot_%';

  GET DIAGNOSTICS v_deleted_users = ROW_COUNT;

  DELETE FROM public.users WHERE username LIKE 'qa_bot_%';
  DELETE FROM public.qa_bot_profiles;

  RETURN json_build_object('success', true, 'deleted_auth_users', v_deleted_users);
END;
$$;


ALTER FUNCTION "public"."qa_cleanup_bots"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."qa_create_full_snapshot_backup"("p_note" "text" DEFAULT 'pre-change full snapshot'::"text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_backup_id text := 'bkp_' || to_char(now(), 'YYYYMMDD_HH24MISS');
  v_schema text := 'backup_' || to_char(now(), 'YYYYMMDD_HH24MISS');
  v_tbl record;
  v_sql text;
  v_rows bigint;
  v_total_rows bigint := 0;
  v_count int := 0;
BEGIN
  EXECUTE format('CREATE SCHEMA IF NOT EXISTS %I', v_schema);

  -- Clone all public tables with data
  FOR v_tbl IN
    SELECT tablename
    FROM pg_tables
    WHERE schemaname = 'public'
      AND tablename NOT LIKE 'backup_%'
    ORDER BY tablename
  LOOP
    v_sql := format('CREATE TABLE %I.%I AS TABLE public.%I', v_schema, v_tbl.tablename, v_tbl.tablename);
    EXECUTE v_sql;

    EXECUTE format('SELECT count(*) FROM %I.%I', v_schema, v_tbl.tablename) INTO v_rows;

    INSERT INTO public.qa_backup_table_stats(backup_id, schema_name, table_name, row_count)
    VALUES (v_backup_id, 'public', v_tbl.tablename, COALESCE(v_rows,0));

    v_total_rows := v_total_rows + COALESCE(v_rows,0);
    v_count := v_count + 1;
  END LOOP;

  -- Snapshot auth.users into backup schema when accessible
  BEGIN
    EXECUTE format('CREATE TABLE %I.auth_users AS TABLE auth.users', v_schema);
    EXECUTE format('SELECT count(*) FROM %I.auth_users', v_schema) INTO v_rows;

    INSERT INTO public.qa_backup_table_stats(backup_id, schema_name, table_name, row_count)
    VALUES (v_backup_id, 'auth', 'users', COALESCE(v_rows,0));

    v_total_rows := v_total_rows + COALESCE(v_rows,0);
    v_count := v_count + 1;
  EXCEPTION WHEN OTHERS THEN
    -- skip if inaccessible
    NULL;
  END;

  -- Snapshot storage.objects if accessible
  BEGIN
    EXECUTE format('CREATE TABLE %I.storage_objects AS TABLE storage.objects', v_schema);
    EXECUTE format('SELECT count(*) FROM %I.storage_objects', v_schema) INTO v_rows;

    INSERT INTO public.qa_backup_table_stats(backup_id, schema_name, table_name, row_count)
    VALUES (v_backup_id, 'storage', 'objects', COALESCE(v_rows,0));

    v_total_rows := v_total_rows + COALESCE(v_rows,0);
    v_count := v_count + 1;
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  INSERT INTO public.qa_backup_registry(backup_id, includes_schemas, table_count, row_count_total, notes)
  VALUES (v_backup_id, ARRAY['public','auth','storage'], v_count, v_total_rows, p_note || ' :: ' || v_schema);

  RETURN json_build_object(
    'success', true,
    'backup_id', v_backup_id,
    'backup_schema', v_schema,
    'table_count', v_count,
    'row_count_total', v_total_rows
  );
END;
$$;


ALTER FUNCTION "public"."qa_create_full_snapshot_backup"("p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."qa_export_run_summary"("p_run_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_bots integer;
  v_d1 integer;
  v_d7 integer;
  v_d30 integer;
  v_base integer;
BEGIN
  SELECT count(*) INTO v_bots FROM public.qa_bot_profiles;

  SELECT active_users INTO v_d1
  FROM public.qa_sim_checkpoints
  WHERE run_id = p_run_id AND checkpoint_day = 1;

  SELECT active_users INTO v_d7
  FROM public.qa_sim_checkpoints
  WHERE run_id = p_run_id AND checkpoint_day = 7;

  SELECT active_users INTO v_d30
  FROM public.qa_sim_checkpoints
  WHERE run_id = p_run_id AND checkpoint_day = 30;

  v_base := GREATEST(v_bots, 1);

  RETURN json_build_object(
    'run_id', p_run_id,
    'bots', v_bots,
    'retention', json_build_object(
      'd1', round(coalesce(v_d1, 0)::numeric / v_base, 4),
      'd7', round(coalesce(v_d7, 0)::numeric / v_base, 4),
      'd30', round(coalesce(v_d30, 0)::numeric / v_base, 4)
    ),
    'economy', (
      SELECT json_build_object(
        'gold_in', coalesce(sum(gold_earned), 0),
        'gold_out', coalesce(sum(gold_spent), 0),
        'item_in', coalesce(sum(items_minted), 0),
        'item_out', coalesce(sum(items_burned), 0),
        'gems_out', coalesce(sum(gems_spent), 0)
      )
      FROM public.qa_sim_daily_events
      WHERE run_id = p_run_id
    ),
    'exploits', (
      SELECT coalesce(json_agg(json_build_object(
        'key', exploit_key,
        'attempts', attempted_count,
        'success', success_count,
        'impact_gold', estimated_impact_gold,
        'impact_gems', estimated_impact_gems,
        'severity', severity
      )), '[]'::json)
      FROM public.qa_sim_exploit_findings
      WHERE run_id = p_run_id
    ),
    'segments', (
      SELECT coalesce(json_object_agg(segment, cnt), '{}'::json)
      FROM (
        SELECT segment, count(*) AS cnt
        FROM public.qa_bot_profiles
        GROUP BY segment
      ) s
    )
  );
END;
$$;


ALTER FUNCTION "public"."qa_export_run_summary"("p_run_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."qa_loot_box_ev"("p_box_id" "text") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  WITH drops AS (
    SELECT e.weight, e.min_quantity, e.max_quantity, COALESCE(i.rarity, 'common') AS rarity,
      COALESCE(i.base_price, 0) AS base_price, COALESCE(i.vendor_sell_price, 0) AS vendor_sell, COALESCE(i.power, 0) AS power
    FROM public.loot_box_drop_entries e JOIN public.items i ON i.id = e.item_id
    WHERE e.box_id = p_box_id AND e.is_active = TRUE
  ), box AS (SELECT * FROM public.loot_box_configs WHERE id = p_box_id),
  agg AS (
    SELECT SUM(weight) AS tw,
      SUM(weight * ((min_quantity + max_quantity) / 2.0) * base_price) / NULLIF(SUM(weight), 0) AS ev_base,
      SUM(weight * ((min_quantity + max_quantity) / 2.0) * vendor_sell) / NULLIF(SUM(weight), 0) AS ev_vendor,
      SUM(weight * power) / NULLIF(SUM(weight), 0) AS ev_power,
      SUM(CASE WHEN rarity = 'common' THEN weight ELSE 0 END) / NULLIF(SUM(weight), 0) * 100 AS pct_common,
      SUM(CASE WHEN rarity = 'uncommon' THEN weight ELSE 0 END) / NULLIF(SUM(weight), 0) * 100 AS pct_uncommon,
      SUM(CASE WHEN rarity = 'rare' THEN weight ELSE 0 END) / NULLIF(SUM(weight), 0) * 100 AS pct_rare,
      SUM(CASE WHEN rarity = 'epic' THEN weight ELSE 0 END) / NULLIF(SUM(weight), 0) * 100 AS pct_epic,
      SUM(CASE WHEN rarity = 'legendary' THEN weight ELSE 0 END) / NULLIF(SUM(weight), 0) * 100 AS pct_legendary,
      SUM(CASE WHEN rarity = 'mythic' THEN weight ELSE 0 END) / NULLIF(SUM(weight), 0) * 100 AS pct_mythic
    FROM drops
  )
  SELECT jsonb_build_object('box_id', b.id, 'name', b.name, 'theme_id', b.theme_id, 'currency', b.currency_type, 'price', b.price,
    'reward_multiplier', b.reward_multiplier, 'jackpot_rate_pct', ROUND(((a.pct_legendary + a.pct_mythic))::numeric, 3),
    'rarity_pct', jsonb_build_object('common', ROUND(a.pct_common::numeric, 2), 'uncommon', ROUND(a.pct_uncommon::numeric, 2),
      'rare', ROUND(a.pct_rare::numeric, 2), 'epic', ROUND(a.pct_epic::numeric, 2), 'legendary', ROUND(a.pct_legendary::numeric, 2),
      'mythic', ROUND(a.pct_mythic::numeric, 2)),
    'ev_base_price', ROUND((a.ev_base * b.reward_multiplier)::numeric, 0), 'ev_vendor_sell', ROUND((a.ev_vendor * b.reward_multiplier)::numeric, 0),
    'ev_power', ROUND(a.ev_power::numeric, 1), 'gold_per_gem_ref', 600,
    'cost_gold_equiv', CASE WHEN b.currency_type = 'gems' THEN b.price * 600 ELSE b.price END,
    'vendor_rtp_pct', ROUND(((a.ev_vendor * b.reward_multiplier) / NULLIF(CASE WHEN b.currency_type = 'gems' THEN b.price * 600.0 ELSE b.price END, 0) * 100)::numeric, 1))
  FROM box b CROSS JOIN agg a;
$$;


ALTER FUNCTION "public"."qa_loot_box_ev"("p_box_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."qa_restore_snapshot_backup"("p_backup_id" "text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_reg record;
  v_schema text;
  v_tbl record;
  v_sql text;
BEGIN
  SELECT * INTO v_reg
  FROM public.qa_backup_registry
  WHERE backup_id = p_backup_id;

  IF v_reg IS NULL THEN
    RETURN json_build_object('success', false, 'error', 'backup_id not found');
  END IF;

  v_schema := split_part(v_reg.notes, '::', 2);
  v_schema := btrim(v_schema);

  IF v_schema IS NULL OR v_schema = '' THEN
    RETURN json_build_object('success', false, 'error', 'backup schema parse failed');
  END IF;

  FOR v_tbl IN
    SELECT table_name
    FROM public.qa_backup_table_stats
    WHERE backup_id = p_backup_id
      AND schema_name = 'public'
    ORDER BY table_name
  LOOP
    v_sql := format('TRUNCATE TABLE public.%I CASCADE', v_tbl.table_name);
    EXECUTE v_sql;

    v_sql := format('INSERT INTO public.%I SELECT * FROM %I.%I', v_tbl.table_name, v_schema, v_tbl.table_name);
    EXECUTE v_sql;
  END LOOP;

  RETURN json_build_object('success', true, 'restored_from', p_backup_id, 'source_schema', v_schema);
END;
$$;


ALTER FUNCTION "public"."qa_restore_snapshot_backup"("p_backup_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."qa_run_30_day_simulation"("p_days" integer DEFAULT 30, "p_run_id" "uuid" DEFAULT "gen_random_uuid"()) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_day integer;
  v_day_ts timestamptz;
BEGIN
  PERFORM public.qa_assert_qa_mode();

  DELETE FROM public.qa_sim_daily_events WHERE run_id = p_run_id;
  DELETE FROM public.qa_sim_checkpoints WHERE run_id = p_run_id;
  DELETE FROM public.qa_sim_exploit_findings WHERE run_id = p_run_id;
  DELETE FROM public.qa_sim_exploit_attempts WHERE run_id = p_run_id;

  INSERT INTO public.qa_sim_daily_events (
    run_id, sim_day, bot_auth_id, segment, is_active, session_minutes,
    quests_done, dungeon_runs, pvp_attacks, market_buys, market_sells,
    craft_actions, guild_actions, mekan_actions,
    hospital_minutes, prison_minutes, hospital_escape_auto, prison_escape_auto,
    gold_earned, gold_spent, gems_earned, gems_spent, xp_earned,
    items_minted, items_burned, churn_risk, created_at
  )
  SELECT
    p_run_id,
    d.sim_day,
    b.bot_auth_id,
    b.segment,
    (random() < public.qa_active_probability(b.segment, d.sim_day)),
    CASE WHEN random() >= public.qa_active_probability(b.segment, d.sim_day) THEN 0
         WHEN b.segment = 'newbie' THEN 3 + floor(random() * 14)::int
         WHEN b.segment = 'casual' THEN 8 + floor(random() * 20)::int
         WHEN b.segment = 'normal' THEN 45 + floor(random() * 75)::int
         WHEN b.segment = 'hardcore' THEN 110 + floor(random() * 130)::int
         WHEN b.segment = 'whale' THEN 70 + floor(random() * 160)::int
         ELSE 20 + floor(random() * 60)::int END,
    floor(random() * 3)::int,
    floor(random() * 4)::int,
    floor(random() * 3)::int,
    floor(random() * 2)::int,
    floor(random() * 3)::int,
    floor(random() * 4)::int,
    floor(random() * 2)::int,
    floor(random() * 2)::int,
    CASE WHEN random() < 0.06 THEN 15 + floor(random() * 120)::int ELSE 0 END,
    CASE WHEN random() < 0.03 THEN 20 + floor(random() * 90)::int ELSE 0 END,
    random() < 0.02,
    random() < 0.015,
    CASE WHEN b.segment IN ('whale', 'hardcore') THEN (800 + floor(random() * 500)::int)
         ELSE (300 + floor(random() * 500)::int) END,
    (120 + floor(random() * 350)::int),
    0,
    CASE WHEN b.segment = 'whale' AND random() < 0.25 THEN 1 + floor(random() * 8)::int
         WHEN random() < 0.04 THEN 1 ELSE 0 END,
    (40 + floor(random() * 200)::int),
    floor(random() * 5)::int,
    floor(random() * 3)::int,
    CASE WHEN b.segment = 'newbie' THEN 0.35 + random() * 0.35 ELSE 0.10 + random() * 0.55 END,
    now() - ((p_days - d.sim_day) || ' days')::interval
  FROM generate_series(1, p_days) AS d(sim_day)
  CROSS JOIN public.qa_bot_profiles b;

  FOR v_day IN SELECT x FROM unnest(ARRAY[1, 3, 7, 14, 30]) AS t(x) WHERE x <= p_days LOOP
    v_day_ts := now() - ((p_days - v_day) || ' days')::interval;
    INSERT INTO public.qa_sim_checkpoints (
      run_id, checkpoint_day, active_users, retained_users, avg_session_minutes,
      total_gold_earned, total_gold_spent, total_gems_spent,
      total_items_minted, total_items_burned,
      daily_gold_earned, daily_gold_spent,
      cumulative_gold_earned, cumulative_gold_spent,
      cumulative_gems_spent, cumulative_items_minted, cumulative_items_burned,
      created_at
    )
    SELECT
      p_run_id, v_day,
      count(*) FILTER (WHERE e.is_active),
      count(*) FILTER (WHERE e.sim_day = 1 OR (e.is_active AND e.churn_risk < 0.80)),
      coalesce(avg(e.session_minutes), 0),
      coalesce(sum(e.gold_earned), 0), coalesce(sum(e.gold_spent), 0),
      coalesce(sum(e.gems_spent), 0), coalesce(sum(e.items_minted), 0),
      coalesce(sum(e.items_burned), 0),
      coalesce(sum(e.gold_earned), 0), coalesce(sum(e.gold_spent), 0),
      coalesce((SELECT sum(gold_earned) FROM public.qa_sim_daily_events x WHERE x.run_id = p_run_id AND x.sim_day <= v_day), 0),
      coalesce((SELECT sum(gold_spent) FROM public.qa_sim_daily_events x WHERE x.run_id = p_run_id AND x.sim_day <= v_day), 0),
      coalesce((SELECT sum(gems_spent) FROM public.qa_sim_daily_events x WHERE x.run_id = p_run_id AND x.sim_day <= v_day), 0),
      coalesce((SELECT sum(items_minted) FROM public.qa_sim_daily_events x WHERE x.run_id = p_run_id AND x.sim_day <= v_day), 0),
      coalesce((SELECT sum(items_burned) FROM public.qa_sim_daily_events x WHERE x.run_id = p_run_id AND x.sim_day <= v_day), 0),
      v_day_ts
    FROM public.qa_sim_daily_events e
    WHERE e.run_id = p_run_id AND e.sim_day = v_day
    ON CONFLICT (run_id, checkpoint_day) DO UPDATE SET
      active_users = EXCLUDED.active_users,
      retained_users = EXCLUDED.retained_users,
      avg_session_minutes = EXCLUDED.avg_session_minutes,
      total_gold_earned = EXCLUDED.total_gold_earned,
      total_gold_spent = EXCLUDED.total_gold_spent,
      total_gems_spent = EXCLUDED.total_gems_spent,
      total_items_minted = EXCLUDED.total_items_minted,
      total_items_burned = EXCLUDED.total_items_burned,
      daily_gold_earned = EXCLUDED.daily_gold_earned,
      daily_gold_spent = EXCLUDED.daily_gold_spent,
      cumulative_gold_earned = EXCLUDED.cumulative_gold_earned,
      cumulative_gold_spent = EXCLUDED.cumulative_gold_spent,
      cumulative_gems_spent = EXCLUDED.cumulative_gems_spent,
      cumulative_items_minted = EXCLUDED.cumulative_items_minted,
      cumulative_items_burned = EXCLUDED.cumulative_items_burned,
      created_at = EXCLUDED.created_at;
  END LOOP;

  PERFORM public.qa_run_exploit_battery(p_run_id);

  RETURN json_build_object(
    'success', true,
    'run_id', p_run_id,
    'days', p_days,
    'bots', (SELECT count(*) FROM public.qa_bot_profiles),
    'events', (SELECT count(*) FROM public.qa_sim_daily_events WHERE run_id = p_run_id),
    'summary', public.qa_export_run_summary(p_run_id),
    'bulk_sim', true
  );
END;
$$;


ALTER FUNCTION "public"."qa_run_30_day_simulation"("p_days" integer, "p_run_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."qa_run_exploit_battery"("p_run_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_run_start timestamptz; v_run_end timestamptz; v_bot uuid; v_resp jsonb; v_attempt integer; v_out json;
BEGIN
  DELETE FROM public.qa_sim_exploit_attempts WHERE run_id = p_run_id;
  DELETE FROM public.qa_sim_exploit_findings WHERE run_id = p_run_id;
  SELECT min(created_at), max(created_at) INTO v_run_start, v_run_end FROM public.qa_sim_daily_events WHERE run_id = p_run_id;
  IF v_run_start IS NULL THEN RETURN json_build_object('success', false, 'error', 'run_not_found'); END IF;

  INSERT INTO public.qa_sim_exploit_attempts (run_id, exploit_key, bot_auth_id, attempt_no, succeeded, response, gold_delta, gems_delta)
  SELECT p_run_id, 'multi_account_gold_funnel', pair.attacker_id, pair.hits, pair.hits >= 3, jsonb_build_object('defender', pair.defender_id, 'hits', pair.hits, 'gold_funneled', pair.total_gold), CASE WHEN pair.hits >= 3 THEN pair.total_gold ELSE 0 END, 0
  FROM (SELECT pm.attacker_id, pm.defender_id, count(*) AS hits, sum(pm.gold_stolen) AS total_gold FROM public.pvp_matches pm JOIN public.qa_bot_profiles b ON b.bot_auth_id = pm.attacker_id AND b.segment = 'multi' WHERE pm.created_at BETWEEN v_run_start AND v_run_end + interval '1 hour' GROUP BY pm.attacker_id, pm.defender_id) pair
  LIMIT 400;

  INSERT INTO public.qa_sim_exploit_attempts (run_id, exploit_key, bot_auth_id, attempt_no, succeeded, response, gold_delta, gems_delta)
  SELECT p_run_id, 'market_price_manipulation', mo.seller_id, row_number() OVER (PARTITION BY mo.seller_id ORDER BY mo.created_at), mo.price > GREATEST(100, i.base_price * 2), jsonb_build_object('price', mo.price, 'base_price', i.base_price, 'item', i.name), mo.price, 0
  FROM public.market_orders mo JOIN public.items i ON i.id = mo.item_id JOIN public.qa_bot_profiles b ON b.bot_auth_id = mo.seller_id WHERE mo.created_at BETWEEN v_run_start AND v_run_end + interval '1 hour' LIMIT 400;

  INSERT INTO public.qa_sim_exploit_attempts (run_id, exploit_key, bot_auth_id, attempt_no, succeeded, response, gold_delta, gems_delta)
  SELECT p_run_id, 'hospital_escape_abuse', e.bot_auth_id, e.sim_day, e.hospital_escape_auto AND e.hospital_minutes > 0 AND e.gems_spent > 0 AND (e.gems_spent::numeric / GREATEST(e.hospital_minutes, 1)) > 0.5, jsonb_build_object('minutes', e.hospital_minutes, 'gems_spent', e.gems_spent, 'segment', e.segment), 0, e.gems_spent
  FROM public.qa_sim_daily_events e WHERE e.run_id = p_run_id AND e.hospital_minutes > 0 AND e.hospital_escape_auto LIMIT 400;

  INSERT INTO public.qa_sim_exploit_attempts (run_id, exploit_key, bot_auth_id, attempt_no, succeeded, response, gold_delta, gems_delta)
  SELECT p_run_id, 'prison_escape_abuse', e.bot_auth_id, e.sim_day, e.prison_escape_auto AND e.prison_minutes > 0 AND e.gems_spent > 0 AND (e.gems_spent::numeric / GREATEST(e.prison_minutes, 1)) > 0.4, jsonb_build_object('minutes', e.prison_minutes, 'gems_spent', e.gems_spent, 'segment', e.segment), 0, e.gems_spent
  FROM public.qa_sim_daily_events e WHERE e.run_id = p_run_id AND e.prison_minutes > 0 AND e.prison_escape_auto LIMIT 400;

  INSERT INTO public.qa_sim_exploit_attempts (run_id, exploit_key, bot_auth_id, attempt_no, succeeded, response, gold_delta, gems_delta)
  SELECT p_run_id, 'cooldown_bypass', e.bot_auth_id, e.sim_day, e.dungeon_runs >= 4, jsonb_build_object('dungeon_runs', e.dungeon_runs, 'segment', e.segment), e.gold_earned, 0
  FROM public.qa_sim_daily_events e WHERE e.run_id = p_run_id AND e.is_active AND e.dungeon_runs >= 3 LIMIT 300;

  v_attempt := 0;
  FOR v_bot IN SELECT bot_auth_id FROM public.qa_bot_profiles WHERE segment = 'whale' ORDER BY random() LIMIT 15 LOOP
    v_resp := public.qa_call_as_bot(v_bot, 'buy_vip_pass'); v_attempt := v_attempt + 1;
    INSERT INTO public.qa_sim_exploit_attempts (run_id, exploit_key, bot_auth_id, attempt_no, succeeded, response, gold_delta, gems_delta)
    VALUES (p_run_id, 'premium_stack_abuse', v_bot, 1, false, jsonb_build_object('phase', 'baseline_first_purchase', 'rpc', v_resp), 0, 0);
    v_resp := public.qa_call_as_bot(v_bot, 'buy_vip_pass'); v_attempt := v_attempt + 1;
    INSERT INTO public.qa_sim_exploit_attempts (run_id, exploit_key, bot_auth_id, attempt_no, succeeded, response, gold_delta, gems_delta)
    VALUES (p_run_id, 'premium_stack_abuse', v_bot, 2, coalesce(v_resp->>'success', 'false') = 'true', jsonb_build_object('phase', 'duplicate_stack_attempt', 'rpc', v_resp), 0, -coalesce((v_resp->>'cost')::bigint, 0));
  END LOOP;

  INSERT INTO public.qa_sim_exploit_findings (run_id, exploit_key, attempted_count, success_count, estimated_impact_gold, estimated_impact_gems, severity, mitigation)
  SELECT p_run_id, a.exploit_key, count(*)::integer, count(*) FILTER (WHERE a.succeeded)::integer, coalesce(sum(a.gold_delta) FILTER (WHERE a.succeeded), 0), coalesce(sum(a.gems_delta) FILTER (WHERE a.succeeded), 0),
    CASE a.exploit_key WHEN 'multi_account_gold_funnel' THEN 'critical' WHEN 'premium_stack_abuse' THEN 'critical' WHEN 'market_price_manipulation' THEN 'high' WHEN 'cooldown_bypass' THEN 'high' WHEN 'prison_escape_abuse' THEN 'high' ELSE 'medium' END,
    CASE a.exploit_key WHEN 'multi_account_gold_funnel' THEN 'Device fingerprint + transfer graph + delayed escrow' WHEN 'market_price_manipulation' THEN 'Median band guardrails + listing caps' WHEN 'cooldown_bypass' THEN 'Server-side cooldown nonce enforcement' WHEN 'hospital_escape_abuse' THEN 'Escalating gem cost + daily cap' WHEN 'prison_escape_abuse' THEN 'Progressive bail cost + alt linkage penalties' WHEN 'premium_stack_abuse' THEN 'Idempotent VIP grant + single entitlement source' ELSE 'Review exploit attempt logs' END
  FROM public.qa_sim_exploit_attempts a WHERE a.run_id = p_run_id GROUP BY a.exploit_key
  ON CONFLICT (run_id, exploit_key) DO UPDATE SET attempted_count = EXCLUDED.attempted_count, success_count = EXCLUDED.success_count, estimated_impact_gold = EXCLUDED.estimated_impact_gold, estimated_impact_gems = EXCLUDED.estimated_impact_gems, severity = EXCLUDED.severity, mitigation = EXCLUDED.mitigation, created_at = now();

  SELECT json_build_object('success', true, 'run_id', p_run_id, 'exploit_types', (SELECT count(DISTINCT exploit_key) FROM public.qa_sim_exploit_findings WHERE run_id = p_run_id), 'total_attempts', (SELECT count(*) FROM public.qa_sim_exploit_attempts WHERE run_id = p_run_id)) INTO v_out;
  RETURN v_out;
END; $$;


ALTER FUNCTION "public"."qa_run_exploit_battery"("p_run_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."qa_seed_bots"("p_bot_count" integer DEFAULT 1000) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp', 'auth'
    AS $$
DECLARE
  v_idx integer;
  v_bot_auth uuid;
  v_bot_user uuid;
  v_segment text;
  v_behavior text;
  v_level integer;
  v_gold bigint;
  v_gems integer;
  v_energy integer;
  v_class text;
  v_guild_id uuid;
  v_guild_number integer;
  v_current_guild_id uuid;
  v_item_id text;
  v_equip_slot text;
  v_slot text;
BEGIN
  PERFORM public.qa_assert_qa_mode();

  DELETE FROM public.guild_contributions
  WHERE guild_id IN (SELECT id FROM public.guilds WHERE name LIKE 'QA Lonca %');
  DELETE FROM public.guild_activities
  WHERE guild_id IN (SELECT id FROM public.guilds WHERE name LIKE 'QA Lonca %');
  DELETE FROM public.guild_blueprints
  WHERE guild_id IN (SELECT id FROM public.guilds WHERE name LIKE 'QA Lonca %');
  DELETE FROM public.guild_daily_donations
  WHERE guild_id IN (SELECT id FROM public.guilds WHERE name LIKE 'QA Lonca %');
  DELETE FROM public.guilds WHERE name LIKE 'QA Lonca %';

  FOR v_idx IN 1..p_bot_count LOOP
    v_bot_auth := gen_random_uuid();
    v_bot_user := gen_random_uuid();
    v_segment := public.qa_segment_for_bot(v_idx, p_bot_count);
    v_behavior := CASE v_segment
      WHEN 'newbie' THEN 'first_time_no_guide_fast_bored'
      WHEN 'casual' THEN 'daily_15_min'
      WHEN 'normal' THEN 'daily_60_120_min'
      WHEN 'hardcore' THEN 'full_energy_optimizer'
      WHEN 'whale' THEN 'vip_premium_spender'
      WHEN 'trader' THEN 'buy_sell_flip_market'
      WHEN 'pvp' THEN 'constant_attack'
      WHEN 'guild' THEN 'social_coop'
      WHEN 'multi' THEN 'alt_account_farmer'
      WHEN 'exploit' THEN 'abuse_hunter'
      ELSE 'generic'
    END;
    v_level := 1 + ((v_idx - 1) * 64 / GREATEST(p_bot_count - 1, 1));
    v_level := LEAST(65, GREATEST(1, v_level + floor(random() * 3)::int));
    v_gold := floor((1500 + power(v_level::numeric, 1.85) * 650) * (0.45 + random() * 1.10))::bigint;
    v_gems := floor((v_level * 2) * (0.5 + random()))::int;
    v_energy := 15 + floor(random() * 85)::int;
    v_class := (ARRAY['warrior', 'alchemist', 'shadow'])[1 + (v_idx % 3)];

    INSERT INTO auth.users (
      id, aud, role, email, email_confirmed_at,
      created_at, updated_at, raw_app_meta_data, raw_user_meta_data
    )
    VALUES (
      v_bot_auth, 'authenticated', 'authenticated',
      format('qa_bot_%s@sim.local', v_idx),
      now(), now(), now(),
      jsonb_build_object('provider', 'email', 'providers', ARRAY['email']),
      jsonb_build_object('username', format('qa_bot_%s', v_idx), 'is_bot', true)
    );

    IF ((v_idx - 1) % 40) = 0 THEN
      v_current_guild_id := gen_random_uuid();
    END IF;
    v_guild_id := v_current_guild_id;
    v_guild_number := 1 + ((v_idx - 1) / 40);

    INSERT INTO public.users (
      id, auth_id, username, email, display_name, level, xp, gold, energy, max_energy,
      attack, defense, health, max_health, power,
      tutorial_completed, total_playtime_seconds, gems, experience,
      addiction_level, tolerance,
      pvp_wins, pvp_losses, pvp_rating, reputation,
      character_class, luck, guild_id, guild_role,
      created_at, updated_at, last_login_at
    )
    VALUES (
      v_bot_user, v_bot_auth,
      format('qa_bot_%s', v_idx),
      format('qa_bot_%s@sim.local', v_idx),
      format('QA Bot %s', v_idx),
      v_level, v_level * 120 + floor(random() * 500)::int,
      v_gold, v_energy, 100,
      18 + v_level * 3 + floor(random() * 8)::int,
      16 + v_level * 2 + floor(random() * 8)::int,
      120 + v_level * 8, 120 + v_level * 8, 100 + v_level * 12,
      true, (600 + floor(random() * 12000)::int),
      v_gems, v_level * 120,
      floor(random() * 12)::int, floor(random() * 10)::int,
      floor(random() * 80)::int, floor(random() * 80)::int,
      850 + floor(random() * 700)::int,
      floor(random() * (v_level * 20))::int,
      v_class, floor(random() * (10 + v_level))::int,
      v_guild_id,
      CASE WHEN ((v_idx - 1) % 40) = 0 THEN 'leader' ELSE 'member' END,
      now() - (floor(random() * 40)::text || ' days')::interval,
      now(), now() - (floor(random() * 6)::text || ' days')::interval
    )
    ON CONFLICT (auth_id) DO UPDATE SET
      username = EXCLUDED.username, level = EXCLUDED.level, gold = EXCLUDED.gold,
      gems = EXCLUDED.gems, character_class = EXCLUDED.character_class,
      guild_id = EXCLUDED.guild_id, guild_role = EXCLUDED.guild_role,
      updated_at = now();

    IF ((v_idx - 1) % 40) = 0 AND v_guild_id IS NOT NULL THEN
      INSERT INTO public.guilds (
        id, name, tag, leader_id, description, level, max_members, monument_level
      )
      VALUES (
        v_guild_id,
        format('QA Lonca %s', lpad(v_guild_number::text, 2, '0')),
        format('Q%s', lpad(v_guild_number::text, 2, '0')),
        v_bot_auth, 'Solo test loncasi',
        1 + floor(random() * 5)::int, 50, floor(random() * 10)::int
      )
      ON CONFLICT (name) DO NOTHING;
    END IF;

    INSERT INTO public.qa_bot_profiles (bot_auth_id, bot_user_id, segment, behavior_model, level_seed)
    VALUES (v_bot_auth, v_bot_user, v_segment, v_behavior, v_level)
    ON CONFLICT (bot_auth_id) DO UPDATE SET
      segment = EXCLUDED.segment, behavior_model = EXCLUDED.behavior_model, level_seed = EXCLUDED.level_seed;
  END LOOP;

  RETURN json_build_object(
    'success', true,
    'seeded_bots', p_bot_count,
    'segments', (
      SELECT coalesce(json_object_agg(segment, cnt), '{}'::json)
      FROM (SELECT segment, count(*) AS cnt FROM public.qa_bot_profiles GROUP BY segment) s
    )
  );
END;
$$;


ALTER FUNCTION "public"."qa_seed_bots"("p_bot_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."qa_seed_mekans"("p_count" integer DEFAULT 1000) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_types text[] := ARRAY['bar', 'kahvehane', 'dovus_kulubu', 'luks_lounge', 'yeralti'];
  v_inserted integer := 0;
  v_bot record;
BEGIN
  PERFORM public.qa_assert_qa_mode();

  DELETE FROM public.mekans WHERE name LIKE 'QA Mekan %';

  FOR v_bot IN
    SELECT b.bot_auth_id, b.level_seed, row_number() OVER (ORDER BY b.bot_auth_id) AS rn
    FROM public.qa_bot_profiles b
    ORDER BY b.bot_auth_id
    LIMIT p_count
  LOOP
    INSERT INTO public.mekans (
      owner_id, mekan_type, name, level, fame, suspicion, is_open, created_at
    )
    VALUES (
      v_bot.bot_auth_id,
      v_types[1 + floor(random() * array_length(v_types, 1))::int],
      format('QA Mekan %s', v_bot.rn),
      GREATEST(1, LEAST(10, 1 + floor(random() * LEAST(10, v_bot.level_seed / 3 + 1))::int)),
      floor(random() * 500)::int,
      floor(random() * 40)::int,
      random() > 0.08,
      now() - (floor(random() * 20)::text || ' days')::interval
    )
    ON CONFLICT (owner_id) DO UPDATE
    SET
      name = EXCLUDED.name,
      mekan_type = EXCLUDED.mekan_type,
      level = EXCLUDED.level,
      fame = EXCLUDED.fame,
      suspicion = EXCLUDED.suspicion,
      is_open = EXCLUDED.is_open;

    v_inserted := v_inserted + 1;
  END LOOP;

  RETURN json_build_object('success', true, 'seeded_mekans', v_inserted);
END;
$$;


ALTER FUNCTION "public"."qa_seed_mekans"("p_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."qa_segment_for_bot"("p_idx" integer, "p_total" integer) RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_slot integer;
BEGIN
  IF p_total IS NULL OR p_total < 1 THEN
    RETURN 'generic';
  END IF;

  v_slot := floor(((p_idx - 1)::numeric * 100.0) / p_total)::integer;

  RETURN CASE
    WHEN v_slot < 15 THEN 'newbie'
    WHEN v_slot < 35 THEN 'casual'
    WHEN v_slot < 55 THEN 'normal'
    WHEN v_slot < 70 THEN 'hardcore'
    WHEN v_slot < 80 THEN 'whale'
    WHEN v_slot < 88 THEN 'trader'
    WHEN v_slot < 94 THEN 'pvp'
    WHEN v_slot < 98 THEN 'guild'
    WHEN v_slot < 99 THEN 'multi'
    ELSE 'exploit'
  END;
END;
$$;


ALTER FUNCTION "public"."qa_segment_for_bot"("p_idx" integer, "p_total" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."qa_smoke_bugfix_batch"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_auth uuid := gen_random_uuid();
  v_row_mat uuid := gen_random_uuid();
  v_row_wpn1 uuid := gen_random_uuid();
  v_row_wpn2 uuid := gen_random_uuid();
  v_row_box1 uuid := gen_random_uuid();
  v_row_box2 uuid := gen_random_uuid();
  v_results jsonb := '[]'::jsonb;
  v_ok boolean;
  v_gems_before integer;
  v_gems_after integer;
  v_slots_before integer;
  v_slots_after integer;
  v_total integer;
  v_free integer;
  v_bad_slots integer;
  v_dup_slots integer;
  v_dep_hits integer;
  v_inv_qty integer;
  v_remain_qty integer;
  v_withdraw_ok boolean;
  v_expected_slot integer;
  v_expand record;
  v_dep record;
  v_equip jsonb;
  v_box1 jsonb;
  v_box2 jsonb;
  v_lb_cnt integer;
  v_lb_weekly_cnt integer;
BEGIN
  PERFORM set_config('app.qa_mode', 'true', true);
  PERFORM public.qa_assert_qa_mode();

  -- cleanup prior run (fixed QA identity)
  DELETE FROM public.box_openings WHERE user_id IN (
    SELECT auth_id FROM public.users WHERE username = 'qa_bugfix_smoke'
  );
  DELETE FROM public.bank_items WHERE user_id IN (
    SELECT auth_id FROM public.users WHERE username = 'qa_bugfix_smoke'
  );
  DELETE FROM public.user_bank_account WHERE user_id IN (
    SELECT auth_id FROM public.users WHERE username = 'qa_bugfix_smoke'
  );
  DELETE FROM public.inventory WHERE user_id IN (
    SELECT auth_id FROM public.users WHERE username = 'qa_bugfix_smoke'
  );
  DELETE FROM public.dungeon_runs WHERE player_id IN (
    SELECT auth_id FROM public.users WHERE username = 'qa_bugfix_smoke'
  );
  DELETE FROM auth.users WHERE email = 'qa_bugfix_smoke@sim.local';
  DELETE FROM public.users WHERE username = 'qa_bugfix_smoke';

  INSERT INTO auth.users (
    id, aud, role, email, email_confirmed_at, created_at, updated_at,
    raw_app_meta_data, raw_user_meta_data
  ) VALUES (
    v_auth, 'authenticated', 'authenticated',
    'qa_bugfix_smoke@sim.local', now(), now(), now(),
    jsonb_build_object('provider', 'email', 'providers', ARRAY['email']),
    jsonb_build_object('username', 'qa_bugfix_smoke', 'is_bot', true)
  );

  INSERT INTO public.users (
    id, auth_id, username, email, display_name, level, xp, gold, energy, max_energy,
    attack, defense, health, max_health, power, gems, created_at, updated_at
  ) VALUES (
    v_auth, v_auth, 'qa_bugfix_smoke', 'qa_bugfix_smoke@sim.local', 'QA Bugfix Smoke',
    10, 1000, 500000, 100, 100, 30, 25, 120, 120, 200, 100, now(), now()
  )
  ON CONFLICT (auth_id) DO UPDATE SET
    username = EXCLUDED.username,
    gems = EXCLUDED.gems,
    updated_at = now();

  INSERT INTO public.user_bank_account (user_id, total_slots, used_slots, free_slots_remaining)
  VALUES (v_auth, 100, 0, 100);

  PERFORM set_config('request.jwt.claim.sub', v_auth::text, true);

  -- BANK-01: expand costs 5 gems, +1 slot
  SELECT gems INTO v_gems_before FROM public.users WHERE auth_id = v_auth;
  SELECT total_slots INTO v_slots_before FROM public.user_bank_account WHERE user_id = v_auth;
  SELECT * INTO v_expand FROM public.expand_bank_slots(1);
  SELECT gems INTO v_gems_after FROM public.users WHERE auth_id = v_auth;
  SELECT total_slots INTO v_slots_after FROM public.user_bank_account WHERE user_id = v_auth;
  v_ok := COALESCE(v_expand.success, false)
      AND COALESCE(v_expand.total_gems_spent, 0) = 5
      AND v_gems_after = v_gems_before - 5
      AND v_slots_after = v_slots_before + 1;
  v_results := v_results || jsonb_build_array(jsonb_build_object(
    'test', 'bank_expand_5_gems_one_slot',
    'area', 'bank',
    'pass', v_ok,
    'detail', jsonb_build_object(
      'gems_before', v_gems_before, 'gems_after', v_gems_after,
      'slots_before', v_slots_before, 'slots_after', v_slots_after,
      'rpc', row_to_json(v_expand)
    )
  ));

  -- BANK-02: first free slot always < total_slots
  SELECT total_slots INTO v_total FROM public.user_bank_account WHERE user_id = v_auth;
  v_free := public.bank_first_free_slot(v_auth, v_total);
  v_ok := v_free IS NOT NULL AND v_free < v_total;
  v_results := v_results || jsonb_build_array(jsonb_build_object(
    'test', 'bank_first_free_slot_within_unlocked',
    'area', 'bank',
    'pass', v_ok,
    'detail', jsonb_build_object('total_slots', v_total, 'free_slot', v_free)
  ));

  -- BANK-03: fill all unlocked slots; full bank rejects new stack (no locked-slot writes)
  SELECT total_slots INTO v_total FROM public.user_bank_account WHERE user_id = v_auth;
  DELETE FROM public.bank_items WHERE user_id = v_auth;
  INSERT INTO public.bank_items (user_id, item_id, category, slot_position, quantity)
  SELECT v_auth, 'res_mining_common', 'material', gs - 1, 1
  FROM generate_series(1, v_total) gs;
  UPDATE public.user_bank_account
  SET used_slots = v_total, updated_at = now()
  WHERE user_id = v_auth;

  DELETE FROM public.inventory WHERE row_id = v_row_mat;
  INSERT INTO public.inventory (row_id, user_id, item_id, quantity, slot_position, is_equipped)
  VALUES (v_row_mat, v_auth, 'potion_energy_minor', 10, 1, false);

  SELECT * INTO v_dep FROM public.deposit_to_bank(ARRAY[v_row_mat], ARRAY[5]);
  SELECT COUNT(*) INTO v_bad_slots
  FROM public.bank_items
  WHERE user_id = v_auth AND slot_position >= v_total;

  SELECT quantity INTO v_inv_qty FROM public.inventory WHERE row_id = v_row_mat;
  v_ok := v_bad_slots = 0 AND COALESCE(v_inv_qty, 0) = 10;
  v_results := v_results || jsonb_build_array(jsonb_build_object(
    'test', 'bank_full_no_deposit_to_locked_slots',
    'area', 'bank',
    'pass', v_ok,
    'detail', jsonb_build_object(
      'total_slots', v_total,
      'bad_slots_gte_total', v_bad_slots,
      'inventory_qty_unchanged', v_inv_qty,
      'deposit_rpc', row_to_json(v_dep)
    )
  ));

  -- BANK-04: unlock one slot then deposit lands in new slot index
  SELECT * INTO v_expand FROM public.expand_bank_slots(1);
  SELECT total_slots INTO v_total FROM public.user_bank_account WHERE user_id = v_auth;
  v_expected_slot := v_total - 1;
  SELECT * INTO v_dep FROM public.deposit_to_bank(ARRAY[v_row_mat], ARRAY[3]);
  SELECT COUNT(*) INTO v_dep_hits FROM public.bank_items
  WHERE user_id = v_auth AND slot_position = v_expected_slot AND quantity >= 3;
  v_ok := COALESCE(v_dep_hits, 0) >= 1;
  v_results := v_results || jsonb_build_array(jsonb_build_object(
    'test', 'bank_unlock_then_deposit_new_slot',
    'area', 'bank',
    'pass', v_ok,
    'detail', jsonb_build_object(
      'total_slots_after_unlock', v_total,
      'expected_slot', v_expected_slot,
      'deposit_rpc', row_to_json(v_dep)
    )
  ));

  -- BANK-05: no duplicate slot_position per user
  SELECT COUNT(*) INTO v_dup_slots
  FROM (
    SELECT slot_position, COUNT(*) c
    FROM public.bank_items
    WHERE user_id = v_auth AND slot_position IS NOT NULL
    GROUP BY slot_position
    HAVING COUNT(*) > 1
  ) d;
  v_ok := v_dup_slots = 0;
  v_results := v_results || jsonb_build_array(jsonb_build_object(
    'test', 'bank_no_duplicate_slot_positions',
    'area', 'bank',
    'pass', v_ok,
    'detail', jsonb_build_object('duplicate_slot_groups', v_dup_slots)
  ));

  -- BANK-06: second expand +5 gems, +1 slot
  SELECT gems INTO v_gems_before FROM public.users WHERE auth_id = v_auth;
  SELECT total_slots INTO v_slots_before FROM public.user_bank_account WHERE user_id = v_auth;
  SELECT * INTO v_expand FROM public.expand_bank_slots(1);
  SELECT gems INTO v_gems_after FROM public.users WHERE auth_id = v_auth;
  SELECT total_slots INTO v_slots_after FROM public.user_bank_account WHERE user_id = v_auth;
  v_ok := COALESCE(v_expand.success, false)
      AND v_gems_after = v_gems_before - 5
      AND v_slots_after = v_slots_before + 1;
  v_results := v_results || jsonb_build_array(jsonb_build_object(
    'test', 'bank_second_expand_5_gems',
    'area', 'bank',
    'pass', v_ok,
    'detail', jsonb_build_object(
      'slots_before', v_slots_before, 'slots_after', v_slots_after,
      'gems_spent', v_expand.total_gems_spent
    )
  ));

  -- BANK-09: expand blocked when insufficient gems
  UPDATE public.users SET gems = 2 WHERE auth_id = v_auth;
  SELECT * INTO v_expand FROM public.expand_bank_slots(1);
  v_ok := COALESCE(v_expand.success, false) = false;
  v_results := v_results || jsonb_build_array(jsonb_build_object(
    'test', 'bank_expand_blocked_insufficient_gems',
    'area', 'bank',
    'pass', v_ok,
    'detail', row_to_json(v_expand)
  ));
  UPDATE public.users SET gems = 500 WHERE auth_id = v_auth;

  -- BANK-07: at max slots expand fails
  DELETE FROM public.bank_items WHERE user_id = v_auth;
  UPDATE public.user_bank_account
  SET total_slots = 200, used_slots = 0, updated_at = now()
  WHERE user_id = v_auth;
  SELECT * INTO v_expand FROM public.expand_bank_slots(1);
  v_ok := COALESCE(v_expand.success, false) = false;
  v_results := v_results || jsonb_build_array(jsonb_build_object(
    'test', 'bank_expand_blocked_at_max_200',
    'area', 'bank',
    'pass', v_ok,
    'detail', row_to_json(v_expand)
  ));

  -- Reset bank for withdraw test
  UPDATE public.user_bank_account
  SET total_slots = 100, used_slots = 1, updated_at = now()
  WHERE user_id = v_auth;
  DELETE FROM public.bank_items WHERE user_id = v_auth;
  INSERT INTO public.bank_items (user_id, item_id, category, slot_position, quantity)
  VALUES (v_auth, 'res_mining_common', 'material', 0, 5);

  -- BANK-08: withdraw reduces bank qty
  PERFORM set_config('request.jwt.claim.sub', v_auth::text, true);
  SELECT w.success INTO v_withdraw_ok
  FROM public.withdraw_from_bank(
    (SELECT ARRAY_AGG(id) FROM public.bank_items WHERE user_id = v_auth),
    ARRAY[2]
  ) w
  LIMIT 1;
  SELECT bi.quantity INTO v_remain_qty
  FROM public.bank_items bi
  WHERE bi.user_id = v_auth AND bi.slot_position = 0;
  v_ok := COALESCE(v_withdraw_ok, false) AND COALESCE(v_remain_qty, 0) = 3;
  v_results := v_results || jsonb_build_array(jsonb_build_object(
    'test', 'bank_withdraw_partial_qty',
    'area', 'bank',
    'pass', v_ok,
    'detail', jsonb_build_object('remaining_bank_qty', v_remain_qty, 'withdraw_ok', v_withdraw_ok)
  ));

  -- EQUIP-01: swap weapon without slot collision
  DELETE FROM public.inventory WHERE user_id = v_auth;
  INSERT INTO public.inventory (row_id, user_id, item_id, quantity, slot_position, is_equipped, equip_slot)
  VALUES
    (v_row_wpn1, v_auth, 'wpn_axe_common', 1, 1, false, NULL),
    (v_row_wpn2, v_auth, 'wpn_axe_common', 1, 2, true, 'weapon');

  PERFORM set_config('request.jwt.claim.sub', v_auth::text, true);
  v_equip := public.equip_item(v_row_wpn1, 'weapon');
  v_ok := COALESCE((v_equip->>'success')::boolean, false)
      AND (
        SELECT COUNT(*)::integer FROM public.inventory
        WHERE user_id = v_auth AND is_equipped = true AND equip_slot = 'weapon'
      ) = 1;
  v_results := v_results || jsonb_build_array(jsonb_build_object(
    'test', 'equip_replace_same_slot_no_collision',
    'area', 'equip',
    'pass', v_ok,
    'detail', v_equip
  ));

  -- BOX-01: only one active opening per user
  DELETE FROM public.box_openings WHERE user_id = v_auth;
  DELETE FROM public.inventory WHERE user_id = v_auth;
  INSERT INTO public.inventory (row_id, user_id, item_id, quantity, slot_position, is_equipped)
  VALUES
    (v_row_box1, v_auth, 'box_weapon_common', 1, 1, false),
    (v_row_box2, v_auth, 'box_armor_rare', 1, 2, false);
  UPDATE public.users SET gems = 500 WHERE auth_id = v_auth;

  PERFORM set_config('request.jwt.claim.sub', v_auth::text, true);
  v_box1 := public.start_box_opening(v_row_box1, 'gems');
  v_box2 := public.start_box_opening(v_row_box2, 'gems');
  v_ok := COALESCE((v_box1->>'success')::boolean, false)
      AND COALESCE((v_box2->>'success')::boolean, true) = false;
  v_results := v_results || jsonb_build_array(jsonb_build_object(
    'test', 'box_one_active_opening_per_user',
    'area', 'loot_box',
    'pass', v_ok,
    'detail', jsonb_build_object('first', v_box1, 'second', v_box2)
  ));

  -- LB-01: weekly gold uses dungeon_runs
  DELETE FROM public.dungeon_runs WHERE player_id = v_auth;
  INSERT INTO public.dungeon_runs (
    player_id, dungeon_id, success, gold_earned, xp_earned, player_power, created_at
  ) VALUES (v_auth, 'dng_001', true, 777, 50, 200, now());

  SELECT COUNT(*) INTO v_lb_weekly_cnt
  FROM public.get_leaderboard('gold', 30, 'weekly') lb
  WHERE lb.username = 'qa_bugfix_smoke' AND lb.value = 777;

  SELECT COUNT(*) INTO v_lb_cnt
  FROM public.get_leaderboard('gold', 30, 'alltime') lb
  WHERE lb.username = 'qa_bugfix_smoke';

  v_ok := v_lb_weekly_cnt >= 1;
  v_results := v_results || jsonb_build_array(jsonb_build_object(
    'test', 'leaderboard_weekly_gold_from_dungeon_runs',
    'area', 'leaderboard',
    'pass', v_ok,
    'detail', jsonb_build_object(
      'weekly_hits', v_lb_weekly_cnt,
      'alltime_hits', v_lb_cnt
    )
  ));

  -- cleanup temp QA user
  DELETE FROM public.box_openings WHERE user_id = v_auth;
  DELETE FROM public.bank_items WHERE user_id = v_auth;
  DELETE FROM public.user_bank_account WHERE user_id = v_auth;
  DELETE FROM public.inventory WHERE user_id = v_auth;
  DELETE FROM public.dungeon_runs WHERE player_id = v_auth;
  DELETE FROM auth.users WHERE id = v_auth;
  DELETE FROM public.users WHERE auth_id = v_auth;

  RETURN jsonb_build_object(
    'verdict', CASE WHEN NOT EXISTS (
      SELECT 1 FROM jsonb_array_elements(v_results) t WHERE COALESCE((t->>'pass')::boolean, false) = false
    ) THEN 'PASS' ELSE 'FAIL' END,
    'tests', v_results,
    'passed', (SELECT COUNT(*) FROM jsonb_array_elements(v_results) t WHERE (t->>'pass')::boolean),
    'failed', (SELECT COUNT(*) FROM jsonb_array_elements(v_results) t WHERE NOT COALESCE((t->>'pass')::boolean, false)),
    'total', jsonb_array_length(v_results),
    'generated_at', now()
  );
END;
$$;


ALTER FUNCTION "public"."qa_smoke_bugfix_batch"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."qa_smoke_comprehensive_10k"("p_bot_count" integer DEFAULT 10000, "p_sim_days" integer DEFAULT 30, "p_cleanup" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_run_id uuid := gen_random_uuid();
  v_report_id uuid := gen_random_uuid();
  v_seed json;
  v_sim json;
  v_summary json;
  v_plan11 jsonb;
  v_facilities jsonb;
  v_failures text[] := ARRAY[]::text[];
  v_verdict text := 'PASS';
  v_bots integer;
  v_gold_in numeric;
  v_gold_out numeric;
  v_item_in numeric;
  v_item_out numeric;
  v_gold_inflation numeric;
  v_item_inflation numeric;
  v_exploit_attempts integer := 0;
  v_exploit_success integer := 0;
  v_exploit_rate numeric;
  v_ret_d1 numeric;
  v_ret_d7 numeric;
  v_ret_d30 numeric;
  v_casual_d30 numeric;
  v_newbie_d30 numeric;
  v_class_stats jsonb;
  v_gameplay jsonb;
  v_gates jsonb;
  v_started timestamptz := clock_timestamp();
BEGIN
  PERFORM set_config('app.qa_mode', 'true', true);
  PERFORM set_config('app.qa_sim_skip_side_inserts', 'true', true);
  PERFORM public.qa_assert_qa_mode();

  IF p_cleanup THEN
    PERFORM public.qa_cleanup_bots();
  END IF;

  v_seed := public.qa_seed_bots(GREATEST(COALESCE(p_bot_count, 10000), 1));
  SELECT count(*) INTO v_bots FROM public.qa_bot_profiles;

  IF v_bots < GREATEST(COALESCE(p_bot_count, 10000), 1) * 0.95 THEN
    v_failures := array_append(v_failures, format('seed_incomplete: %s/%s bots', v_bots, p_bot_count));
  END IF;

  v_plan11 := public.qa_smoke_plan11_passives();
  IF COALESCE((v_plan11->>'all_pass')::boolean, false) IS NOT TRUE THEN
    v_failures := array_append(v_failures, 'plan11_passives_failed');
  END IF;

  v_sim := public.qa_run_30_day_simulation(p_sim_days, v_run_id);
  v_summary := v_sim->'summary';

  v_gold_in := COALESCE((v_summary->'economy'->>'gold_in')::numeric, 0);
  v_gold_out := COALESCE((v_summary->'economy'->>'gold_out')::numeric, 0);
  v_item_in := COALESCE((v_summary->'economy'->>'item_in')::numeric, 0);
  v_item_out := COALESCE((v_summary->'economy'->>'item_out')::numeric, 0);
  v_gold_inflation := CASE WHEN v_gold_in > 0 THEN round((v_gold_in - v_gold_out) / v_gold_in, 4) ELSE 0 END;
  v_item_inflation := CASE WHEN v_item_in > 0
    THEN round((v_item_in - v_item_out) / v_item_in, 4) ELSE 0 END;

  SELECT
    coalesce(sum(attempted_count), 0),
    coalesce(sum(success_count), 0)
  INTO v_exploit_attempts, v_exploit_success
  FROM public.qa_sim_exploit_findings
  WHERE run_id = v_run_id;
  v_exploit_rate := CASE WHEN v_exploit_attempts > 0
    THEN round(v_exploit_success::numeric / v_exploit_attempts, 4) ELSE 0 END;

  v_ret_d1 := COALESCE((v_summary->'retention'->>'d1')::numeric, 0);
  v_ret_d7 := COALESCE((v_summary->'retention'->>'d7')::numeric, 0);
  v_ret_d30 := COALESCE((v_summary->'retention'->>'d30')::numeric, 0);

  SELECT round(coalesce(avg(CASE WHEN e.sim_day = p_sim_days AND e.is_active THEN 1.0 ELSE 0.0 END), 0), 4)
  INTO v_casual_d30
  FROM public.qa_sim_daily_events e
  WHERE e.run_id = v_run_id AND e.segment = 'casual';

  SELECT round(coalesce(avg(CASE WHEN e.sim_day = p_sim_days AND e.is_active THEN 1.0 ELSE 0.0 END), 0), 4)
  INTO v_newbie_d30
  FROM public.qa_sim_daily_events e
  WHERE e.run_id = v_run_id AND e.segment = 'newbie';

  -- PLAN_13 exit thresholds
  IF v_gold_inflation > 0.12 THEN
    v_failures := array_append(v_failures, format('gold_inflation_%s%%_exceeds_12%%', round(v_gold_inflation * 100, 2)));
  END IF;
  IF v_item_inflation > 0.15 THEN
    v_failures := array_append(v_failures, format('item_inflation_%s_exceeds_0.15', round(v_item_inflation, 4)));
  END IF;
  IF v_exploit_rate > 0.05 THEN
    v_failures := array_append(v_failures, format('exploit_success_rate_%s%%_exceeds_5%%', round(v_exploit_rate * 100, 2)));
  END IF;
  IF v_casual_d30 < 0.15 THEN
    v_failures := array_append(v_failures, format('casual_d30_retention_%s_below_15%%', round(v_casual_d30 * 100, 2)));
  END IF;
  IF v_newbie_d30 < 0.10 THEN
    v_failures := array_append(v_failures, format('newbie_d30_retention_%s_below_10%%', round(v_newbie_d30 * 100, 2)));
  END IF;

  v_facilities := public.qa_smoke_facilities_stress(LEAST(v_bots, 2000));
  IF COALESCE(v_facilities->>'verdict', '') NOT LIKE 'PASS:%' THEN
    v_failures := array_append(v_failures, 'facilities_stress: ' || COALESCE(v_facilities->>'verdict', 'unknown'));
  END IF;

  -- Class balance & gameplay proxies (PLAN_06 / PLAN_11 — no class should dominate economy)
  SELECT coalesce(jsonb_object_agg(character_class, stats), '{}'::jsonb)
  INTO v_class_stats
  FROM (
    SELECT
      coalesce(u.character_class, 'none') AS character_class,
      jsonb_build_object(
        'bots', count(DISTINCT u.auth_id),
        'avg_gold_earned_d30', round(avg(e.gold_earned) FILTER (WHERE e.sim_day = p_sim_days), 2),
        'avg_dungeon_runs', round(avg(e.dungeon_runs), 2),
        'avg_craft_actions', round(avg(e.craft_actions), 2),
        'avg_session_minutes', round(avg(e.session_minutes) FILTER (WHERE e.is_active), 2)
      ) AS stats
    FROM public.qa_sim_daily_events e
    JOIN public.users u ON u.auth_id = e.bot_auth_id
    WHERE e.run_id = v_run_id
    GROUP BY coalesce(u.character_class, 'none')
  ) s;

  SELECT jsonb_build_object(
    'retention', v_summary->'retention',
    'avg_session_by_segment', (
      SELECT coalesce(jsonb_object_agg(segment, avg_mins), '{}'::jsonb)
      FROM (
        SELECT e.segment, round(avg(e.session_minutes) FILTER (WHERE e.is_active), 2) AS avg_mins
        FROM public.qa_sim_daily_events e
        WHERE e.run_id = v_run_id
        GROUP BY e.segment
      ) seg
    ),
    'class_engagement', v_class_stats,
    'alchemist_craft_vs_warrior', (
      SELECT round(
        coalesce(avg(e.craft_actions) FILTER (WHERE u.character_class = 'alchemist'), 0)
        / GREATEST(coalesce(avg(e.craft_actions) FILTER (WHERE u.character_class = 'warrior'), 0), 0.01),
        2
      )
      FROM public.qa_sim_daily_events e
      JOIN public.users u ON u.auth_id = e.bot_auth_id
      WHERE e.run_id = v_run_id
    ),
    'warnings', '[]'::jsonb
  ) INTO v_gameplay;

  -- Sim uses random craft_actions (not class-biased); informational only per PLAN_11 identity
  IF COALESCE((v_gameplay->>'alchemist_craft_vs_warrior')::numeric, 0) < 1.0 THEN
    v_gameplay := jsonb_set(
      v_gameplay,
      '{warnings}',
      coalesce(v_gameplay->'warnings', '[]'::jsonb)
        || jsonb_build_array('info: sim craft_actions not class-biased yet — alchemist/warrior ratio < 1')
    );
  END IF;

  v_gates := jsonb_build_object(
    'plan13', jsonb_build_object(
      'gold_inflation_pct', round(v_gold_inflation * 100, 2),
      'gold_inflation_pass', v_gold_inflation <= 0.12,
      'item_inflation_pct', round(v_item_inflation * 100, 2),
      'item_inflation_pass', v_item_inflation <= 0.15,
      'exploit_success_rate_pct', round(v_exploit_rate * 100, 2),
      'exploit_pass', v_exploit_rate <= 0.05,
      'casual_d30_retention', v_casual_d30,
      'casual_d30_pass', v_casual_d30 >= 0.15,
      'newbie_d30_retention', v_newbie_d30,
      'newbie_d30_pass', v_newbie_d30 >= 0.10
    ),
    'plan11', v_plan11,
    'facilities_stress', v_facilities
  );

  IF array_length(v_failures, 1) IS NOT NULL THEN
    v_verdict := 'FAIL';
  END IF;

  INSERT INTO public.qa_comprehensive_smoke_runs (id, bots, sim_days, report, verdict)
  VALUES (
    v_report_id,
    v_bots,
    p_sim_days,
    jsonb_build_object(
      'run_id', v_run_id,
      'bots', v_bots,
      'sim_days', p_sim_days,
      'events', (v_sim->>'events')::bigint,
      'duration_seconds', round(extract(epoch FROM clock_timestamp() - v_started)::numeric, 2),
      'verdict', v_verdict,
      'failures', to_jsonb(v_failures),
      'gates', v_gates,
      'summary', v_summary,
      'gameplay', v_gameplay,
      'seed', v_seed::jsonb
    ),
    v_verdict
  );

  RETURN (
    SELECT report || jsonb_build_object('report_id', v_report_id)
    FROM public.qa_comprehensive_smoke_runs
    WHERE id = v_report_id
  );
END;
$$;


ALTER FUNCTION "public"."qa_smoke_comprehensive_10k"("p_bot_count" integer, "p_sim_days" integer, "p_cleanup" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."qa_smoke_facilities_stress"("p_bot_count" integer DEFAULT 1000) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_bot record;
  v_idx integer := 0;
  v_unlock_ok integer := 0;
  v_unlock_fail integer := 0;
  v_fetch_ok integer := 0;
  v_fetch_fail integer := 0;
  v_double_unlock_blocked integer := 0;
  v_fetch_cnt integer := 0;
  v_result jsonb;
BEGIN
  PERFORM public.qa_assert_qa_mode();

  FOR v_bot IN
    SELECT u.auth_id, u.username, u.level, u.gold
    FROM public.users u
    WHERE u.username LIKE 'qa_bot_%'
    ORDER BY u.username
    LIMIT GREATEST(COALESCE(p_bot_count, 1000), 1)
  LOOP
    v_idx := v_idx + 1;

    BEGIN
      SELECT COUNT(*)::integer INTO v_fetch_cnt
      FROM public.facilities f
      WHERE f.user_id = v_bot.auth_id
        AND COALESCE(f.is_active, true) = true;
      v_fetch_ok := v_fetch_ok + 1;

      IF COALESCE(v_bot.gold, 0) >= 50000 AND COALESCE(v_bot.level, 1) >= 1 THEN
        v_result := public._fac_unlock_facility_core(v_bot.auth_id, 'mining');
        IF COALESCE((v_result->>'success')::boolean, false) THEN
          v_unlock_ok := v_unlock_ok + 1;
        ELSE
          v_unlock_fail := v_unlock_fail + 1;
        END IF;

        v_result := public._fac_unlock_facility_core(v_bot.auth_id, 'mining');
        IF COALESCE((v_result->>'success')::boolean, false) = false THEN
          v_double_unlock_blocked := v_double_unlock_blocked + 1;
        END IF;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_fetch_fail := v_fetch_fail + 1;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'success', v_fetch_fail = 0 AND v_double_unlock_blocked >= v_unlock_ok,
    'bots_tested', v_idx,
    'fetch_ok', v_fetch_ok,
    'fetch_fail', v_fetch_fail,
    'unlock_ok', v_unlock_ok,
    'unlock_fail', v_unlock_fail,
    'double_unlock_blocked', v_double_unlock_blocked,
    'verdict', CASE
      WHEN v_idx = 0 THEN 'FAIL: no qa bots found — run qa_seed_bots(1000) first'
      WHEN v_fetch_fail > 0 THEN 'FAIL: fetch RPC errors under load'
      WHEN v_double_unlock_blocked < v_unlock_ok THEN 'FAIL: duplicate unlock not blocked'
      ELSE 'PASS: facilities RPCs stable under ' || v_idx || ' bots'
    END
  );
END;
$$;


ALTER FUNCTION "public"."qa_smoke_facilities_stress"("p_bot_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."qa_smoke_horse_race_fairness"("p_runs" integer DEFAULT 500) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_settings RECORD;
  v_run INTEGER;
  v_winner RECORD;
  v_house_edge NUMERIC := 0.92;
  v_gold_bet INTEGER := 10000;
  v_gem_bet INTEGER := 1;

  v_winner_sort_counts JSONB := '{}'::jsonb;
  v_winner_gold_mult_sum NUMERIC := 0;
  v_lowest_gold_wins INTEGER := 0;
  v_lowest_gem_wins INTEGER := 0;
  v_highest_gem_wins INTEGER := 0;

  v_gold_low_wins INTEGER := 0;
  v_gold_low_losses INTEGER := 0;
  v_gold_low_wagered BIGINT := 0;
  v_gold_low_payout BIGINT := 0;

  v_gold_high_wins INTEGER := 0;
  v_gold_high_losses INTEGER := 0;
  v_gold_high_wagered BIGINT := 0;
  v_gold_high_payout BIGINT := 0;

  v_gems_low_wins INTEGER := 0;
  v_gems_low_losses INTEGER := 0;
  v_gems_low_wagered NUMERIC := 0;
  v_gems_low_payout NUMERIC := 0;

  v_gems_high_wins INTEGER := 0;
  v_gems_high_losses INTEGER := 0;
  v_gems_high_wagered NUMERIC := 0;
  v_gems_high_payout NUMERIC := 0;

  v_low_gold_horse TEXT;
  v_high_gold_horse TEXT;
  v_low_gem_horse TEXT;
  v_high_gem_horse TEXT;
  v_low_gold_mult NUMERIC;
  v_high_gold_mult NUMERIC;
  v_low_gem_mult NUMERIC;
  v_high_gem_mult NUMERIC;
  v_payout NUMERIC;
  v_sort_key TEXT;
  v_samples JSONB := '[]'::jsonb;
  v_report JSONB;
BEGIN
  IF p_runs < 1 OR p_runs > 100000 THEN
    RAISE EXCEPTION 'p_runs must be between 1 and 100000';
  END IF;

  SELECT *
  INTO v_settings
  FROM public.horse_race_settings
  WHERE id = 'default' AND is_active = TRUE
  LIMIT 1;

  IF FOUND THEN
    v_house_edge := COALESCE(v_settings.house_edge, 0.92);
    v_gold_bet := COALESCE(v_settings.gold_min_bet, 10000);
    v_gem_bet := COALESCE(v_settings.gem_min_bet, 1);
  END IF;

  CREATE TEMP TABLE _qa_round_entries (
    horse_id TEXT PRIMARY KEY,
    gold_multiplier NUMERIC NOT NULL,
    gem_multiplier NUMERIC NOT NULL,
    win_weight NUMERIC NOT NULL,
    win_chance_pct NUMERIC NOT NULL,
    sort_order INTEGER NOT NULL
  ) ON COMMIT DROP;

  FOR v_run IN 1..p_runs LOOP
    TRUNCATE _qa_round_entries;

    INSERT INTO _qa_round_entries (
      horse_id,
      gold_multiplier,
      gem_multiplier,
      win_weight,
      win_chance_pct,
      sort_order
    )
    SELECT
      horse_id,
      gold_multiplier,
      gem_multiplier,
      win_weight,
      ROUND((win_weight / NULLIF(SUM(win_weight) OVER (), 0) * 100)::NUMERIC, 2),
      sort_order
    FROM public._qa_horse_race_sim_entries();

    SELECT horse_id, gold_multiplier
    INTO v_low_gold_horse, v_low_gold_mult
    FROM _qa_round_entries ORDER BY sort_order ASC LIMIT 1;

    SELECT horse_id, gold_multiplier
    INTO v_high_gold_horse, v_high_gold_mult
    FROM _qa_round_entries ORDER BY sort_order DESC LIMIT 1;

    SELECT horse_id, gem_multiplier
    INTO v_low_gem_horse, v_low_gem_mult
    FROM _qa_round_entries ORDER BY sort_order ASC LIMIT 1;

    SELECT horse_id, gem_multiplier
    INTO v_high_gem_horse, v_high_gem_mult
    FROM _qa_round_entries ORDER BY sort_order DESC LIMIT 1;

    SELECT e.horse_id, e.sort_order, e.gold_multiplier, e.gem_multiplier
    INTO v_winner
    FROM _qa_round_entries e
    ORDER BY -LN(GREATEST(random(), 1e-9)) / GREATEST(e.win_weight, 1e-9)
    LIMIT 1;

    v_sort_key := v_winner.sort_order::TEXT;
    v_winner_sort_counts := jsonb_set(
      v_winner_sort_counts,
      ARRAY[v_sort_key],
      to_jsonb(COALESCE((v_winner_sort_counts ->> v_sort_key)::INTEGER, 0) + 1),
      TRUE
    );
    v_winner_gold_mult_sum := v_winner_gold_mult_sum + v_winner.gold_multiplier;

    IF v_winner.horse_id = v_low_gold_horse THEN v_lowest_gold_wins := v_lowest_gold_wins + 1; END IF;
    IF v_winner.horse_id = v_low_gem_horse THEN v_lowest_gem_wins := v_lowest_gem_wins + 1; END IF;
    IF v_winner.horse_id = v_high_gem_horse THEN v_highest_gem_wins := v_highest_gem_wins + 1; END IF;

    v_gold_low_wagered := v_gold_low_wagered + v_gold_bet;
    IF v_winner.horse_id = v_low_gold_horse THEN
      v_gold_low_wins := v_gold_low_wins + 1;
      v_payout := GREATEST(1, FLOOR(v_gold_bet * v_low_gold_mult)::INTEGER);
      v_gold_low_payout := v_gold_low_payout + v_payout::BIGINT;
    ELSE
      v_gold_low_losses := v_gold_low_losses + 1;
    END IF;

    v_gold_high_wagered := v_gold_high_wagered + v_gold_bet;
    IF v_winner.horse_id = v_high_gold_horse THEN
      v_gold_high_wins := v_gold_high_wins + 1;
      v_payout := GREATEST(1, FLOOR(v_gold_bet * v_high_gold_mult)::INTEGER);
      v_gold_high_payout := v_gold_high_payout + v_payout::BIGINT;
    ELSE
      v_gold_high_losses := v_gold_high_losses + 1;
    END IF;

    v_gems_low_wagered := v_gems_low_wagered + v_gem_bet;
    IF v_winner.horse_id = v_low_gem_horse THEN
      v_gems_low_wins := v_gems_low_wins + 1;
      v_payout := ROUND((v_gem_bet::NUMERIC * v_low_gem_mult)::NUMERIC, 2);
      v_gems_low_payout := v_gems_low_payout + v_payout;
    ELSE
      v_gems_low_losses := v_gems_low_losses + 1;
    END IF;

    v_gems_high_wagered := v_gems_high_wagered + v_gem_bet;
    IF v_winner.horse_id = v_high_gem_horse THEN
      v_gems_high_wins := v_gems_high_wins + 1;
      v_payout := ROUND((v_gem_bet::NUMERIC * v_high_gem_mult)::NUMERIC, 2);
      v_gems_high_payout := v_gems_high_payout + v_payout;
    ELSE
      v_gems_high_losses := v_gems_high_losses + 1;
    END IF;

    IF v_run <= 5 THEN
      v_samples := v_samples || jsonb_build_array(
        jsonb_build_object(
          'run', v_run,
          'winner_sort_order', v_winner.sort_order,
          'winner_gold_mult', v_winner.gold_multiplier,
          'lowest_gold_mult', v_low_gold_mult,
          'lowest_gem_mult', v_low_gem_mult,
          'highest_gem_mult', v_high_gem_mult
        )
      );
    END IF;
  END LOOP;

  v_report := jsonb_build_object(
    'success', TRUE,
    'runs', p_runs,
    'generated_at', now(),
    'config', jsonb_build_object(
      'house_edge', v_house_edge,
      'house_edge_meaning', 'target RTP (0.92 = 92% player return)',
      'gold_bet_per_round', v_gold_bet,
      'gem_bet_per_round', v_gem_bet,
      'multiplier_formula', '(1 / win_probability) * house_edge',
      'payout_formula', 'bet_amount * multiplier (RTP already in multiplier)'
    ),
    'fairness_check', jsonb_build_object(
      'lowest_gold_mult_wins', v_lowest_gold_wins,
      'lowest_gold_mult_win_pct', ROUND((v_lowest_gold_wins::NUMERIC / p_runs * 100), 2),
      'lowest_gem_mult_wins', v_lowest_gem_wins,
      'lowest_gem_mult_win_pct', ROUND((v_lowest_gem_wins::NUMERIC / p_runs * 100), 2),
      'highest_gem_mult_wins', v_highest_gem_wins,
      'highest_gem_mult_win_pct', ROUND((v_highest_gem_wins::NUMERIC / p_runs * 100), 2),
      'gems_low_beats_high', v_lowest_gem_wins > v_highest_gem_wins,
      'always_lowest_gold_wins', v_lowest_gold_wins = p_runs,
      'avg_winner_gold_mult', ROUND(v_winner_gold_mult_sum / p_runs, 2),
      'verdict', CASE
        WHEN v_lowest_gold_wins = p_runs THEN 'FAIL: lowest gold mult wins every round'
        WHEN v_lowest_gem_wins <= v_highest_gem_wins THEN 'FAIL: gems low mult does not beat high mult win rate'
        WHEN (v_lowest_gold_wins::NUMERIC / p_runs) < 0.15 THEN 'WARN: lowest gold mult win rate unusually low'
        ELSE 'PASS: inverse odds + aligned gem ranks'
      END
    ),
    'winner_distribution_by_sort_order', (
      SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
          'sort_order', s.sort_order,
          'wins', COALESCE((v_winner_sort_counts ->> s.sort_order::TEXT)::INTEGER, 0),
          'win_pct', ROUND(
            COALESCE((v_winner_sort_counts ->> s.sort_order::TEXT)::NUMERIC, 0) / p_runs * 100,
            2
          )
        )
        ORDER BY s.sort_order
      ), '[]'::jsonb)
      FROM generate_series(1, 6) AS s(sort_order)
    ),
    'gold_lowest_mult_strategy', jsonb_build_object(
      'rounds', p_runs,
      'wins', v_gold_low_wins,
      'losses', v_gold_low_losses,
      'win_rate_pct', ROUND(v_gold_low_wins::NUMERIC / p_runs * 100, 2),
      'total_wagered', v_gold_low_wagered,
      'total_payout', v_gold_low_payout,
      'net_profit', v_gold_low_payout - v_gold_low_wagered,
      'rtp_pct', ROUND(
        CASE WHEN v_gold_low_wagered > 0 THEN v_gold_low_payout::NUMERIC / v_gold_low_wagered * 100 ELSE 0 END,
        2
      ),
      'target_rtp_pct', ROUND(v_house_edge * 100, 2)
    ),
    'gold_highest_mult_strategy', jsonb_build_object(
      'rounds', p_runs,
      'wins', v_gold_high_wins,
      'losses', v_gold_high_losses,
      'win_rate_pct', ROUND(v_gold_high_wins::NUMERIC / p_runs * 100, 2),
      'total_wagered', v_gold_high_wagered,
      'total_payout', v_gold_high_payout,
      'net_profit', v_gold_high_payout - v_gold_high_wagered,
      'rtp_pct', ROUND(
        CASE WHEN v_gold_high_wagered > 0 THEN v_gold_high_payout::NUMERIC / v_gold_high_wagered * 100 ELSE 0 END,
        2
      ),
      'target_rtp_pct', ROUND(v_house_edge * 100, 2)
    ),
    'gems_lowest_mult_strategy', jsonb_build_object(
      'rounds', p_runs,
      'wins', v_gems_low_wins,
      'losses', v_gems_low_losses,
      'win_rate_pct', ROUND(v_gems_low_wins::NUMERIC / p_runs * 100, 2),
      'total_wagered', v_gems_low_wagered,
      'total_payout', v_gems_low_payout,
      'net_profit', v_gems_low_payout - v_gems_low_wagered,
      'rtp_pct', ROUND(
        CASE WHEN v_gems_low_wagered > 0 THEN v_gems_low_payout / v_gems_low_wagered * 100 ELSE 0 END,
        2
      ),
      'target_rtp_pct', ROUND(v_house_edge * 100, 2)
    ),
    'gems_highest_mult_strategy', jsonb_build_object(
      'rounds', p_runs,
      'wins', v_gems_high_wins,
      'losses', v_gems_high_losses,
      'win_rate_pct', ROUND(v_gems_high_wins::NUMERIC / p_runs * 100, 2),
      'total_wagered', v_gems_high_wagered,
      'total_payout', v_gems_high_payout,
      'net_profit', v_gems_high_payout - v_gems_high_wagered,
      'rtp_pct', ROUND(
        CASE WHEN v_gems_high_wagered > 0 THEN v_gems_high_payout / v_gems_high_wagered * 100 ELSE 0 END,
        2
      ),
      'target_rtp_pct', ROUND(v_house_edge * 100, 2)
    ),
    'sample_rounds', v_samples
  );

  INSERT INTO public.qa_horse_race_smoke_runs (runs, report)
  VALUES (p_runs, v_report);

  RETURN v_report;
END;
$$;


ALTER FUNCTION "public"."qa_smoke_horse_race_fairness"("p_runs" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."qa_smoke_plan11_passives"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_shadow_auth uuid := gen_random_uuid();
  v_alch_auth uuid := gen_random_uuid();
  v_row_id uuid := gen_random_uuid();
  v_gems_before numeric;
  v_gems_after numeric;
  v_tol_before integer;
  v_tol_after integer;
  v_risk integer;
  v_bribe jsonb;
  v_detox jsonb;
  v_results jsonb := '[]'::jsonb;
  v_ok boolean;
BEGIN
  PERFORM public.qa_assert_qa_mode();

  DELETE FROM public.inventory WHERE user_id IN (
    SELECT auth_id FROM public.users WHERE username LIKE 'qa_smoke_%'
  );
  DELETE FROM public.facilities WHERE user_id IN (
    SELECT auth_id FROM public.users WHERE username LIKE 'qa_smoke_%'
  );
  DELETE FROM auth.users WHERE email LIKE 'qa_smoke_%@sim.local';
  DELETE FROM public.users WHERE username LIKE 'qa_smoke_%';

  -- 1) Hayalet Adımlar — etkin şüphe tavanı 80
  v_ok := public._effective_suspicion_risk(100, 'shadow') = 80
      AND public._effective_suspicion_risk(100, 'warrior') = 100
      AND public._effective_suspicion_risk(50, 'shadow') = 50;
  v_results := v_results || jsonb_build_array(jsonb_build_object(
    'test', 'shadow_effective_suspicion_cap_80',
    'plan', 'PLAN_11 §2.3 Hayalet Adımlar',
    'pass', v_ok,
    'detail', jsonb_build_object(
      'shadow_100', public._effective_suspicion_risk(100, 'shadow'),
      'warrior_100', public._effective_suspicion_risk(100, 'warrior')
    )
  ));

  -- 2) Gizli Operasyon — tesis şüphe birikimi -30%
  INSERT INTO auth.users (id, aud, role, email, email_confirmed_at, created_at, updated_at, raw_app_meta_data, raw_user_meta_data)
  VALUES (
    v_shadow_auth, 'authenticated', 'authenticated',
    'qa_smoke_shadow@sim.local', now(), now(), now(),
    jsonb_build_object('provider', 'email', 'providers', ARRAY['email']),
    jsonb_build_object('username', 'qa_smoke_shadow', 'is_bot', true)
  );
  INSERT INTO public.users (
    id, auth_id, username, email, display_name, level, xp, gold, energy, max_energy,
    attack, defense, health, max_health, power, gems, character_class, global_suspicion_level,
    created_at, updated_at
  )
  VALUES (
    v_shadow_auth, v_shadow_auth, 'qa_smoke_shadow', 'qa_smoke_shadow@sim.local', 'QA Smoke Shadow',
    10, 1200, 500000, 100, 100, 30, 25, 120, 120, 200, 50, 'shadow', 0, now(), now()
  )
  ON CONFLICT (auth_id) DO UPDATE SET
    username = EXCLUDED.username,
    gems = EXCLUDED.gems,
    character_class = EXCLUDED.character_class,
    global_suspicion_level = EXCLUDED.global_suspicion_level,
    updated_at = now();
  INSERT INTO public.facilities (user_id, type, level, is_active, production_started_at, created_at, updated_at)
  VALUES
    (v_shadow_auth, 'mining', 4, true, now(), now(), now()),
    (v_shadow_auth, 'quarry', 4, true, now(), now(), now()),
    (v_shadow_auth, 'lumber_mill', 4, true, now(), now(), now()),
    (v_shadow_auth, 'clay_pit', 4, true, now(), now(), now());
  v_risk := public._recompute_global_suspicion(v_shadow_auth);
  -- (4*5 + 16/2) = 28 → floor(28*0.7) = 19
  v_ok := v_risk = 19;
  v_results := v_results || jsonb_build_array(jsonb_build_object(
    'test', 'shadow_facility_suspicion_reduction_30pct',
    'plan', 'PLAN_11 §2.3 Gizli Operasyon',
    'pass', v_ok,
    'detail', jsonb_build_object('raw_formula_risk', 28, 'expected', 19, 'actual', v_risk)
  ));

  -- 3) Pazarlık — rüşvet gem -25% (5 → 4)
  UPDATE public.users
  SET gems = 50, global_suspicion_level = 40, last_bribe_at = NULL
  WHERE auth_id = v_shadow_auth;
  v_gems_before := 50;
  PERFORM set_config('request.jwt.claim.sub', v_shadow_auth::text, true);
  v_bribe := public.bribe_officials('mining', 5);
  SELECT gems INTO v_gems_after FROM public.users WHERE auth_id = v_shadow_auth;
  v_ok := COALESCE((v_bribe->>'success')::boolean, false)
      AND COALESCE((v_bribe->>'gems_spent')::integer, 0) = 4
      AND v_gems_after = v_gems_before - 4;
  v_results := v_results || jsonb_build_array(jsonb_build_object(
    'test', 'shadow_bribe_gem_cost_minus_25pct',
    'plan', 'PLAN_11 §2.3 Pazarlık',
    'pass', v_ok,
    'detail', jsonb_build_object(
      'rpc', v_bribe,
      'gems_before', v_gems_before,
      'gems_after', v_gems_after
    )
  ));

  -- 4) Detox Gücü — simyacı +25% etkinlik (minor 15 → 19)
  INSERT INTO auth.users (id, aud, role, email, email_confirmed_at, created_at, updated_at, raw_app_meta_data, raw_user_meta_data)
  VALUES (
    v_alch_auth, 'authenticated', 'authenticated',
    'qa_smoke_alchemist@sim.local', now(), now(), now(),
    jsonb_build_object('provider', 'email', 'providers', ARRAY['email']),
    jsonb_build_object('username', 'qa_smoke_alchemist', 'is_bot', true)
  );
  INSERT INTO public.users (
    id, auth_id, username, email, display_name, level, xp, gold, energy, max_energy,
    attack, defense, health, max_health, power, tolerance, addiction_level,
    character_class, last_detox_used_at, created_at, updated_at
  )
  VALUES (
    v_alch_auth, v_alch_auth, 'qa_smoke_alchemist', 'qa_smoke_alchemist@sim.local', 'QA Smoke Alchemist',
    10, 1200, 500000, 100, 100, 15, 20, 120, 120, 180, 50, 5,
    'alchemist', NULL, now(), now()
  )
  ON CONFLICT (auth_id) DO UPDATE SET
    username = EXCLUDED.username,
    tolerance = EXCLUDED.tolerance,
    addiction_level = EXCLUDED.addiction_level,
    character_class = EXCLUDED.character_class,
    last_detox_used_at = NULL,
    updated_at = now();
  INSERT INTO public.inventory (row_id, user_id, item_id, quantity, slot_position, is_equipped, created_at, updated_at)
  VALUES (v_row_id, v_alch_auth, 'detox_minor', 1, 1, false, now(), now());
  v_tol_before := 50;
  PERFORM set_config('request.jwt.claim.sub', v_alch_auth::text, true);
  v_detox := public.use_detox(v_row_id, v_alch_auth);
  SELECT tolerance INTO v_tol_after FROM public.users WHERE auth_id = v_alch_auth;
  v_ok := COALESCE((v_detox->>'success')::boolean, false)
      AND v_tol_after = v_tol_before - 19;
  v_results := v_results || jsonb_build_array(jsonb_build_object(
    'test', 'alchemist_detox_effectiveness_plus_25pct',
    'plan', 'PLAN_11 §2.2 Detox Gücü',
    'pass', v_ok,
    'detail', jsonb_build_object(
      'rpc', v_detox,
      'tolerance_before', v_tol_before,
      'tolerance_after', v_tol_after,
      'expected_reduction', 19
    )
  ));

  -- 5) character_classes seed aligns with PLAN_11 passive keys
  v_ok := EXISTS (
    SELECT 1 FROM public.character_classes
    WHERE id = 'shadow'
      AND (passive_bonuses ? 'facility_suspicion_reduction')
      AND (passive_bonuses ? 'bribe_cost_reduction')
      AND (passive_bonuses ? 'loot_luck_bonus')
  ) AND EXISTS (
    SELECT 1 FROM public.character_classes
    WHERE id = 'alchemist'
      AND (passive_bonuses ? 'detox_effectiveness_bonus')
  ) AND EXISTS (
    SELECT 1 FROM public.character_classes
    WHERE id = 'warrior'
      AND (passive_bonuses ? 'pvp_damage_bonus')
  );
  v_results := v_results || jsonb_build_array(jsonb_build_object(
    'test', 'character_classes_passive_bonuses_seeded',
    'plan', 'PLAN_11 §4 DB',
    'pass', v_ok
  ));

  -- cleanup ephemeral smoke users
  DELETE FROM public.inventory WHERE user_id IN (v_shadow_auth, v_alch_auth);
  DELETE FROM public.facilities WHERE user_id = v_shadow_auth;
  DELETE FROM auth.users WHERE id IN (v_shadow_auth, v_alch_auth);
  DELETE FROM public.users WHERE auth_id IN (v_shadow_auth, v_alch_auth);

  RETURN jsonb_build_object(
    'all_pass', NOT EXISTS (SELECT 1 FROM jsonb_array_elements(v_results) e WHERE (e->>'pass')::boolean IS NOT TRUE),
    'tests', v_results
  );
END;
$$;


ALTER FUNCTION "public"."qa_smoke_plan11_passives"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."qa_trade_inventory_smoke_test"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_results jsonb := '[]'::jsonb;
  v_user_a uuid := gen_random_uuid();
  v_user_b uuid := gen_random_uuid();
  v_session_id uuid;
  v_row_stone_a uuid;
  v_row_wood_a uuid;
  v_row_stone_b uuid;
  v_row_wood_b uuid;
  v_row_extra uuid;
  v_check jsonb;
  v_item_stone text;
  v_item_wood text;
  v_item_extra text;
  v_stone_max integer;
  v_wood_max integer;
  v_stone_existing integer;
  v_wood_existing integer;
  v_stone_incoming integer;
  v_wood_incoming integer;
  v_stone_overflow integer;
  v_merged_qty integer;
BEGIN
  SELECT id, max_stack
  INTO v_item_stone, v_stone_max
  FROM public.items
  WHERE COALESCE(is_stackable, false) = true
    AND COALESCE(max_stack, 0) >= 10
  ORDER BY max_stack ASC, id ASC
  LIMIT 1;

  SELECT id, max_stack
  INTO v_item_wood, v_wood_max
  FROM public.items
  WHERE COALESCE(is_stackable, false) = true
    AND COALESCE(max_stack, 0) >= 10
    AND id <> COALESCE(v_item_stone, '')
  ORDER BY max_stack ASC, id ASC
  LIMIT 1;

  SELECT id INTO v_item_extra
  FROM public.items
  WHERE COALESCE(is_stackable, false) = false
    AND id <> ALL (ARRAY[COALESCE(v_item_stone, ''), COALESCE(v_item_wood, '')])
  ORDER BY id
  LIMIT 1;

  IF v_item_stone IS NULL OR v_item_wood IS NULL OR v_item_extra IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Smoke test items missing in catalog',
      'results', v_results
    );
  END IF;

  v_stone_max := public._trade_resolve_max_stack(v_item_stone, v_stone_max);
  v_wood_max := public._trade_resolve_max_stack(v_item_wood, v_wood_max);

  v_stone_incoming := GREATEST(1, v_stone_max / 3);
  v_wood_incoming := GREATEST(1, v_wood_max / 2);
  v_stone_existing := v_stone_max - v_stone_incoming;
  v_wood_existing := v_wood_max - v_wood_incoming;
  v_stone_overflow := v_stone_incoming + 1;

  INSERT INTO auth.users (id, aud, role, email, email_confirmed_at, created_at, updated_at, raw_app_meta_data, raw_user_meta_data)
  VALUES
    (
      v_user_a,
      'authenticated',
      'authenticated',
      'qa_trade_smoke_a_' || substr(v_user_a::text, 1, 8) || '@test.local',
      now(),
      now(),
      now(),
      jsonb_build_object('provider', 'email', 'providers', ARRAY['email']),
      jsonb_build_object('username', 'qa_trade_smoke_a_' || substr(v_user_a::text, 1, 8))
    ),
    (
      v_user_b,
      'authenticated',
      'authenticated',
      'qa_trade_smoke_b_' || substr(v_user_b::text, 1, 8) || '@test.local',
      now(),
      now(),
      now(),
      jsonb_build_object('provider', 'email', 'providers', ARRAY['email']),
      jsonb_build_object('username', 'qa_trade_smoke_b_' || substr(v_user_b::text, 1, 8))
    );

  v_row_stone_a := gen_random_uuid();
  v_row_wood_a := gen_random_uuid();
  v_row_stone_b := gen_random_uuid();
  v_row_wood_b := gen_random_uuid();

  INSERT INTO public.inventory (row_id, user_id, item_id, quantity, slot_position, is_equipped, enhancement_level, obtained_at, max_stack)
  VALUES
    (v_row_stone_a, v_user_a, v_item_stone, v_stone_existing, 0, false, 0, 1, v_stone_max),
    (v_row_wood_a, v_user_a, v_item_wood, v_wood_existing, 1, false, 0, 2, v_wood_max);

  FOR i IN 2..19 LOOP
    INSERT INTO public.inventory (row_id, user_id, item_id, quantity, slot_position, is_equipped, enhancement_level, obtained_at)
    VALUES (gen_random_uuid(), v_user_a, v_item_extra, 1, i, false, 0, 10 + i);
  END LOOP;

  INSERT INTO public.inventory (row_id, user_id, item_id, quantity, slot_position, is_equipped, enhancement_level, obtained_at, max_stack)
  VALUES
    (v_row_stone_b, v_user_b, v_item_stone, v_stone_incoming, 0, false, 0, 1, v_stone_max),
    (v_row_wood_b, v_user_b, v_item_wood, v_wood_incoming, 1, false, 0, 2, v_wood_max);

  INSERT INTO public.trade_sessions (id, initiator_id, partner_id, status, partner_accepted_at)
  VALUES (gen_random_uuid(), v_user_a, v_user_b, 'active', now())
  RETURNING id INTO v_session_id;

  INSERT INTO public.trade_items (session_id, owner_id, inventory_row_id)
  VALUES
    (v_session_id, v_user_b, v_row_stone_b),
    (v_session_id, v_user_b, v_row_wood_b);

  v_check := public._trade_validate_recipient_for_session(v_user_a, v_session_id);
  v_results := v_results || jsonb_build_array(jsonb_build_object(
    'case', 'full_inventory_stack_merge_only',
    'expected', true,
    'actual', COALESCE((v_check->>'success')::boolean, false),
    'stone_max_stack', v_stone_max,
    'wood_max_stack', v_wood_max
  ));

  DELETE FROM public.trade_items WHERE session_id = v_session_id;

  v_row_extra := gen_random_uuid();
  INSERT INTO public.inventory (row_id, user_id, item_id, quantity, slot_position, is_equipped, enhancement_level, obtained_at)
  VALUES (v_row_extra, v_user_b, v_item_extra, 1, 2, false, 0, 99);

  INSERT INTO public.trade_items (session_id, owner_id, inventory_row_id)
  VALUES (v_session_id, v_user_b, v_row_extra);

  v_check := public._trade_validate_recipient_for_session(v_user_a, v_session_id);
  v_results := v_results || jsonb_build_array(jsonb_build_object(
    'case', 'full_inventory_extra_non_stackable_item',
    'expected', false,
    'actual', COALESCE((v_check->>'success')::boolean, false)
  ));

  DELETE FROM public.trade_items WHERE session_id = v_session_id;
  DELETE FROM public.inventory WHERE row_id = v_row_extra;

  UPDATE public.inventory SET quantity = v_stone_overflow WHERE row_id = v_row_stone_b;

  INSERT INTO public.trade_items (session_id, owner_id, inventory_row_id)
  VALUES (v_session_id, v_user_b, v_row_stone_b);

  v_check := public._trade_validate_recipient_for_session(v_user_a, v_session_id);
  v_results := v_results || jsonb_build_array(jsonb_build_object(
    'case', 'full_inventory_rejects_overflow_stack',
    'expected', false,
    'actual', COALESCE((v_check->>'success')::boolean, false),
    'incoming_qty', v_stone_overflow,
    'stack_room', v_stone_max - v_stone_existing
  ));

  DELETE FROM public.trade_items WHERE session_id = v_session_id;

  UPDATE public.inventory SET quantity = v_stone_incoming WHERE row_id = v_row_stone_b;

  INSERT INTO public.trade_items (session_id, owner_id, inventory_row_id)
  VALUES
    (v_session_id, v_user_a, v_row_stone_a),
    (v_session_id, v_user_b, v_row_stone_b);

  v_check := public._trade_validate_recipient_for_session(v_user_a, v_session_id);
  v_results := v_results || jsonb_build_array(jsonb_build_object(
    'case', 'cross_trade_outgoing_frees_slot_for_incoming_stack',
    'expected', true,
    'actual', COALESCE((v_check->>'success')::boolean, false)
  ));

  v_check := public._trade_validate_recipient_for_session(v_user_b, v_session_id);
  v_results := v_results || jsonb_build_array(jsonb_build_object(
    'case', 'partner_receives_outgoing_stone_merge',
    'expected', true,
    'actual', COALESCE((v_check->>'success')::boolean, false)
  ));

  v_merged_qty := LEAST(v_stone_max, v_stone_incoming + v_stone_existing);
  PERFORM public._trade_transfer_inventory_row(v_row_stone_a, v_user_b);
  v_results := v_results || jsonb_build_array(jsonb_build_object(
    'case', 'transfer_stack_merge',
    'expected', true,
    'actual', EXISTS (
      SELECT 1 FROM public.inventory
      WHERE user_id = v_user_b AND item_id = v_item_stone AND quantity = v_merged_qty
    ),
    'expected_qty', v_merged_qty
  ));

  DELETE FROM public.trade_items WHERE session_id = v_session_id;
  DELETE FROM public.trade_sessions WHERE id = v_session_id;
  DELETE FROM auth.users WHERE id IN (v_user_a, v_user_b);

  RETURN jsonb_build_object(
    'success', NOT EXISTS (
      SELECT 1
      FROM jsonb_array_elements(v_results) e
      WHERE (e->>'expected')::boolean IS DISTINCT FROM (e->>'actual')::boolean
    ),
    'results', v_results
  );
END;
$$;


ALTER FUNCTION "public"."qa_trade_inventory_smoke_test"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reduce_timer_with_ad"("p_timer" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
  v_user RECORD;
  v_uses INTEGER := 0;
  v_daily_limit CONSTANT INTEGER := 3;
  v_reduction CONSTANT INTERVAL := INTERVAL '30 minutes';
  v_until TIMESTAMPTZ;
  v_new_until TIMESTAMPTZ;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  IF p_timer NOT IN ('prison', 'hospital') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invalid timer');
  END IF;

  SELECT * INTO v_user FROM public.users WHERE auth_id = v_user_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'User not found');
  END IF;

  v_until := CASE p_timer
    WHEN 'prison' THEN v_user.prison_until
    ELSE v_user.hospital_until
  END;

  IF v_until IS NULL OR v_until <= now() THEN
    RETURN jsonb_build_object('success', false, 'error', 'Aktif süre yok');
  END IF;

  SELECT uses INTO v_uses
  FROM public.ad_timer_reductions
  WHERE user_id = v_user_id AND timer_type = p_timer AND used_on = CURRENT_DATE;

  IF COALESCE(v_uses, 0) >= v_daily_limit THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'daily_limit',
      'message', 'Bugünlük reklam hakkın bitti (3/3).'
    );
  END IF;

  v_new_until := v_until - v_reduction;
  IF v_new_until <= now() THEN
    v_new_until := NULL;
  END IF;

  IF p_timer = 'prison' THEN
    UPDATE public.users
    SET prison_until = v_new_until,
        in_prison = (v_new_until IS NOT NULL),
        prison_reason = CASE WHEN v_new_until IS NULL THEN NULL ELSE prison_reason END,
        updated_at = now()
    WHERE auth_id = v_user_id;
  ELSE
    UPDATE public.users
    SET hospital_until = v_new_until,
        updated_at = now()
    WHERE auth_id = v_user_id;
  END IF;

  INSERT INTO public.ad_timer_reductions (user_id, timer_type, used_on, uses)
  VALUES (v_user_id, p_timer, CURRENT_DATE, 1)
  ON CONFLICT (user_id, timer_type, used_on)
  DO UPDATE SET uses = public.ad_timer_reductions.uses + 1;

  RETURN jsonb_build_object(
    'success', true,
    'new_until', v_new_until,
    'released', v_new_until IS NULL,
    'reduction_minutes', 30,
    'uses_left', v_daily_limit - COALESCE(v_uses, 0) - 1
  );
END;
$$;


ALTER FUNCTION "public"."reduce_timer_with_ad"("p_timer" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refund_partial_materials"("p_user_id" "uuid", "p_ingredients" "jsonb", "p_refund_rate" double precision) RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_ingredient jsonb;
    v_item_id TEXT;
    v_quantity INT;
    v_refund_quantity INT;
BEGIN
    FOR v_ingredient IN SELECT jsonb_array_elements(p_ingredients) LOOP
        v_item_id := v_ingredient->>'item_id';
        v_quantity := (v_ingredient->>'quantity')::INT;
        v_refund_quantity := FLOOR(v_quantity * p_refund_rate)::INT;
        
        IF v_refund_quantity > 0 THEN
            INSERT INTO inventory (user_id, item_id, quantity)
            VALUES (p_user_id, v_item_id, v_refund_quantity)
            ON CONFLICT (user_id, item_id) DO UPDATE
            SET quantity = inventory.quantity + v_refund_quantity;
        END IF;
    END LOOP;
END;
$$;


ALTER FUNCTION "public"."refund_partial_materials"("p_user_id" "uuid", "p_ingredients" "jsonb", "p_refund_rate" double precision) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."release_from_hospital"("p_auth_id" "uuid", "p_method" "text", "p_cost" integer DEFAULT 0) RETURNS TABLE("success" boolean, "new_gems" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_current_gems INT;
BEGIN
  -- Get current gems
  SELECT gems INTO v_current_gems
  FROM public.users
  WHERE auth_id = p_auth_id;
  
  -- Check if player has enough gems
  IF p_method = 'gems' AND v_current_gems < p_cost THEN
    RETURN QUERY SELECT FALSE, v_current_gems;
    RETURN;
  END IF;
  
  -- Update user
  UPDATE public.users
  SET 
    hospital_until = NULL,
    hospital_reason = NULL,
    gems = CASE WHEN p_method = 'gems' THEN gems - p_cost ELSE gems END,
    updated_at = NOW()
  WHERE auth_id = p_auth_id;
  
  -- Return success with new gems count
  SELECT gems INTO v_current_gems
  FROM public.users
  WHERE auth_id = p_auth_id;
  
  RETURN QUERY SELECT TRUE, v_current_gems;
END;
$$;


ALTER FUNCTION "public"."release_from_hospital"("p_auth_id" "uuid", "p_method" "text", "p_cost" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."release_from_prison"("p_use_bail" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_user_id UUID;
    v_user RECORD;
    v_now TIMESTAMPTZ;
    v_bail_gems INT;
    v_remaining_mins INT;
BEGIN
    v_user_id := auth.uid();
    v_now := NOW();

    SELECT * INTO v_user FROM public.users WHERE auth_id = v_user_id;

    IF v_user IS NULL THEN
      RETURN jsonb_build_object('success', false, 'error', 'User not found in public.users');
    END IF;

    IF v_user.prison_until IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Not in prison');
    END IF;

    IF p_use_bail THEN
        IF v_user.prison_until <= v_now THEN
            UPDATE public.users SET
                in_prison = false, prison_until = NULL, prison_reason = NULL,
                updated_at = v_now
            WHERE auth_id = v_user_id;
            RETURN jsonb_build_object('success', true, 'message', 'Prison time served');
        END IF;

        v_remaining_mins := CEIL(EXTRACT(EPOCH FROM (v_user.prison_until - v_now)) / 60);
        v_bail_gems := GREATEST(1, v_remaining_mins);

        IF v_user.gems < v_bail_gems THEN
            RETURN jsonb_build_object('success', false, 'error', 'Insufficient gems', 'cost', v_bail_gems);
        END IF;

        UPDATE public.users SET
            gems = gems - v_bail_gems,
            in_prison = false,
            prison_until = NULL,
            prison_reason = NULL,
            updated_at = v_now
        WHERE auth_id = v_user_id;

        RETURN jsonb_build_object('success', true, 'message', 'Released from prison via bail', 'gems_spent', v_bail_gems);
    ELSE
        IF v_user.prison_until > v_now THEN
            RETURN jsonb_build_object('success', false, 'error', 'Süre henüz dolmadı');
        END IF;

        UPDATE public.users SET
            in_prison = false,
            prison_until = NULL,
            prison_reason = NULL,
            updated_at = v_now
        WHERE auth_id = v_user_id;

        RETURN jsonb_build_object('success', true, 'message', 'Prison time served');
    END IF;
END;
$$;


ALTER FUNCTION "public"."release_from_prison"("p_use_bail" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_friend"("p_friendship_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_me UUID;
BEGIN
  v_me := auth.uid();
  IF v_me IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  DELETE FROM public.friendships
  WHERE id = p_friendship_id AND auth.uid() IN (requester_id, addressee_id);

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Kayıt bulunamadı');
  END IF;

  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."remove_friend"("p_friendship_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_inventory_item"("p_item_id" "text", "p_quantity" integer DEFAULT 1) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
    v_user_id uuid;
    v_current_quantity int;
    v_row_id uuid;
begin
    -- Get User ID
    v_user_id := auth.uid();
    if v_user_id is null then
        return jsonb_build_object('success', false, 'error', 'Not authenticated');
    end if;

    -- Validate quantity
    if p_quantity <= 0 then
        return jsonb_build_object('success', false, 'error', 'Quantity must be positive');
    end if;

    -- Find the inventory item and get current quantity
    select inv.row_id, inv.quantity
    into v_row_id, v_current_quantity
    from public.inventory inv
    where inv.user_id = v_user_id
      and inv.item_id = p_item_id
    limit 1;

    -- Check if item exists
    if v_row_id is null then
        return jsonb_build_object('success', false, 'error', 'Item not found in inventory');
    end if;

    -- Check if enough quantity
    if v_current_quantity < p_quantity then
        return jsonb_build_object(
            'success', false, 
            'error', format('Not enough items (have: %s, trying to remove: %s)', v_current_quantity, p_quantity)
        );
    end if;

    -- Remove or update quantity
    if v_current_quantity = p_quantity then
        -- Delete the entire row
        delete from public.inventory
        where row_id = v_row_id
          and user_id = v_user_id;
    else
        -- Decrease quantity
        update public.inventory
        set quantity = quantity - p_quantity,
            updated_at = now()
        where row_id = v_row_id
          and user_id = v_user_id;
    end if;

    return jsonb_build_object(
        'success', true, 
        'item_id', p_item_id,
        'removed_quantity', p_quantity,
        'remaining_quantity', greatest(0, v_current_quantity - p_quantity)
    );
end;
$$;


ALTER FUNCTION "public"."remove_inventory_item"("p_item_id" "text", "p_quantity" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_inventory_item_by_row"("p_row_id" "uuid", "p_quantity" integer DEFAULT 1) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_current_qty int;
BEGIN
  IF v_user IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT quantity INTO v_current_qty
  FROM public.inventory
  WHERE row_id = p_row_id AND user_id = v_user;

  IF v_current_qty IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Item not found or not owned');
  END IF;

  IF p_quantity >= v_current_qty THEN
    DELETE FROM public.inventory
    WHERE row_id = p_row_id AND user_id = v_user;
    RETURN jsonb_build_object('success', true);
  END IF;

  UPDATE public.inventory
  SET quantity = quantity - p_quantity, updated_at = NOW()
  WHERE row_id = p_row_id AND user_id = v_user;

  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."remove_inventory_item_by_row"("p_row_id" "uuid", "p_quantity" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_trade_item"("p_session_id" "uuid", "p_item_row_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid UUID;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Oturum bulunamadı.');
  END IF;

  DELETE FROM public.trade_items ti
  USING public.trade_sessions ts
  WHERE ti.session_id = p_session_id
    AND ti.inventory_row_id = p_item_row_id
    AND ti.owner_id = v_uid
    AND ts.id = p_session_id
    AND ts.status = 'active'
    AND (ts.initiator_id = v_uid OR ts.partner_id = v_uid);

  UPDATE public.trade_sessions
  SET initiator_confirmed = false, partner_confirmed = false, updated_at = now()
  WHERE id = p_session_id;

  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."remove_trade_item"("p_session_id" "uuid", "p_item_row_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."report_chat_message"("p_message_id" "uuid", "p_reason" "text", "p_details" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user public.users%ROWTYPE;
BEGIN
  v_user := public.get_current_chat_user();

  IF p_message_id IS NULL OR public.normalize_chat_content(p_reason) = '' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Gecersiz rapor');
  END IF;

  INSERT INTO public.chat_reports (message_id, reporter_user_id, reason, details)
  VALUES (p_message_id, v_user.id, left(public.normalize_chat_content(p_reason), 120), left(public.normalize_chat_content(COALESCE(p_details, '')), 400))
  ON CONFLICT (message_id, reporter_user_id)
  DO UPDATE SET reason = EXCLUDED.reason, details = EXCLUDED.details, created_at = now();

  PERFORM public.write_chat_audit(v_user.id, 'message_reported', NULL, p_message_id, jsonb_build_object('reason', p_reason));

  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."report_chat_message"("p_message_id" "uuid", "p_reason" "text", "p_details" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reset_all_facility_production"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_user_id UUID;
    v_deleted_queue INT := 0;
    v_reset_count INT := 0;
BEGIN
    v_user_id := auth.uid();
    
    -- Clear all production queues for this user
    DELETE FROM public.facility_queue
    WHERE facility_id IN (
        SELECT id FROM public.facilities WHERE user_id = v_user_id
    ) AND status = 'in_progress';
    
    GET DIAGNOSTICS v_deleted_queue = ROW_COUNT;
    
    -- Reset all facilities for this user
    UPDATE public.facilities
    SET 
        production_started_at = NULL,
        last_production_collected_at = NULL,
        suspicion_level = 0,
        updated_at = NOW()
    WHERE user_id = v_user_id;
    
    GET DIAGNOSTICS v_reset_count = ROW_COUNT;
    
    RETURN jsonb_build_object(
        'success', true,
        'message', 'All facility production reset',
        'facilities_reset', v_reset_count,
        'queue_items_deleted', COALESCE(v_deleted_queue, 0)
    );
END;
$$;


ALTER FUNCTION "public"."reset_all_facility_production"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reset_facility_production"("p_facility_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_user_id UUID;
    v_facility RECORD;
    v_deleted_queue INT := 0;
BEGIN
    v_user_id := auth.uid();
    
    SELECT * INTO v_facility FROM public.facilities
    WHERE id = p_facility_id AND user_id = v_user_id;
    
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Facility not found or not owned');
    END IF;
    
    -- Clear production queue for this facility
    DELETE FROM public.facility_queue
    WHERE facility_id = p_facility_id AND status = 'in_progress'
    RETURNING COUNT(*) INTO v_deleted_queue;
    
    -- Reset facility production
    UPDATE public.facilities
    SET 
        production_started_at = NULL,
        last_production_collected_at = NULL,
        suspicion_level = 0,
        updated_at = NOW()
    WHERE id = p_facility_id;
    
    RETURN jsonb_build_object(
        'success', true,
        'message', 'Facility production reset',
        'queue_items_deleted', COALESCE(v_deleted_queue, 0),
        'facility_id', p_facility_id,
        'facility_type', v_facility.type
    );
END;
$$;


ALTER FUNCTION "public"."reset_facility_production"("p_facility_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."respond_friend_request"("p_friendship_id" "uuid", "p_accept" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_me UUID;
  v_row RECORD;
BEGIN
  v_me := auth.uid();
  IF v_me IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT * INTO v_row
  FROM public.friendships
  WHERE id = p_friendship_id AND addressee_id = v_me AND status = 'pending'
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'İstek bulunamadı');
  END IF;

  IF p_accept THEN
    UPDATE public.friendships
    SET status = 'accepted', responded_at = now()
    WHERE id = p_friendship_id;

    INSERT INTO public.friendship_events (recipient_id, actor_id, event_type, friendship_id)
    VALUES (v_row.requester_id, v_me, 'accepted', p_friendship_id);
  ELSE
    INSERT INTO public.friendship_events (recipient_id, actor_id, event_type, friendship_id)
    VALUES (v_row.requester_id, v_me, 'rejected', p_friendship_id);

    DELETE FROM public.friendships WHERE id = p_friendship_id;
  END IF;

  RETURN jsonb_build_object('success', true, 'accepted', p_accept);
END;
$$;


ALTER FUNCTION "public"."respond_friend_request"("p_friendship_id" "uuid", "p_accept" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."respond_pvp_invite"("p_invite_id" "uuid", "p_accept" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_me UUID;
  v_invite RECORD;
  v_challenger RECORD;
  v_target RECORD;
  v_att_power NUMERIC;
  v_def_power NUMERIC;
  v_win_chance NUMERIC;
  v_winner_id UUID;
  v_loser_id UUID;
  v_pool BIGINT := 0;
  v_tax BIGINT := 0;
  v_net_win BIGINT := 0;
  v_ch_rating INT;
  v_tg_rating INT;
  v_result JSONB;
BEGIN
  v_me := auth.uid();
  IF v_me IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT * INTO v_invite
  FROM public.pvp_invites
  WHERE id = p_invite_id AND target_id = v_me AND status = 'pending'
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Davet bulunamadı');
  END IF;

  IF v_invite.expires_at <= now() THEN
    UPDATE public.pvp_invites SET status = 'expired' WHERE id = p_invite_id;
    RETURN jsonb_build_object('success', false, 'error', 'Davetin süresi doldu');
  END IF;

  IF NOT p_accept THEN
    UPDATE public.pvp_invites SET status = 'declined' WHERE id = p_invite_id;
    RETURN jsonb_build_object('success', true, 'declined', true);
  END IF;

  SELECT * INTO v_challenger FROM public.users WHERE auth_id = v_invite.challenger_id FOR UPDATE;
  SELECT * INTO v_target FROM public.users WHERE auth_id = v_me FOR UPDATE;

  IF v_challenger IS NULL OR v_target IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Oyuncu bulunamadı');
  END IF;

  IF v_invite.wager > 0 THEN
    IF v_challenger.gold < v_invite.wager THEN
      UPDATE public.pvp_invites SET status = 'expired' WHERE id = p_invite_id;
      RETURN jsonb_build_object('success', false, 'error', 'Rakibin altını yetersiz');
    END IF;
    IF v_target.gold < v_invite.wager THEN
      RETURN jsonb_build_object('success', false, 'error', 'Bahis için altının yetersiz');
    END IF;
  END IF;

  v_att_power := COALESCE(v_challenger.attack, 10) + COALESCE(v_challenger.defense, 10);
  v_def_power := COALESCE(v_target.attack, 10) + COALESCE(v_target.defense, 10);
  IF COALESCE(v_challenger.character_class, '') = 'shadow' THEN v_att_power := v_att_power * 1.15; END IF;
  IF COALESCE(v_target.character_class, '') = 'shadow' THEN v_def_power := v_def_power * 1.15; END IF;

  v_win_chance := v_att_power / NULLIF(v_att_power + v_def_power, 0);
  IF v_win_chance IS NULL THEN v_win_chance := 0.5; END IF;

  IF random() <= v_win_chance THEN
    v_winner_id := v_invite.challenger_id;
    v_loser_id := v_me;
    v_ch_rating := 15 + floor(random() * 10)::INT;
    v_tg_rating := -(10 + floor(random() * 5)::INT);
  ELSE
    v_winner_id := v_me;
    v_loser_id := v_invite.challenger_id;
    v_ch_rating := -(10 + floor(random() * 5)::INT);
    v_tg_rating := 15 + floor(random() * 10)::INT;
  END IF;

  IF v_invite.wager > 0 THEN
    v_pool := v_invite.wager * 2;
    v_tax := floor(v_pool * 0.05)::BIGINT;
    v_net_win := v_pool - v_tax;

    UPDATE public.users SET gold = gold - v_invite.wager
    WHERE auth_id = v_invite.challenger_id AND gold >= v_invite.wager;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('success', false, 'error', 'Rakibin altını yetersiz kaldı');
    END IF;

    UPDATE public.users SET gold = gold - v_invite.wager
    WHERE auth_id = v_me AND gold >= v_invite.wager;
    IF NOT FOUND THEN
      UPDATE public.users SET gold = gold + v_invite.wager WHERE auth_id = v_invite.challenger_id;
      RETURN jsonb_build_object('success', false, 'error', 'Altının yetersiz kaldı');
    END IF;

    UPDATE public.users SET gold = gold + v_net_win WHERE auth_id = v_winner_id;
  END IF;

  UPDATE public.users SET
    pvp_rating = GREATEST(0, COALESCE(pvp_rating, 1000) + v_ch_rating),
    pvp_wins = COALESCE(pvp_wins, 0) + CASE WHEN v_winner_id = v_invite.challenger_id THEN 1 ELSE 0 END,
    pvp_losses = COALESCE(pvp_losses, 0) + CASE WHEN v_loser_id = v_invite.challenger_id THEN 1 ELSE 0 END
  WHERE auth_id = v_invite.challenger_id;

  UPDATE public.users SET
    pvp_rating = GREATEST(0, COALESCE(pvp_rating, 1000) + v_tg_rating),
    pvp_wins = COALESCE(pvp_wins, 0) + CASE WHEN v_winner_id = v_me THEN 1 ELSE 0 END,
    pvp_losses = COALESCE(pvp_losses, 0) + CASE WHEN v_loser_id = v_me THEN 1 ELSE 0 END
  WHERE auth_id = v_me;

  v_result := jsonb_build_object(
    'winner_id', v_winner_id,
    'challenger_won', v_winner_id = v_invite.challenger_id,
    'wager', v_invite.wager,
    'net_win', v_net_win,
    'tax', v_tax,
    'challenger_rating_change', v_ch_rating,
    'target_rating_change', v_tg_rating,
    'challenger_name', COALESCE(v_challenger.display_name, v_challenger.username),
    'target_name', COALESCE(v_target.display_name, v_target.username)
  );

  UPDATE public.pvp_invites
  SET status = 'accepted', result = v_result
  WHERE id = p_invite_id;

  RETURN jsonb_build_object('success', true, 'declined', false, 'duel', v_result);
END;
$$;


ALTER FUNCTION "public"."respond_pvp_invite"("p_invite_id" "uuid", "p_accept" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."respond_trade_invite"("p_session_id" "uuid", "p_accept" boolean, "p_block_sender" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid UUID;
  v_sess RECORD;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Oturum bulunamadı.');
  END IF;

  PERFORM public._trade_expire_stale_sessions();

  SELECT * INTO v_sess FROM public.trade_sessions WHERE id = p_session_id FOR UPDATE;
  IF v_sess IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Ticaret oturumu bulunamadı.');
  END IF;
  IF v_sess.partner_id <> v_uid THEN
    RETURN jsonb_build_object('success', false, 'error', 'Bu davet size ait değil.');
  END IF;
  IF v_sess.status <> 'pending' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Davet artık geçerli değil.');
  END IF;
  IF v_sess.partner_accepted_at IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Davet zaten yanıtlandı.');
  END IF;

  IF p_accept THEN
    UPDATE public.trade_sessions
    SET status = 'active',
        partner_accepted_at = now(),
        initiator_confirmed = false,
        partner_confirmed = false,
        updated_at = now()
    WHERE id = p_session_id;
    RETURN jsonb_build_object('success', true, 'status', 'active');
  END IF;

  UPDATE public.trade_sessions SET status = 'cancelled', updated_at = now() WHERE id = p_session_id;

  INSERT INTO public.trade_rejection_events (rejector_id, initiator_id, session_id)
  VALUES (v_uid, v_sess.initiator_id, p_session_id);

  IF p_block_sender THEN
    INSERT INTO public.trade_blocks (blocker_id, blocked_id, blocked_until)
    VALUES (v_uid, v_sess.initiator_id, now() + interval '4 hours')
    ON CONFLICT (blocker_id, blocked_id)
    DO UPDATE SET blocked_until = EXCLUDED.blocked_until, created_at = now();
  END IF;

  PERFORM public._trade_apply_rejection_penalty(v_uid);

  RETURN jsonb_build_object('success', true, 'status', 'rejected');
END;
$$;


ALTER FUNCTION "public"."respond_trade_invite"("p_session_id" "uuid", "p_accept" boolean, "p_block_sender" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_chat_users"("p_query" "text", "p_limit" integer DEFAULT 8) RETURNS TABLE("id" "uuid", "username" "text", "display_name" "text", "is_online" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user public.users%ROWTYPE;
  v_query TEXT;
BEGIN
  v_user := public.get_current_chat_user();
  v_query := lower(btrim(COALESCE(p_query, '')));

  IF char_length(v_query) < 2 THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    u.id,
    u.username,
    u.display_name,
    public.is_user_online(u.is_online, u.last_active_at)
  FROM public.users u
  WHERE u.id <> v_user.id
    AND (
      lower(u.username) LIKE v_query || '%'
      OR lower(COALESCE(u.display_name, '')) LIKE '%' || v_query || '%'
    )
  ORDER BY
    CASE WHEN lower(u.username) = v_query THEN 0 ELSE 1 END,
    CASE WHEN lower(u.username) LIKE v_query || '%' THEN 0 ELSE 1 END,
    u.username ASC
  LIMIT LEAST(GREATEST(COALESCE(p_limit, 8), 1), 20);
END;
$$;


ALTER FUNCTION "public"."search_chat_users"("p_query" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_guilds"("p_query" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_results JSONB; v_query TEXT;
BEGIN
  v_query := trim(COALESCE(p_query, ''));
  IF v_query = '' THEN RETURN '[]'::jsonb; END IF;
  SELECT jsonb_agg(jsonb_build_object('id', g.id, 'guild_id', g.id, 'name', g.name, 'level', g.level, 'description', g.description, 'member_count', (SELECT COUNT(*) FROM public.users WHERE guild_id = g.id), 'max_members', g.max_members, 'total_power', COALESCE((SELECT SUM(power) FROM public.users WHERE guild_id = g.id), 0), 'monument_level', COALESCE(g.monument_level, 0), 'min_join_power', COALESCE(g.min_join_power, 0)))
  INTO v_results FROM public.guilds g WHERE g.name ILIKE '%' || v_query || '%' LIMIT 20;
  RETURN COALESCE(v_results, '[]'::jsonb);
END;
$$;


ALTER FUNCTION "public"."search_guilds"("p_query" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."seed_guild_war_tournament_bracket"("p_tournament_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_tournament RECORD;
  v_participant_count INT;
  v_bracket_size INT;
  v_rounds INT;
  v_round INT;
  v_match_order INT;
  v_seed_order INT[];
  v_guild_ids UUID[];
  v_slots UUID[];
  v_slot INT;
  v_seed INT;
  v_g1 UUID;
  v_g2 UUID;
BEGIN
  SELECT t.id, t.status, t.season_id
  INTO v_tournament
  FROM public.guild_war_tournaments t
  WHERE t.id = p_tournament_id;

  IF v_tournament.id IS NULL OR v_tournament.status <> 'active' THEN
    RETURN;
  END IF;

  SELECT COUNT(*) INTO v_participant_count
  FROM public.guild_war_participants
  WHERE tournament_id = p_tournament_id;

  IF v_participant_count < 2 THEN
    RETURN;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.guild_war_tournament_matches
    WHERE tournament_id = p_tournament_id
  ) THEN
    RETURN;
  END IF;

  v_bracket_size := 1;
  WHILE v_bracket_size < v_participant_count LOOP
    v_bracket_size := v_bracket_size * 2;
  END LOOP;

  v_rounds := CEIL(LOG(2, v_bracket_size))::INT;
  v_seed_order := public._guild_war_bracket_seed_order(v_bracket_size);
  v_slots := ARRAY_FILL(NULL::UUID, ARRAY[v_bracket_size]);

  SELECT COALESCE(array_agg(p.guild_id ORDER BY p.seed_rank), '{}'::uuid[])
  INTO v_guild_ids
  FROM (
    SELECT
      gp.guild_id,
      ROW_NUMBER() OVER (
        ORDER BY
          COALESCE(r.points, 0) DESC,
          gp.joined_at ASC
      ) AS seed_rank
    FROM public.guild_war_participants gp
    LEFT JOIN public.guild_war_rankings r
      ON r.guild_id = gp.guild_id
     AND r.season_id = v_tournament.season_id
    WHERE gp.tournament_id = p_tournament_id
  ) p;

  FOR v_slot IN 1..v_bracket_size LOOP
    v_seed := v_seed_order[v_slot];
    IF v_seed <= v_participant_count THEN
      v_slots[v_slot] := v_guild_ids[v_seed];
    END IF;
  END LOOP;

  v_match_order := 0;
  FOR v_slot IN 1..(v_bracket_size / 2) LOOP
    v_g1 := v_slots[(v_slot * 2) - 1];
    v_g2 := v_slots[v_slot * 2];
    v_match_order := v_match_order + 1;
    INSERT INTO public.guild_war_tournament_matches (
      tournament_id, round_number, round_name, match_order,
      guild1_id, guild2_id, status
    ) VALUES (
      p_tournament_id,
      1,
      public._guild_war_round_name(v_bracket_size, 1),
      v_match_order,
      v_g1,
      v_g2,
      CASE
        WHEN v_g1 IS NOT NULL AND v_g2 IS NULL THEN 'completed'
        WHEN v_g1 IS NULL AND v_g2 IS NOT NULL THEN 'completed'
        ELSE 'pending'
      END
    );
  END LOOP;

  UPDATE public.guild_war_tournament_matches m
  SET winner_guild_id = COALESCE(m.guild1_id, m.guild2_id)
  WHERE m.tournament_id = p_tournament_id
    AND m.round_number = 1
    AND m.status = 'completed'
    AND m.winner_guild_id IS NULL;

  FOR v_round IN 2..v_rounds LOOP
    FOR v_match_order IN 1..(v_bracket_size / (2 ^ v_round)) LOOP
      INSERT INTO public.guild_war_tournament_matches (
        tournament_id, round_number, round_name, match_order, status
      ) VALUES (
        p_tournament_id,
        v_round,
        public._guild_war_round_name(v_bracket_size, v_round),
        v_match_order,
        'pending'
      );
    END LOOP;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."seed_guild_war_tournament_bracket"("p_tournament_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."seed_pvp_tournament_bracket"("p_tournament_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_participant_count INT;
  v_bracket_size INT;
  v_rounds INT;
  v_round INT;
  v_match_order INT;
  v_p1 UUID;
  v_p2 UUID;
  rec RECORD;
BEGIN
  SELECT COUNT(*) INTO v_participant_count
  FROM public.pvp_tournament_participants
  WHERE tournament_id = p_tournament_id;

  IF v_participant_count < 2 THEN
    RETURN;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.pvp_tournament_matches WHERE tournament_id = p_tournament_id
  ) THEN
    RETURN;
  END IF;

  v_bracket_size := 1;
  WHILE v_bracket_size < v_participant_count LOOP
    v_bracket_size := v_bracket_size * 2;
  END LOOP;

  v_rounds := CEIL(LOG(2, v_bracket_size))::INT;

  v_match_order := 0;
  FOR rec IN
    SELECT p.user_id,
           ROW_NUMBER() OVER (
             ORDER BY COALESCE(u.pvp_rating, 1000) DESC, p.joined_at ASC
           ) AS rn
    FROM public.pvp_tournament_participants p
    JOIN public.users u ON u.auth_id = p.user_id
    WHERE p.tournament_id = p_tournament_id
  LOOP
    IF rec.rn % 2 = 1 THEN
      v_p1 := rec.user_id;
      v_p2 := NULL;
    ELSE
      v_p2 := rec.user_id;
      v_match_order := v_match_order + 1;
      INSERT INTO public.pvp_tournament_matches (
        tournament_id, round_number, round_name, match_order,
        player1_id, player2_id, status
      ) VALUES (
        p_tournament_id,
        1,
        public._pvp_round_name(v_bracket_size, 1),
        v_match_order,
        v_p1,
        v_p2,
        'pending'
      );
      v_p1 := NULL;
      v_p2 := NULL;
    END IF;
  END LOOP;

  IF v_p1 IS NOT NULL THEN
    v_match_order := v_match_order + 1;
    INSERT INTO public.pvp_tournament_matches (
      tournament_id, round_number, round_name, match_order,
      player1_id, player2_id, status
    ) VALUES (
      p_tournament_id,
      1,
      public._pvp_round_name(v_bracket_size, 1),
      v_match_order,
      v_p1,
      NULL,
      'pending'
    );
  END IF;

  FOR v_round IN 2..v_rounds LOOP
    FOR v_match_order IN 1..(v_bracket_size / (2 ^ v_round)) LOOP
      INSERT INTO public.pvp_tournament_matches (
        tournament_id, round_number, round_name, match_order, status
      ) VALUES (
        p_tournament_id,
        v_round,
        public._pvp_round_name(v_bracket_size, v_round),
        v_match_order,
        'pending'
      );
    END LOOP;
  END LOOP;

  UPDATE public.pvp_tournaments
  SET status = 'active', registration_open = false, updated_at = now()
  WHERE id = p_tournament_id;
END;
$$;


ALTER FUNCTION "public"."seed_pvp_tournament_bracket"("p_tournament_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."select_character_class"("p_class_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id uuid;
  v_user record;
  v_class record;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  -- SÄ±nÄ±f geÃ§erliliÄŸini kontrol et
  SELECT * INTO v_class FROM public.character_classes WHERE id = p_class_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'GeÃ§ersiz sÄ±nÄ±f: ' || p_class_id);
  END IF;

  -- Mevcut kullanÄ±cÄ± bilgisini al
  SELECT * INTO v_user FROM public.users WHERE auth_id = v_user_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'KullanÄ±cÄ± bulunamadÄ±');
  END IF;

  -- Eğer kullanıcı zaten bir sınıf seçmişse değiştirme yapılamaz
  IF v_user.character_class IS NOT NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Sınıf zaten seçilmiş',
      'selected_class', v_user.character_class
    );
  END IF;

  -- KullanÄ±cÄ±yÄ± gÃ¼ncelle: sÄ±nÄ±f statlarÄ±nÄ± uygula
  UPDATE public.users SET
    character_class     = p_class_id,
    attack              = v_class.base_attack + (v_class.attack_per_level * (COALESCE(v_user.level, 1) - 1)),
    defense             = v_class.base_defense + (v_class.defense_per_level * (COALESCE(v_user.level, 1) - 1)),
    health              = v_class.base_health + (v_class.health_per_level * (COALESCE(v_user.level, 1) - 1)),
    max_health          = v_class.base_health + (v_class.health_per_level * (COALESCE(v_user.level, 1) - 1)),
    luck                = v_class.base_luck + (v_class.luck_per_level * (COALESCE(v_user.level, 1) - 1))
  WHERE auth_id = v_user_id;

  RETURN jsonb_build_object(
    'success', true,
    'class_id', p_class_id,
    'class_name', v_class.name_tr,
    'stats', jsonb_build_object(
      'attack', v_class.base_attack,
      'defense', v_class.base_defense,
      'health', v_class.base_health,
      'luck', v_class.base_luck
    ),
    'passive_bonuses', v_class.passive_bonuses
  );
END;
$$;


ALTER FUNCTION "public"."select_character_class"("p_class_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sell_inventory_item_by_row"("p_row_id" "uuid", "p_quantity" integer DEFAULT 1) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_current_qty int;
  v_vendor_sell_price int;
  v_sell_qty int;
  v_gold_earned int := 0;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  IF p_quantity IS NULL OR p_quantity <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invalid quantity');
  END IF;

  SELECT quantity, COALESCE(vendor_sell_price, 0)
  INTO v_current_qty, v_vendor_sell_price
  FROM public.inventory
  WHERE row_id = p_row_id
    AND user_id = v_user_id
  FOR UPDATE;

  IF v_current_qty IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Item not found or not owned');
  END IF;

  v_sell_qty := LEAST(v_current_qty, p_quantity);
  v_gold_earned := GREATEST(0, v_vendor_sell_price * v_sell_qty);

  IF v_sell_qty >= v_current_qty THEN
    DELETE FROM public.inventory
    WHERE row_id = p_row_id
      AND user_id = v_user_id;
  ELSE
    UPDATE public.inventory
    SET quantity = quantity - v_sell_qty,
        updated_at = NOW()
    WHERE row_id = p_row_id
      AND user_id = v_user_id;
  END IF;

  UPDATE public.users
  SET gold = COALESCE(gold, 0) + v_gold_earned
  WHERE auth_id = v_user_id;

  RETURN jsonb_build_object(
    'success', true,
    'sold_quantity', v_sell_qty,
    'currency', 'gold',
    'gold_earned', v_gold_earned,
    'gems_earned', 0
  );
END;
$$;


ALTER FUNCTION "public"."sell_inventory_item_by_row"("p_row_id" "uuid", "p_quantity" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."send_chat_message"("p_channel" "text", "p_content" "text", "p_recipient_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user public.users%ROWTYPE;
  v_recipient public.users%ROWTYPE;
  v_clean TEXT;
  v_filtered TEXT;
  v_last_message_at TIMESTAMPTZ;
  v_ban public.chat_bans%ROWTYPE;
  v_message_id UUID;
  v_sender_name TEXT;
BEGIN
  v_user := public.get_current_chat_user();

  IF p_channel NOT IN ('global', 'guild', 'dm', 'trade') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Gecersiz kanal');
  END IF;

  v_clean := public.normalize_chat_content(p_content);
  IF char_length(v_clean) = 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Bos mesaj gonderilemez');
  END IF;

  IF char_length(v_clean) > 200 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Mesaj en fazla 200 karakter olabilir');
  END IF;

  IF p_channel = 'guild' AND v_user.guild_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Lonca sohbeti icin bir loncaya ait olmalisiniz');
  END IF;

  IF p_channel = 'dm' AND p_recipient_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Ozel mesaj icin hedef kullanici gerekli');
  END IF;

  IF p_channel = 'dm' THEN
    SELECT * INTO v_recipient FROM public.users WHERE id = p_recipient_user_id;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('success', false, 'error', 'Hedef oyuncu bulunamadi');
    END IF;

    IF v_recipient.id = v_user.id THEN
      RETURN jsonb_build_object('success', false, 'error', 'Kendinize ozel mesaj gonderemezsiniz');
    END IF;

    IF EXISTS (
      SELECT 1
      FROM public.chat_blocks cb
      WHERE (cb.blocker_user_id = v_user.id AND cb.blocked_user_id = v_recipient.id)
         OR (cb.blocker_user_id = v_recipient.id AND cb.blocked_user_id = v_user.id)
    ) THEN
      RETURN jsonb_build_object('success', false, 'error', 'Bu oyuncu ile ozel mesaj kullanilamiyor');
    END IF;
  END IF;

  SELECT created_at INTO v_last_message_at
  FROM public.chat_messages
  WHERE sender_user_id = v_user.id
  ORDER BY created_at DESC
  LIMIT 1;

  IF v_last_message_at IS NOT NULL AND v_last_message_at > now() - interval '2 seconds' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Cok hizli mesaj gonderiyorsunuz');
  END IF;

  v_ban := public.get_active_chat_ban(v_user.id, p_channel, v_user.guild_id);
  IF v_ban.id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Sohbetten gecici olarak uzaklastirildiniz',
      'ban_expires_at', v_ban.expires_at,
      'ban_reason', v_ban.reason
    );
  END IF;

  v_filtered := public.apply_chat_filters(v_clean, p_channel, v_user.guild_id);
  v_sender_name := COALESCE(NULLIF(v_user.display_name, ''), v_user.username);

  INSERT INTO public.chat_messages (
    channel,
    sender_user_id,
    recipient_user_id,
    guild_id,
    sender_name,
    content,
    metadata
  ) VALUES (
    p_channel,
    v_user.id,
    p_recipient_user_id,
    CASE WHEN p_channel = 'guild' THEN v_user.guild_id ELSE NULL END,
    v_sender_name,
    v_filtered,
    jsonb_build_object('original_length', char_length(v_clean))
  )
  RETURNING id INTO v_message_id;

  PERFORM public.write_chat_audit(v_user.id, 'message_sent', NULL, v_message_id, jsonb_build_object('channel', p_channel));

  RETURN jsonb_build_object('success', true, 'message_id', v_message_id, 'content', v_filtered);
END;
$$;


ALTER FUNCTION "public"."send_chat_message"("p_channel" "text", "p_content" "text", "p_recipient_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."send_friend_request"("p_username" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_me UUID;
  v_target UUID;
  v_existing RECORD;
BEGIN
  v_me := auth.uid();
  IF v_me IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT auth_id INTO v_target
  FROM public.users
  WHERE lower(username) = lower(trim(p_username))
  LIMIT 1;

  IF v_target IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Oyuncu bulunamadı');
  END IF;

  IF v_target = v_me THEN
    RETURN jsonb_build_object('success', false, 'error', 'Kendine istek gönderemezsin');
  END IF;

  SELECT * INTO v_existing
  FROM public.friendships
  WHERE (requester_id = v_me AND addressee_id = v_target)
     OR (requester_id = v_target AND addressee_id = v_me)
  LIMIT 1;

  IF FOUND THEN
    IF v_existing.status = 'accepted' THEN
      RETURN jsonb_build_object('success', false, 'error', 'Zaten arkadaşsınız');
    ELSIF v_existing.status = 'blocked' THEN
      RETURN jsonb_build_object('success', false, 'error', 'İstek gönderilemedi');
    ELSIF v_existing.requester_id = v_me THEN
      RETURN jsonb_build_object('success', false, 'error', 'İstek zaten gönderildi');
    ELSE
      UPDATE public.friendships
      SET status = 'accepted', responded_at = now()
      WHERE id = v_existing.id;

      INSERT INTO public.friendship_events (recipient_id, actor_id, event_type, friendship_id)
      VALUES (v_existing.requester_id, v_me, 'accepted', v_existing.id);

      RETURN jsonb_build_object('success', true, 'auto_accepted', true);
    END IF;
  END IF;

  INSERT INTO public.friendships (requester_id, addressee_id)
  VALUES (v_me, v_target);

  RETURN jsonb_build_object('success', true, 'auto_accepted', false);
END;
$$;


ALTER FUNCTION "public"."send_friend_request"("p_username" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."send_pvp_invite"("p_target" "uuid", "p_wager" bigint DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_me UUID;
  v_challenger RECORD;
  v_target RECORD;
  v_invite_id UUID;
BEGIN
  v_me := auth.uid();
  IF v_me IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  IF p_target = v_me THEN
    RETURN jsonb_build_object('success', false, 'error', 'Kendine davet gönderemezsin');
  END IF;

  IF p_wager < 0 OR p_wager > 5000000 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Geçersiz bahis (0 - 5.000.000)');
  END IF;

  SELECT * INTO v_challenger FROM public.users WHERE auth_id = v_me;
  SELECT * INTO v_target FROM public.users WHERE auth_id = p_target;
  IF v_target IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Oyuncu bulunamadı');
  END IF;

  IF p_wager > 0 AND v_challenger.gold < p_wager THEN
    RETURN jsonb_build_object('success', false, 'error', 'Yetersiz altın');
  END IF;

  UPDATE public.pvp_invites SET status = 'expired'
  WHERE status = 'pending' AND expires_at <= now();

  IF EXISTS (
    SELECT 1 FROM public.pvp_invites
    WHERE challenger_id = v_me AND target_id = p_target AND status = 'pending'
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Zaten bekleyen davetin var');
  END IF;

  INSERT INTO public.pvp_invites (challenger_id, target_id, wager)
  VALUES (v_me, p_target, p_wager)
  RETURNING id INTO v_invite_id;

  RETURN jsonb_build_object('success', true, 'invite_id', v_invite_id);
END;
$$;


ALTER FUNCTION "public"."send_pvp_invite"("p_target" "uuid", "p_wager" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_guild_min_join_power"("p_min_power" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_auth_id UUID; v_user RECORD;
BEGIN
  v_auth_id := auth.uid();
  IF v_auth_id IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'Kimlik dogrulama gerekli'); END IF;
  IF p_min_power IS NULL OR p_min_power < 0 OR p_min_power > 100000000 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Gecersiz guc limiti (0-100.000.000)');
  END IF;
  SELECT guild_id, guild_role FROM public.users WHERE auth_id = v_auth_id INTO v_user;
  IF NOT FOUND OR v_user.guild_id IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'Bir loncaya uye degilsiniz'); END IF;
  IF COALESCE(v_user.guild_role, '') <> 'leader' THEN RETURN jsonb_build_object('success', false, 'error', 'Sadece lonca lideri guc limiti belirleyebilir'); END IF;
  UPDATE public.guilds SET min_join_power = p_min_power WHERE id = v_user.guild_id;
  RETURN jsonb_build_object('success', true, 'min_join_power', p_min_power);
END;
$$;


ALTER FUNCTION "public"."set_guild_min_join_power"("p_min_power" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_mekan_happy_hour"("p_mekan_id" "uuid", "p_active" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_auth_id UUID;
  v_mekan RECORD;
BEGIN
  v_auth_id := auth.uid();
  IF v_auth_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Kimlik dogrulama gerekli');
  END IF;
  SELECT * INTO v_mekan FROM public.mekans WHERE id = p_mekan_id AND owner_id = v_auth_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Mekan bulunamadi veya size ait degil');
  END IF;
  IF p_active THEN
    UPDATE public.mekans SET happy_hour_until = now() + INTERVAL '1 hour' WHERE id = p_mekan_id;
    RETURN jsonb_build_object('success', true, 'happy_hour_until', (now() + INTERVAL '1 hour'));
  ELSE
    UPDATE public.mekans SET happy_hour_until = NULL WHERE id = p_mekan_id;
    RETURN jsonb_build_object('success', true, 'happy_hour_until', NULL);
  END IF;
END;
$$;


ALTER FUNCTION "public"."set_mekan_happy_hour"("p_mekan_id" "uuid", "p_active" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_online_status"("p_is_online" boolean, "p_mekan_id" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  UPDATE public.users
  SET is_online = p_is_online,
      last_active_at = now(),
      current_mekan_id = CASE WHEN p_is_online THEN p_mekan_id ELSE NULL END
  WHERE auth_id = auth.uid();
END;
$$;


ALTER FUNCTION "public"."set_online_status"("p_is_online" boolean, "p_mekan_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_queue_estimated_completion"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.estimated_completion_at IS NULL AND NEW.duration_seconds IS NOT NULL THEN
    NEW.estimated_completion_at := NEW.started_at + (NEW.duration_seconds || ' seconds')::INTERVAL;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."set_queue_estimated_completion"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_referral_code"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
    IF NEW.referral_code IS NULL THEN
        NEW.referral_code := generate_referral_code();
        -- Ensure uniqueness
        WHILE EXISTS (SELECT 1 FROM game.users WHERE referral_code = NEW.referral_code) LOOP
            NEW.referral_code := generate_referral_code();
        END LOOP;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."set_referral_code"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_trade_gold"("p_session_id" "uuid", "p_amount" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid UUID;
  v_sess RECORD;
  v_balance bigint;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Oturum bulunamadı.');
  END IF;
  IF p_amount < 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Geçersiz altın miktarı.');
  END IF;

  SELECT * INTO v_sess FROM public.trade_sessions WHERE id = p_session_id FOR UPDATE;
  IF v_sess IS NULL OR v_sess.status <> 'active' OR v_sess.partner_accepted_at IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Aktif ticaret yok.');
  END IF;
  IF v_uid <> v_sess.initiator_id AND v_uid <> v_sess.partner_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'Bu ticaretin katılımcısı değilsiniz.');
  END IF;

  SELECT gold INTO v_balance FROM public.users WHERE auth_id = v_uid;
  IF COALESCE(v_balance, 0) < p_amount THEN
    RETURN jsonb_build_object('success', false, 'error', 'Yetersiz altın.');
  END IF;

  IF v_uid = v_sess.initiator_id THEN
    UPDATE public.trade_sessions SET initiator_gold = p_amount, initiator_confirmed = false, partner_confirmed = false, updated_at = now()
    WHERE id = p_session_id;
  ELSE
    UPDATE public.trade_sessions SET partner_gold = p_amount, initiator_confirmed = false, partner_confirmed = false, updated_at = now()
    WHERE id = p_session_id;
  END IF;

  RETURN jsonb_build_object('success', true, 'gold', p_amount);
END;
$$;


ALTER FUNCTION "public"."set_trade_gold"("p_session_id" "uuid", "p_amount" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."solve_captcha"("p_action" "text", "p_answer" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_me UUID;
  v_row public.rpc_rate_limits%ROWTYPE;
BEGIN
  v_me := auth.uid();
  IF v_me IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT * INTO v_row
  FROM public.rpc_rate_limits
  WHERE user_id = v_me AND action = p_action
  FOR UPDATE;

  IF NOT FOUND OR NOT v_row.captcha_required THEN
    RETURN jsonb_build_object('success', true, 'message', 'Captcha gerekli degil');
  END IF;

  IF v_row.captcha_expires_at IS NULL OR v_row.captcha_expires_at <= now() THEN
    RETURN jsonb_build_object('success', false, 'error', 'Sorunun suresi doldu, yenisini iste');
  END IF;

  IF v_row.captcha_a + v_row.captcha_b != p_answer THEN
    RETURN jsonb_build_object('success', false, 'error', 'Yanlis cevap');
  END IF;

  UPDATE public.rpc_rate_limits
  SET captcha_required = false,
      captcha_a = NULL,
      captcha_b = NULL,
      captcha_expires_at = NULL,
      window_start = now(),
      call_count = 0
  WHERE user_id = v_me AND action = p_action;

  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."solve_captcha"("p_action" "text", "p_answer" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."split_stack_item"("p_row_id" "uuid", "p_split_quantity" integer, "p_target_slot" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id uuid;
  v_row record;
  v_is_stackable boolean;
  v_new_row jsonb;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  IF p_split_quantity <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invalid split quantity');
  END IF;

  SELECT * INTO v_row FROM public.inventory WHERE row_id = p_row_id AND user_id = v_user_id LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Item not found');
  END IF;

  -- Ensure stackable and have enough quantity
  SELECT COALESCE(is_stackable, true) INTO v_is_stackable FROM public.items WHERE id = v_row.item_id;
  IF NOT v_is_stackable THEN
    RETURN jsonb_build_object('success', false, 'error', 'Item is not stackable');
  END IF;

  IF v_row.quantity <= p_split_quantity THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not enough quantity to split');
  END IF;

  -- Validate target slot
  IF p_target_slot < 0 OR p_target_slot > 9999 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invalid target slot');
  END IF;

  -- Ensure target slot is not occupied for this user
  IF EXISTS (SELECT 1 FROM public.inventory WHERE user_id = v_user_id AND slot_position = p_target_slot) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Target slot occupied');
  END IF;

  -- Reduce original stack
  UPDATE public.inventory
  SET quantity = quantity - p_split_quantity, updated_at = NOW()
  WHERE row_id = v_row.row_id AND user_id = v_user_id
  RETURNING to_jsonb(public.inventory.*) INTO v_row;

  -- Insert new split row
  INSERT INTO public.inventory (
    user_id, item_id, quantity, enhancement_level, is_equipped, obtained_at, slot_position
  ) VALUES (
    v_user_id, v_row.item_id, p_split_quantity, COALESCE(v_row.enhancement_level, 0), false, EXTRACT(EPOCH FROM NOW())::bigint, p_target_slot
  ) RETURNING to_jsonb(public.inventory.*) INTO v_new_row;

  RETURN jsonb_build_object('success', true, 'new_row', v_new_row);
END;
$$;


ALTER FUNCTION "public"."split_stack_item"("p_row_id" "uuid", "p_split_quantity" integer, "p_target_slot" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."start_box_opening"("p_row_id" "uuid", "p_payment" "text" DEFAULT 'gems'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
  v_inv RECORD;
  v_cfg RECORD;
  v_cost NUMERIC := 0;
  v_gems NUMERIC;
  v_opens_at TIMESTAMPTZ;
  v_opening_id UUID;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  IF p_payment NOT IN ('gems', 'ad') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invalid payment');
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.box_openings
    WHERE user_id = v_user_id AND status = 'opening'
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Zaten bir kutu açılıyor');
  END IF;

  SELECT * INTO v_inv
  FROM public.inventory
  WHERE row_id = p_row_id AND user_id = v_user_id AND quantity > 0
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Kutu bulunamadı');
  END IF;

  IF v_inv.item_id NOT LIKE 'box\_%' ESCAPE '\' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Bu eşya açılabilir bir kutu değil');
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.box_openings
    WHERE inventory_row_id = p_row_id AND status = 'opening'
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Bu kutu zaten açılıyor');
  END IF;

  SELECT * INTO v_cfg FROM public.loot_box_configs WHERE id = v_inv.item_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Kutu ödül havuzu tanımlı değil');
  END IF;

  IF p_payment = 'gems' THEN
    v_cost := GREATEST(COALESCE(v_cfg.price, 1), 1);
    SELECT gems INTO v_gems FROM public.users WHERE auth_id = v_user_id FOR UPDATE;
    IF COALESCE(v_gems, 0) < v_cost THEN
      RETURN jsonb_build_object('success', false, 'error', 'Yetersiz gem');
    END IF;
    UPDATE public.users SET gems = gems - v_cost WHERE auth_id = v_user_id;
    v_opens_at := now();
  ELSE
    v_opens_at := now() + interval '30 minutes';
  END IF;

  INSERT INTO public.box_openings (user_id, inventory_row_id, box_id, payment, gems_spent, opens_at)
  VALUES (v_user_id, p_row_id, v_inv.item_id, p_payment, v_cost, v_opens_at)
  RETURNING id INTO v_opening_id;

  RETURN jsonb_build_object(
    'success', true,
    'opening_id', v_opening_id,
    'opens_at', v_opens_at,
    'gems_spent', v_cost
  );
END;
$$;


ALTER FUNCTION "public"."start_box_opening"("p_row_id" "uuid", "p_payment" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."start_crafting"("p_user_id" "uuid", "p_recipe_id" "uuid", "p_quantity" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_recipe RECORD;
  v_user RECORD;
  v_facility RECORD;
  v_total_gold BIGINT;
  v_total_duration INT;
  v_materials JSONB;
  v_key TEXT;
  v_val INT;
  v_inv_qty INT;
  v_monument_level INT := 0;
  v_success_rate NUMERIC;
BEGIN
  SELECT * INTO v_recipe FROM public.craft_recipes WHERE id = p_recipe_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'Tarif bulunamadı'); END IF;

  SELECT * INTO v_user FROM public.users WHERE auth_id = p_user_id FOR UPDATE;
  IF v_user.level < v_recipe.required_player_level THEN RETURN jsonb_build_object('success', false, 'error', 'Seviyeniz yetersiz'); END IF;

  IF v_user.guild_id IS NOT NULL THEN
    SELECT monument_level INTO v_monument_level FROM public.guilds WHERE id = v_user.guild_id;
  END IF;

  v_total_gold := (v_recipe.gold_cost * p_quantity)::BIGINT;
  IF v_user.gold < v_total_gold THEN RETURN jsonb_build_object('success', false, 'error', 'Altınınız yetersiz'); END IF;

  IF v_recipe.facility_type != 'none' THEN
    SELECT * INTO v_facility FROM public.player_facilities WHERE user_id = p_user_id AND facility_type = v_recipe.facility_type;
    IF NOT FOUND OR v_facility.level < v_recipe.required_facility_level THEN
      RETURN jsonb_build_object('success', false, 'error', 'Gerekli tesis seviyesi yetersiz');
    END IF;
  END IF;

  v_materials := v_recipe.materials;
  FOR v_key, v_val IN SELECT * FROM jsonb_each_text(v_materials) LOOP
    SELECT COALESCE(SUM(quantity), 0) INTO v_inv_qty FROM public.inventory WHERE user_id = p_user_id AND item_id = v_key;
    IF v_inv_qty < (v_val::INT * p_quantity) THEN RETURN jsonb_build_object('success', false, 'error', 'Gerekli materyaller eksik'); END IF;
  END LOOP;

  UPDATE public.users SET gold = gold - v_total_gold WHERE auth_id = p_user_id AND gold >= v_total_gold;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'İşlem sırasında altın yetersiz kaldı'); END IF;

  FOR v_key, v_val IN SELECT * FROM jsonb_each_text(v_materials) LOOP
    DECLARE
      v_needed INT := v_val::INT * p_quantity;
      v_row RECORD;
    BEGIN
      FOR v_row IN SELECT row_id, quantity FROM public.inventory WHERE user_id = p_user_id AND item_id = v_key AND quantity > 0 ORDER BY quantity ASC LOOP
        IF v_needed <= 0 THEN EXIT; END IF;
        IF v_row.quantity <= v_needed THEN
          DELETE FROM public.inventory WHERE row_id = v_row.row_id;
          v_needed := v_needed - v_row.quantity;
        ELSE
          UPDATE public.inventory SET quantity = quantity - v_needed WHERE row_id = v_row.row_id;
          v_needed := 0;
        END IF;
      END LOOP;
    END;
  END LOOP;

  v_total_duration := v_recipe.duration_minutes * p_quantity;
  -- Alchemist: %20 süre azaltma, %15 success rate artışı
  IF COALESCE(v_user.character_class, '') = 'alchemist' THEN
    v_total_duration := floor(v_total_duration * 0.80);
  END IF;

  v_success_rate := v_recipe.success_rate;
  IF COALESCE(v_user.character_class, '') = 'alchemist' THEN
    v_success_rate := v_success_rate + 0.15;
  END IF;

  -- Monument Lv 35: +%3 success
  IF v_monument_level >= 35 THEN
    v_success_rate := v_success_rate + 0.03;
  END IF;

  v_success_rate := LEAST(v_success_rate, 1.0);

  INSERT INTO public.craft_queue (user_id, recipe_id, quantity, expected_success_rate, status, started_at, completes_at)
  VALUES (p_user_id, p_recipe_id, p_quantity, v_success_rate, 'crafting', now(), now() + (v_total_duration || ' minutes')::INTERVAL);

  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."start_crafting"("p_user_id" "uuid", "p_recipe_id" "uuid", "p_quantity" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."start_facility_production"("p_facility_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_facility record;
  v_player record;
  v_energy_cost integer := 50;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT * INTO v_player
  FROM public.users u
  WHERE u.auth_id = v_user_id
  FOR UPDATE;

  IF v_player.prison_until IS NOT NULL AND v_player.prison_until > now() THEN
    RETURN jsonb_build_object('success', false, 'error', 'Cezaevindeyken uretim baslatilamaz');
  END IF;

  IF COALESCE(v_player.energy, 0) < v_energy_cost THEN
    RETURN jsonb_build_object('success', false, 'error', 'Enerji yetersiz');
  END IF;

  SELECT *
  INTO v_facility
  FROM public.facilities
  WHERE id = p_facility_id
    AND user_id = v_user_id
    AND COALESCE(is_active, true) = true
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Facility not found');
  END IF;

  IF v_facility.production_started_at IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Production already active');
  END IF;

  UPDATE public.users
  SET energy = energy - v_energy_cost,
      updated_at = now()
  WHERE auth_id = v_user_id
    AND energy >= v_energy_cost;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Enerji yetersiz');
  END IF;

  UPDATE public.facilities
  SET production_started_at = now(),
      updated_at = now()
  WHERE id = p_facility_id;

  PERFORM public._recompute_global_suspicion(v_user_id);

  RETURN jsonb_build_object('success', true, 'facility_id', p_facility_id, 'production_started_at', now());
END;
$$;


ALTER FUNCTION "public"."start_facility_production"("p_facility_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."start_facility_production"("p_facility_id" "uuid", "p_recipe_id" "text", "p_quantity" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_user_id UUID;
    v_facility RECORD;
    v_recipe RECORD;
    v_total_gold INT;
    v_now BIGINT;
    v_duration INT;
    v_suspicion_inc INT;
    v_mat_id TEXT;
    v_mat_req_single INT;
    v_mat_total_needed INT;
    v_user_has INT;
    v_deduct INT;
    v_inv_row RECORD;
BEGIN
    v_user_id := auth.uid();
    v_now := EXTRACT(EPOCH FROM NOW())::BIGINT;
    
    SELECT * INTO v_facility FROM public.facilities WHERE id = p_facility_id AND user_id = v_user_id;
    IF v_facility IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'Facility not found'); END IF;
    SELECT * INTO v_recipe FROM public.facility_recipes WHERE id = p_recipe_id;
    IF v_recipe IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'Recipe not found'); END IF;
    IF v_facility.level < v_recipe.required_level THEN RETURN jsonb_build_object('success', false, 'error', 'Facility level too low'); END IF;
    
    v_total_gold := v_recipe.gold_cost * p_quantity;
    
    -- CHECK public.users
    IF (SELECT gold FROM public.users WHERE id = v_user_id) < v_total_gold THEN
         RETURN jsonb_build_object('success', false, 'error', 'Insufficient gold');
    END IF;
    
    -- Check Materials
    FOR v_mat_id, v_mat_req_single IN SELECT * FROM jsonb_each_text(v_recipe.input_materials)
    LOOP
        v_mat_total_needed := v_mat_req_single::INT * p_quantity;
        SELECT COALESCE(SUM(quantity), 0) INTO v_user_has FROM public.inventory WHERE user_id = v_user_id AND item_id = v_mat_id;
        IF v_user_has < v_mat_total_needed THEN RAISE EXCEPTION 'Insufficient material: %', v_mat_id; END IF;
    END LOOP;
    
    -- UPDATE public.users
    UPDATE public.users SET gold = gold - v_total_gold WHERE id = v_user_id;
    
    -- Deduct Materials
    FOR v_mat_id, v_mat_req_single IN SELECT * FROM jsonb_each_text(v_recipe.input_materials)
    LOOP
        v_mat_total_needed := v_mat_req_single::INT * p_quantity;
        WHILE v_mat_total_needed > 0 LOOP
            SELECT row_id, quantity INTO v_inv_row FROM public.inventory WHERE user_id = v_user_id AND item_id = v_mat_id ORDER BY quantity ASC LIMIT 1;
            v_deduct := LEAST(v_inv_row.quantity, v_mat_total_needed);
            UPDATE public.inventory SET quantity = quantity - v_deduct WHERE row_id = v_inv_row.row_id;
            DELETE FROM public.inventory WHERE row_id = v_inv_row.row_id AND quantity <= 0;
            v_mat_total_needed := v_mat_total_needed - v_deduct;
        END LOOP;
    END LOOP;

    v_suspicion_inc := v_recipe.base_suspicion_increase * p_quantity;
    UPDATE public.facilities SET suspicion = LEAST(100, suspicion + v_suspicion_inc) WHERE id = p_facility_id;
    
    v_duration := (v_recipe.duration_seconds * p_quantity);
    INSERT INTO public.facility_queue (facility_id, recipe_id, quantity, started_at, completed_at)
    VALUES (p_facility_id, p_recipe_id, p_quantity, v_now, v_now + v_duration);
    
    RETURN jsonb_build_object('success', true);
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;


ALTER FUNCTION "public"."start_facility_production"("p_facility_id" "uuid", "p_recipe_id" "text", "p_quantity" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."start_kingdom_election"("p_end_at" timestamp with time zone, "p_month" "date" DEFAULT ("date_trunc"('month'::"text", "now"()))::"date", "p_start_at" timestamp with time zone DEFAULT "now"()) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_election_id uuid;
  v_active record;
BEGIN
  IF p_end_at IS NULL OR p_end_at <= p_start_at THEN
    RETURN json_build_object(
      'success', false,
      'error', 'Bitiş zamanı başlangıçtan sonra olmalıdır.'
    );
  END IF;

  -- Finalize overdue active elections first
  FOR v_active IN
    SELECT id FROM public.kingdom_elections
    WHERE status = 'active'
      AND end_at IS NOT NULL
      AND end_at <= now()
  LOOP
    PERFORM public.finalize_kingdom_election(v_active.id);
  END LOOP;

  -- Close any still-active election before starting new one
  FOR v_active IN
    SELECT id FROM public.kingdom_elections WHERE status = 'active'
  LOOP
    PERFORM public.finalize_kingdom_election(v_active.id);
  END LOOP;

  INSERT INTO public.kingdom_elections (month, status, start_at, end_at, winner_guild_id)
  VALUES (p_month, 'active', p_start_at, p_end_at, NULL)
  ON CONFLICT (month) DO UPDATE SET
    status = 'active',
    start_at = EXCLUDED.start_at,
    end_at = EXCLUDED.end_at,
    winner_guild_id = NULL
  RETURNING id INTO v_election_id;

  RETURN json_build_object(
    'success', true,
    'election_id', v_election_id,
    'month', p_month,
    'start_at', p_start_at,
    'end_at', p_end_at
  );
END;
$$;


ALTER FUNCTION "public"."start_kingdom_election"("p_end_at" timestamp with time zone, "p_month" "date", "p_start_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."start_quest"("p_quest_id" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_energy_cost integer;
  v_current_energy integer;
  v_target integer;
BEGIN
  IF p_quest_id LIKE 'bp_%' THEN
    RAISE EXCEPTION 'Sezon görevleri otomatik takip edilir.';
  END IF;

  SELECT energy_cost, target INTO v_energy_cost, v_target
  FROM public.quests WHERE quest_id = p_quest_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Görev bulunamadı.';
  END IF;

  SELECT energy INTO v_current_energy
  FROM public.users WHERE auth_id = v_user_id;

  IF v_current_energy < v_energy_cost THEN
    RAISE EXCEPTION 'Yetersiz enerji.';
  END IF;

  IF v_energy_cost > 0 THEN
    UPDATE public.users SET energy = energy - v_energy_cost WHERE auth_id = v_user_id;
  END IF;

  INSERT INTO public.player_quests (user_id, quest_id, status, progress, progress_max)
  VALUES (v_user_id, p_quest_id, 'active', 0, v_target)
  ON CONFLICT (user_id, quest_id) DO UPDATE
  SET status = 'active', progress = 0, progress_max = v_target;
END;
$$;


ALTER FUNCTION "public"."start_quest"("p_quest_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."swap_equip_with_slot"("p_equip_slot" "text", "p_target_slot" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_equip_row uuid;
  v_inv_row uuid;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  IF p_equip_slot IS NULL OR p_target_slot IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invalid args');
  END IF;

  -- Find currently equipped item in that equipment slot
  SELECT row_id INTO v_equip_row FROM public.inventory
    WHERE user_id = v_user_id AND is_equipped = TRUE AND lower(COALESCE(equip_slot, '')) = lower(COALESCE(p_equip_slot, ''))
    LIMIT 1 FOR UPDATE;

  -- Find item at target inventory slot
  SELECT row_id INTO v_inv_row FROM public.inventory
    WHERE user_id = v_user_id AND slot_position = p_target_slot
    LIMIT 1 FOR UPDATE;

  -- Both exist: swap atomically
  -- To avoid unique-index conflicts on equip_slot we first move the currently equipped
  -- item out of the equip slot (freeing the slot), then mark the inventory item as equipped.
  IF v_equip_row IS NOT NULL AND v_inv_row IS NOT NULL THEN
    -- Clear the inventory slot on the target row first to avoid idx_inventory_user_slot_unique collisions
    UPDATE public.inventory SET slot_position = NULL, updated_at = NOW()
      WHERE row_id = v_inv_row;

    -- Move currently equipped item into the inventory target slot (now free)
    UPDATE public.inventory SET slot_position = p_target_slot, is_equipped = FALSE, equip_slot = NULL, updated_at = NOW()
      WHERE row_id = v_equip_row;

    -- Now equip the inventory item into the equip slot (equip_slot is free)
    UPDATE public.inventory SET slot_position = NULL, is_equipped = TRUE, equip_slot = p_equip_slot, updated_at = NOW()
      WHERE row_id = v_inv_row;

    RETURN jsonb_build_object('success', true, 'moved', jsonb_build_array(
      jsonb_build_object('row_id', v_inv_row, 'slot', NULL::int),
      jsonb_build_object('row_id', v_equip_row, 'slot', p_target_slot)
    ));
  END IF;

  -- Only equip exists: move it to inventory slot (unequip)
  IF v_equip_row IS NOT NULL AND v_inv_row IS NULL THEN
    UPDATE public.inventory SET slot_position = p_target_slot, is_equipped = FALSE, equip_slot = NULL, updated_at = NOW()
      WHERE row_id = v_equip_row;
    RETURN jsonb_build_object('success', true, 'moved', jsonb_build_array(jsonb_build_object('row_id', v_equip_row, 'slot', p_target_slot)));
  END IF;

  -- Only inventory exists: equip it
  IF v_equip_row IS NULL AND v_inv_row IS NOT NULL THEN
    -- Defensive: ensure any stray equipped row for this equip slot is cleared
    UPDATE public.inventory
    SET is_equipped = FALSE, equip_slot = NULL, slot_position = NULL, updated_at = NOW()
    WHERE user_id = v_user_id
      AND lower(COALESCE(equip_slot, '')) = lower(COALESCE(p_equip_slot, ''))
      AND is_equipped = TRUE
      AND row_id != v_inv_row;

    -- Equip the inventory item
    UPDATE public.inventory SET slot_position = NULL, is_equipped = TRUE, equip_slot = p_equip_slot, updated_at = NOW()
      WHERE row_id = v_inv_row;
    RETURN jsonb_build_object('success', true, 'moved', jsonb_build_array(jsonb_build_object('row_id', v_inv_row, 'slot', NULL)));
  END IF;

  RETURN jsonb_build_object('success', false, 'error', 'No items to swap');
END;
$$;


ALTER FUNCTION "public"."swap_equip_with_slot"("p_equip_slot" "text", "p_target_slot" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."swap_inventory_bank"("p_source_type" "text", "p_source_id" "uuid", "p_target_type" "text", "p_target_id" "uuid", "p_quantity" integer DEFAULT NULL::integer, "p_target_slot" integer DEFAULT NULL::integer) RETURNS TABLE("success" boolean, "message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_source_item_id text;
  v_source_qty integer;
  v_source_slot integer;
  v_target_item_id text;
  v_target_qty integer;
  v_target_slot integer;
  v_max_stack integer;
  v_transfer_qty integer;
  v_remaining_qty integer;
  v_actual_transfer integer;
  v_max_bank_slots integer;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN QUERY SELECT false, 'Not authenticated'::text;
    RETURN;
  END IF;

  IF p_source_type = 'inventory' THEN
    SELECT item_id, quantity, slot_position INTO v_source_item_id, v_source_qty, v_source_slot
    FROM public.inventory
    WHERE row_id = p_source_id AND user_id = v_user_id;
  ELSIF p_source_type = 'bank' THEN
    SELECT item_id, quantity, slot_position INTO v_source_item_id, v_source_qty, v_source_slot
    FROM public.bank_items
    WHERE id = p_source_id AND user_id = v_user_id;
  END IF;

  IF v_source_item_id IS NULL THEN
    RETURN QUERY SELECT false, 'Source item not found'::text;
    RETURN;
  END IF;

  v_actual_transfer := COALESCE(p_quantity, v_source_qty);
  v_actual_transfer := LEAST(v_actual_transfer, v_source_qty);
  IF v_actual_transfer <= 0 THEN
    RETURN QUERY SELECT false, 'Invalid transfer quantity'::text;
    RETURN;
  END IF;

  IF p_target_id IS NOT NULL AND p_source_type = p_target_type AND p_source_id = p_target_id THEN
    RETURN QUERY SELECT true, 'Source and target are the same slot'::text;
    RETURN;
  END IF;

  IF p_target_id IS NOT NULL THEN
    IF p_target_type = 'inventory' THEN
      SELECT item_id, quantity, slot_position INTO v_target_item_id, v_target_qty, v_target_slot
      FROM public.inventory
      WHERE row_id = p_target_id AND user_id = v_user_id;
    ELSIF p_target_type = 'bank' THEN
      SELECT item_id, quantity, slot_position INTO v_target_item_id, v_target_qty, v_target_slot
      FROM public.bank_items
      WHERE id = p_target_id AND user_id = v_user_id;
    END IF;
  END IF;

  v_target_slot := COALESCE(v_target_slot, p_target_slot);

  IF p_target_type = 'bank'
     AND p_source_type = 'inventory'
     AND v_target_item_id IS NULL
     AND (v_target_slot IS NULL OR v_target_slot < 0) THEN
    SELECT total_slots INTO v_max_bank_slots
    FROM public.user_bank_account
    WHERE user_id = v_user_id;
    v_max_bank_slots := COALESCE(v_max_bank_slots, 100);
    v_target_slot := public.bank_first_free_slot(v_user_id, v_max_bank_slots);
    IF v_target_slot IS NULL THEN
      RETURN QUERY SELECT false, 'Bank is full'::text;
      RETURN;
    END IF;
  END IF;

  IF v_target_slot IS NULL THEN
    RETURN QUERY SELECT false, 'Target slot is required'::text;
    RETURN;
  END IF;

  SELECT max_stack INTO v_max_stack
  FROM public.items WHERE id = v_source_item_id;
  v_max_stack := COALESCE(v_max_stack, 1);

  IF v_target_item_id IS NOT NULL AND v_target_item_id = v_source_item_id THEN
    v_transfer_qty := LEAST(v_actual_transfer, v_max_stack - v_target_qty);
    IF v_transfer_qty <= 0 THEN
      RETURN QUERY SELECT false, 'Target stack is full'::text;
      RETURN;
    END IF;

    v_remaining_qty := v_source_qty - v_transfer_qty;

    IF p_target_type = 'inventory' THEN
      UPDATE public.inventory SET quantity = quantity + v_transfer_qty, updated_at = now()
      WHERE row_id = p_target_id;
    ELSIF p_target_type = 'bank' THEN
      UPDATE public.bank_items SET quantity = quantity + v_transfer_qty, updated_at = now()
      WHERE id = p_target_id;
    END IF;

    IF v_remaining_qty > 0 THEN
      IF p_source_type = 'inventory' THEN
        UPDATE public.inventory SET quantity = v_remaining_qty, updated_at = now()
        WHERE row_id = p_source_id;
      ELSIF p_source_type = 'bank' THEN
        UPDATE public.bank_items SET quantity = v_remaining_qty, updated_at = now()
        WHERE id = p_source_id;
      END IF;
    ELSE
      IF p_source_type = 'inventory' THEN
        DELETE FROM public.inventory WHERE row_id = p_source_id;
      ELSIF p_source_type = 'bank' THEN
        DELETE FROM public.bank_items WHERE id = p_source_id;
        UPDATE public.user_bank_account
        SET used_slots = GREATEST(0, used_slots - 1), updated_at = now()
        WHERE user_id = v_user_id;
      END IF;
    END IF;

    RETURN QUERY SELECT true, 'Items merged successfully'::text;
    RETURN;
  END IF;

  IF v_target_item_id IS NULL THEN
    IF p_target_type = 'inventory' THEN
      IF EXISTS (
        SELECT 1 FROM public.inventory
        WHERE user_id = v_user_id
          AND is_equipped = FALSE
          AND slot_position = v_target_slot
          AND row_id <> p_source_id
      ) THEN
        RETURN QUERY SELECT false, 'Target inventory slot is occupied'::text;
        RETURN;
      END IF;
    ELSIF p_target_type = 'bank' THEN
      IF EXISTS (
        SELECT 1 FROM public.bank_items
        WHERE user_id = v_user_id
          AND slot_position = v_target_slot
          AND id <> p_source_id
      ) THEN
        RETURN QUERY SELECT false, 'Target bank slot is occupied'::text;
        RETURN;
      END IF;
    END IF;

    IF p_source_type = 'inventory' AND p_target_type = 'bank' THEN
      INSERT INTO public.bank_items (user_id, item_id, quantity, category, slot_position)
      SELECT v_user_id, inv.item_id, v_actual_transfer,
        CASE
          WHEN it.type = 'equipment' THEN 'equipment'
          WHEN it.type = 'consumable' THEN 'consumable'
          WHEN it.type = 'special' THEN 'special'
          ELSE 'material'
        END,
        v_target_slot
      FROM public.inventory inv
      JOIN public.items it ON inv.item_id = it.id
      WHERE inv.row_id = p_source_id;

      IF v_source_qty - v_actual_transfer > 0 THEN
        UPDATE public.inventory SET quantity = v_source_qty - v_actual_transfer, updated_at = now()
        WHERE row_id = p_source_id;
      ELSE
        DELETE FROM public.inventory WHERE row_id = p_source_id;
      END IF;

      UPDATE public.user_bank_account
      SET used_slots = (
            SELECT COUNT(*)::integer
            FROM public.bank_items bi
            WHERE bi.user_id = v_user_id
          ),
          updated_at = now()
      WHERE user_id = v_user_id;

    ELSIF p_source_type = 'bank' AND p_target_type = 'inventory' THEN
      INSERT INTO public.inventory (user_id, item_id, quantity, slot_position)
      SELECT v_user_id, b.item_id, v_actual_transfer, v_target_slot
      FROM public.bank_items b
      WHERE b.id = p_source_id;

      IF v_source_qty - v_actual_transfer > 0 THEN
        UPDATE public.bank_items SET quantity = v_source_qty - v_actual_transfer, updated_at = now()
        WHERE id = p_source_id;
      ELSE
        DELETE FROM public.bank_items WHERE id = p_source_id;
        UPDATE public.user_bank_account
        SET used_slots = (
              SELECT COUNT(*)::integer
              FROM public.bank_items bi
              WHERE bi.user_id = v_user_id
            ),
            updated_at = now()
        WHERE user_id = v_user_id;
      END IF;

    ELSIF p_source_type = 'inventory' AND p_target_type = 'inventory' THEN
      IF v_actual_transfer < v_source_qty THEN
        RETURN QUERY SELECT false, 'Partial move is only allowed between inventory and bank'::text;
        RETURN;
      END IF;

      UPDATE public.inventory
      SET slot_position = v_target_slot,
          updated_at = now()
      WHERE row_id = p_source_id;

    ELSIF p_source_type = 'bank' AND p_target_type = 'bank' THEN
      IF v_actual_transfer < v_source_qty THEN
        RETURN QUERY SELECT false, 'Partial move is only allowed between inventory and bank'::text;
        RETURN;
      END IF;

      UPDATE public.bank_items
      SET slot_position = v_target_slot,
          updated_at = now()
      WHERE id = p_source_id;
    END IF;

    RETURN QUERY SELECT true, 'Item moved to empty slot'::text;
    RETURN;
  END IF;

  IF v_actual_transfer < v_source_qty THEN
    RETURN QUERY SELECT false, 'Partial swap is not allowed on different items'::text;
    RETURN;
  END IF;

  IF p_source_type = 'inventory' AND p_target_type = 'bank' THEN
    UPDATE public.inventory SET item_id = v_target_item_id, quantity = v_target_qty, updated_at = now()
    WHERE row_id = p_source_id;

    UPDATE public.bank_items SET item_id = v_source_item_id, quantity = v_source_qty, updated_at = now()
    WHERE id = p_target_id;
  ELSIF p_source_type = 'bank' AND p_target_type = 'inventory' THEN
    UPDATE public.bank_items SET item_id = v_target_item_id, quantity = v_target_qty, updated_at = now()
    WHERE id = p_source_id;

    UPDATE public.inventory SET item_id = v_source_item_id, quantity = v_source_qty, updated_at = now()
    WHERE row_id = p_target_id;
  ELSIF p_source_type = 'inventory' AND p_target_type = 'inventory' THEN
    UPDATE public.inventory SET item_id = v_target_item_id, quantity = v_target_qty, updated_at = now()
    WHERE row_id = p_source_id;

    UPDATE public.inventory SET item_id = v_source_item_id, quantity = v_source_qty, updated_at = now()
    WHERE row_id = p_target_id;
  ELSIF p_source_type = 'bank' AND p_target_type = 'bank' THEN
    UPDATE public.bank_items SET item_id = v_target_item_id, quantity = v_target_qty, updated_at = now()
    WHERE id = p_source_id;

    UPDATE public.bank_items SET item_id = v_source_item_id, quantity = v_source_qty, updated_at = now()
    WHERE id = p_target_id;
  END IF;

  RETURN QUERY SELECT true, 'Items swapped successfully'::text;
END;
$$;


ALTER FUNCTION "public"."swap_inventory_bank"("p_source_type" "text", "p_source_id" "uuid", "p_target_type" "text", "p_target_id" "uuid", "p_quantity" integer, "p_target_slot" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."swap_slots"("p_from_slot" integer, "p_to_slot" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_a_row uuid;
  v_b_row uuid;
  v_tmp int := -999999999;
  v_result jsonb := '{}'::jsonb;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  IF p_from_slot IS NULL OR p_to_slot IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invalid slot args');
  END IF;

  IF p_from_slot = p_to_slot THEN
    RETURN jsonb_build_object('success', true, 'note', 'no-op');
  END IF;

  -- Ensure equipped items do not retain grid slot positions (cleanup corrupted rows)
  UPDATE public.inventory
  SET slot_position = NULL, updated_at = NOW()
  WHERE user_id = v_user_id AND is_equipped = TRUE AND slot_position IS NOT NULL;

  -- Lock involved rows
  SELECT row_id INTO v_a_row FROM public.inventory
    WHERE user_id = v_user_id AND slot_position = p_from_slot
    LIMIT 1 FOR UPDATE;

  SELECT row_id INTO v_b_row FROM public.inventory
    WHERE user_id = v_user_id AND slot_position = p_to_slot
    LIMIT 1 FOR UPDATE;

  -- Both rows exist: swap
  IF v_a_row IS NOT NULL AND v_b_row IS NOT NULL THEN
    UPDATE public.inventory SET slot_position = v_tmp WHERE row_id = v_a_row;
    UPDATE public.inventory SET slot_position = p_from_slot WHERE row_id = v_b_row;
    UPDATE public.inventory SET slot_position = p_to_slot WHERE slot_position = v_tmp AND user_id = v_user_id;
    v_result := jsonb_build_object('success', true, 'moved', jsonb_build_array(
      jsonb_build_object('row_id', v_a_row, 'slot', p_to_slot),
      jsonb_build_object('row_id', v_b_row, 'slot', p_from_slot)
    ));
    RETURN v_result;
  END IF;

  -- Only A exists
  IF v_a_row IS NOT NULL AND v_b_row IS NULL THEN
    UPDATE public.inventory SET slot_position = p_to_slot, updated_at = NOW()
      WHERE row_id = v_a_row;
    RETURN jsonb_build_object('success', true, 'moved', jsonb_build_array(jsonb_build_object('row_id', v_a_row, 'slot', p_to_slot)));
  END IF;

  -- Only B exists
  IF v_a_row IS NULL AND v_b_row IS NOT NULL THEN
    UPDATE public.inventory SET slot_position = p_from_slot, updated_at = NOW()
      WHERE row_id = v_b_row;
    RETURN jsonb_build_object('success', true, 'moved', jsonb_build_array(jsonb_build_object('row_id', v_b_row, 'slot', p_from_slot)));
  END IF;

  -- Neither exists
  RETURN jsonb_build_object('success', false, 'error', 'No items at given slots');

EXCEPTION WHEN others THEN
  RAISE;
END;
$$;


ALTER FUNCTION "public"."swap_slots"("p_from_slot" integer, "p_to_slot" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_guild_blueprint_completion"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF COALESCE(NEW.fragments, 0) >= COALESCE(NEW.fragments_required, 100) THEN
    NEW.is_complete := true;
    IF NEW.completed_at IS NULL THEN
      NEW.completed_at := now();
    END IF;
  ELSE
    NEW.is_complete := false;
    NEW.completed_at := NULL;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sync_guild_blueprint_completion"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_guild_member_monument_stats"("p_guild_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_level INT;
BEGIN
  SELECT monument_level INTO v_level FROM public.guilds WHERE id = p_guild_id;
  IF NOT FOUND THEN RETURN; END IF;
  UPDATE public.users u SET max_energy = 100 + public._monument_energy_bonus(v_level) WHERE u.guild_id = p_guild_id;
END;
