CREATE OR REPLACE FUNCTION "public"."sync_tutorial_progress"("p_progress" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_merged jsonb;
  v_completed boolean := false;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  v_merged := COALESCE(
    (SELECT tutorial_progress FROM public.users WHERE auth_id = v_user_id),
    '{}'::jsonb
  ) || COALESCE(p_progress, '{}'::jsonb);

  v_completed := COALESCE((v_merged->>'core_completed')::boolean, false)
    OR COALESCE((v_merged->>'skipped_all')::boolean, false);

  UPDATE public.users
  SET tutorial_progress = v_merged,
      tutorial_completed = CASE WHEN v_completed THEN true ELSE tutorial_completed END,
      updated_at = now()
  WHERE auth_id = v_user_id;

  RETURN jsonb_build_object(
    'success', true,
    'tutorial_progress', v_merged,
    'tutorial_completed', v_completed
  );
END;
$$;


ALTER FUNCTION "public"."sync_tutorial_progress"("p_progress" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_user_hospital_prison_states"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF NEW.hospital_until IS NOT NULL AND NEW.hospital_until <= now() THEN
    NEW.hospital_until := NULL;
    NEW.hospital_reason := NULL;
    NEW.hospital_escape_attempted := false;
  END IF;

  IF NEW.prison_until IS NOT NULL AND NEW.prison_until <= now() THEN
    NEW.prison_until := NULL;
    NEW.prison_reason := NULL;
    NEW.prison_escape_attempted := false;
  END IF;

  IF NEW.hospital_until IS NULL THEN
    NEW.hospital_escape_attempted := false;
  END IF;

  IF NEW.prison_until IS NULL THEN
    NEW.prison_escape_attempted := false;
  END IF;

  IF NEW.hospital_until IS NOT NULL AND NEW.hospital_until > now() THEN
    IF NEW.hospital_reason IS NULL OR btrim(NEW.hospital_reason) = '' THEN
      NEW.hospital_reason := 'dungeon_failure';
    END IF;

    IF OLD IS NULL OR OLD.hospital_until IS NULL OR OLD.hospital_until <= now() THEN
      NEW.hospital_escape_attempted := false;
    END IF;
  END IF;

  IF NEW.prison_until IS NOT NULL AND NEW.prison_until > now() THEN
    IF NEW.prison_reason IS NULL OR btrim(NEW.prison_reason) = '' THEN
      NEW.prison_reason := 'legal_violation';
    END IF;

    IF OLD IS NULL OR OLD.prison_until IS NULL OR OLD.prison_until <= now() THEN
      NEW.prison_escape_attempted := false;
    END IF;
  END IF;

  BEGIN
    NEW.in_hospital := (NEW.hospital_until IS NOT NULL AND NEW.hospital_until > now());
  EXCEPTION
    WHEN undefined_column THEN
      NULL;
  END;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sync_user_hospital_prison_states"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tick_horse_race_engine"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_round RECORD;
BEGIN
  SELECT * INTO v_round FROM public.horse_race_rounds ORDER BY created_at DESC LIMIT 1 FOR UPDATE;
  IF NOT FOUND THEN PERFORM public._horse_race_create_round(); RETURN; END IF;
  IF v_round.status = 'betting' AND now() >= v_round.betting_ends_at THEN
    UPDATE public.horse_race_rounds SET status = 'locked', updated_at = now() WHERE id = v_round.id;
    PERFORM public._horse_race_resolve_round(v_round.id); RETURN;
  END IF;
  IF v_round.status = 'racing' AND v_round.racing_ends_at IS NOT NULL AND now() >= v_round.racing_ends_at THEN
    UPDATE public.horse_race_rounds SET status = 'finished', updated_at = now() WHERE id = v_round.id; RETURN;
  END IF;
  IF v_round.status = 'finished' AND v_round.finished_ends_at IS NOT NULL AND now() >= v_round.finished_ends_at THEN
    PERFORM public._horse_race_create_round(); RETURN;
  END IF;
END;
$$;


ALTER FUNCTION "public"."tick_horse_race_engine"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."toggle_item_favorite"("p_row_id" "uuid", "p_is_favorite" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id uuid;
  v_updated int := 0;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  UPDATE public.inventory
  SET is_favorite = p_is_favorite, updated_at = NOW()
  WHERE row_id = p_row_id AND user_id = v_user_id
  RETURNING 1 INTO v_updated;

  IF v_updated > 0 THEN
    RETURN jsonb_build_object('success', true);
  END IF;

  RETURN jsonb_build_object('success', false, 'error', 'Item not found or not owned');
END;
$$;


ALTER FUNCTION "public"."toggle_item_favorite"("p_row_id" "uuid", "p_is_favorite" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."toggle_mekan_status"("p_mekan_id" "uuid", "p_is_open" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_auth_id UUID;
  v_mekan RECORD;
BEGIN
  v_auth_id := auth.uid();
  IF v_auth_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Kimlik dogrulama gerekli');
  END IF;

  SELECT * INTO v_mekan FROM public.mekans WHERE id = p_mekan_id AND owner_id = v_auth_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Mekan bulunamadi veya size ait degil');
  END IF;

  IF v_mekan.closed_until IS NOT NULL AND v_mekan.closed_until > now() THEN
    RETURN jsonb_build_object('success', false, 'error', 'Mekan polis baskini nedeniyle kapali');
  END IF;

  UPDATE public.mekans SET is_open = p_is_open WHERE id = p_mekan_id AND owner_id = v_auth_id;

  RETURN jsonb_build_object('success', true, 'is_open', p_is_open);
END;
$$;


ALTER FUNCTION "public"."toggle_mekan_status"("p_mekan_id" "uuid", "p_is_open" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."total_xp_for_level"("p_level" integer) RETURNS integer
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_total integer := 0;
  v_i integer;
BEGIN
  IF p_level IS NULL OR p_level <= 1 THEN
    RETURN 0;
  END IF;

  FOR v_i IN 1..(p_level - 1) LOOP
    v_total := v_total + public.xp_needed_for_level(v_i);
  END LOOP;

  RETURN v_total;
END;
$$;


ALTER FUNCTION "public"."total_xp_for_level"("p_level" integer) OWNER TO "postgres";


