    -- Get zone from dungeons table
    SELECT zone FROM public.dungeons WHERE id = NEW.dungeon_id INTO v_zone;
    PERFORM public.bp_trigger_dungeon_clear(NEW.player_id, COALESCE(v_zone, 1));
