CREATE OR REPLACE FUNCTION "public"."unblock_chat_user"("p_blocked_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user public.users%ROWTYPE;
  v_deleted_count INTEGER;
BEGIN
  v_user := public.get_current_chat_user();

  IF p_blocked_user_id IS NULL OR p_blocked_user_id = v_user.id THEN
    RETURN jsonb_build_object('success', false, 'error', 'Gecersiz kullanici');
  END IF;

  DELETE FROM public.chat_blocks
  WHERE blocker_user_id = v_user.id
    AND blocked_user_id = p_blocked_user_id;

  GET DIAGNOSTICS v_deleted_count = ROW_COUNT;

  RETURN jsonb_build_object(
    'success', v_deleted_count > 0,
    'deleted_count', v_deleted_count
  );
END;
$$;


ALTER FUNCTION "public"."unblock_chat_user"("p_blocked_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."unblock_trade_user"("p_blocked_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid;
  v_deleted int;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Oturum bulunamadı.');
  END IF;
  IF p_blocked_id IS NULL OR p_blocked_id = v_uid THEN
    RETURN jsonb_build_object('success', false, 'error', 'Geçersiz oyuncu.');
  END IF;

  DELETE FROM public.trade_blocks
  WHERE blocker_id = v_uid AND blocked_id = p_blocked_id;

  GET DIAGNOSTICS v_deleted = ROW_COUNT;

  RETURN jsonb_build_object('success', v_deleted > 0, 'deleted_count', v_deleted);
END;
$$;


ALTER FUNCTION "public"."unblock_trade_user"("p_blocked_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."unequip_item"("p_slot" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_user_id UUID;
    v_updated_count INT;
BEGIN
    v_user_id := auth.uid();

    IF v_user_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
    END IF;

    UPDATE public.inventory
    SET is_equipped = FALSE, equip_slot = NULL, slot_position = NULL, updated_at = NOW()
    WHERE user_id = v_user_id
      AND lower(COALESCE(equip_slot, '')) = lower(COALESCE(p_slot, ''))
      AND is_equipped = TRUE;

    GET DIAGNOSTICS v_updated_count = ROW_COUNT;
    IF v_updated_count = 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'Item not found, not owned, or not equipped');
    END IF;

    RETURN jsonb_build_object('success', true, 'slot', p_slot);
END;
$$;


