CREATE OR REPLACE FUNCTION "public"."upgrade_facility"("p_facility_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_facility record;
  v_cost bigint;
  v_player record;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT * INTO v_facility
  FROM public.facilities
  WHERE id = p_facility_id
    AND user_id = v_user_id
    AND COALESCE(is_active, true) = true
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Facility not found');
  END IF;

  IF v_facility.production_started_at IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Uretim varken yukseltilemez');
  END IF;

  IF COALESCE(v_facility.level, 1) >= 10 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Maksimum seviye');
  END IF;

  v_cost := public._plan2_facility_upgrade_cost(v_facility.type, COALESCE(v_facility.level, 1));

  SELECT * INTO v_player
  FROM public.users u
  WHERE u.auth_id = v_user_id
  FOR UPDATE;

  IF COALESCE(v_player.gold, 0) < v_cost THEN
    RETURN jsonb_build_object('success', false, 'error', 'Altin yetersiz');
  END IF;

  IF v_player.prison_until IS NOT NULL AND v_player.prison_until > now() THEN
    RETURN jsonb_build_object('success', false, 'error', 'Cezaevindeyken yukseltilemez');
  END IF;

  UPDATE public.users
  SET gold = gold - v_cost,
      updated_at = now()
  WHERE auth_id = v_user_id
    AND gold >= v_cost;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Altin yetersiz');
  END IF;

  UPDATE public.facilities
  SET level = COALESCE(level, 1) + 1,
      updated_at = now()
  WHERE id = p_facility_id;

  RETURN jsonb_build_object('success', true, 'facility_id', p_facility_id, 'new_level', COALESCE(v_facility.level, 1) + 1);
END;
$$;


ALTER FUNCTION "public"."upgrade_facility"("p_facility_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upgrade_item_enhancement"("p_new_level" integer, "p_row_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_affected_rows INT;
BEGIN
    UPDATE public.inventory
    SET enhancement_level = p_new_level,
        updated_at = NOW()
    WHERE row_id = p_row_id;

    GET DIAGNOSTICS v_affected_rows = ROW_COUNT;

    IF v_affected_rows > 0 THEN
        RETURN json_build_object('success', true, 'new_level', p_new_level);
    ELSE
        RETURN json_build_object('success', false, 'error', 'Item not found or permission denied');
    END IF;
EXCEPTION WHEN OTHERS THEN
    RETURN json_build_object('success', false, 'error', SQLERRM);
END;
$$;


ALTER FUNCTION "public"."upgrade_item_enhancement"("p_new_level" integer, "p_row_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upgrade_mekan"("p_mekan_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_auth_id UUID;
  v_mekan RECORD;
  v_cost BIGINT;
  v_gold BIGINT;
BEGIN
  v_auth_id := auth.uid();
  IF v_auth_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Kimlik dogrulama gerekli');
  END IF;
  SELECT * INTO v_mekan FROM public.mekans WHERE id = p_mekan_id AND owner_id = v_auth_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Mekan bulunamadi veya size ait degil');
  END IF;
  IF v_mekan.level >= 10 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Mekan zaten maksimum seviyede');
  END IF;
  v_cost := public.mekan_upgrade_cost(v_mekan.level);
  IF v_cost IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Yukseltme maliyeti hesaplanamadi');
  END IF;
  SELECT gold INTO v_gold FROM public.users WHERE auth_id = v_auth_id FOR UPDATE;
  IF v_gold < v_cost THEN
    RETURN jsonb_build_object('success', false, 'error', 'Gold yetersiz. Gereken: ' || v_cost);
  END IF;
  UPDATE public.users SET gold = gold - v_cost WHERE auth_id = v_auth_id AND gold >= v_cost;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Islem sirasinda altin yetersiz kaldi');
  END IF;
  UPDATE public.mekans SET level = level + 1, fame = fame + 100 WHERE id = p_mekan_id;
  RETURN jsonb_build_object('success', true, 'new_level', v_mekan.level + 1, 'cost', v_cost,
    'new_capacity', public.mekan_total_capacity(v_mekan.mekan_type, v_mekan.level + 1));
END;
$$;


ALTER FUNCTION "public"."upgrade_mekan"("p_mekan_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upgrade_monument"("p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user RECORD;
  v_guild RECORD;
  v_next_level INT;
  v_cost RECORD;
  v_members INT;
  v_mult NUMERIC;
  v_req_structural BIGINT;
  v_req_mystical BIGINT;
  v_req_critical BIGINT;
  v_req_gold BIGINT;
BEGIN
  IF p_user_id != auth.uid() THEN
    RETURN jsonb_build_object('success', false, 'error', 'Yetkisiz islem');
  END IF;
  SELECT * INTO v_user FROM public.users WHERE auth_id = p_user_id FOR UPDATE;
  IF v_user.guild_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Bir loncaya uye degilsiniz');
  END IF;
  IF COALESCE(v_user.guild_role, '') NOT IN ('leader', 'officer', 'commander') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Yetkiniz yok (Lider veya Subay gerekli)');
  END IF;
  SELECT * INTO v_guild FROM public.guilds WHERE id = v_user.guild_id FOR UPDATE;
  v_next_level := v_guild.monument_level + 1;
  IF v_next_level > 100 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Anit zaten maksimum seviyede');
  END IF;
  SELECT * INTO v_cost FROM public.monument_level_costs WHERE level = v_next_level;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Seviye maliyeti tanimli degil');
  END IF;
  SELECT COUNT(*)::INT INTO v_members FROM public.users WHERE guild_id = v_guild.id;
  v_mult := public.guild_size_multiplier(v_members);
  v_req_structural := CEIL(v_cost.structural * v_mult)::BIGINT;
  v_req_mystical := CEIL(v_cost.mystical * v_mult)::BIGINT;
  v_req_critical := CEIL(v_cost.critical * v_mult)::BIGINT;
  v_req_gold := CEIL(v_cost.gold * v_mult)::BIGINT;
  IF v_cost.blueprint_type IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.guild_blueprints
      WHERE guild_id = v_guild.id AND blueprint_type = v_cost.blueprint_type AND is_complete = true
    ) THEN
      RETURN jsonb_build_object('success', false, 'error', v_cost.blueprint_type || ' blueprint tamamlanmali');
    END IF;
  END IF;
  IF v_guild.monument_structural < v_req_structural OR
     v_guild.monument_mystical < v_req_mystical OR
     v_guild.monument_critical < v_req_critical OR
     v_guild.monument_gold_pool < v_req_gold THEN
    RETURN jsonb_build_object('success', false, 'error', 'Yeterli kaynak yok');
  END IF;
  UPDATE public.guilds SET
    monument_level = v_next_level,
    monument_structural = monument_structural - v_req_structural,
    monument_mystical = monument_mystical - v_req_mystical,
    monument_critical = monument_critical - v_req_critical,
    monument_gold_pool = monument_gold_pool - v_req_gold,
    monument_100_first = CASE WHEN v_next_level = 100 AND NOT EXISTS (SELECT 1 FROM public.guilds WHERE monument_level >= 100 AND id != v_guild.id) THEN true ELSE monument_100_first END,
    monument_100_at = CASE WHEN v_next_level = 100 THEN now() ELSE monument_100_at END
  WHERE id = v_guild.id;
  INSERT INTO public.monument_upgrades (guild_id, from_level, to_level, structural_spent, mystical_spent, critical_spent, gold_spent, upgraded_by)
  VALUES (v_guild.id, v_guild.monument_level, v_next_level, v_req_structural, v_req_mystical, v_req_critical, v_req_gold, p_user_id);
  PERFORM public.sync_guild_member_monument_stats(v_guild.id);
  RETURN jsonb_build_object('success', true, 'new_level', v_next_level);
END;
$$;


ALTER FUNCTION "public"."upgrade_monument"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."use_detox"("p_row_id" "uuid", "p_user_id" "uuid" DEFAULT "auth"."uid"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_inv RECORD;
  v_item RECORD;
  v_user RECORD;
  v_tolerance_reduction INT;
  v_addiction_reduction INT;
  v_cooldown_hours INT;
  v_new_tolerance INT;
  v_new_addiction INT;
  v_detox_type TEXT;
  v_detox_mult numeric := 1.0;
BEGIN
  IF p_user_id IS NULL OR p_user_id != auth.uid() THEN
    RETURN jsonb_build_object('error', 'Yetkisiz işlem');
  END IF;

  SELECT * INTO v_user FROM public.users WHERE auth_id = p_user_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'Kullanıcı bulunamadı');
  END IF;

  SELECT * INTO v_inv
  FROM public.inventory
  WHERE row_id = p_row_id AND user_id = p_user_id AND quantity > 0
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'Eşya bulunamadı veya miktar yetersiz');
  END IF;

  SELECT * INTO v_item FROM public.items WHERE id = v_inv.item_id;
  IF NOT FOUND OR NOT (
    lower(COALESCE(v_item.sub_type, '')) = 'detox'
    OR v_item.id LIKE 'detox_%'
  ) THEN
    RETURN jsonb_build_object('error', 'Geçersiz detox içeceği');
  END IF;

  IF v_item.id = 'detox_minor' THEN
    v_detox_type := 'minor'; v_tolerance_reduction := 15; v_addiction_reduction := 0; v_cooldown_hours := 4;
  ELSIF v_item.id = 'detox_major' THEN
    v_detox_type := 'major'; v_tolerance_reduction := 35; v_addiction_reduction := 1; v_cooldown_hours := 8;
  ELSIF v_item.id = 'detox_supreme' THEN
    v_detox_type := 'supreme'; v_tolerance_reduction := 60; v_addiction_reduction := 2; v_cooldown_hours := 12;
  ELSIF v_item.id = 'detox_full_cleanse' THEN
    v_detox_type := 'full_cleanse'; v_tolerance_reduction := 100; v_addiction_reduction := 10; v_cooldown_hours := 24;
  ELSE
    v_detox_type := 'minor'; v_tolerance_reduction := 15; v_addiction_reduction := 0; v_cooldown_hours := 4;
  END IF;

  IF COALESCE(v_user.character_class, '') = 'alchemist' THEN
    v_detox_mult := 1 + public._passive_bonus('alchemist', 'detox_effectiveness_bonus', 0.25);
    v_tolerance_reduction := CEIL(v_tolerance_reduction * v_detox_mult)::integer;
    v_addiction_reduction := CEIL(v_addiction_reduction * v_detox_mult)::integer;
  END IF;

  IF v_user.last_detox_used_at IS NOT NULL
     AND v_user.last_detox_used_at + (v_cooldown_hours || ' hours')::interval > now() THEN
    RETURN jsonb_build_object('error', 'Detox cooldown aktif. Kalan süre için bekleyin.');
  END IF;

  v_new_tolerance := GREATEST(COALESCE(v_user.tolerance, 0) - v_tolerance_reduction, 0);
  v_new_addiction := GREATEST(COALESCE(v_user.addiction_level, 0) - v_addiction_reduction, 0);

  IF NOT public._consume_inventory_row(p_row_id, p_user_id) THEN
    RETURN jsonb_build_object('error', 'Eşya bulunamadı veya miktar yetersiz');
  END IF;

  UPDATE public.users
  SET tolerance = v_new_tolerance,
      addiction_level = v_new_addiction,
      last_detox_used_at = now(),
      detox_type_last = v_detox_type
  WHERE auth_id = p_user_id;

  INSERT INTO public.tolerance_log (
    user_id, event_type, item_id,
    tolerance_before, tolerance_after,
    addiction_before, addiction_after
  )
  VALUES (
    p_user_id, 'detox', v_item.id,
    COALESCE(v_user.tolerance, 0), v_new_tolerance,
    COALESCE(v_user.addiction_level, 0), v_new_addiction
  );

  RETURN jsonb_build_object(
    'success', true,
    'detox_type', v_detox_type,
    'new_tolerance', v_new_tolerance,
    'new_addiction', v_new_addiction
  );
END;
$$;


ALTER FUNCTION "public"."use_detox"("p_row_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."use_han_item"("p_user_id" "uuid", "p_row_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_inv RECORD;
  v_item RECORD;
  v_user RECORD;
  v_overdose_chance NUMERIC;
  v_is_overdose BOOLEAN := false;
  v_tolerance_mult NUMERIC := 1.0;
  v_hospital_minutes INT;
BEGIN
  IF p_user_id != auth.uid() THEN
    RETURN jsonb_build_object('error', 'Yetkisiz işlem');
  END IF;

  -- Get user
  SELECT * INTO v_user FROM public.users WHERE auth_id = p_user_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'Kullanıcı bulunamadı');
  END IF;

  -- Get inventory item
  SELECT * INTO v_inv FROM public.inventory WHERE row_id = p_row_id AND user_id = p_user_id AND quantity > 0;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'Eşya bulunamadı');
  END IF;

  -- Get item stats
  SELECT * INTO v_item FROM public.items WHERE id = v_inv.item_id;
  IF NOT v_item.is_han_only THEN
    RETURN jsonb_build_object('error', 'Bu bir Han eşyası değil, use_potion kullanın');
  END IF;

  -- Check overdose risk
  IF COALESCE(v_user.tolerance, 0) > 60 AND COALESCE(v_item.overdose_risk, 0) > 0 THEN
    v_tolerance_mult := v_user.tolerance / 50.0;
    v_overdose_chance := v_item.overdose_risk * v_tolerance_mult;
    
    -- Alchemist overdose reduction
    IF COALESCE(v_user.character_class, '') = 'alchemist' THEN
      v_overdose_chance := v_overdose_chance * 0.80;
    END IF;

    IF random() <= v_overdose_chance THEN
      v_is_overdose := true;
    END IF;
  END IF;

  -- Consume item FIRST with quantity check to prevent double use
  UPDATE public.inventory SET quantity = quantity - 1 WHERE row_id = p_row_id AND quantity > 0;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'Eşya bulunamadı veya miktar yetersiz');
  END IF;
  
  DELETE FROM public.inventory WHERE quantity <= 0 AND row_id = p_row_id;

  -- Apply effects or overdose
  IF v_is_overdose THEN
    -- Overdose penalty: Hospital for 2-4 hours, massive tolerance penalty
    v_hospital_minutes := 120 + floor(random() * 120);
    
    UPDATE public.users
    SET
      hospital_until = now() + (v_hospital_minutes || ' minutes')::INTERVAL,
      hospital_reason = 'Han İksiri Overdose',
      tolerance = LEAST(100, COALESCE(tolerance, 0) + 15)
    WHERE auth_id = p_user_id;

    RETURN jsonb_build_object(
      'success', true,
      'overdose', true,
      'hospital_minutes', v_hospital_minutes
    );
  ELSE
    -- Normal use
    UPDATE public.users
    SET
      energy = LEAST(100, energy + COALESCE(v_item.energy_restore, 0)),
      health = LEAST(max_health, health + COALESCE(v_item.heal_amount, 0)),
      tolerance = GREATEST(0, LEAST(100, COALESCE(tolerance, 0) + COALESCE(v_item.tolerance_increase, 0)))
    WHERE auth_id = p_user_id;

    RETURN jsonb_build_object(
      'success', true,
      'overdose', false,
      'energy_restored', COALESCE(v_item.energy_restore, 0),
      'new_tolerance', GREATEST(0, LEAST(100, COALESCE(v_user.tolerance, 0) + COALESCE(v_item.tolerance_increase, 0)))
    );
  END IF;
END;
$$;


ALTER FUNCTION "public"."use_han_item"("p_user_id" "uuid", "p_row_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."use_potion"("p_row_id" "uuid", "p_user_id" "uuid" DEFAULT "auth"."uid"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_inv RECORD;
  v_item RECORD;
  v_user RECORD;
  v_new_tolerance INT;
  v_overdose BOOLEAN := false;
  v_efficiency NUMERIC;
  v_overdose_chance NUMERIC;
  v_roll NUMERIC;
  v_hospital_minutes INT;
  v_heal_amount INT;
  v_energy_gain INT;
  v_monument_level INT := 0;
  v_saved_from_overdose BOOLEAN := false;
BEGIN
  IF p_user_id IS NULL OR p_user_id != auth.uid() THEN
    RETURN jsonb_build_object('error', 'Yetkisiz işlem');
  END IF;

  SELECT * INTO v_user FROM public.users WHERE auth_id = p_user_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'Kullanıcı bulunamadı');
  END IF;

  IF v_user.guild_id IS NOT NULL THEN
    SELECT monument_level INTO v_monument_level FROM public.guilds WHERE id = v_user.guild_id;
  END IF;

  SELECT * INTO v_inv
  FROM public.inventory
  WHERE row_id = p_row_id AND user_id = p_user_id AND quantity > 0
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'Eşya bulunamadı veya miktar yetersiz');
  END IF;

  SELECT * INTO v_item FROM public.items WHERE id = v_inv.item_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'Geçersiz iksir');
  END IF;

  IF v_item.id LIKE 'box\_%' ESCAPE '\' THEN
    RETURN jsonb_build_object('error', 'Odul kasasi icin envanterden Ac kullanin');
  END IF;

  IF lower(COALESCE(v_item.type, '')) NOT IN ('potion', 'consumable') THEN
    RETURN jsonb_build_object('error', 'Geçersiz iksir');
  END IF;

  v_new_tolerance := COALESCE(v_user.tolerance, 0) + COALESCE(v_item.tolerance_increase, 0);
  IF COALESCE(v_user.character_class, '') = 'alchemist' THEN
    v_new_tolerance := COALESCE(v_user.tolerance, 0)
      + floor(COALESCE(v_item.tolerance_increase, 0) * 0.75);
  END IF;
  v_new_tolerance := GREATEST(0, LEAST(v_new_tolerance, 100));

  v_efficiency := CASE
    WHEN COALESCE(v_user.tolerance, 0) <= 20 THEN 1.0
    WHEN COALESCE(v_user.tolerance, 0) <= 40 THEN 0.85
    WHEN COALESCE(v_user.tolerance, 0) <= 60 THEN 0.65
    WHEN COALESCE(v_user.tolerance, 0) <= 80 THEN 0.45
    ELSE 0.25
  END;

  IF COALESCE(v_user.character_class, '') = 'alchemist' THEN
    v_efficiency := LEAST(1.0, v_efficiency * 1.30);
  END IF;

  v_overdose_chance := COALESCE(v_item.overdose_risk, 0) * CASE
    WHEN COALESCE(v_user.tolerance, 0) <= 40 THEN 0.0
    WHEN COALESCE(v_user.tolerance, 0) <= 60 THEN 1.0
    WHEN COALESCE(v_user.tolerance, 0) <= 80 THEN 2.0
    WHEN COALESCE(v_user.tolerance, 0) <= 90 THEN 4.0
    ELSE 8.0
  END;

  IF COALESCE(v_user.character_class, '') = 'alchemist' THEN
    v_overdose_chance := v_overdose_chance * 0.80;
  END IF;

  IF v_monument_level >= 20 THEN
    v_overdose_chance := v_overdose_chance * 0.90;
  END IF;

  v_roll := random();
  IF v_roll <= v_overdose_chance THEN
    v_overdose := true;

    IF v_monument_level >= 80 AND (
      v_user.last_overdose_save_at IS NULL OR
      v_user.last_overdose_save_at::date < CURRENT_DATE
    ) THEN
      v_overdose := false;
      v_saved_from_overdose := true;
    END IF;
  END IF;

  IF NOT public._consume_inventory_row(p_row_id, p_user_id) THEN
    RETURN jsonb_build_object('error', 'Eşya bulunamadı veya miktar yetersiz');
  END IF;

  PERFORM public.bp_trigger_potion_usage(p_user_id);

  IF v_overdose THEN
    v_hospital_minutes := 30 + (COALESCE(v_user.tolerance, 0) * 2);

    UPDATE public.users
    SET addiction_level = LEAST(COALESCE(addiction_level, 0) + 1, 10),
        tolerance = LEAST(v_new_tolerance + 10, 100),
        hospital_until = now() + (v_hospital_minutes || ' minutes')::interval,
        hospital_reason = 'Overdose',
        last_potion_used_at = now()
    WHERE auth_id = p_user_id;

    INSERT INTO public.tolerance_log (
      user_id, event_type, item_id,
      tolerance_before, tolerance_after,
      addiction_before, addiction_after
    )
    VALUES (
      p_user_id, 'overdose', v_inv.item_id,
      COALESCE(v_user.tolerance, 0), LEAST(v_new_tolerance + 10, 100),
      COALESCE(v_user.addiction_level, 0), LEAST(COALESCE(v_user.addiction_level, 0) + 1, 10)
    );

    RETURN jsonb_build_object(
      'success', true,
      'overdose', true,
      'hospital_minutes', v_hospital_minutes,
      'efficiency', 0
    );
  END IF;

  v_heal_amount := floor(COALESCE(v_item.heal_amount, v_item.health_restore, 0) * v_efficiency);
  v_energy_gain := floor(COALESCE(v_item.energy_restore, 0) * v_efficiency);

  IF lower(COALESCE(v_item.potion_type, '')) = 'health' AND v_heal_amount = 0 THEN
    v_heal_amount := floor(COALESCE(v_item.heal_amount, 50) * v_efficiency);
  END IF;

  IF lower(COALESCE(v_item.potion_type, '')) = 'energy' AND v_energy_gain = 0 THEN
    v_energy_gain := floor(COALESCE(v_item.heal_amount, 20) * v_efficiency);
  END IF;

  UPDATE public.users
  SET tolerance = v_new_tolerance,
      last_potion_used_at = now(),
      last_overdose_save_at = CASE WHEN v_saved_from_overdose THEN now() ELSE last_overdose_save_at END,
      energy = LEAST(max_energy, COALESCE(energy, 0) + v_energy_gain),
      health = LEAST(max_health, COALESCE(health, 0) + v_heal_amount)
  WHERE auth_id = p_user_id;

  INSERT INTO public.tolerance_log (
    user_id, event_type, item_id,
    tolerance_before, tolerance_after,
    addiction_before, addiction_after
  )
  VALUES (
    p_user_id, 'potion_use', v_inv.item_id,
    COALESCE(v_user.tolerance, 0), v_new_tolerance,
    COALESCE(v_user.addiction_level, 0), COALESCE(v_user.addiction_level, 0)
  );

  RETURN jsonb_build_object(
    'success', true,
    'overdose', false,
    'saved_from_overdose', v_saved_from_overdose,
    'efficiency', v_efficiency,
    'new_tolerance', v_new_tolerance,
    'heal_amount', v_heal_amount,
    'energy_restored', v_energy_gain
  );
END;
$$;


ALTER FUNCTION "public"."use_potion"("p_row_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."use_stat_reset_scroll"("p_row_id" "uuid", "p_user_id" "uuid" DEFAULT "auth"."uid"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_inv RECORD;
  v_user RECORD;
  v_refund INTEGER;
BEGIN
  IF p_user_id IS NULL OR p_user_id != auth.uid() THEN
    RETURN jsonb_build_object('success', false, 'error', 'Yetkisiz işlem');
  END IF;

  SELECT * INTO v_user
  FROM public.users
  WHERE auth_id = p_user_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Kullanıcı bulunamadı');
  END IF;

  SELECT * INTO v_inv
  FROM public.inventory
  WHERE row_id = p_row_id
    AND user_id = p_user_id
    AND quantity > 0
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Eşya bulunamadı');
  END IF;

  IF v_inv.item_id <> 'scroll_stat_reset' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Geçersiz eşya');
  END IF;

  v_refund := COALESCE(v_user.stat_allocated_attack, 0)
            + COALESCE(v_user.stat_allocated_defense, 0)
            + COALESCE(v_user.stat_allocated_luck, 0);

  IF v_refund <= 0 THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Sıfırlanacak dağıtılmış stat puanı yok'
    );
  END IF;

  IF NOT public._consume_inventory_row(p_row_id, p_user_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Eşya tüketilemedi');
  END IF;

  UPDATE public.users
  SET attack = GREATEST(0, COALESCE(attack, 0) - COALESCE(stat_allocated_attack, 0)),
      defense = GREATEST(0, COALESCE(defense, 0) - COALESCE(stat_allocated_defense, 0)),
      luck = GREATEST(0, COALESCE(luck, 0) - COALESCE(stat_allocated_luck, 0)),
      stat_points = COALESCE(stat_points, 0) + v_refund,
      stat_allocated_attack = 0,
      stat_allocated_defense = 0,
      stat_allocated_luck = 0,
      updated_at = NOW()
  WHERE auth_id = p_user_id;

  RETURN jsonb_build_object(
    'success', true,
    'refunded', v_refund,
    'message', format('%s stat puanı geri alındı', v_refund)
  );
END;
$$;


ALTER FUNCTION "public"."use_stat_reset_scroll"("p_row_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_materials_in_inventory"("p_user_id" "uuid", "p_ingredients" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_ingredient jsonb;
    v_item_id TEXT;
    v_required INT;
    v_owned INT;
BEGIN
    FOR v_ingredient IN SELECT jsonb_array_elements(p_ingredients) LOOP
        v_item_id := v_ingredient->>'item_id';
        v_required := (v_ingredient->>'quantity')::INT;
        
        SELECT COALESCE(SUM(quantity), 0) INTO v_owned
        FROM inventory
        WHERE user_id = p_user_id AND item_id = v_item_id;
        
        IF v_owned < v_required THEN
            RETURN FALSE;
        END IF;
    END LOOP;
    
    RETURN TRUE;
END;
$$;


