CREATE OR REPLACE FUNCTION "public"."vote_in_election"("p_election_id" "uuid", "p_candidate_guild_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_player_id uuid := auth.uid();
  v_voter_guild_id uuid;
  v_is_leader boolean;
  v_guild_rank integer;
  v_candidate_rank integer;
  v_election record;
BEGIN
  SELECT * INTO v_election
  FROM public.kingdom_elections
  WHERE id = p_election_id;

  IF v_election IS NULL THEN
    RETURN json_build_object('success', false, 'error', 'Seçim bulunamadı.');
  END IF;

  IF v_election.status != 'active' THEN
    RETURN json_build_object('success', false, 'error', 'Bu seçim artık aktif değil.');
  END IF;

  IF v_election.start_at IS NOT NULL AND v_election.start_at > now() THEN
    RETURN json_build_object('success', false, 'error', 'Seçim henüz başlamadı.');
  END IF;

  IF v_election.end_at IS NOT NULL AND v_election.end_at <= now() THEN
    PERFORM public.finalize_kingdom_election(p_election_id);
    RETURN json_build_object('success', false, 'error', 'Seçim süresi doldu.');
  END IF;

  SELECT g.id, (g.leader_id = v_player_id)
  INTO v_voter_guild_id, v_is_leader
  FROM public.guilds g
  JOIN public.users u ON u.guild_id = g.id
  WHERE u.auth_id = v_player_id;

  IF v_voter_guild_id IS NULL THEN
    RETURN json_build_object('success', false, 'error', 'Bir loncaya üye değilsiniz.');
  END IF;

  IF NOT v_is_leader THEN
    RETURN json_build_object('success', false, 'error', 'Sadece lonca liderleri oy kullanabilir.');
  END IF;

  v_guild_rank := public._guild_war_season_rank(v_voter_guild_id);

  IF v_guild_rank IS NULL OR v_guild_rank > 20 THEN
    RETURN json_build_object(
      'success', false,
      'error', 'Krallık oylamasına yalnızca sezon sıralamasında ilk 20 loncanın liderleri katılabilir.'
    );
  END IF;

  SELECT cg.season_rank
  INTO v_candidate_rank
  FROM public._kingdom_election_candidate_guilds(20) cg
  WHERE cg.guild_id = p_candidate_guild_id;

  IF v_candidate_rank IS NULL THEN
    RETURN json_build_object(
      'success', false,
      'error', 'Yalnızca sezon sıralamasında ilk 20 lonca aday olabilir.'
    );
  END IF;

  BEGIN
    INSERT INTO public.kingdom_election_votes (election_id, voter_guild_id, candidate_guild_id)
    VALUES (p_election_id, v_voter_guild_id, p_candidate_guild_id);
  EXCEPTION WHEN unique_violation THEN
    RETURN json_build_object('success', false, 'error', 'Bu seçimde zaten oy kullandınız.');
  END;

  RETURN json_build_object('success', true, 'message', 'Oyunuz başarıyla kaydedildi.');
END;
$$;


ALTER FUNCTION "public"."vote_in_election"("p_election_id" "uuid", "p_candidate_guild_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."withdraw_from_bank"("p_bank_item_ids" "uuid"[], "p_quantities" integer[] DEFAULT NULL::integer[]) RETURNS TABLE("success" boolean, "message" "text", "items_withdrawn" integer, "new_used_slots" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_processed_count integer := 0;
  v_deleted_slots integer := 0;
  v_used_slots integer;
  v_bank_item_id uuid;
  v_item_id text;
  v_bank_quantity integer;
  v_requested_qty integer;
  v_max_stack integer;
  v_existing_inv_qty integer;
  v_can_stack integer;
  v_will_withdraw integer;
  v_will_remain integer;
  v_add_result jsonb;
  i integer;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN QUERY SELECT false, 'Not authenticated'::text, 0::integer, 0::integer;
    RETURN;
  END IF;

  IF p_bank_item_ids IS NULL OR array_length(p_bank_item_ids, 1) IS NULL THEN
    RETURN QUERY SELECT false, 'No bank items specified'::text, 0::integer, 0::integer;
    RETURN;
  END IF;

  SELECT used_slots
  INTO v_used_slots
  FROM public.user_bank_account
  WHERE user_id = v_user_id;

  FOR i IN 1..array_length(p_bank_item_ids, 1) LOOP
    v_bank_item_id := p_bank_item_ids[i];

    SELECT item_id, quantity INTO v_item_id, v_bank_quantity
    FROM public.bank_items
    WHERE id = v_bank_item_id AND user_id = v_user_id;

    IF v_item_id IS NULL THEN
      CONTINUE;
    END IF;

    v_requested_qty := v_bank_quantity;
    IF p_quantities IS NOT NULL
       AND array_length(p_quantities, 1) IS NOT NULL
       AND i <= array_length(p_quantities, 1)
       AND p_quantities[i] IS NOT NULL THEN
      v_requested_qty := LEAST(v_bank_quantity, GREATEST(1, p_quantities[i]));
    END IF;

    SELECT max_stack INTO v_max_stack
    FROM public.items
    WHERE id = v_item_id;

    v_max_stack := COALESCE(v_max_stack, 1);

    SELECT COALESCE(SUM(quantity), 0) INTO v_existing_inv_qty
    FROM public.inventory
    WHERE user_id = v_user_id
      AND item_id = v_item_id
      AND is_equipped = FALSE;

    v_can_stack := v_max_stack - v_existing_inv_qty;

    IF v_can_stack <= 0 THEN
      CONTINUE;
    END IF;

    v_will_withdraw := LEAST(v_requested_qty, v_can_stack);
    v_will_remain := v_bank_quantity - v_will_withdraw;

    IF v_will_withdraw <= 0 THEN
      CONTINUE;
    END IF;

    v_add_result := public.add_inventory_item_v2(
      jsonb_build_object(
        'item_id', v_item_id,
        'quantity', v_will_withdraw
      ),
      NULL
    );

    IF COALESCE((v_add_result->>'success')::boolean, false) IS NOT TRUE THEN
      CONTINUE;
    END IF;

    IF v_will_remain > 0 THEN
      UPDATE public.bank_items
      SET quantity = v_will_remain,
          updated_at = now()
      WHERE id = v_bank_item_id;
    ELSE
      DELETE FROM public.bank_items WHERE id = v_bank_item_id;
      v_deleted_slots := v_deleted_slots + 1;
    END IF;

    v_processed_count := v_processed_count + 1;
  END LOOP;

  UPDATE public.user_bank_account
  SET used_slots = GREATEST(0, used_slots - v_deleted_slots),
      updated_at = now()
  WHERE user_id = v_user_id;

  IF v_processed_count <= 0 THEN
    RETURN QUERY SELECT false,
      'Envanter dolu veya secilen esyalar cekilemedi'::text,
      0::integer,
      COALESCE(v_used_slots, 0)::integer;
    RETURN;
  END IF;

  RETURN QUERY SELECT true,
    'Withdrawn successfully'::text,
    v_processed_count::integer,
    GREATEST(0, COALESCE(v_used_slots, 0) - v_deleted_slots)::integer;
END;
$$;


