CREATE OR REPLACE FUNCTION "public"."write_chat_audit"("p_actor_user_id" "uuid", "p_action" "text", "p_target_user_id" "uuid" DEFAULT NULL::"uuid", "p_target_message_id" "uuid" DEFAULT NULL::"uuid", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  INSERT INTO public.chat_audit_log (actor_user_id, action, target_user_id, target_message_id, metadata)
  VALUES (p_actor_user_id, p_action, p_target_user_id, p_target_message_id, COALESCE(p_metadata, '{}'::jsonb));
END;
$$;


ALTER FUNCTION "public"."write_chat_audit"("p_actor_user_id" "uuid", "p_action" "text", "p_target_user_id" "uuid", "p_target_message_id" "uuid", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."xp_needed_for_level"("p_level" integer) RETURNS integer
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF p_level IS NULL OR p_level < 1 THEN
    RETURN 0;
  END IF;

  RETURN floor(100 * p_level * (1 + p_level * 0.15));
END;
$$;


