CREATE TABLE IF NOT EXISTS "public"."horse_race_settings" (
    "id" "text" DEFAULT 'default'::"text" NOT NULL,
    "gold_min_bet" integer DEFAULT 10000 NOT NULL,
    "gold_max_bet" integer DEFAULT 5000000 NOT NULL,
    "gem_min_bet" integer DEFAULT 1 NOT NULL,
    "gem_max_bet" integer DEFAULT 50 NOT NULL,
    "daily_bet_limit" integer,
    "is_active" boolean DEFAULT true NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "betting_seconds" integer DEFAULT 90 NOT NULL,
    "racing_seconds" integer DEFAULT 8 NOT NULL,
    "finished_seconds" integer DEFAULT 10 NOT NULL,
    "gold_max_multiplier" numeric(6,2) DEFAULT 12.00 NOT NULL,
    "gem_max_multiplier" numeric(6,2) DEFAULT 12.00 NOT NULL,
    "house_edge" numeric(4,2) DEFAULT 0.92 NOT NULL,
    CONSTRAINT "horse_race_settings_betting_seconds_check" CHECK (("betting_seconds" > 0)),
    CONSTRAINT "horse_race_settings_check" CHECK (("gold_max_bet" >= "gold_min_bet")),
    CONSTRAINT "horse_race_settings_check1" CHECK (("gem_max_bet" >= "gem_min_bet")),
    CONSTRAINT "horse_race_settings_daily_bet_limit_check" CHECK ((("daily_bet_limit" IS NULL) OR ("daily_bet_limit" > 0))),
    CONSTRAINT "horse_race_settings_finished_seconds_check" CHECK (("finished_seconds" > 0)),
    CONSTRAINT "horse_race_settings_gem_max_multiplier_check" CHECK (("gem_max_multiplier" > (0)::numeric)),
    CONSTRAINT "horse_race_settings_gem_min_bet_check" CHECK (("gem_min_bet" > 0)),
    CONSTRAINT "horse_race_settings_gold_max_multiplier_check" CHECK (("gold_max_multiplier" > (0)::numeric)),
    CONSTRAINT "horse_race_settings_gold_min_bet_check" CHECK (("gold_min_bet" > 0)),
    CONSTRAINT "horse_race_settings_house_edge_check" CHECK ((("house_edge" > (0)::numeric) AND ("house_edge" <= (1)::numeric))),
    CONSTRAINT "horse_race_settings_racing_seconds_check" CHECK (("racing_seconds" > 0))
);


ALTER TABLE "public"."horse_race_settings" OWNER TO "postgres";


COMMENT ON COLUMN "public"."horse_race_settings"."gold_max_multiplier" IS 'Upper clamp for displayed/paid gold multiplier. Must exceed house_edge / min_win_prob for full RTP on long-shot horses (e.g. 0.92/0.095 ≈ 9.7 at ~9.5% win).';



COMMENT ON COLUMN "public"."horse_race_settings"."gem_max_multiplier" IS 'Upper clamp for displayed/paid gem multiplier. Same RTP formula as gold; cap must not bind typical sort_order-6 horses.';



COMMENT ON COLUMN "public"."horse_race_settings"."house_edge" IS 'Target RTP for a single-horse bet when multipliers are uncapped (0.92 = 92% return).';



